INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('googlicius/obsidian-steward/user-defined-command', 'community', 'googlicius', 'obsidian-steward', 'googlicius/obsidian-steward', 'user-defined-command', 0, 0, 60, '2026-03-08T01:57:15.404Z', '2026-03-08T02:06:52.100Z', 'f8b7768b4cf87f920e5798bde2b4e25e35bdb963d33bb2b100f82894da8d7c16', '{"id":"googlicius/obsidian-steward/user-defined-command","name":"user-defined-command","description":{"en":"The user-defined-command skill enables developers to create and edit valid Steward user-defined commands stored as markdown files. It benefits AI agent developers by providing a flexible way to define custom commands.","zh":"用户自定义命令技能允许您创建和编辑有效的Steward用户自定义命令，使用YAML代码块和markdown内容","ja":"ユーザー定義コマンドスキルを使用して、Stewardユーザー定義コマンドを作成および編集します。YAMLコードブロックとマークダウンコンテンツを使用します","ko":"사용자 정의 명령어 스킬을 사용하여 Steward 사용자 정의 명령어를 생성하고 편집합니다. YAML 코드 블록과 markdown 내용을 사용합니다","es":"El skill de comando definido por el usuario permite crear y editar comandos válidos de Steward con YAML y markdown. Aprende a configurar tus propios comandos personalizados.","fr":"Le skill de commande définie par l''utilisateur permet de créer et d''éditer des commandes valides de Steward avec YAML et markdown. Apprenez à configurer vos propres commandes personnalisées.","de":"Der Skill für benutzerdefinierte Befehle ermöglicht die Erstellung und Bearbeitung von gültigen Steward-Befehlen mit YAML und Markdown. Erfahren Sie, wie Sie Ihre eigenen benutzerdefinierten Befehle konfigurieren können.","pt":"O skill de comando personalizado do Steward permite criar e editar comandos válidos em YAML e markdown. Aprenda a configurar comandos personalizados para melhorar sua experiência de desenvolvimento","ru":"Навык пользовательской команды Steward позволяет создавать и редактировать действительные команды в форматах YAML и markdown. Узнайте, как настроить пользовательские команды для улучшения вашего опыта разработки","ar":"مهارة الأمر المخصص لمستخدمي Steward تمكن من إنشاء وتحرير أوامر صالحة في YAML و markdown. تعرف على كيفية إعداد أوامر مخصصة لتحسين تجربة التطوير الخاصة بك"},"seo":{"title":{"en":"User-Defined Command: YAML-Based Command Setup Guide | AI...","zh":"用户自定义命令设置指南 - AIエージェント","ja":"ユーザー定義コマンドのベストプラクティス - AIエージェント","ko":"사용자 정의 명령어 설정 가이드 - AI 도구","es":"Guía de Configuración de Comandos Personalizados de AI","fr":"Guide d''Installation de Commandes Définies par l''Utilisat...","de":"Einrichtungsleitfaden für Benutzerdefinierte Befehle von ...","pt":"Guia de Configuração de Comandos Personalizados do Steward","ru":"Настройка пользовательских команд Steward: лучшие практик...","ar":"دليل إعداد أوامر مخصصة لمستخدمي Steward"},"description":{"en":"Discover how to create custom Steward commands with YAML-based definitions and markdown files. Learn to harness user-defined commands for AI agents now!","zh":"了解如何创建和编辑有效的Steward用户自定义命令，包括YAML代码块和markdown内容","ja":"Stewardユーザー定義コマンドの作成と編集方法を学び、YAMLコードブロックとマークダウンコンテンツを活用する","ko":"Steward 사용자 정의 명령어를 생성하고 편집하는 방법을 알아보세요. YAML 코드 블록과 markdown 내용을 포함하여","es":"Aprende a crear y editar comandos personalizados de AI con nuestro skill de comando definido por el usuario. Descubre cómo funciona con YAML y markdown.","fr":"Découvrez comment créer et éditer des commandes personnalisées d''AI Outils avec notre skill de commande définie par l''utilisateur. Apprenez-en plus sur son f...","de":"Erfahren Sie, wie Sie benutzerdefinierte Befehle von KI-Agenten erstellen und bearbeiten können. Entdecken Sie, wie unser Skill mit YAML und Markdown funktio...","pt":"Aprenda a criar e editar comandos personalizados do Steward em YAML e markdown. Descubra como otimizar sua experiência de desenvolvimento com comandos person...","ru":"Узнайте, как создавать и редактировать пользовательские команды Steward в форматах YAML и markdown. Оптимизируйте свою разработку с помощью ИИ Агентов","ar":"تعرف على كيفية إنشاء وتحرير أوامر مخصصة لمستخدمي Steward باستخدام YAML و markdown. تحسين تجربة التطوير الخاصة بك مع أوامر مخصصة"},"definition":{"en":"User-defined-command is a skill that allows developers to create custom YAML-based command definitions stored as markdown files in the Steward/Commands folder.","zh":"用户自定义命令是指使用YAML代码块和markdown内容创建的Steward命令","ja":"ユーザー定義コマンドは、YAMLコードブロックとマークダウンコンテンツを使用して作成されるStewardコマンドです","ko":"사용자 정의 명령어는 YAML 코드 블록과 markdown 내용을 사용하여 생성되는 Steward 명령어입니다","es":"Un comando personalizado de AI es una definición de comando basada en YAML almacenada en un archivo markdown en la carpeta Steward/Commands.","fr":"Une commande personnalisée d''AI Outils est une définition de commande basée sur YAML stockée dans un fichier markdown dans le dossier Steward/Commands.","de":"Ein benutzerdefinierter Befehl von KI-Agenten ist eine YAML-basierte Befehlsdefinition, die in einer Markdown-Datei im Steward/Commands-Verzeichnis gespeichert ist.","pt":"Comando personalizado do Steward é uma funcionalidade que permite criar e editar comandos em YAML e markdown","ru":"Пользовательская команда Steward - это функция, которая позволяет создавать и редактировать команды в форматах YAML и markdown","ar":"الأمر المخصص لمستخدمي Steward هو ميزة تمكن من إنشاء وتحرير أوامر في YAML و markdown"},"features":{"en":["Supports YAML code blocks in markdown files","Allows plain text, headings, and other markdown content","Enables creation and editing of valid Steward user-defined commands","Stores command definitions in the Steward/Commands folder","Uses markdown files (.md) for command definitions","Includes command-level fields for customization"],"zh":["支持YAML代码块","支持markdown内容","命令存储在Steward/Commands文件夹中","支持命令级字段","支持YAML模式"],"ja":["YAMLコードブロックをサポート","マークダウンコンテンツをサポート","コマンドはSteward/Commandsフォルダーに保存","コマンドレベルフィールドをサポート","YAMLスキーマをサポート"],"ko":["YAML 코드 블록 지원","markdown 내용 지원","명령어는 Steward/Commands 폴더에 저장","명령어 수준 필드를 지원","YAML 스키마 지원"],"es":["Creación de comandos personalizados con YAML","Edición de comandos válidos de Steward","Almacenamiento de comandos en archivos markdown","Uso de campos de nivel de comando como tipo y esquema","Compatibilidad con texto plano, encabezados y otros contenidos de markdown"],"fr":["Création de commandes personnalisées avec YAML","Édition de commandes valides de Steward","Stockage de commandes dans des fichiers markdown","Utilisation de champs de niveau de commande tels que type et schéma","Compatibilité avec du texte brut, des en-têtes et d''autres contenus markdown"],"de":["Erstellung benutzerdefinierter Befehle mit YAML","Bearbeitung gültiger Steward-Befehle","Speicherung von Befehlen in Markdown-Dateien","Verwendung von Befehlsfeldern wie Typ und Schema","Kompatibilität mit Klartext, Überschriften und anderen Markdown-Inhalten"],"pt":["Criação de comandos personalizados em YAML","Edição de comandos em markdown","Armazenamento de comandos em arquivos markdown","Referência a prompts do sistema","Suporte a campos de nível de comando"],"ru":["Создание пользовательских команд в формате YAML","Редактирование команд в формате markdown","Хранение команд в файлах markdown","Ссылка на системные промпты","Поддержка полей уровня команды"],"ar":["إنشاء أوامر مخصصة في YAML","تحرير أوامر في markdown","تخزين أوامر في ملفات markdown","مرجع إلى مُحفزات النظام","دعم حقول مستوى الأمر"]},"keywords":{"en":["how to use user-defined-command","user-defined-command setup guide","YAML-based command definitions","Steward user-defined commands","user-defined-command alternative","user-defined-command vs custom commands","user-defined-command install","what is user-defined-command","user-defined-command for AI agents"],"zh":["用户自定义命令","Steward命令","YAML代码块","markdown内容","AIエージェント","命令设置指南","用户自定义命令设置"],"ja":["ユーザー定義コマンド","Stewardコマンド","YAMLコードブロック","マークダウンコンテンツ","AIエージェント","コマンド設定ガイド","ユーザー定義コマンド設定"],"ko":["사용자 정의 명령어","Steward 명령어","YAML 코드 블록","markdown 내용","AI 도구","명령어 설정 가이드","사용자 정의 명령어 설정"],"es":["comandos personalizados de AI","skill de comando definido por el usuario","YAML","markdown","Steward","comandos válidos","creación de comandos","edición de comandos"],"fr":["commandes personnalisées d''AI Outils","skill de commande définie par l''utilisateur","YAML","markdown","Steward","commandes valides","création de commandes","édition de commandes"],"de":["benutzerdefinierte Befehle von KI-Agenten","Skill für benutzerdefinierte Befehle","YAML","Markdown","Steward","gültige Befehle","Erstellung von Befehlen","Bearbeitung von Befehlen"],"pt":["comando personalizado Steward","YAML","markdown","desenvolvimento de software","comandos personalizados","Steward","configuração de comandos","otimização de desenvolvimento"],"ru":["пользовательская команда Steward","YAML","markdown","разработка программного обеспечения","пользовательские команды","Steward","настройка команд","оптимизация разработки","ИИ Агенты"],"ar":["الأمر المخصص لمستخدمي Steward","YAML","markdown","تطوير البرمجيات","أوامر مخصصة","Steward","إعداد أوامر","تحسين التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"googlicius","repo":"obsidian-steward","repoPath":"googlicius/obsidian-steward","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.404Z","topics":[],"category":"community","skillMd":{"name":"user-defined-command","description":"Create and edit Steward user-defined commands (UDCs). Use when the user wants to create, modify, or troubleshoot custom command workflows defined as YAML in the Steward/Commands folder.","bodyPreview":"# User-Defined Command Skill\n\nThis skill enables you to create and edit valid Steward user-defined commands — YAML-based command definitions stored as markdown files in the `Steward/Commands` folder.\n\n## File Format\n\nEach command is a markdown file (`.md`) containing one or more YAML code blocks. The file can also contain plain text, headings, and other markdown content that can be referenced by system prompts.\n\n## YAML Schema\n\n### Command-Level Fields\n\n| Field            | Type","body":"# User-Defined Command Skill\n\nThis skill enables you to create and edit valid Steward user-defined commands — YAML-based command definitions stored as markdown files in the `Steward/Commands` folder.\n\n## File Format\n\nEach command is a markdown file (`.md`) containing one or more YAML code blocks. The file can also contain plain text, headings, and other markdown content that can be referenced by system prompts.\n\n## YAML Schema\n\n### Command-Level Fields\n\n| Field            | Type                     | Required | Description                                                                              |\n| ---------------- | ------------------------ | -------- | ---------------------------------------------------------------------------------------- |\n| `command_name`   | string                   | **Yes**  | The name (In kebab-case) to invoke the command (e.g., `clean-up` invoked as `/clean-up`) |\n| `query_required` | boolean                  | No       | If `true`, the command requires user input after the prefix. Default: `false`            |\n| `model`          | string                   | No       | Default model for all steps (e.g., `gpt-4o`, `gemini-2.5-flash`)                         |\n| `system_prompt`  | array of strings         | No       | Additional system prompts applied to all steps                                           |\n| `use_tool`       | boolean                  | No       | If `false`, disables the core tool usage instructions                                    |\n| `hidden`         | boolean                  | No       | If `true`, the command does not appear in the autocomplete menu                          |\n| `triggers`       | array of trigger objects | No       | Automatically execute when file events match criteria                                    |\n| `steps`          | array of step objects    | **Yes**  | The sequence of steps to execute                                                         |\n\n### Step-Level Fields\n\n| Field           | Type             | Required    | Description                                                                                                                                                         |\n| --------------- | ---------------- | ----------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| `name`          | string           | No          | Step name that activates corresponding tools: `read`, `edit`, `search`, `vault`, `generate`, `image`, `speech`. Use `generate` for direct AI response without tools |\n| `query`         | string           | Conditional | The query to send. Required if `query_required` is `true`. Use `$from_user` as placeholder for user input                                                           |\n| `system_prompt` | array of strings | No          | Additional system prompts for this step only                                                                                                                        |\n| `model`         | string           | No          | Model override for this step                                                                                                                                        |\n| `no_confirm`    | boolean          | No          | If `true`, skips confirmation prompts for this step                                                                                                                 |\n\n### Trigger Fields\n\n| Field                 | Type             | Required | Description                                               |\n| --------------------- | ---------------- | -------- | --------------------------------------------------------- |\n| `events`              | array of strings | **Yes**  | Events to watch: `create`, `modify`, `delete`             |\n| `folders`             | array of strings | No       | Folder paths to watch (e.g., `[\"Inbox\", \"Daily Notes\"]`)  |\n| `patterns`            | object           | No       | Pattern matching criteria (all must match)                |\n| `patterns.tags`       | string or array  | No       | Tags to match (e.g., `\"#todo\"` or `[\"#todo\", \"#review\"]`) |\n| `patterns.content`    | string           | No       | Regex pattern to match file content                       |\n| `patterns.<property>` | string or array  | No       | Any frontmatter property name and value to match          |\n\n## Command Syntax (Direct Tool Calls)\n\nSteps can use **command syntax** in the `query` field to invoke tools directly without an AI round trip. This is the preferred approach for deterministic operations.\n\n### Syntax\n\n```\nc:<tool> [--arg=value]...\n```\n\n- `c:` prefix identifies a direct command call\n- `<tool>` is a short alias (see reference below)\n- `--key=value` pairs map to the tool''s input schema\n- Multiple commands can be chained with `;` separator: `c:read --blocks=1; c:conclude`\n- Quoted values for strings with spaces: `--content=\"hello world\"`\n- Comma-separated values for arrays: `--files=Note1.md,Note2.md`\n\n### Command Reference\n\n| Alias        | Tool            | Flags                                                     |\n| ------------ | --------------- | --------------------------------------------------------- |\n| `c:read`     | Content Reading | `--type`, `--files`, `--element`, `--blocks`, `--pattern` |\n| `c:search`   | Search          | `--keywords`, `--filenames`, `--folders`, `--properties`  |\n| `c:delete`   | Delete          | `--artifact`, `--files`                                   |\n| `c:list`     | List            | `--folder`, `--pattern`                                   |\n| `c:move`     | Move            | `--artifact`, `--files`, `--destination`                  |\n| `c:rename`   | Rename          | `--artifact`, `--pattern`, `--replace`                    |\n| `c:grep`     | Grep            | `--pattern`, `--paths`                                    |\n| `c:speech`   | Speech          | `--text`                                                  |\n| `c:image`    | Image           | `--prompt`                                                |\n| `c:conclude` | Conclude (stop) |                                                           |\n\n### `c:read` Flags\n\n| Flag         | Type     | Default | Description                                                                    |\n| ------------ | -------- | ------- | ------------------------------------------------------------------------------ |\n| `--type`     | string   | `above` | One of: `above`, `below`, `pattern`, `entire`, `frontmatter`                   |\n| `--files`    | string[] | `[]`    | Comma-separated file names to read from                                        |\n| `--artifact` | string   | —       | Artifact ID (or `latest`) to resolve file names from.                          |\n| `--element`  | string   | `null`  | One of: `paragraph`, `table`, `code`, `list`, `blockquote`, `image`, `heading` |\n| `--blocks`   | number   | `1`     | Number of blocks to read. Use `-1` for all content from current position       |\n| `--pattern`  | string   | —       | RegExp pattern (required when `--type=pattern`)                                |\n\n### `c:search` Flags\n\n| Flag           | Type     | Description                                                                              |\n| -------------- | -------- | ---------------------------------------------------------------------------------------- |\n| `--keywords`   | string[] | Comma-separated search terms                                                             |\n| `--filenames`  | string[] | Comma-separated file names to search for                                                 |\n| `--folders`    | string[] | Comma-separated folder paths to search within                                            |\n| `--properties` | json     | Property filters in `name:value` format, comma-separated (e.g. `tag:todo,status:active`) |\n\n### `c:delete` Flags\n\n| Flag         | Type     | Description                            |\n| ------------ | -------- | -------------------------------------- |\n| `--artifact` | string   | Artifact ID containing files to delete |\n| `--files`    | string[] | Comma-separated file paths to delete   |\n\nOne of `--artifact` or `--files` is required.\n\n### `c:list` Flags\n\n| Flag        | Type   | Description                         |\n| ----------- | ------ | ----------------------------------- |\n| `--folder`  | string | Folder path to list files from      |\n| `--pattern` | string | RegExp pattern to filter file names |\n\n### `c:move` Flags\n\n| Flag            | Type     | Description                          |\n| --------------- | -------- | ------------------------------------ |\n| `--artifact`    | string   | Artifact ID containing files to move |\n| `--files`       | string[] | Comma-separated file paths to move   |\n| `--destination` | string   | Destination folder path              |\n\nOne of `--artifact` or `--files` is required, along with `--destination`.\n\n### `c:rename` Flags\n\n| Flag         | Type   | Description                            |\n| ------------ | ------ | -------------------------------------- |\n| `--artifact` | string | Artifact ID containing files to rename |\n| `--pattern`  | string | Pattern to match in file names         |\n| `--replace`  | string | Replacement text for matched pattern   |\n\n### `c:grep` Flags\n\n| Flag        | Type     | Description                                          |\n| ----------- | -------- | ---------------------------------------------------- |\n| `--pattern` | string   | Text or RegExp pattern to search for in file content |\n| `--paths`   | string[] | Comma-separated folder paths to search within        |\n\n### Composing Steps\n\nWhen composing UDC steps, prefer `c:` command syntax for **deterministic operations** to avoid unnecessary AI round trips. Reserve natural language queries for steps that require **AI reasoning** (e.g., content generation, summarization, complex editing decisions).\n\n**Use command syntax when the step:**\n\n- Reads content from a known location (`c:read`)\n- Searches with specific criteria (`c:search`)\n- Performs file operations: delete, move, rename, list, grep\n- Generates speech or images from known text/prompts (`c:speech`, `c:image`)\n\n**Use natural language when the step:**\n\n- Needs AI to generate, summarize, or transform content\n- Requires the AI to decide what to edit or how to structure output\n- Involves complex reasoning about the content\n\nWhen `c:` syntax is used, the step `name` is still recommended for tool activation but the query is parsed directly, bypassing the AI entirely.\n\n## System Prompt Values\n\nThe `system_prompt` field accepts an array of strings. Each string can be:\n\n- **Plain text**: Direct instructions (e.g., `''Always use formal language''`)\n- **Wiki link to a note**: `''[[Note Name]]''` — includes the full content of that note\n- **Wiki link to a heading**: `''[[Note Name#Heading]]''` — includes content under that heading only\n- **Wiki link to local heading**: `''[[#Heading]]''` — includes content under a heading in the current command file\n\n## Placeholders\n\nThese placeholders are replaced with actual values at execution time:\n\n- `$from_user` — The user''s input text\n- `$file_name` — The file name that triggered the command (for triggered commands)\n- `$steward` — The Steward folder path\n- `$active_file` — The file path of the currently active file in the workspace\n\n## Examples\n\n### Simple multi-step command (with command syntax)\n\n```yaml\ncommand_name: clean-up\nquery_required: false\nsteps:\n  - name: search\n    query: ''c:search --keywords=Untitled --properties=tag:delete''\n    no_confirm: true\n  - name: vault\n    query: ''c:delete --artifact=latest; c:conclude''\n    no_confirm: true\n```\n\n### Simple multi-step command (natural language)\n\n```yaml\ncommand_name: clean-up\nquery_required: false\nmodel: gpt-4o\nsteps:\n  - name: search\n    query: ''Notes name starts with Untitled or with tag #delete''\n  - name: vault\n    query: ''Delete them''\n    model: gpt-3.5-turbo\n```\n\n### Mixed: command syntax for read, natural language for AI-driven edit\n\n```yaml\ncommand_name: format-lists\nquery_required: false\nsteps:\n  - name: read\n    query: ''c:read --blocks=-1 --element=list''\n    no_confirm: true\n  - name: edit\n    query: ''Format the list items from the previous step into a clean bulleted list''\n    system_prompt:\n      - ''Rewrite the list using consistent bullet formatting''\n```\n\n### Chaining multiple commands in a single step\n\n```yaml\ncommand_name: quick-search-delete\nquery_required: false\nsteps:\n  - query: ''c:search --keywords=Untitled; c:delete --artifact=latest; c:conclude''\n    no_confirm: true\n```\n\n### Question-answering command with system prompt\n\n```yaml\ncommand_name: ask\nquery_required: true\nuse_tool: false\nsystem_prompt:\n  - ''[[#Instructions]]''\nsteps:\n  - query: ''$from_user''\n```\n\n### Command with step-level system prompts\n\n```yaml\ncommand_name: summarize\nquery_required: true\nsteps:\n  - name: generate\n    system_prompt:\n      - ''[[My Context Note]]''\n      - ''Focus on key takeaways''\n      - ''Use bullet points''\n    query: $from_user\n```\n\n### Automated trigger command (with command syntax for read)\n\n```yaml\ncommand_name: generate_flashcards\nquery_required: false\n\ntriggers:\n  - events: [modify]\n    patterns:\n      tags: ''#flashcard-gen''\n\nsteps:\n  - name: read\n    query: ''c:read --type=entire --files=$file_name; c:conclude''\n    no_confirm: true\n  - name: edit\n    query: |\n      Generate flashcards from this note content.\n      Format each flashcard as:\n      Q: [question]\n      A: [answer]\n      ---\n      Append the flashcards at the end of the note under a \"## Flashcards\" heading.\n```\n\n### Hidden command (not shown in autocomplete)\n\n```yaml\ncommand_name: internal-helper\nhidden: true\nquery_required: true\nsteps:\n  - name: generate\n    query: $from_user\n```\n\n## Rules\n\n- Note name should use sentence case: capitalize the first letter with spaces between words (e.g., `Clean up vault.md`).\n- Do NOT add any heading at the beginning of the note. A short introduction should be the first content in the file.\n- The YAML block MUST be inside a fenced code block with the `yaml` language tag.\n- `command_name` and `steps` are always required.\n- Step `name` determines which tools are available. Omitting `name` uses the default tool set.\n- When `query_required` is `true`, at least one step must use `$from_user` in its `query`.\n- When `use_tool` is `false`, the core system prompt with tool instructions is not sent — useful for pure conversational commands.\n- System prompts and instructions referenced via `[[#Heading]]` should be placed BELOW the YAML code block, not above it.\n- System prompts with wiki links are resolved at execution time. If a linked note or heading does not exist, an error occurs and the command will stop.\n- For triggered commands, ensure the `query` in steps uses `$file_name` to reference the triggering file.\n- Multiple triggers can be defined; any matching trigger will execute the command.\n- A command file can contain multiple YAML code blocks, each defining a separate command.\n- Markdown content outside YAML blocks (headings, text, lists) can be referenced by system prompts using `[[#Heading]]` syntax.\n- When composing UDC steps, **prefer `c:` command syntax** for deterministic operations (read, search, delete, move, rename, list, grep, speech, image) to avoid unnecessary AI round trips. Reserve natural language queries for steps that require AI reasoning.\n"},"lastSynced":"2026-03-08T02:06:52.100Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing customized command definitions, such as Cursor, Windsurf, or Claude Code, to enhance their interaction capabilities.","zh":"非常适合需要自定义命令定义的AI代理，例如Cursor、Windsurf或Claude Code，以增强其交互能力。","ja":"カーソル、ウィンドサーフィン、またはClaude Codeなどのカスタムコマンド定義を必要とするAIエージェントに最適です。これにより、エージェントの相互作用能力が強化されます。","ko":"Cursor, Windsurf 또는 Claude Code와 같은 커스텀 명령 정의가 필요한 AI 에이전트에게 적합합니다. 이를 통해 에이전트의 상호 작용 능력이 향상됩니다.","es":"Perfecto para agentes de IA que necesitan definiciones de comandos personalizados, como Cursor, Windsurf o Claude Code, para mejorar sus capacidades de interacción.","fr":"Parfait pour les agents IA qui ont besoin de définitions de commandes personnalisées, telles que Cursor, Windsurf ou Claude Code, pour améliorer leurs capacités d''interaction.","de":"Perfekt für KI-Agents, die benutzerdefinierte Befehlsdefinitionen benötigen, wie z.B. Cursor, Windsurf oder Claude Code, um ihre Interaktionsfähigkeiten zu verbessern.","pt":"Perfeito para Agentes de IA que necessitam de definições de comandos personalizadas, como Cursor, Windsurf ou Claude Code, para melhorar suas capacidades de interação.","ru":"Идеально подходит для агентов ИИ, которым требуются настраиваемые определения команд, такие как Cursor, Windsurf или Claude Code, для улучшения их возможностей взаимодействия.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تحتاج إلى تعريفات أوامر مخصصة، مثل Cursor أو Windsurf أو Claude Code، لتعزيز قابليتها للتفاعل."},"recommendation":{"en":"Empowers agents to define and edit custom commands stored as markdown files, utilizing YAML-based command definitions, enabling flexible and tailored interactions with the Steward system through the `Steward/Commands` folder.","zh":"赋予代理定义和编辑存储为markdown文件的自定义命令，利用基于YAML的命令定义，使得代理能够通过`Steward/Commands`文件夹与Steward系统进行灵活和定制的交互。","ja":"エージェントに、YAMLベースのコマンド定義を使用してMarkdownファイルとして保存されたカスタムコマンドを定義および編集する機能を提供します。これにより、エージェントは`Steward/Commands`フォルダを介してStewardシステムと柔軟かつカスタマイズされたやり取りを行うことができます。","ko":"에이전트에 YAML 기반의 명령 정의를 사용하여 마크다운 파일로 저장된 사용자 지정 명령을 정의 및 편집할 수 있는 기능을 제공합니다. 이를 통해 에이전트는 `Steward/Commands` 폴더를 통해 스튜어드 시스템과 유연하고 맞춤형으로 상호 작용할 수 있습니다.","es":"Habilita a los agentes a definir y editar comandos personalizados almacenados como archivos markdown, utilizando definiciones de comandos basadas en YAML, lo que permite interacciones flexibles y personalizadas con el sistema Steward a través de la carpeta `Steward/Commands`.","fr":"Permet aux agents de définir et de modifier des commandes personnalisées stockées sous forme de fichiers markdown, en utilisant des définitions de commandes basées sur YAML, ce qui permet des interactions flexibles et sur mesure avec le système Steward via le dossier `Steward/Commands`.","de":"Ermöglicht es den Agents, benutzerdefinierte Befehle zu definieren und zu bearbeiten, die als markdown-Dateien gespeichert sind, unter Verwendung von YAML-basierten Befehlsdefinitionen, was flexible und maßgeschneiderte Interaktionen mit dem Steward-System über den Ordner `Steward/Commands` ermöglicht.","pt":"Habilita os agentes a definirem e editarem comandos personalizados armazenados como arquivos markdown, utilizando definições de comandos baseadas em YAML, permitindo interações flexíveis e personalizadas com o sistema Steward por meio da pasta `Steward/Commands`.","ru":"Наделяет агентов возможностью определять и редактировать пользовательские команды, хранящиеся в виде файлов markdown, используя определения команд на основе YAML, что позволяет осуществлять гибкие и настраиваемые взаимодействия с системой Steward через папку `Steward/Commands`.","ar":"تمكين الوكيل من تعريف وتحرير أوامر مخصصة محفوظة كملفات markdown، باستخدام تعريفات أوامر قائم على YAML، وتمكن من تفاعلات مرنة ومخصصة مع نظام Steward من خلال مجلد `Steward/Commands`."},"useCases":{"en":["Defining custom commands for specific tasks","Editing existing commands to adapt to new requirements","Creating markdown files with YAML code blocks for command definitions"],"zh":["为特定任务定义自定义命令","编辑现有命令以适应新要求","创建包含YAML代码块的markdown文件以进行命令定义"],"ja":["特定タスクのカスタムコマンドを定義する","新しい要件に適応するために既存のコマンドを編集する","コマンド定義のためにYAMLコードブロックを含むMarkdownファイルを作成する"],"ko":["특정 작업에 대한 사용자 지정 명령을 정의하는 것","새로운 요구 사항에 맞추기 위해 기존 명령을 편집하는 것","명령 정의를 위해 YAML 코드 블록을 포함하는 마크다운 파일을 생성하는 것"],"es":["Definir comandos personalizados para tareas específicas","Editar comandos existentes para adaptarse a nuevos requisitos","Crear archivos markdown con bloques de código YAML para definiciones de comandos"],"fr":["Définir des commandes personnalisées pour des tâches spécifiques","Modifier des commandes existantes pour s''adapter à de nouvelles exigences","Créer des fichiers markdown avec des blocs de code YAML pour des définitions de commandes"],"de":["Benutzerdefinierte Befehle für bestimmte Aufgaben definieren","Vorhandene Befehle bearbeiten, um neuen Anforderungen gerecht zu werden","Markdown-Dateien mit YAML-Codeblöcken für Befehlsdefinitionen erstellen"],"pt":["Definir comandos personalizados para tarefas específicas","Editar comandos existentes para se adaptar a novos requisitos","Criar arquivos markdown com blocos de código YAML para definições de comandos"],"ru":["Определение пользовательских команд для конкретных задач","Редактирование существующих команд для адаптации к новым требованиям","Создание файлов markdown с блоками кода YAML для определений команд"],"ar":["تحديد أوامر مخصصة لمهام محددة","تحرير الأوامر الحالية للتكيف مع المتطلبات الجديدة","إنشاء ملفات markdown مع كتل من رمز YAML لتعريفات الأوامر"]},"limitations":{"en":["Requires access to the `Steward/Commands` folder","Commands must be defined in YAML-based markdown files"],"zh":["需要访问`Steward/Commands`文件夹","命令必须在基于YAML的markdown文件中定义"],"ja":["`Steward/Commands`フォルダへのアクセスが必要","コマンドはYAMLベースのMarkdownファイル内で定義する必要がある"],"ko":["`Steward/Commands` 폴더에 접근할 수 있어야 함","명령은 YAML 기반의 마크다운 파일 내에서 정의되어야 함"],"es":["Requiere acceso a la carpeta `Steward/Commands`","Los comandos deben definirse en archivos markdown basados en YAML"],"fr":["Nécessite un accès au dossier `Steward/Commands`","Les commandes doivent être définies dans des fichiers markdown basés sur YAML"],"de":["Benötigt Zugriff auf den Ordner `Steward/Commands`","Befehle müssen in YAML-basierten markdown-Dateien definiert werden"],"pt":["Exige acesso à pasta `Steward/Commands`","Os comandos devem ser definidos em arquivos markdown baseados em YAML"],"ru":["Требуется доступ к папке `Steward/Commands`","Команды должны быть определены в файлах markdown на основе YAML"],"ar":["يتطلب الوصول إلى مجلد `Steward/Commands`","يجب تعريف الأوامر في ملفات markdown قائم على YAML"]},"version":4},"contentHash":"f8b7768b4cf87f920e5798bde2b4e25e35bdb963d33bb2b100f82894da8d7c16","qualityScore":60}');
