INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('googlicius/obsidian-steward/user-defined-command', 'user-defined-command', 'googlicius', 'obsidian-steward', 'community', 'user-defined-command googlicius obsidian-steward community The user-defined-command skill enables developers to create and edit valid Steward user-defined commands stored as markdown files. It benefits AI agent developers by providing a flexible way to define custom commands. 用户自定义命令技能允许您创建和编辑有效的Steward用户自定义命令，使用YAML代码块和markdown内容 ユーザー定義コマンドスキルを使用して、Stewardユーザー定義コマンドを作成および編集します。YAMLコードブロックとマークダウンコンテンツを使用します 사용자 정의 명령어 스킬을 사용하여 Steward 사용자 정의 명령어를 생성하고 편집합니다. YAML 코드 블록과 markdown 내용을 사용합니다 El skill de comando definido por el usuario permite crear y editar comandos válidos de Steward con YAML y markdown. Aprende a configurar tus propios comandos personalizados. Le skill de commande définie par l''utilisateur permet de créer et d''éditer des commandes valides de Steward avec YAML et markdown. Apprenez à configurer vos propres commandes personnalisées. Der Skill für benutzerdefinierte Befehle ermöglicht die Erstellung und Bearbeitung von gültigen Steward-Befehlen mit YAML und Markdown. Erfahren Sie, wie Sie Ihre eigenen benutzerdefinierten Befehle konfigurieren können. O skill de comando personalizado do Steward permite criar e editar comandos válidos em YAML e markdown. Aprenda a configurar comandos personalizados para melhorar sua experiência de desenvolvimento Навык пользовательской команды Steward позволяет создавать и редактировать действительные команды в форматах YAML и markdown. Узнайте, как настроить пользовательские команды для улучшения вашего опыта разработки مهارة الأمر المخصص لمستخدمي Steward تمكن من إنشاء وتحرير أوامر صالحة في YAML و markdown. تعرف على كيفية إعداد أوامر مخصصة لتحسين تجربة التطوير الخاصة بك how to use user-defined-command user-defined-command setup guide YAML-based command definitions Steward user-defined commands user-defined-command alternative user-defined-command vs custom commands user-defined-command install what is user-defined-command user-defined-command for AI agents 用户自定义命令 Steward命令 YAML代码块 markdown内容 AIエージェント 命令设置指南 用户自定义命令设置 Supports YAML code blocks in markdown files Allows plain text, headings, and other markdown content Enables creation and editing of valid Steward user-defined commands Stores command definitions in the Steward/Commands folder Uses markdown files (.md) for command definitions Includes command-level fields for customization User-defined-command is a skill that allows developers to create custom YAML-based command definitions stored as markdown files in the Steward/Commands folder.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Lubu-Labs/langchain-agent-skills/langgraph-agent-patterns', 'community', 'Lubu-Labs', 'langchain-agent-skills', 'Lubu-Labs/langchain-agent-skills', 'langgraph-agent-patterns', 0, 0, 60, '2026-03-08T01:57:15.405Z', '2026-03-08T02:06:53.860Z', 'a25c90f818e5f9a6323b71e189d4ed643f43ad156c419913eddbfef8721c4567', '{"id":"Lubu-Labs/langchain-agent-skills/langgraph-agent-patterns","name":"langgraph-agent-patterns","description":{"en":"The langgraph-agent-patterns skill provides a collection of agent-optimized LangChain, LangGraph, and LangSmith skills for AI coding assistants, benefiting developers who need to implement multi-agent coordination patterns.","zh":"LangGraph Agent Patterns 是一组优化的 LangChain、LangGraph 和 LangSmith 技能，用于 AI 编码助手，提供 Supervisor 和 Router 模式","ja":"LangGraph エージェント パターンは、AI エージェントのための LangChain、LangGraph、LangSmith スキルのコレクションで、Supervisor と Router パターンを提供します","ko":"LangGraph 에이전트 패턴은 AI 에이전트를 위한 LangChain, LangGraph 및 LangSmith 스킬의 모음으로, Supervisor 및 Router 패턴을 제공합니다","es":"La colección de patrones de agentes LangGraph ofrece implementaciones y configuraciones de coordinación de agentes para aplicaciones LangGraph","fr":"La collection de modèles d''agents LangGraph propose des mises en place et des configurations de coordination d''agents pour les applications LangGraph","de":"Die Sammlung von LangGraph-Agentenmustern bietet Implementierungen und Konfigurationen von Agentenkoordinierung für LangGraph-Anwendungen","pt":"LangGraph Agent Patterns é uma coleção de habilidades otimizadas para assistentes de codificação de IA, permitindo a implementação de padrões de coordenação de multiagentes para aplicações LangGraph.","ru":"LangGraph Agent Patterns - это коллекция оптимизированных навыков для помощников кодирования ИИ, позволяющая реализовать шаблоны координации многоагентных систем для приложений LangGraph.","ar":"LangGraph Agent Patterns هو مجموعة من القدرات المُحسّنة للوكلاء الذكاء الاصطناعي، مما يسمح بتنفيذ أنماط التنسيق المتعددة للوكلاء في تطبيقات LangGraph."},"seo":{"title":{"en":"langgraph-agent-patterns: Multi-Agent Coordination Setup ...","zh":"LangGraph Agent Patterns 设置指南 - 实现多代理协调","ja":"LangGraph エージェント パターン ベストプラクティス - AIエージェントのためのマルチエージェント調整","ko":"LangGraph 에이전트 패턴 구축 가이드 - 멀티 에이전트 조정하기","es":"Guía de configuración de patrones de agentes LangGraph","fr":"Guide de mise en place des modèles d''agents LangGraph","de":"Einrichtungsleitfaden für LangGraph-Agentenmuster","pt":"Guia de Configuração de LangGraph Agent Patterns","ru":"Настройка Шаблонов LangGraph Agent: Лучшие Практики","ar":"دليل إعداد نمطز LangGraph Agent للوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to implement LangGraph agent patterns for efficient AI coding assistance. Learn to choose the right pattern and configure multi-agent coordinati...","zh":"了解 LangGraph Agent Patterns 的优点和用例，包括 Supervisor 和 Router 模式，以提高 AI 编码助手的性能","ja":"LangGraph エージェント パターンを使用して AI エージェントのパフォーマンスを向上させる - Supervisor と Router パターンのベストプラクティス","ko":"LangGraph 에이전트 패턴을 사용하여 AI 에이전트의 성능을 향상시키는 방법 - Supervisor 및 Router 패턴의 장점","es":"Aprende a implementar y configurar patrones de coordinación de agentes para aplicaciones LangGraph con esta colección de habilidades de LangChain, LangGraph ...","fr":"Découvrez comment mettre en place et configurer des modèles de coordination d''agents pour les applications LangGraph avec cette collection de compétences Lan...","de":"Erfahren Sie, wie Sie Koordinierungsmuster für LangGraph-Anwendungen mit dieser Sammlung von LangChain-, LangGraph- und LangSmith-Fähigkeiten implementieren ...","pt":"Aprenda a implementar padrões de coordenação de multiagentes para aplicações LangGraph com o LangGraph Agent Patterns","ru":"Узнайте, как реализовать шаблоны координации многоагентных систем для приложений LangGraph с помощью LangGraph Agent Patterns","ar":"تعرف على كيفية تنفيذ أنماط التنسيق المتعددة للوكلاء في تطبيقات LangGraph باستخدام LangGraph Agent Patterns"},"definition":{"en":"langgraph-agent-patterns is a set of patterns for implementing and configuring multi-agent coordination in LangGraph applications, including Supervisor, Router, and Orchestrator patterns.","zh":"LangGraph Agent Patterns 是一种用于 AI 编码助手的多代理协调技术","ja":"LangGraph エージェント パターンは、AI エージェントのためのマルチエージェント調整技術です","ko":"LangGraph 에이전트 패턴은 AI 에이전트를 위한 멀티 에이전트 조정 기술입니다","es":"Los patrones de agentes LangGraph son un conjunto de habilidades de LangChain, LangGraph y LangSmith para la coordinación de agentes en aplicaciones LangGraph","fr":"Les modèles d''agents LangGraph sont un ensemble de compétences LangChain, LangGraph et LangSmith pour la coordination d''agents dans les applications LangGraph","de":"Die LangGraph-Agentenmuster sind eine Sammlung von LangChain-, LangGraph- und LangSmith-Fähigkeiten für die Agentenkoordinierung in LangGraph-Anwendungen","pt":"LangGraph Agent Patterns é um conjunto de padrões de coordenação de multiagentes para aplicações LangGraph.","ru":"LangGraph Agent Patterns - это набор шаблонов координации многоагентных систем для приложений LangGraph.","ar":"LangGraph Agent Patterns هو مجموعة من أنماط التنسيق المتعددة للوكلاء في تطبيقات LangGraph."},"features":{"en":["Implements Supervisor pattern for complex workflows and dynamic routing","Supports Router pattern for simple categorization and independent tasks","Enables Orchestrator pattern for coordinated task execution","Allows for context-dependent routing and collaboration between agents","Provides a framework for choosing the right pattern based on coordination needs"],"zh":["支持 Supervisor 模式，适用于复杂工作流和动态路由","支持 Router 模式，适用于简单分类和独立任务","提供多代理协调能力，提高 AI 编码助手的性能","易于配置和实现","支持 LangChain、LangGraph 和 LangSmith 技能"],"ja":["Supervisor パターンをサポートし、複雑なワークフローと動的ルーティングに適しています","Router パターンをサポートし、シンプルな分類と独立したタスクに適しています","マルチエージェント調整機能を提供し、AI エージェントのパフォーマンスを向上させます","簡単に設定および実装できます","LangChain、LangGraph、LangSmith スキルをサポートします"],"ko":["Supervisor 패턴을 지원하여 복잡한 워크플ロー와 동적 라우팅에 적합","Router 패턴을 지원하여 단순한 분류와 독립적인 태스크에 적합","멀티 에이전트 조정 기능을 제공하여 AI 에이전트의 성능을 향상","쉽게 설정 및 구현할 수 있음","LangChain, LangGraph, LangSmith 스킬을 지원"],"es":["Implementación de patrones de coordinación de agentes","Configuración de flujos de trabajo complejos con el patrón Supervisor","Enrutamiento simple con el patrón Router","Compatibilidad con LangChain, LangGraph y LangSmith"],"fr":["Mise en place de modèles de coordination d''agents","Configuration de flux de travail complexes avec le modèle Supervisor","Enrutamiento simple avec le modèle Router","Compatibilité avec LangChain, LangGraph et LangSmith"],"de":["Implementierung von Agentenkoordinierungsmustern","Konfiguration von komplexen Workflows mit dem Supervisor-Muster","Einfaches Routing mit dem Router-Muster","Kompatibilität mit LangChain, LangGraph und LangSmith"],"pt":["Implementação de padrões de coordenação de multiagentes","Suporte a fluxos de trabalho complexos e dinâmicos","Opção de padrão Supervisor para colaboração de agentes","Opção de padrão Router para categorização simples e tarefas independentes"],"ru":["Реализация шаблонов координации многоагентных систем","Поддержка сложных и динамических рабочих процессов","Вариант шаблона Supervisor для сотрудничества агентов","Вариант шаблона Router для простой категоризации и независимых задач"],"ar":["تنفيذ أنماط التنسيق المتعددة للوكلاء","دعم سلاسل العمل المعقدة والديناميكية","خيار نمط Supervisor للتعاون بين الوكلاء","خيار نمط Router للتصنيف البسيط والمهام المستقلة"]},"keywords":{"en":["how to use langgraph-agent-patterns","langgraph-agent-patterns setup guide","langgraph-agent-patterns vs LangChain","multi-agent coordination patterns","LangGraph agent optimization","AI coding assistant integration","langgraph-agent-patterns install","what is langgraph-agent-patterns","langgraph-agent-patterns alternative"],"zh":["LangGraph Agent Patterns","AI 编码助手","多代理协调","Supervisor 模式","Router 模式","LangChain","LangGraph","LangSmith"],"ja":["LangGraph エージェント パターン","AI エージェント","マルチエージェント調整","Supervisor パターン","Router パターン","LangChain","LangGraph","LangSmith","AIエージェント"],"ko":["LangGraph 에이전트 패턴","AI 에이전트","멀티 에이전트 조정","Supervisor 패턴","Router 패턴","LangChain","LangGraph","LangSmith","에이전트 개발"],"es":["patrones de agentes LangGraph","coordinación de agentes","LangChain","LangGraph","LangSmith","agentes de IA","herramientas de IA","desarrollo de aplicaciones LangGraph"],"fr":["modèles d''agents LangGraph","coordination d''agents","LangChain","LangGraph","LangSmith","agents d''IA","outils d''IA","développement d''applications LangGraph"],"de":["LangGraph-Agentenmuster","Agentenkoordinierung","LangChain","LangGraph","LangSmith","KI-Agents","KI-Tools","Entwicklung von LangGraph-Anwendungen"],"pt":["LangGraph Agent Patterns","assistente de codificação de IA","padrões de coordenação de multiagentes","aplicações LangGraph","desenvolvimento de software","IA e machine learning"],"ru":["LangGraph Agent Patterns","помощник кодирования ИИ","шаблоны координации многоагентных систем","приложения LangGraph","разработка программного обеспечения","ИИ и машинное обучение"],"ar":["LangGraph Agent Patterns","مساعد الترميز الذكاء الاصطناعي","أنماط التنسيق المتعددة للوكلاء","تطبيقات LangGraph","تطوير البرمجيات","الذكاء الاصطناعي وتعلم الآلة"]}},"owner":"Lubu-Labs","repo":"langchain-agent-skills","repoPath":"Lubu-Labs/langchain-agent-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.405Z","topics":[],"category":"community","skillMd":{"name":"langgraph-agent-patterns","description":"Implement multi-agent coordination patterns (supervisor-subagent, router, orchestrator-worker, handoffs) for LangGraph applications. Use when users want to (1) implement multi-agent systems, (2) coordinate multiple specialized agents, (3) choose between coordination patterns, (4) set up supervisor-subagent workflows, (5) implement router-based agent selection, (6) create parallel orchestrator-worker patterns, (7) implement agent handoffs, (8) design state schemas for multi-agent systems, or (9) debug multi-agent coordination issues.","bodyPreview":"# LangGraph Agent Patterns\n\nImplement and configure multi-agent coordination patterns for LangGraph applications.\n\n## Pattern Selection\n\nChoose the right pattern based on your coordination needs:\n\n| Pattern | Best For | When to Use |\n|---------|----------|-------------|\n| **Supervisor** | Complex workflows, dynamic routing | Agents need to collaborate, routing is context-dependent |\n| **Router** | Simple categorization, independent tasks | One-time routing, deterministic decisions |\n| **Orchestr","body":"# LangGraph Agent Patterns\n\nImplement and configure multi-agent coordination patterns for LangGraph applications.\n\n## Pattern Selection\n\nChoose the right pattern based on your coordination needs:\n\n| Pattern | Best For | When to Use |\n|---------|----------|-------------|\n| **Supervisor** | Complex workflows, dynamic routing | Agents need to collaborate, routing is context-dependent |\n| **Router** | Simple categorization, independent tasks | One-time routing, deterministic decisions |\n| **Orchestrator-Worker** | Parallel execution, high throughput | Independent subtasks, results need aggregation |\n| **Handoffs** | Sequential workflows, context preservation | Clear sequence, each agent builds on previous |\n\n**Quick Decision:**\n- **Dynamic routing needed?** → Supervisor\n- **Tasks can run in parallel?** → Orchestrator-Worker\n- **Simple categorization?** → Router\n- **Linear sequence?** → Handoffs\n\nFor detailed comparison: See references/pattern-comparison.md\n\n## Pattern Implementation Guides\n\n### Supervisor-Subagent Pattern\n\n**Overview:** Central coordinator delegates to specialized subagents based on context.\n\n**Quick Start:**\n\n```bash\n# Generate supervisor graph boilerplate\nuv run scripts/generate_supervisor_graph.py my-team \\\n  --subagents \"researcher,writer,reviewer\"\n\n# TypeScript\nuv run scripts/generate_supervisor_graph.py my-team \\\n  --subagents \"researcher,writer,reviewer\" \\\n  --typescript\n```\n\n**Key Components:**\n1. **State with routing**: `next` field for routing decisions\n2. **Supervisor node**: Makes routing decisions based on context\n3. **Subagent nodes**: Specialized agents with distinct capabilities\n4. **Conditional edges**: Route from supervisor to subagents\n\n**Example Flow:**\n```\nUser Request → Supervisor → Researcher → Supervisor → Writer → Supervisor → FINISH\n```\n\n**For complete implementation:** See references/supervisor-subagent.md\n\n### Router Pattern\n\n**Overview:** One-time routing to specialized agents based on initial request.\n\n**Key Components:**\n1. **State with route**: Single routing decision field\n2. **Router node**: Categorizes request (keyword, LLM, or semantic)\n3. **Specialized agents**: Independent agents for each category\n4. **Conditional routing**: Route to agent, then END\n\n**Example Flow:**\n```\nUser Request → Router → Sales Agent → END\n                   ├→ Support Agent → END\n                   └→ Billing Agent → END\n```\n\n**Routing Strategies:**\n- **Keyword-based**: Fast, simple string matching\n- **LLM-based**: Semantic understanding, flexible\n- **Embedding-based**: Similarity matching\n- **Model-based**: Fine-tuned classifier\n\n**For complete implementation:** See references/router-pattern.md\n\n### Orchestrator-Worker Pattern\n\n**Overview:** Decompose task into parallel subtasks, aggregate results.\n\n**Key Components:**\n1. **State with subtasks**: Task decomposition and results accumulation\n2. **Orchestrator node**: Splits task into independent subtasks\n3. **Worker nodes**: Process subtasks in parallel\n4. **Aggregator node**: Synthesizes results\n5. **Send fan-out**: Return `Send(...)` objects from conditional edges and use a list reducer (for example `Annotated[list[dict], operator.add]`) so worker outputs accumulate\n\n**Example Flow:**\n```\nTask → Orchestrator → Worker 1 ┐\n                  → Worker 2  ├→ Aggregator → Result\n                  → Worker 3 ┘\n```\n\n**Best Practices:**\n- Ensure subtasks are independent\n- Handle worker failures gracefully\n- Limit concurrent workers for resource management\n- Use LLM for result synthesis\n\n**For complete implementation:** See references/orchestrator-worker.md\n\n### Handoffs Pattern\n\n**Overview:** Sequential agent handoffs with context preservation.\n\n**Key Components:**\n1. **State with context**: Shared context across handoffs\n2. **Agent nodes**: Each agent hands off to next\n3. **Handoff logic**: Explicit or conditional handoffs\n4. **Context management**: Preserve and pass information\n\n**Example Flow:**\n```\nRequest → Researcher → Writer → Editor → FINISH\n         (with context preservation)\n```\n\n**Handoff Strategies:**\n- **Explicit**: Agent declares next agent\n- **Conditional**: Based on completion criteria\n- **Circular**: Agents can hand back for revisions\n\n**For complete implementation:** See references/handoffs.md\n\n## Examples\n\nRunnable mini-projects (Python + JavaScript):\n\n- `assets/examples/supervisor-example/`\n- `assets/examples/router-example/`\n- `assets/examples/orchestrator-example/`\n- `assets/examples/handoff-example/`\n\n## State Design for Multi-Agent Patterns\n\nEach pattern requires specific state schema design:\n\n**Supervisor Pattern:**\n```python\nclass SupervisorState(TypedDict):\n    messages: Annotated[list[BaseMessage], add_messages]\n    next: Literal[\"agent1\", \"agent2\", \"FINISH\"]\n    current_agent: str\n```\n\n**Router Pattern:**\n```python\nclass RouterState(TypedDict):\n    messages: list[BaseMessage]\n    route: Literal[\"category1\", \"category2\"]\n```\n\n**Orchestrator-Worker:**\n```python\nimport operator\nclass OrchestratorState(TypedDict):\n    task: str\n    subtasks: list[dict]\n    results: Annotated[list[dict], operator.add]\n```\n\n**Handoffs:**\n```python\nclass HandoffState(TypedDict):\n    messages: Annotated[list[BaseMessage], add_messages]\n    next_agent: str\n    context: dict\n```\n\n**For detailed state patterns:** See references/state-management-patterns.md\n\n## Validation and Visualization\n\n### Validate Graph Structure\n\n```bash\n# Validate agent graph for issues\nuv run scripts/validate_agent_graph.py path/to/graph.py:graph\n\n# Checks for:\n# - Unreachable nodes\n# - Cycles without termination\n# - Dead ends\n# - Invalid routing\n```\n\n### Visualize Graph\n\n```bash\n# Generate Mermaid diagram\nuv run scripts/visualize_graph.py path/to/graph.py:graph --output diagram.md\n\n# View in browser or IDE with Mermaid support\n```\n\n## Common Patterns and Anti-Patterns\n\n### Best Practices\n\n**1. Clear Agent Responsibilities**\n- Define non-overlapping capabilities\n- Document each agent''s purpose\n- Avoid agent duplication\n\n**2. Loop Prevention**\n- Track iteration count in state\n- Set maximum iterations\n- Implement loop detection\n\n**3. Context Management**\n- Summarize context when it grows large\n- Only pass necessary information\n- Use structured context where possible\n\n**4. Error Handling**\n- Validate routing decisions\n- Handle invalid routes gracefully\n- Default to safe fallbacks\n\n### Anti-Patterns to Avoid\n\n**1. Over-Supervision**\n```python\n# ❌ Bad: Supervisor for simple linear flow\nUser → Supervisor → Agent1 → Supervisor → Agent2 → Supervisor\n\n# ✅ Good: Use handoffs instead\nUser → Agent1 → Agent2 → FINISH\n```\n\n**2. Complex Router Logic**\n```python\n# ❌ Bad: Complex routing rules in router\nif complex_condition_A and (condition_B or condition_C):\n    route = determine_complex_route()\n\n# ✅ Good: Use supervisor with LLM\nroute = llm.invoke(\"Analyze and route: {query}\")\n```\n\n**3. Unmanaged State Growth**\n```python\n# ❌ Bad: Accumulating all messages forever\nmessages: list[BaseMessage]  # Grows unbounded\n\n# ✅ Good: Summarize or limit\nif len(messages) > 20:\n    messages = summarize_context(messages)\n```\n\n## Debugging Multi-Agent Systems\n\n### 1. Trace Agent Flow\n\nUse LangSmith to visualize agent interactions:\n\n```python\nimport os\nos.environ[\"LANGSMITH_TRACING\"] = \"true\"\nos.environ[\"LANGSMITH_API_KEY\"] = \"<your-api-key>\"\nos.environ[\"LANGSMITH_PROJECT\"] = \"multi-agent-debug\"\n\nresult = graph.invoke(input_state)\n```\n\n### 2. Log Routing Decisions\n\nAdd logging to routing nodes:\n\n```python\ndef supervisor_node(state: SupervisorState) -> dict:\n    decision = make_routing_decision(state)\n\n    print(f\"Supervisor routing to: {decision}\")\n    print(f\"Current state: {len(state[''messages''])} messages\")\n    print(f\"Iteration: {state.get(''iteration'', 0)}\")\n\n    return {\"next\": decision}\n```\n\n### 3. Validate Graph Structure\n\n```bash\n# Detect common issues\nuv run scripts/validate_agent_graph.py my_agent/graph.py:graph\n\n# Check for:\n# - Unreachable nodes\n# - Infinite loops\n# - Dead ends\n```\n\n### 4. Visualize Flow\n\n```bash\n# Generate diagram\nuv run scripts/visualize_graph.py my_agent/graph.py:graph -o flow.md\n```\n\n## Performance Optimization\n\n### Latency Optimization\n\n**Supervisor Pattern:**\n- Use faster models for routing (gpt-4o-mini)\n- Cache routing decisions\n- Implement early termination\n\n**Router Pattern:**\n- Use keyword matching for simple cases\n- Cache routing for similar queries\n- Avoid LLM calls when possible\n\n**Orchestrator-Worker:**\n- True parallelization already optimal\n- Limit worker count to avoid rate limits\n- Stream results to aggregator\n\n**Handoffs:**\n- Minimize context size\n- Skip unnecessary handoffs\n- Use cheaper models where appropriate\n\n### Cost Optimization\n\n**Token Usage:**\n- Summarize context regularly\n- Use structured output for reliability\n- Employ cheaper models for simple tasks\n\n**LLM Calls:**\n- Cache routing decisions\n- Use deterministic logic when possible\n- Batch similar requests\n\n**Pattern Selection:**\n- Router < Handoffs < Orchestrator < Supervisor (cost)\n\n## Testing Multi-Agent Patterns\n\n### Unit Test Routing Logic\n\n```python\ndef test_supervisor_routing():\n    \"\"\"Test supervisor routes correctly.\"\"\"\n    state = {\n        \"messages\": [HumanMessage(content=\"Need research\")],\n        \"next\": \"\",\n        \"current_agent\": \"\"\n    }\n\n    result = supervisor_node(state)\n    assert result[\"next\"] == \"researcher\"\n```\n\n### Integration Testing\n\n```python\ndef test_full_workflow():\n    \"\"\"Test complete multi-agent workflow.\"\"\"\n    graph = create_supervisor_graph()\n\n    result = graph.invoke({\n        \"messages\": [HumanMessage(content=\"Write article about AI\")]\n    })\n\n    # Verify agents were called in correct order\n    assert \"researcher\" in result[\"agent_history\"]\n    assert \"writer\" in result[\"agent_history\"]\n```\n\n### Test Graph Structure\n\n```bash\n# Validate before deployment\npython3 scripts/validate_agent_graph.py graph.py:graph\n```\n\n## Migration Between Patterns\n\n### Router to Supervisor\n\nWhen routing logic becomes complex:\n\n```python\n# Before: Complex router\ndef route(query):\n    if complex_rules(query):\n        return category\n\n# After: Supervisor with LLM\ndef supervisor(state):\n    return llm_routing_decision(state)\n```\n\n### Handoffs to Supervisor\n\nWhen need dynamic routing:\n\n```python\n# Before: Fixed sequence\nAgent1 → Agent2 → Agent3\n\n# After: Dynamic routing\nSupervisor ⇄ Agent1/Agent2/Agent3\n```\n\n### Sequential to Parallel\n\nWhen tasks become independent:\n\n```python\n# Before: Sequential\nAgent1 → Agent2 → Agent3\n\n# After: Parallel\nOrchestrator → [Agent1, Agent2, Agent3] → Aggregator\n```\n\n## Common Use Cases\n\n### Customer Support System\n\n**Pattern:** Router + Supervisor\n```\nRouter → Sales Supervisor → Sales Agents\n     ↓\n     Support Supervisor → Support Agents\n```\n\n### Research & Writing Pipeline\n\n**Pattern:** Supervisor or Handoffs\n```\nSupervisor ⇄ Researcher\n         ⇄ Writer\n         ⇄ Editor\n```\n\n### Data Analysis Pipeline\n\n**Pattern:** Orchestrator-Worker\n```\nOrchestrator → Data Collectors → Aggregator\n```\n\n### Document Processing\n\n**Pattern:** Orchestrator-Worker + Supervisor\n```\nRouter → PDF Orchestrator → Workers → Aggregator\n     ↓\n     DOCX Orchestrator → Workers → Aggregator\n```\n\n## Scripts Reference\n\n### generate_supervisor_graph.py\n\nGenerate supervisor-subagent boilerplate:\n\n```bash\nuv run scripts/generate_supervisor_graph.py <name> [options]\n\nOptions:\n  --subagents AGENTS    Comma-separated list (default: researcher,writer,reviewer)\n  --output DIR          Output directory (default: current directory)\n  --typescript          Generate TypeScript instead of Python\n```\n\n### validate_agent_graph.py\n\nValidate graph structure:\n\n```bash\nuv run scripts/validate_agent_graph.py <module_path>\n\nFormat: path/to/module.py:graph_name\n\nChecks:\n  - Unreachable nodes\n  - Cycles\n  - Dead ends\n  - Invalid routing\n```\n\n### visualize_graph.py\n\nGenerate Mermaid diagrams:\n\n```bash\nuv run scripts/visualize_graph.py <module_path> [options]\n\nOptions:\n  --output FILE         Output file (default: stdout)\n  --diagram-only        Skip documentation, output diagram only\n```\n\n## Troubleshooting\n\n### \"Agents not coordinating correctly\"\n\n**Check:**\n1. State schema supports your pattern (see state-management-patterns.md)\n2. Routing logic validates correctly\n3. Context is preserved across agents\n\n### \"Infinite loops detected\"\n\n**Solutions:**\n1. Add iteration counter to state\n2. Implement max iteration limit\n3. Add loop detection logic\n4. Validate with validate_agent_graph.py\n\n### \"Poor routing decisions\"\n\n**Solutions:**\n1. Improve supervisor prompt with clear agent descriptions\n2. Use structured output for reliability\n3. Add examples to routing prompt\n4. Use better model for routing decisions\n\n### \"High latency\"\n\n**Solutions:**\n1. Consider router pattern for simple cases\n2. Use faster models for routing\n3. Implement parallel execution where possible\n4. Cache routing decisions\n\n### \"High token usage\"\n\n**Solutions:**\n1. Summarize context regularly\n2. Use cheaper models for simple tasks\n3. Implement context windowing\n4. Choose more efficient pattern\n\n## Additional Resources\n\n- **Pattern Details:**\n  - Supervisor: references/supervisor-subagent.md\n  - Router: references/router-pattern.md\n  - Orchestrator-Worker: references/orchestrator-worker.md\n  - Handoffs: references/handoffs.md\n\n- **State Management:** references/state-management-patterns.md\n- **Pattern Comparison:** references/pattern-comparison.md\n- **Working Examples:** assets/examples/\n\n- **LangGraph Documentation:**\n  - Multi-Agent Patterns: https://docs.langchain.com/oss/python/langchain/multi-agent/subagents-personal-assistant; https://docs.langchain.com/oss/python/langchain/multi-agent/handoffs-customer-support; https://docs.langchain.com/oss/python/langchain/multi-agent/router-knowledge-base\n  - Conditional Edges: https://docs.langchain.com/oss/python/langgraph/graph-api\n  - Map-Reduce: https://docs.langchain.com/oss/python/langgraph/graph-api#map-reduce-and-the-send-api\n"},"lastSynced":"2026-03-08T02:06:53.860Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing advanced LangGraph and LangChain integration for multi-agent coordination patterns","zh":"适合于像Cursor、Windsurf和Claude Code这样的AI代理，需要高级的LangGraph和LangChain集成，以实现多代理协调模式","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。これらはLangGraphとLangChainの高度な統合を必要とし、多エージェントの調整パターンを実現します","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 이러한 에이전트는 다중 에이전트 조정 패턴을 위해 LangGraph와 LangChain의 고급 통합을 필요로 합니다","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan una integración avanzada de LangGraph y LangChain para patrones de coordinación de multiagentes","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin d''une intégration avancée de LangGraph et LangChain pour des modèles de coordination multi-agents","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine erweiterte LangGraph- und LangChain-Integration für Muster der Multiagentenkoordination benötigen","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de integração avançada do LangGraph e do LangChain para padrões de coordenação multiagente","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих расширенной интеграции LangGraph и LangChain для шаблонов координации нескольких агентов","ar":"مثالي لعميل ذكاء اصطناعي مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى إدماج متقدم من LangGraph و LangChain لعملية تنسيق وكيل متعددة"},"recommendation":{"en":"Empowers agents to implement Supervisor, Router, and Orchestrator patterns for complex workflows and dynamic routing using LangGraph and LangChain, enabling seamless multi-agent collaboration and context-dependent decision making","zh":"赋予代理实现监督器、路由器和编排器模式的能力，用于复杂的工作流程和动态路由，利用LangGraph和LangChain，实现无缝的多代理协作和上下文依赖的决策","ja":"エージェントに、LangGraphとLangChainを利用して、複雑なワークフローと動的ルーティングのためのサーパバイザー、ルーター、オーケストレーター パターンを実装する能力を与え、シームレスな多エージェントのコラボレーションとコンテキスト依存の意思決定を実現します","ko":"에이전트가 LangGraph와 LangChain을 사용하여 복잡한 워크플로 및 동적 라우팅을 위한 Supervisor, Router, Orchestrator 패턴을 구현할 수 있도록 하여, 무중단의 다중 에이전트 협업 및 문맥 종속적 의사결정을 가능하게 합니다","es":"Habilita a los agentes a implementar patrones de Supervisor, Router y Orchestrator para flujos de trabajo complejos y enrutamiento dinámico utilizando LangGraph y LangChain, lo que permite una colaboración sin problemas entre multiagentes y una toma de decisiones dependiente del contexto","fr":"Permet aux agents de mettre en œuvre des modèles de Supervisor, Router et Orchestrator pour des flux de travail complexes et un routage dynamique en utilisant LangGraph et LangChain, ce qui permet une collaboration multi-agents sans rupture et une prise de décision dépendante du contexte","de":"Ermöglicht es Agents, Muster von Supervisor, Router und Orchestrator für komplexe Workflows und dynamisches Routing mit LangGraph und LangChain zu implementieren, was eine nahtlose Zusammenarbeit zwischen Multiagenten und kontextabhängige Entscheidungsfindung ermöglicht","pt":"Habilita os agentes a implementar padrões de Supervisor, Router e Orchestrator para fluxos de trabalho complexos e roteamento dinâmico usando LangGraph e LangChain, permitindo uma colaboração multiagente sem interrupções e tomada de decisões dependente de contexto","ru":"Позволяет агентам реализовывать шаблоны Supervisor, Router и Orchestrator для сложных рабочих процессов и динамического маршрутизации с использованием LangGraph и LangChain, обеспечивая беспрепятственную сотрудничество нескольких агентов и контекстно-зависимое принятие решений","ar":"تمكين الوكلاء من تنفيذ أنماط المشرف و الوسيط و أوركسترا لتدفقات العمل المعقدة والتوجيه الديناميكي باستخدام LangGraph و LangChain، وتمكين التعاون المتوازي للوكيل وتحديد قرارات متعلقة بالسياق"},"useCases":{"en":["Implementing Supervisor patterns for complex workflows with dynamic routing","Configuring Router patterns for simple categorization and independent tasks","Orchestrating multi-agent coordination for context-dependent decision making"],"zh":["实现复杂工作流程的监督器模式，具有动态路由","配置路由器模式，用于简单分类和独立任务","编排多代理协调，用于上下文依赖的决策"],"ja":["複雑なワークフローのためのサーパバイザー パターンの実装、動的ルーティングを伴う","シンプルな分類と独立したタスクのためのルーター パターンの構成","コンテキスト依存の意思決定のための多エージェントの調整"],"ko":["복잡한 워크플로를 위한 Supervisor 패턴 구현, 동적 라우팅을 포함","단순 분류 및 독립 작업을 위한 Router 패턴 구성","문맥 종속적 의사결정을 위한 다중 에이전트 조정"],"es":["Implementar patrones de Supervisor para flujos de trabajo complejos con enrutamiento dinámico","Configurar patrones de Router para categorización simple y tareas independientes","Orquestar la coordinación de multiagentes para la toma de decisiones dependiente del contexto"],"fr":["Mettre en œuvre des modèles de Supervisor pour des flux de travail complexes avec un routage dynamique","Configurer des modèles de Router pour une catégorisation simple et des tâches indépendantes","Orchestrer la coordination multi-agents pour la prise de décision dépendante du contexte"],"de":["Implementieren von Supervisor-Mustern für komplexe Workflows mit dynamischem Routing","Konfigurieren von Router-Mustern für einfache Kategorisierung und unabhängige Aufgaben","Orchestrieren der Multiagentenkoordination für kontextabhängige Entscheidungsfindung"],"pt":["Implementação de padrões de Supervisor para fluxos de trabalho complexos com roteamento dinâmico","Configuração de padrões de Router para categorização simples e tarefas independentes","Orquestração de coordenação multiagente para tomada de decisões dependente de contexto"],"ru":["Реализация шаблонов Supervisor для сложных рабочих процессов с динамической маршрутизацией","Настройка шаблонов Router для простой категоризации и независимых задач","Оркестровка координации нескольких агентов для контекстно-зависимого принятия решений"],"ar":["تنفيذ أنماط المشرف لتدفقات العمل المعقدة مع التوجيه الديناميكي","تكوين أنماط الوسيط للتصنيف البسيط والمهام المستقلة","أوركسترا تنسيق وكيل متعددة للأخذ القرارات المتعلقة بالسياق"]},"limitations":{"en":["Requires LangGraph and LangChain integration","Limited to LangGraph applications","Dependent on agent''s ability to collaborate and make context-dependent decisions"],"zh":["需要LangGraph和LangChain集成","仅限于LangGraph应用","依赖于代理的协作和上下文依赖的决策能力"],"ja":["LangGraphとLangChainの統合が必要","LangGraphアプリケーションに限定される","エージェントのコラボレーションとコンテキスト依存の意思決定能力に依存する"],"ko":["LangGraph와 LangChain의 통합이 필요","LangGraph 애플리케이션에 한정됨","에이전트의 협업 및 문맥 종속적 의사결정 능력에 의존"],"es":["Requiere integración de LangGraph y LangChain","Limitado a aplicaciones de LangGraph","Dependiente de la capacidad del agente para colaborar y tomar decisiones dependientes del contexto"],"fr":["Nécessite une intégration de LangGraph et LangChain","Limité aux applications LangGraph","Dépend de la capacité de l''agent à collaborer et à prendre des décisions dépendantes du contexte"],"de":["Erfordert LangGraph- und LangChain-Integration","Begrenzt auf LangGraph-Anwendungen","Abhängig von der Fähigkeit des Agents, zusammenzuarbeiten und kontextabhängige Entscheidungen zu treffen"],"pt":["Exige integração do LangGraph e do LangChain","Limitado a aplicações do LangGraph","Dependente da capacidade do agente de colaborar e tomar decisões dependente de contexto"],"ru":["Требует интеграции LangGraph и LangChain","Ограничен приложениями LangGraph","Зависит от способности агента сотрудничать и принимать контекстно-зависимые решения"],"ar":["يتطلب إدماج LangGraph و LangChain","محدود بتطبيقات LangGraph","يتعلق بقدرة الوكيل على التعاون والأخذ القرارات المتعلقة بالسياق"]},"version":4},"contentHash":"a25c90f818e5f9a6323b71e189d4ed643f43ad156c419913eddbfef8721c4567","qualityScore":60}');
