INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Lubu-Labs/langchain-agent-skills/langgraph-agent-patterns', 'langgraph-agent-patterns', 'Lubu-Labs', 'langchain-agent-skills', 'community', 'langgraph-agent-patterns Lubu-Labs langchain-agent-skills community The langgraph-agent-patterns skill provides a collection of agent-optimized LangChain, LangGraph, and LangSmith skills for AI coding assistants, benefiting developers who need to implement multi-agent coordination patterns. LangGraph Agent Patterns 是一组优化的 LangChain、LangGraph 和 LangSmith 技能，用于 AI 编码助手，提供 Supervisor 和 Router 模式 LangGraph エージェント パターンは、AI エージェントのための LangChain、LangGraph、LangSmith スキルのコレクションで、Supervisor と Router パターンを提供します LangGraph 에이전트 패턴은 AI 에이전트를 위한 LangChain, LangGraph 및 LangSmith 스킬의 모음으로, Supervisor 및 Router 패턴을 제공합니다 La colección de patrones de agentes LangGraph ofrece implementaciones y configuraciones de coordinación de agentes para aplicaciones LangGraph La collection de modèles d''agents LangGraph propose des mises en place et des configurations de coordination d''agents pour les applications LangGraph Die Sammlung von LangGraph-Agentenmustern bietet Implementierungen und Konfigurationen von Agentenkoordinierung für LangGraph-Anwendungen LangGraph Agent Patterns é uma coleção de habilidades otimizadas para assistentes de codificação de IA, permitindo a implementação de padrões de coordenação de multiagentes para aplicações LangGraph. LangGraph Agent Patterns - это коллекция оптимизированных навыков для помощников кодирования ИИ, позволяющая реализовать шаблоны координации многоагентных систем для приложений LangGraph. LangGraph Agent Patterns هو مجموعة من القدرات المُحسّنة للوكلاء الذكاء الاصطناعي، مما يسمح بتنفيذ أنماط التنسيق المتعددة للوكلاء في تطبيقات LangGraph. how to use langgraph-agent-patterns langgraph-agent-patterns setup guide langgraph-agent-patterns vs LangChain multi-agent coordination patterns LangGraph agent optimization AI coding assistant integration langgraph-agent-patterns install what is langgraph-agent-patterns langgraph-agent-patterns alternative LangGraph Agent Patterns AI 编码助手 多代理协调 Supervisor 模式 Router 模式 LangChain LangGraph LangSmith Implements Supervisor pattern for complex workflows and dynamic routing Supports Router pattern for simple categorization and independent tasks Enables Orchestrator pattern for coordinated task execution Allows for context-dependent routing and collaboration between agents Provides a framework for choosing the right pattern based on coordination needs langgraph-agent-patterns is a set of patterns for implementing and configuring multi-agent coordination in LangGraph applications, including Supervisor, Router, and Orchestrator patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ZhangHanDong/cowork-skills/memory-skills', 'community', 'ZhangHanDong', 'cowork-skills', 'ZhangHanDong/cowork-skills', 'memory-skills', 0, 0, 60, '2026-03-08T01:57:15.405Z', '2026-03-08T02:06:54.180Z', 'fb8c79b10d6453bd8cf32a62fcce1418a0cd4ed15d8fa63785a6f02cfb03ba31', '{"id":"ZhangHanDong/cowork-skills/memory-skills","name":"memory-skills","description":{"en":"The memory-skills provide a complete memory system with four memory types for AI agents, utilizing the CoALA framework for efficient language processing. This skill benefits developers of cognitive architectures for language agents.","zh":"基于CoALA框架的记忆技能实现了语言代理的认知架构，包括四种记忆类型。该技能提供了一个完整的记忆系统，用于提高AIエージェント的性能","ja":"CoALAベースのメモリースキルは、言語エージェントの認知アーキテクチャを実現し、4種類のメモリタイプを提供します。このスキルは、AIエージェントのパフォーマンスを向上させるための完全なメモリーシステムを提供します","ko":"CoALA 기반 메모리 스킬은 언어 에이전트의 인지 아키텍처를 구현하고 4가지 유형의 메모리를 제공합니다. 이 스킬은 AI 에이전트의 성능을 향상시키는 완전한 메모리 시스템을 제공합니다","es":"El sistema de memoria se basa en el marco CoALA y ofrece cuatro tipos de memoria para Agentes de IA. La arquitectura de memoria utiliza un enfoque de sistema de archivos","fr":"Le système de mémoire repose sur le cadre CoALA et propose quatre types de mémoire pour les Agents de l''IA. L''architecture de mémoire utilise une approche de système de fichiers","de":"Das Gedächtnissystem basiert auf dem CoALA-Framework und bietet vier Gedächtnistypen für KI-Agenten. Die Gedächtnisarchitektur verwendet einen Dateisystemansatz","pt":"As habilidades de memória são baseadas no framework CoALA e implementam um sistema de memória completo com quatro tipos de memória. A arquitetura de memória é projetada para linguagem","ru":"Навыки памяти основаны на фреймворке CoALA и реализуют полную систему памяти с четырьмя типами памяти. Архитектура памяти предназначена для языка","ar":"مهارات الذاكرة تستند إلى إطار العمل CoALA وتنفذ نظام ذاكرة كامل مع أربعة أنواع من الذاكرة. هندسة الذاكرة مصممة للغة"},"seo":{"title":{"en":"memory-skills: CoALA-based Memory System Setup Guide | AI...","zh":"基于CoALA框架的记忆技能设置指南","ja":"CoALAベースのメモリースキルセットアップガイド","ko":"CoALA 기반 메모리 스킬 설정 가이드","es":"Guía de configuración de habilidades de memoria para Agen...","fr":"Guide de mise en place des compétences de mémoire pour le...","de":"Einrichtungsleitfaden für Gedächtnisfähigkeiten in KI-Age...","pt":"Guia de Configuração de Habilidades de Memória para Agent...","ru":"Настройка навыков памяти для ИИ Агентов: Руководство","ar":"دليل إعداد مهارات الذاكرة للوكلاء الذكيين"},"description":{"en":"Unlock efficient memory management for your AI agents with memory-skills, featuring a cognitive architecture based on CoALA framework - learn how to implemen...","zh":"了解基于CoALA框架的记忆技能，实现语言代理的认知架构，提高AIエージェント的性能","ja":"CoALAベースのメモリースキルを使用して、AIエージェントの認知アーキテクチャを実現し、パフォーマンスを向上させる","ko":"CoALA 기반 메모리 스킬을 사용하여 언어 에이전트의 인지 아키텍처를 구현하고 성능을 향상시키는 방법","es":"Aprende a implementar un sistema de memoria completo con cuatro tipos de memoria en tus Agentes de IA con habilidades de memoria","fr":"Découvrez comment mettre en œuvre un système de mémoire complet avec quatre types de mémoire pour vos Agents de l''IA avec des compétences de mémoire","de":"Erfahren Sie, wie Sie ein vollständiges Gedächtnissystem mit vier Gedächtnistypen in Ihren KI-Agenten mit Gedächtnisfähigkeiten implementieren","pt":"Aprenda a configurar habilidades de memória para agentes de IA com base no framework CoALA. Desbloqueie o poder da arquitetura cognitiva para linguagem","ru":"Узнайте, как настроить навыки памяти для ИИ Агентов на основе фреймворка CoALA. Расблокируйте мощь когнитивной архитектуры для языка","ar":"تعلم كيفية إعداد مهارات الذاكرة للوكلاء الذكيين باستخدام إطار العمل CoALA. افتح قوة الهندسة المعرفية للغة"},"definition":{"en":"memory-skills is a cognitive architecture for language agents that implements a complete memory system based on the CoALA framework, enabling efficient memory management.","zh":"记忆技能是基于CoALA框架的语言代理认知架构，用于实现AIエージェント的记忆功能","ja":"メモリースキルは、CoALAベースの言語エージェントの認知アーキテクチャであり、AIエージェントのメモリ機能を実現する","ko":"메모리 스킬은 CoALA 기반 언어 에이전트의 인지 아키텍처로서 AI 에이전트의 메모리 기능을 구현하는 것입니다","es":"Habilidad de memoria para Agentes de IA que implementa un sistema de memoria completo con cuatro tipos de memoria","fr":"Compétence de mémoire pour les Agents de l''IA qui met en œuvre un système de mémoire complet avec quatre types de mémoire","de":"Gedächtnisfähigkeit für KI-Agenten, die ein vollständiges Gedächtnissystem mit vier Gedächtnistypen implementiert","pt":"Habilidades de memória são capacidades de armazenamento e recuperação de informações em agentes de IA, baseadas na arquitetura cognitiva CoALA","ru":"Навыки памяти - это способности хранения и извлечения информации в ИИ Агентах, основанные на когнитивной архитектуре CoALA","ar":"مهارات الذاكرة هي قدرات تخزين واسترجاع المعلومات في الوكلاء الذكيين، تستند إلى الهندسة المعرفية CoALA"},"features":{"en":["Implements a complete memory system with four memory types","Utilizes the CoALA framework for cognitive architecture","Features a working memory as a short-term, central hub","Supports memory architecture based on filesystem","Integrates with language agents for efficient processing","Based on the research paper https://arxiv.org/abs/2309.02427"],"zh":["基于CoALA框架的认知架构","四种记忆类型：工作记忆、短期记忆、中央枢纽","完整的记忆系统","提高AIエージェント的性能","支持语言代理的开发"],"ja":["CoALAベースの認知アーキテクチャ","4種類のメモリタイプ：ワーキングメモリー、短期メモリー、中央ハブ","完全なメモリーシステム","AIエージェントのパフォーマンスの向上","言語エージェントの開発をサポート"],"ko":["CoALA 기반 인지 아키텍처","4가지 유형의 메모리：작업 메모리, 단기 메모리, 중앙 허브","완전한 메모리 시스템","AI 에이전트의 성능 향상","언어 에이전트의 개발 지원"],"es":["Sistema de memoria basado en el marco CoALA","Cuatro tipos de memoria para Agentes de IA","Arquitectura de memoria que utiliza un enfoque de sistema de archivos","Implementación de un sistema de memoria completo","Compatibilidad con la arquitectura cognitiva para Agentes de lenguaje","Soporte para la gestión de la memoria a corto plazo"],"fr":["Système de mémoire basé sur le cadre CoALA","Quatre types de mémoire pour les Agents de l''IA","Architecture de mémoire qui utilise une approche de système de fichiers","Mise en œuvre d''un système de mémoire complet","Compatibilité avec l''architecture cognitive pour les Agents de langage","Prise en charge de la gestion de la mémoire à court terme"],"de":["Gedächtnissystem basierend auf dem CoALA-Framework","Vier Gedächtnistypen für KI-Agenten","Gedächtnisarchitektur, die einen Dateisystemansatz verwendet","Implementierung eines vollständigen Gedächtnissystems","Kompatibilität mit der kognitiven Architektur für Sprachagenten","Unterstützung für die Verwaltung von Kurzzeitgedächtnis"],"pt":["Arquitetura de memória baseada no framework CoALA","Quatro tipos de memória: memória de trabalho, memória a longo prazo, etc.","Sistema de memória completo para agentes de IA","Desenvolvida para linguagem natural","Integração com outras habilidades de IA","Flexibilidade e escalabilidade"],"ru":["Архитектура памяти на основе фреймворка CoALA","Четыре типа памяти: рабочая память, долгосрочная память и т.д.","Полная система памяти для ИИ Агентов","Разработана для естественного языка","Интеграция с другими навыками ИИ","Гибкость и масштабируемость"],"ar":["هندسة الذاكرة تستند إلى إطار العمل CoALA","أربعة أنواع من الذاكرة: ذاكرة العمل، ذاكرة طويلة الأجل، إلخ","نظام ذاكرة كامل للوكلاء الذكيين","تم تطويرها للغة الطبيعية","التكامل مع مهارات الذكاء الاصطناعي الأخرى","المرونة والقابلية للتوسيع"]},"keywords":{"en":["how to use memory-skills","what is memory-skills","memory-skills alternative","memory-skills vs CoALA","memory-skills install","memory-skills setup guide","CoALA framework","cognitive architecture for language agents","memory management for AI agents"],"zh":["CoALA框架","记忆技能","语言代理","AIエージェント","认知架构","记忆系统","语言代理开发"],"ja":["CoALAベース","メモリースキル","言語エージェント","AIエージェント","認知アーキテクチャ","メモリーシステム","言語エージェント開発"],"ko":["CoALA 기반","메모리 스킬","언어 에이전트","AI 에이전트","인지 아키텍처","메모리 시스템","언어 에이전트 개발"],"es":["habilidades de memoria para Agentes de IA","sistema de memoria CoALA","arquitectura de memoria para Agentes de lenguaje","gestión de la memoria a corto plazo"," Agentes de IA con habilidades de memoria","desarrollo de Agentes de IA con CoALA","integración de habilidades de memoria en Agentes de IA","soluciones de memoria para Agentes de IA","tecnologías de memoria para Agentes de IA"],"fr":["compétences de mémoire pour les Agents de l''IA","système de mémoire CoALA","architecture de mémoire pour les Agents de langage","gestion de la mémoire à court terme","Agents de l''IA avec des compétences de mémoire","développement d''Agents de l''IA avec CoALA","intégration de compétences de mémoire dans les Agents de l''IA","solutions de mémoire pour les Agents de l''IA","technologies de mémoire pour les Agents de l''IA"],"de":["Gedächtnisfähigkeiten für KI-Agenten","Gedächtnissystem CoALA","Gedächtnisarchitektur für Sprachagenten","Verwaltung von Kurzzeitgedächtnis","KI-Agenten mit Gedächtnisfähigkeiten","Entwicklung von KI-Agenten mit CoALA","Integration von Gedächtnisfähigkeiten in KI-Agenten","Gedächtnislösungen für KI-Agenten","Gedächtnistechnologien für KI-Agenten"],"pt":["habilidades de memória","agentes de IA","framework CoALA","arquitetura cognitiva","linguagem natural","desenvolvimento de IA","navegação de IA","transação de IA","configuração de habilidades de memória"],"ru":["навыки памяти","ИИ Агенты","фреймворк CoALA","когнитивная архитектура","естественный язык","разработка ИИ","навигация ИИ","транзакция ИИ","настройка навыков памяти"],"ar":["مهارات الذاكرة","الوكلاء الذكيين","إطار العمل CoALA","الهندسة المعرفية","اللغة الطبيعية","تطوير الذكاء الاصطناعي","تنقل الذكاء الاصطناعي","تعامل الذكاء الاصطناعي","إعداد مهارات الذاكرة"]}},"owner":"ZhangHanDong","repo":"cowork-skills","repoPath":"ZhangHanDong/cowork-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.405Z","topics":[],"category":"community","skillMd":{"name":"memory-skills","description":"|","bodyPreview":"# Memory Skills (CoALA-based)\n\n> **Memory = Filesystem** - Cognitive architecture for language agents\n\nBased on the [CoALA framework](https://arxiv.org/abs/2309.02427) (Cognitive Architectures for Language Agents), this skill implements a complete memory system with four memory types.\n\n## Memory Architecture\n\n```\n                    ┌─────────────────┐\n                    │  Working Memory │  ← Short-term, central hub\n                    └────────┬────────┘\n                             │","body":"# Memory Skills (CoALA-based)\n\n> **Memory = Filesystem** - Cognitive architecture for language agents\n\nBased on the [CoALA framework](https://arxiv.org/abs/2309.02427) (Cognitive Architectures for Language Agents), this skill implements a complete memory system with four memory types.\n\n## Memory Architecture\n\n```\n                    ┌─────────────────┐\n                    │  Working Memory │  ← Short-term, central hub\n                    └────────┬────────┘\n                             │\n        ┌────────────────────┼────────────────────┐\n        ↓                    ↓                    ↓\n┌───────────────┐   ┌───────────────┐   ┌───────────────┐\n│   Episodic    │   │   Semantic    │   │  Procedural   │\n│   情景记忆     │   │   语义记忆     │   │   程序性记忆   │\n└───────────────┘   └───────────────┘   └───────────────┘\n        ↑                                        ↑\n    Long-term ─────────────────────────────── Long-term\n```\n\n## Memory Types (CoALA)\n\n| Type | Purpose | Example |\n|------|---------|---------|\n| **Working** | Current session context | Active goals, intermediate reasoning |\n| **Episodic** | Past experiences | Mistakes, solutions, conversation history |\n| **Semantic** | World knowledge | Facts, learnings, reflections |\n| **Procedural** | How to do things | Preferences, workflows, prompt templates |\n\n## Directory Structure\n\n### Global Memory (`~/.claude/memory/`)\n\nCross-project shared knowledge:\n\n```\n~/.claude/memory/\n├── working/                    # Working Memory (可持久化的会话上下文)\n│   └── {name}-context.md       # 保存的会话状态 (通过 /save-context)\n│\n├── procedural/                 # Procedural Memory\n│   ├── preferences.md          # User preferences\n│   ├── workflows.md            # Common workflows\n│   └── prompts/                # Reusable prompt templates\n│       └── {name}.md\n│\n├── semantic/                   # Semantic Memory\n│   ├── learnings/              # Knowledge by topic\n│   │   ├── rust-tips.md\n│   │   ├── git-tips.md\n│   │   └── {topic}.md\n│   └── reflections/            # Insights from reflection\n│       └── {date}-{insight}.md\n│\n├── episodic/                   # Episodic Memory\n│   ├── mistakes/               # Errors and how they were fixed\n│   │   └── {date}-{error}.md\n│   ├── solutions/              # Successfully solved problems\n│   │   └── {date}-{problem}.md\n│   └── trajectories/           # Complete task execution logs\n│       └── {date}-{task}.md\n│\n└── index.json                  # Search index (auto-generated)\n```\n\n### Project Memory (`.claude/memory/`)\n\nProject-specific knowledge:\n\n```\n{project}/.claude/memory/\n├── semantic/\n│   ├── architecture.md         # Project architecture\n│   ├── conventions.md          # Coding conventions\n│   └── decisions.md            # Technical decisions (ADRs)\n│\n├── episodic/\n│   └── sessions/               # Session summaries\n│       └── {date}-{topic}.md\n│\n└── index.json                  # Project search index\n```\n\n## Commands\n\n| Command | Action | Memory Type |\n|---------|--------|-------------|\n| `/remember <content>` | Save to appropriate memory | Auto-detect |\n| `/recall <topic>` | Search and retrieve | All types |\n| `/forget <topic>` | Delete specific memory | All types |\n| `/reflect` | Generate insights from episodic → semantic | Episodic → Semantic |\n| `/summarize-session` | Save current session summary | Episodic |\n| `/save-context` | Save key context for later resume | Working → File |\n| `/load-context` | Load saved context into session | File → Working |\n\n### Working Memory Commands\n\n**`/save-context [name]`** - 保存当前会话的关键上下文\n\n触发词: \"保存上下文\", \"save context\", \"保存当前状态\"\n\n```markdown\n# 保存到: ~/.claude/memory/working/{name}-context.md 或 .claude/memory/working/\n\n## Session Context: {name}\n**Saved**: {timestamp}\n\n### Current Goals\n- {what we''re trying to accomplish}\n\n### Key Decisions Made\n- {important decisions in this session}\n\n### Important Context\n- {critical information to remember}\n\n### Next Steps\n- {what to do when resuming}\n```\n\n**`/load-context [name]`** - 加载之前保存的上下文\n\n触发词: \"加载上下文\", \"load context\", \"恢复上下文\", \"继续之前的工作\"\n\n1. Search for context files in working/ directory\n2. Display available contexts if name not specified\n3. Load and summarize the selected context\n4. Confirm: \"已加载上下文: {name}\"\n\n## Instructions for Claude\n\n### Action Space (CoALA)\n\nYou have four memory actions:\n\n1. **Retrieval** (读取): Load from long-term → working memory\n2. **Reasoning** (推理): Process in working memory\n3. **Learning** (写入): Save from working → long-term memory\n4. **Forgetting** (遗忘): Remove from long-term memory\n\n### When User Says \"Remember\" / \"记住\"\n\n1. **Detect memory type**:\n   ```\n   Content about...        → Memory Type      → Location\n   ─────────────────────────────────────────────────────\n   User preference         → Procedural       → procedural/preferences.md\n   Workflow/process        → Procedural       → procedural/workflows.md\n   Fact/knowledge          → Semantic         → semantic/learnings/{topic}.md\n   Project architecture    → Semantic         → .claude/memory/semantic/architecture.md\n   Error encountered       → Episodic         → episodic/mistakes/{date}-{error}.md\n   Problem solved          → Episodic         → episodic/solutions/{date}-{problem}.md\n   ```\n\n2. **Format content**:\n   ```markdown\n   ## {YYYY-MM-DD} - {brief title}\n\n   {content}\n\n   **Context**: {why this is important}\n   **Tags**: {relevant keywords}\n\n   ---\n   ```\n\n3. **Update index** (if index.json exists):\n   ```json\n   {\n     \"entries\": [\n       {\n         \"file\": \"semantic/learnings/rust-tips.md\",\n         \"keywords\": [\"rust\", \"ownership\", \"borrow\"],\n         \"updated\": \"2026-01-25\"\n       }\n     ]\n   }\n   ```\n\n4. **Confirm**: Tell user what was saved, where, and memory type\n\n### When User Says \"Recall\" / \"回忆\"\n\n1. **Search priority**:\n   - First: Project memory `.claude/memory/`\n   - Then: Global memory `~/.claude/memory/`\n   - Check: `index.json` for keyword matches\n   - Fallback: Scan file names and content\n\n2. **Return results with metadata**:\n   ```\n   Found 2 relevant memories:\n\n   📁 [Semantic] ~/.claude/memory/semantic/learnings/rust-tips.md\n      → \"Use Arc<Mutex<T>> for shared mutable state...\"\n\n   📁 [Episodic] .claude/memory/episodic/solutions/2026-01-20-async-bug.md\n      → \"Fixed by adding .await after spawn...\"\n   ```\n\n3. **If nothing found**:\n   ```\n   没有找到关于 \"{topic}\" 的记忆。\n   → 使用 /remember 来保存新知识\n   ```\n\n### When User Says \"Forget\" / \"忘记\"\n\n1. **Confirm before deletion**:\n   ```\n   找到以下相关记忆:\n   - ~/.claude/memory/semantic/learnings/old-api.md\n\n   确认删除吗? (y/n)\n   ```\n\n2. **Delete and update index**\n\n3. **Confirm**: \"已删除关于 {topic} 的记忆\"\n\n### When User Says \"Reflect\" / \"反思\"\n\nReflection converts episodic memories into semantic knowledge:\n\n1. **Scan recent episodic memories** (last 7 days)\n\n2. **Identify patterns**:\n   - Repeated mistakes → Learning opportunity\n   - Multiple solutions → Best practice\n   - Common trajectories → Workflow template\n\n3. **Generate reflection**:\n   ```markdown\n   ## 2026-01-25 - Reflection: Async Error Handling\n\n   **Pattern observed**: In 3 recent sessions, async errors were caused by missing .await\n\n   **Insight**: Always check for missing .await when debugging async code\n\n   **Source episodes**:\n   - episodic/mistakes/2026-01-20-async-bug.md\n   - episodic/mistakes/2026-01-22-tokio-error.md\n   - episodic/solutions/2026-01-23-fixed-spawn.md\n\n   ---\n   ```\n\n4. **Save to**: `semantic/reflections/{date}-{insight}.md`\n\n### When User Says \"Summarize Session\" / \"总结会话\"\n\n1. **Gather session context**:\n   - What was accomplished\n   - Key decisions made\n   - Problems encountered and solutions\n   - New learnings\n\n2. **Generate summary**:\n   ```markdown\n   ## 2026-01-25 - Session: Implementing Memory System\n\n   **Goals**: Improve memory-filesystem skill based on CoALA\n\n   **Accomplished**:\n   - Added working memory support\n   - Implemented forgetting mechanism\n   - Added reflection capability\n\n   **Key Decisions**:\n   - Used JSON for search index\n   - Separated global vs project memory\n\n   **Learnings**:\n   - CoALA has 4 memory types, not 3\n\n   ---\n   ```\n\n3. **Save to**:\n   - Project: `.claude/memory/episodic/sessions/{date}-{topic}.md`\n   - Or global: `~/.claude/memory/episodic/trajectories/{date}-{task}.md`\n\n### Auto-Learning (Proactive)\n\nWhen you discover valuable information during a session:\n\n1. **Detect learning opportunity**:\n   - Error fixed → Potential mistake memory\n   - New technique used → Potential learning\n   - Repeated action → Potential workflow\n\n2. **Ask user**: \"发现了一个有用的技巧，要我记住吗？\"\n\n3. **If confirmed**: Save to appropriate memory location\n\n## Quick Reference\n\n| Trigger | Memory Type | Location |\n|---------|-------------|----------|\n| \"保存上下文\" / \"save context\" | Working | `working/{name}-context.md` |\n| \"加载上下文\" / \"load context\" | Working | Read from `working/` |\n| \"记住这个偏好\" | Procedural | `procedural/preferences.md` |\n| \"记住这个流程\" | Procedural | `procedural/workflows.md` |\n| \"记住这个技巧\" | Semantic | `semantic/learnings/{topic}.md` |\n| \"记住项目架构\" | Semantic | `.claude/memory/semantic/architecture.md` |\n| \"记住这个错误\" | Episodic | `episodic/mistakes/{date}-{error}.md` |\n| \"记住这个解决方案\" | Episodic | `episodic/solutions/{date}-{problem}.md` |\n| \"回忆/你知道...\" | Retrieval | Search all locations |\n| \"忘记...\" | Forgetting | Delete from memory |\n| \"反思\" | Reflection | Episodic → Semantic |\n| \"总结会话\" | Learning | Save session to episodic |\n\n## Example Interactions\n\n### Example 1: Remember\n```\nUser: \"记住：Rust 中使用 thiserror 来定义错误类型\"\n\nClaude:\n1. Detect: Knowledge/fact → Semantic memory\n2. Location: ~/.claude/memory/semantic/learnings/rust-tips.md\n3. Append with date, tags\n4. Update index.json\n5. Response: \"✓ 已保存到语义记忆 (rust-tips.md)\"\n```\n\n### Example 2: Reflect\n```\nUser: \"/reflect\"\n\nClaude:\n1. Scan episodic/mistakes/ and episodic/solutions/ (last 7 days)\n2. Found pattern: 3 instances of borrow checker errors\n3. Generate insight: \"Common cause: trying to move value after borrow\"\n4. Save to: semantic/reflections/2026-01-25-borrow-patterns.md\n5. Response: \"✓ 生成了 1 条反思，已保存到语义记忆\"\n```\n\n### Example 3: Forget\n```\nUser: \"忘记关于旧 API 的记忆\"\n\nClaude:\n1. Search: Found semantic/learnings/old-api-v1.md\n2. Confirm: \"找到 1 条相关记忆，确认删除?\"\n3. User confirms\n4. Delete file, update index\n5. Response: \"✓ 已删除关于旧 API 的记忆\"\n```\n"},"lastSynced":"2026-03-08T02:06:54.180Z","agentAnalysis":{"suitability":{"en":"Ideal for Cognitive Architecture Agents requiring advanced memory management with the CoALA framework","zh":"适用于需要使用 CoALA 框架进行高级内存管理的认知架构代理","ja":"CoALA フレームワークを使用した高度なメモリ管理を必要とする認知アーキテクチャエージェントに適しています","ko":"CoALA 프레임워크를 사용하여 고급 메모리 관리가 필요한 인지 아키텍처 에이전트에 적합합니다","es":"Ideal para Agentes de Arquitectura Cognitiva que requieren una gestión de memoria avanzada con el framework CoALA","fr":"Idéal pour les agents d''architecture cognitive nécessitant une gestion de mémoire avancée avec le framework CoALA","de":"Ideal für kognitive Architektur-Agenten, die eine erweiterte Speicherverwaltung mit dem CoALA-Framework benötigen","pt":"Ideal para Agentes de Arquitetura Cognitiva que requerem gerenciamento de memória avançado com o framework CoALA","ru":"Идеально для агентов когнитивной архитектуры, требующих продвинутого управления памятью с помощью фреймворка CoALA","ar":"مثالي للوكلاء قوس قزح الذين يتطلبون إدارة ذاكرة متقدمة مع إطار العمل CoALA"},"recommendation":{"en":"Empowers agents to utilize a complete memory system with four memory types, leveraging the CoALA framework for efficient language processing and enabling seamless integration with cognitive architectures for language agents, supporting protocols like Working Memory for short-term data storage","zh":"赋予代理使用完整的内存系统，具有四种内存类型，利用 CoALA 框架进行高效的语言处理，并实现与语言代理的认知架构的无缝集成，支持像工作内存这样的短期数据存储协议","ja":"エージェントに、4 つのメモリタイプを備えた完全なメモリシステムを使用することを可能にし、CoALA フレームワークを使用して効率的な言語処理を行い、言語エージェントの認知アーキテクチャとのシームレスな統合を可能にし、Working Memory などの短期データストレージプロトコルをサポートします","ko":"에이전트가 4가지 종류의 메모리를 갖춘 완전한 메모리 시스템을 사용할 수 있도록 하며, CoALA 프레임워크를 사용하여 효율적인 언어 처리를 수행하며, 언어 에이전트의 인지 아키텍처와의无缝한 통합을 가능하게 하며, Working Memory 등의 短期 데이터 저장 프로토콜을 지원합니다","es":"Permite a los agentes utilizar un sistema de memoria completo con cuatro tipos de memoria, aprovechando el framework CoALA para un procesamiento de lenguaje eficiente y permitiendo una integración sin problemas con arquitecturas cognitivas para agentes de lenguaje, admitiendo protocolos como Working Memory para el almacenamiento de datos a corto plazo","fr":"Permet aux agents d''utiliser un système de mémoire complet avec quatre types de mémoire, en exploitant le framework CoALA pour un traitement de langage efficace et en permettant une intégration transparente avec les architectures cognitives pour les agents de langage, en prenant en charge des protocoles tels que Working Memory pour le stockage de données à court terme","de":"Ermöglicht es Agenten, ein vollständiges Speichersystem mit vier Speichertypen zu nutzen, indem es das CoALA-Framework für effiziente Sprachverarbeitung nutzt und eine nahtlose Integration mit kognitiven Architekturen für Sprachagenten ermöglicht, einschließlich Protokollen wie Working Memory für die kurzfristige Datenspeicherung","pt":"Habilita os agentes a utilizarem um sistema de memória completo com quatro tipos de memória, aproveitando o framework CoALA para processamento de linguagem eficiente e permitindo integração sem problemas com arquiteturas cognitivas para agentes de linguagem, suportando protocolos como Memória de Trabalho para armazenamento de dados de curto prazo","ru":"Наделяет агентов возможностью использовать полную систему памяти с четырьмя типами памяти, используя фреймворк CoALA для эффективной обработки языка и обеспечивая бесшовную интеграцию с когнитивными архитектурами для языковых агентов, поддерживая протоколы, такие как Рабочая Память для краткосрочного хранения данных","ar":"تمكين الوكلاء من استخدام نظام ذاكرة كامل مع أربعة أنواع من الذاكرة، واستخدام إطار العمل CoALA لمعالجة اللغة الفعالة وتمكين التكامل السلس مع الهياكل المعرفية للوكلاء اللغويين، ودعم البروتوكولات مثل ذاكرة العمل لتخزين البيانات قصيرة المدى"},"useCases":{"en":["Implementing Working Memory for short-term data storage","Developing Episodic Memory for event-based knowledge retrieval","Integrating Semantic Memory for conceptual knowledge representation","Utilizing Procedural Memory for skill-based learning"],"zh":["为短期数据存储实现工作内存","为基于事件的知识检索开发情节记忆","为概念知识表示集成语义记忆","为基于技能的学习利用程序记忆"],"ja":["短期データストレージのためにワーキングメモリを実装する","イベントベースの知識检索のためにエピソードメモリを開発する","概念知識表現のためにセマンティックメモリを統合する","スキルベースの学習のために手続き記憶を利用する"],"ko":["短期 데이터 저장을 위한 작업 메모리 구현","이벤트 기반 지식 검색을 위한 에피소드 메모리 개발","개념 지식 표현을 위한 의미 메모리 통합","스킬 기반 학습을 위한 절차 메모리 활용"],"es":["Implementar Working Memory para el almacenamiento de datos a corto plazo","Desarrollar Episodic Memory para la recuperación de conocimiento basada en eventos","Integrar Semantic Memory para la representación de conocimiento conceptual","Utilizar Procedural Memory para el aprendizaje basado en habilidades"],"fr":["Mettre en œuvre Working Memory pour le stockage de données à court terme","Développer Episodic Memory pour la récupération de connaissances basée sur les événements","Intégrer Semantic Memory pour la représentation de connaissances conceptuelles","Utiliser Procedural Memory pour l''apprentissage basé sur les compétences"],"de":["Implementierung von Working Memory für die kurzfristige Datenspeicherung","Entwicklung von Episodic Memory für die ereignisbasierte Wissensrückgewinnung","Integration von Semantic Memory für die konzeptuelle Wissensrepräsentation","Nutzung von Procedural Memory für das kompetenzbasierte Lernen"],"pt":["Implementando Memória de Trabalho para armazenamento de dados de curto prazo","Desenvolvendo Memória Episódica para recuperação de conhecimento baseada em eventos","Integrando Memória Semântica para representação de conhecimento conceitual","Utilizando Memória Procedural para aprendizado baseado em habilidades"],"ru":["Реализация Рабочей Памяти для краткосрочного хранения данных","Разработка Эпизодической Памяти для извлечения знаний на основе событий","Интеграция Семантической Памяти для представления концептуальных знаний","Использование Процедурной Памяти для обучения на основе навыков"],"ar":["تنفيذ ذاكرة العمل لتخزين البيانات قصيرة المدى","تطوير ذاكرة الحوادث لاسترجاع المعرفة على أساس الحوادث","دمج ذاكرة دلالية لتمثيل المعرفة المفاهيمية","استخدام ذاكرة إجرائية لتعلم على أساس المهارات"]},"limitations":{"en":["Requires CoALA framework compatibility","Limited to cognitive architectures for language agents"],"zh":["需要 CoALA 框架兼容性","仅限于语言代理的认知架构"],"ja":["CoALA フレームワークの互換性が必要","言語エージェントの認知アーキテクチャに限定されている"],"ko":["CoALA 프레임워크 호환성이 필요","언어 에이전트의 인지 아키텍처에 한정"],"es":["Requiere compatibilidad con el framework CoALA","Limitado a arquitecturas cognitivas para agentes de lenguaje"],"fr":["Nécessite la compatibilité avec le framework CoALA","Limité aux architectures cognitives pour les agents de langage"],"de":["Benötigt Kompatibilität mit dem CoALA-Framework","Begrenzt auf kognitive Architekturen für Sprachagenten"],"pt":["Requer compatibilidade com o framework CoALA","Limitado a arquiteturas cognitivas para agentes de linguagem"],"ru":["Требует совместимости с фреймворком CoALA","Ограничен когнитивными архитектурами для языковых агентов"],"ar":["يتطلب توافقًا مع إطار العمل CoALA","محدود بالهياكل المعرفية للوكلاء اللغويين"]},"version":4},"contentHash":"fb8c79b10d6453bd8cf32a62fcce1418a0cd4ed15d8fa63785a6f02cfb03ba31","qualityScore":60}');
