INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rshankras/claude-code-apple-skills/review-prompt', 'review-prompt', 'rshankras', 'claude-code-apple-skills', 'community', 'review-prompt rshankras claude-code-apple-skills community The review-prompt skill generates smart App Store review prompting with configurable trigger conditions and platform detection for developers. It benefits developers who want to prompt users for reviews at the right time. Review-Prompt 技术用于生成智能 App Store 评论提示，支持配置触发条件、平台检测和时序逻辑 Review-Prompt AIエージェントは、App Store レビューの促進を支援するスマートな方法です 리뷰 프롬프트 기능은 앱스토어 리뷰를 요청하는 방법을 제공합니다 Review Prompt es un generador de solicitudes de revisión para la App Store con condiciones de activación personalizables y lógica de temporización. Permite la detección de plataforma y el uso de StoreKit para solicitudes de revisión. Review Prompt est un générateur de demandes d''avis pour l''App Store avec des conditions de déclenchement personnalisables et une logique de temporisation. Il permet la détection de plateforme et l''utilisation de StoreKit pour les demandes d''avis. Review Prompt ist ein Generator für Bewertungsanfragen im App Store mit anpassbaren Auslösebedingungen und Zeitlogik. Er ermöglicht die Plattformerkennung und den Einsatz von StoreKit für Bewertungsanfragen. O review-prompt é um gerador de pedidos de revisão inteligentes para a App Store, com detecção de plataforma e lógica de temporização adequada ИИ Агент Review-Prompt - это генератор умных запросов отзывов для App Store с обнаружением платформы и правильной логикой тайминга Review-Prompt هو مولد طلبات مراجعة ذكية لمتجر التطبيقات، مع الكشف عن المنصة و_logic المناسبة للزمن how to use review-prompt what is review-prompt review-prompt alternative review-prompt vs StoreKit review-prompt install review-prompt setup guide App Store review prompting configurable trigger conditions platform detection for reviews Review-Prompt App Store 评论提示 触发条件 平台检测 时序逻辑 StoreKit Review SKStoreReviewController AIエージェント Generates smart App Store review prompting with configurable trigger conditions Supports platform detection for App Store reviews Includes proper timing logic for review prompts Triggers on user requests such as ''add review prompt'' or ''request reviews'' Integrates with StoreKit review and SKStoreReviewController review-prompt is a skill that generates smart App Store review prompting with configurable trigger conditions, platform detection, and proper timing logic.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lisbeth718/pseo-skills/pseo-discovery', 'community', 'lisbeth718', 'pseo-skills', 'lisbeth718/pseo-skills', 'pseo-discovery', 0, 0, 60, '2026-03-08T01:57:15.405Z', '2026-03-08T02:06:54.443Z', 'c8f5e10b74b2d7159306fe6d22e006b1a52ee8a4dccc9e1315e15aab560a3203', '{"id":"lisbeth718/pseo-skills/pseo-discovery","name":"pseo-discovery","description":{"en":"pseo-discovery analyzes codebases, business context, and markets to determine programmatic SEO page opportunities, benefiting AI coding assistants and developers. It answers what to build and if the data exists to support it.","zh":"pseo-discovery技能用于分析代码库、业务背景和市场，确定程序化SEO页面的生成，确保数据驱动和意图匹配","ja":"pseo-discoveryスキルは、コードベース、ビジネス背景、市場を分析してプログラム化SEOページの生成を決定し、データ駆動と意図の一致を保証する","ko":"pseo-discovery 기능은 코드베이스, 비즈니스 contexto, 시장 분석을 통해 프로그램형 SEO 페이지 생성을 결정하며, 데이터 주도 및 의도 일치를 보장","es":"pseo-discovery es una habilidad que analiza el código, el contexto empresarial y el mercado para determinar qué páginas de SEO programáticas se pueden y deben generar","fr":"pseo-discovery est une compétence qui analyse le code, le contexte commercial et le marché pour déterminer quelles pages de SEO programmatiques peuvent et doivent être générées","de":"pseo-discovery ist eine Fähigkeit, die Code, Geschäftskontext und Markt analysiert, um zu bestimmen, welche programmatischen SEO-Seiten generiert werden können und sollten","pt":"O pSEO Discovery é uma habilidade que analisa o código, contexto de negócios e mercado para determinar quais páginas de SEO programáticas podem e devem ser criadas, com base em dados estruturados","ru":"pSEO Discovery — это навык, который анализирует код, бизнес-контекст и рынок, чтобы определить, какие программные страницы SEO можно и должны создать, на основе структурированных данных","ar":"pSEO Discovery هو مهارة تقوم بتحليل الكود والسياق التجاري والسوق لتحديد الصفحات التي يمكن وينبغي إنشاؤها من أجل تحسين محركات البحث بشكل برمجي، بالاعتماد على البيانات المهيكلة"},"seo":{"title":{"en":"pseo-discovery: Programmatic SEO Page Builder Setup Guide...","zh":"pseo-discovery Setup Guide: AIエージェント用于程序化SEO页面生成","ja":"pseo-discovery ベストプラクティス: AIエージェントによるSEOページ生成","ko":"pseo-discovery 시작하기: AI 에이전트를 이용한 프로그램형 SEO 페이지 생성","es":"Guía de Configuración de pseo-discovery para Agentes de IA","fr":"Guide de Mise en Place de pseo-discovery pour Outils d''IA","de":"Einrichtungsleitfaden für pseo-discovery in KI-Agenten","pt":"Guia de Configuração pSEO Discovery para Ferramentas de I...","ru":"Руководство по настройке pSEO Discovery для ИИ Агентов","ar":"دليل إعداد pSEO Discovery لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock data-driven SEO with pseo-discovery. Learn how to analyze codebases and markets to determine programmatic SEO page potential. Get started now!","zh":"了解pseo-discovery技能，用于分析代码库、业务背景和市场，确定程序化SEO页面的生成","ja":"pseo-discoveryスキルを使用して、コードベース、ビジネス背景、市場を分析し、プログラム化SEOページの生成を決定する","ko":"pseo-discovery 기능을 사용하여 코드베이스, 비즈니스 contexto, 시장 분석을 통해 프로그램형 SEO 페이지 생성을 결정","es":"Aprende a configurar pseo-discovery para analizar código, contexto empresarial y mercado, y determinar qué páginas de SEO programáticas se pueden y deben gen...","fr":"Découvrez comment configurer pseo-discovery pour analyser le code, le contexte commercial et le marché, et déterminer quelles pages de SEO programmatiques pe...","de":"Erfahren Sie, wie Sie pseo-discovery einrichten, um Code, Geschäftskontext und Markt zu analysieren und zu bestimmen, welche programmatischen SEO-Seiten gene...","pt":"Descubra como o pSEO Discovery ajuda a determinar quais páginas de SEO programáticas devem ser criadas, com base em dados estruturados e contexto de negócios","ru":"Узнайте, как pSEO Discovery помогает определить, какие программные страницы SEO следует создать, на основе структурированных данных и бизнес-контекста","ar":"اكتشف كيف يساعد pSEO Discovery في تحديد الصفحات التي يجب إنشاؤها من أجل تحسين محركات البحث بشكل برمجي، بالاعتماد على البيانات المهيكلة والسياق التجاري"},"definition":{"en":"pseo-discovery is a skill that analyzes codebases, business context, and markets to identify potential programmatic SEO pages, following data-first and intent-matched principles.","zh":"pseo-discovery是AIエージェント的一种技能，用于分析代码库和业务背景以确定程序化SEO页面的生成","ja":"pseo-discoveryは、AIエージェントのスキルの一種で、コードベースとビジネス背景を分析してプログラム化SEOページの生成を決定する","ko":"pseo-discovery는 AI 에이전트의 기능 중 하나로, 코드베이스와 비즈니스 contexto를 분석하여 프로그램형 SEO 페이지 생성을 결정","es":"pseo-discovery es una habilidad de IA que determina qué páginas de SEO programáticas se pueden generar en función de datos estructurados","fr":"pseo-discovery est une compétence d''IA qui détermine quelles pages de SEO programmatiques peuvent être générées en fonction de données structurées","de":"pseo-discovery ist eine KI-Fähigkeit, die bestimmt, welche programmatischen SEO-Seiten auf der Grundlage von strukturierten Daten generiert werden können","pt":"pSEO Discovery é uma habilidade que determina quais páginas de SEO programáticas devem ser criadas com base em dados estruturados e contexto de negócios","ru":"pSEO Discovery — это навык, который определяет, какие программные страницы SEO следует создать, на основе структурированных данных и бизнес-контекста","ar":"pSEO Discovery هو مهارة تحدد الصفحات التي يجب إنشاؤها من أجل تحسين محركات البحث بشكل برمجي، بالاعتماد على البيانات المهيكلة والسياق التجاري"},"features":{"en":["Analyzes codebase and business context to determine programmatic SEO page potential","Follows data-first principle, requiring structured data to support page generation","Applies intent-matched principle to ensure every page type has a clear purpose","Runs before pseo-audit to determine what to build before assessing codebase readiness","Evaluates market data to inform programmatic SEO page generation decisions","Identifies available data sources to support programmatic SEO page building"],"zh":["数据驱动：仅提出具有结构化数据支持的页面类型","意图匹配：每个页面类型都与特定的用户意图相匹配","代码库分析：分析代码库以确定程序化SEO页面的生成","业务背景分析：分析业务背景以确定程序化SEO页面的生成","市场分析：分析市场以确定程序化SEO页面的生成"],"ja":["データ駆動：構造化データを備えたページタイプのみを提案","意図の一致：各ページタイプは特定のユーザー意図と一致","コードベース分析：コードベースを分析してプログラム化SEOページの生成を決定","ビジネス背景分析：ビジネス背景を分析してプログラム化SEOページの生成を決定","市場分析：市場を分析してプログラム化SEOページの生成を決定"],"ko":["데이터 주도: 구조화된 데이터를 갖춘 페이지 유형만을 제안","의도 일치: 각 페이지 유형은 특정 사용자 의도와 일치","코드베이스 분석: 코드베이스를 분석하여 프로그램형 SEO 페이지 생성을 결정","비즈니스 contexto 분석: 비즈니스 contexto를 분석하여 프로그램형 SEO 페이지 생성을 결정","시장 분석: 시장을 분석하여 프로그램형 SEO 페이지 생성을 결정"],"es":["Análisis de código y contexto empresarial","Determinación de páginas de SEO programáticas generables","Requisito de datos estructurados para la generación de páginas","Integración con habilidades de auditoría para garantizar la preparación del código","Capacidad para identificar oportunidades de optimización de SEO","Compatibilidad con herramientas de desarrollo como React y Python"],"fr":["Analyse de code et de contexte commercial","Détermination de pages de SEO programmatiques générables","Exigence de données structurées pour la génération de pages","Intégration avec des compétences d''audit pour garantir la préparation du code","Capacité à identifier des opportunités d''optimisation de SEO","Compatibilité avec des outils de développement tels que React et Python"],"de":["Code- und Geschäftskontext-Analyse","Bestimmung von generierbaren programmatischen SEO-Seiten","Erfordernis von strukturierten Daten für die Generierung von Seiten","Integration mit Audit-Fähigkeiten, um die Vorbereitung des Codes zu gewährleisten","Fähigkeit, Optimierungsmöglichkeiten für SEO zu identifizieren","Kompatibilität mit Entwicklungstools wie React und Python"],"pt":["Análise de código e contexto de negócios","Determinação de páginas de SEO programáticas com base em dados estruturados","Integração com pseo-audit para garantir a prontidão do código","Apoio à criação de páginas de SEO personalizadas","Utilização de dados estruturados para garantir a precisão"],"ru":["Анализ кода и бизнес-контекста","Определение программных страниц SEO на основе структурированных данных","Интеграция с pseo-audit для обеспечения готовности кода","Поддержка создания индивидуальных страниц SEO","Использование структурированных данных для обеспечения точности"],"ar":["تحليل الكود والسياق التجاري","تحديد الصفحات البرمجية لتحسين محركات البحث بالاعتماد على البيانات المهيكلة","التكامل مع pseo-audit لضمان جاهزية الكود","دعم إنشاء صفحات تحسين محركات البحث المخصصة","استخدام البيانات المهيكلة لضمان الدقة"]},"keywords":{"en":["how to use pseo-discovery","what is pseo-discovery","pseo-discovery alternative","pseo-discovery vs pseo-audit","pseo-discovery install","pseo-discovery setup guide","programmatic SEO page generation","data-driven SEO","AI coding assistant SEO"],"zh":["pseo-discovery","AIエージェント","程序化SEO页面生成","数据驱动","意图匹配","代码库分析","业务背景分析","市场分析"],"ja":["pseo-discovery","AIエージェント","プログラム化SEOページ生成","データ駆動","意図の一致","コードベース分析","ビジネス背景分析","市場分析"],"ko":["pseo-discovery","AI 에이전트","프로그램형 SEO 페이지 생성","데이터 주도","의도 일치","코드베이스 분석","비즈니스 contexto 분석","시장 분석"],"es":["pseo-discovery","agentes de IA","SEO programático","análisis de código","contexto empresarial","datos estructurados","React","Python","optimización de SEO"],"fr":["pseo-discovery","outils d''IA","SEO programmatique","analyse de code","contexte commercial","données structurées","React","Python","optimisation de SEO"],"de":["pseo-discovery","KI-Agenten","programmatischer SEO","Code-Analyse","Geschäftskontext","strukturierte Daten","React","Python","SEO-Optimierung"],"pt":["pSEO Discovery","SEO programático","dados estruturados","contexto de negócios","pseo-audit","criação de páginas de SEO","otimização de motores de busca","ferramentas de inteligência artificial"],"ru":["pSEO Discovery","Программный SEO","Структурированные данные","Бизнес-контекст","pseo-audit","Создание страниц SEO","Оптимизация поисковых систем","ИИ Агенты"],"ar":["pSEO Discovery","تحسين محركات البحث البرمجي","البيانات المهيكلة","السياق التجاري","pseo-audit","إنشاء صفحات تحسين محركات البحث","تحسين محركات البحث","أدوات الذكاء الاصطناعي"]}},"owner":"lisbeth718","repo":"pseo-skills","repoPath":"lisbeth718/pseo-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.405Z","topics":[],"category":"community","skillMd":{"name":"pseo-discovery","description":"Analyze a codebase and business context to discover programmatic SEO opportunities, identifying what page types to generate, what data assets exist, and what search intent can be matched at scale. Use when starting a new pSEO project, when the user isnt sure what to build programmatically, or when exploring what structured data exists in the codebase or business that could power scalable pages.","bodyPreview":"# pSEO Discovery\n\nAnalyze the codebase, business context, and market to determine what programmatic SEO pages can and should be built. This skill answers the question: **\"What should we generate, and do we have the data to do it?\"**\n\nThis skill runs BEFORE pseo-audit. The audit checks if the codebase is ready; this skill figures out what to build.\n\n## Core Principles\n\n1. **Data-first**: Only propose page types backed by structured data that exists or can be sourced\n2. **Intent-matched**: Every p","body":"# pSEO Discovery\n\nAnalyze the codebase, business context, and market to determine what programmatic SEO pages can and should be built. This skill answers the question: **\"What should we generate, and do we have the data to do it?\"**\n\nThis skill runs BEFORE pseo-audit. The audit checks if the codebase is ready; this skill figures out what to build.\n\n## Core Principles\n\n1. **Data-first**: Only propose page types backed by structured data that exists or can be sourced\n2. **Intent-matched**: Every proposed page type must target a real search intent with volume\n3. **Differentiated**: Each page must be able to produce genuinely unique content — not just variable swaps\n4. **Feasible**: Proposals must be realistic given the current data, codebase, and team capacity\n5. **Business-aligned**: pSEO pages should serve the business''s actual audience and goals\n\n## Discovery Procedure\n\n### 1. Explore the Codebase for Data Assets\n\nSearch the codebase for existing structured data that could power pages:\n\n**Database/ORM models:**\n- Search for schema definitions (Prisma, Drizzle, TypeORM, Mongoose, SQL migrations)\n- Identify entities with many records (products, locations, services, users, listings, articles)\n- Note which entities have rich attributes (descriptions, categories, images, metadata)\n\n**CMS content types:**\n- Check for headless CMS configs (Contentful, Sanity, Strapi, etc.)\n- Identify content types and their field schemas\n- Count records per content type\n\n**API endpoints:**\n- Map all API routes and their response shapes\n- Identify list endpoints that return collections of entities\n- Check for paginated endpoints (signals large datasets)\n\n**Static data files:**\n- Search for JSON, CSV, YAML, MDX files in `data/`, `content/`, `src/data/` directories\n- Count records and inspect field richness\n- Check for categorization or taxonomy structures\n\n**What to extract per data source:**\n- Entity name and count (e.g., \"2,500 products\", \"150 cities\", \"80 services\")\n- Available fields (especially: name, description, category, attributes, images)\n- Relationships between entities (product → category, service → location)\n- Data freshness (how often updated, is there a lastModified field)\n\n### 2. Map Business Entities to Page Types\n\nFor each data asset found, evaluate whether it can power a pSEO page type:\n\n| Question | Must answer \"yes\" |\n|----------|-------------------|\n| Are there 50+ unique records? | Minimum for pSEO to make sense |\n| Does each record have enough data for a full page? | Title, description, 3+ unique attributes |\n| Would someone search for this? | Real search intent exists |\n| Can each page be meaningfully different? | Not just variable swaps |\n| Does this serve the business? | Drives traffic the business can convert |\n\n**Common pSEO page patterns by business type:**\n\n- **E-commerce**: Product pages, category pages, brand pages, `[product] vs [product]` comparisons, `best [category] for [use-case]`\n- **SaaS**: Feature pages, integration pages, `[tool] alternative`, `[tool] vs [competitor]`, use-case pages\n- **Marketplace**: Listing pages, location pages, `[service] in [city]`, category + location combinations\n- **Content/Media**: Topic pages, tag pages, author pages, `[topic] guide`, glossary/definition pages\n- **Local business**: Service + location pages, `[service] in [neighborhood]`, FAQ pages per service\n- **Directory**: Profile pages, category pages, comparison pages, `top [category] in [location]`\n\n### 3. Identify Keyword Patterns and Search Intent\n\nFor each proposed page type, validate that search demand exists:\n\n**Keyword pattern analysis:**\n- Identify the base keyword pattern (e.g., `[service] in [city]`, `best [product] for [use-case]`)\n- Estimate volume per pattern using keyword research tools or inferred demand\n- Check for long-tail variations that indicate intent depth\n- Verify that existing top results are not exclusively high-authority domains\n\n**Intent classification per page type:**\n- **Informational**: User wants to learn (guides, definitions, how-tos)\n- **Commercial investigation**: User is comparing options (comparisons, reviews, \"best X\")\n- **Transactional**: User wants to buy/sign up (product pages, pricing, service pages)\n- **Navigational**: User wants a specific entity (brand pages, location pages)\n\nEach pSEO page type should clearly map to one intent category.\n\n### 4. Evaluate Data Sufficiency for Content Uniqueness\n\nFor each proposed page type, assess whether the data produces genuinely unique pages:\n\n**The Content Differentiation Test:**\nTake 5 random records. For each, write out what the page would contain:\n- Title\n- H1\n- Intro paragraph\n- Main content sections\n- FAQ questions\n\nIf 3+ of these elements are essentially the same text with different proper nouns, the data is insufficient. Either:\n- Enrich the data (add more attributes, descriptions, FAQs per record)\n- Combine data sources (e.g., product data + user reviews + competitor data)\n- Narrow the page type to records with richer data\n- Abandon the page type as a pSEO candidate\n\n**Minimum data requirements per page:**\n- 2+ unique text fields beyond title and description (for body content)\n- 3+ structured attributes (for data tables, stat highlights)\n- Category or taxonomy data (for hub-spoke linking)\n- Ideally: 3-5 FAQ pairs per record (for FAQ schema and content depth)\n\n### 5. Assess URL Structure and Taxonomy\n\nPropose a URL hierarchy for the pSEO pages:\n\n```\n/{category}/{slug}                     # standard\n/{location}/{service}                  # location-based\n/{product-type}/{product-slug}         # e-commerce\n/{topic}/{subtopic}                    # content-based\n```\n\nCheck:\n- Will all slugs be unique within their URL namespace?\n- Does the hierarchy create natural hub-spoke relationships?\n- Is the URL structure human-readable and keyword-inclusive?\n- How deep is the hierarchy? (Maximum 3 levels recommended)\n\n### 6. Competitive Landscape Check\n\nIdentify whether competitors are already doing pSEO for the same patterns:\n\n- Search for the target keyword patterns and see what ranks\n- Check if competitors have programmatic pages (signs: similar URL patterns, templated content, large indexed page counts)\n- Assess competitor content quality — can you do meaningfully better?\n- Look for gaps they haven''t covered (long-tail variations, underserved locations, new categories)\n\n### 7. Propose a pSEO Strategy\n\nCompile findings into a ranked list of pSEO opportunities.\n\n## Output Format\n\n```\n## pSEO Discovery Report\n\n### Data Assets Found\n| Entity | Record Count | Key Fields | Source |\n|--------|-------------|------------|--------|\n| [entity] | [count] | [fields] | [DB/CMS/API/files] |\n\n### Proposed Page Types (ranked by opportunity)\n\n#### 1. [Page Type Name]\n- **Pattern**: [URL pattern, e.g., /services/[service]-in-[city]]\n- **Record count**: [number of pages this would generate]\n- **Search intent**: [informational / commercial / transactional]\n- **Keyword pattern**: [e.g., \"[service] in [city]\"]\n- **Data source**: [where the data comes from]\n- **Content uniqueness**: [High / Medium / Low — with justification]\n- **Data gaps**: [what fields are missing or need enrichment]\n- **Feasibility**: [Ready / Needs data enrichment / Needs new data source]\n\n#### 2. [Next page type...]\n\n### Rejected Candidates\n| Entity | Reason Rejected |\n|--------|----------------|\n| [entity] | [too few records / insufficient data / no search intent / ...] |\n\n### Recommended URL Structure\n[Proposed hierarchy with examples]\n\n### Data Enrichment Needed\n[List of data fields that need to be added to unlock page types]\n\n### Next Steps\n1. [Confirm page types with stakeholder]\n2. [Enrich data where needed]\n3. [Run pseo-audit on the codebase]\n4. [Begin implementation with pseo-data]\n```\n\n## Scope Parameter\n\nIf `$ARGUMENTS` specifies a focus:\n- `all` (default): Full discovery\n- `codebase`: Only analyze existing data assets in the code (steps 1-2)\n- `business`: Focus on business entity mapping and page type proposals (steps 2-4)\n- `keywords`: Focus on keyword patterns and competitive landscape (steps 3, 6)\n\n## YMYL Risk Assessment\n\nGoogle''s September 2025 Quality Rater Guidelines expanded YMYL (Your Money or Your Life) to include civic information alongside health, finance, and legal content. pSEO in YMYL verticals carries elevated risk.\n\n**YMYL categories (as of September 2025):**\n- Health and medical information\n- Financial information (investing, taxes, loans, insurance)\n- Legal information\n- Civic information (voting, government, public trust)\n- Safety information (product safety, emergency procedures)\n- News about major events\n\n**If the proposed page types fall into ANY YMYL category:**\n\n1. **Flag the risk explicitly** in the discovery report\n2. **Elevate content quality requirements**: Every page needs cited authoritative sources, expert attribution, and review processes\n3. **Evaluate if pSEO is appropriate at all**: YMYL content often requires human expert review per page, which conflicts with the \"programmatic\" approach. Be honest about this tension.\n4. **Recommend stricter quality guard thresholds**: Higher minimum word counts, stricter uniqueness requirements, mandatory E-E-A-T fields\n5. **Consider hybrid approach**: Programmatic data structure + human-reviewed content per page\n\n**Discovery output should include a YMYL assessment:**\n```\n### YMYL Assessment\n- YMYL category: [None | Health | Finance | Legal | Civic | Safety]\n- Risk level: [Low | Medium | High]\n- Recommendation: [Standard pSEO OK | Needs elevated quality standards | Human review per page required | pSEO not recommended for this vertical]\n```\n\n## Output Artifact\n\nSave the discovery report to `.pseo/discovery-report.md` in the project root. This file is consumed by pseo-audit and pseo-orchestrate to inform subsequent phases. The file must include at minimum:\n\n- Confirmed page types with their URL patterns\n- Data source locations (file paths, API endpoints, CMS content types)\n- YMYL assessment (if applicable)\n- Data gaps that need enrichment before implementation\n\nIf running within a single Claude Code session, the report can also be kept in conversation context. The file serves as a persistent artifact for multi-session workflows.\n\n## Important Constraints\n\n- This is a research-only skill. Do NOT modify code or create files.\n- Be honest about data gaps. Don''t propose page types the data can''t support.\n- Quantity of pages is not the goal. 200 genuinely unique pages beats 5,000 thin pages.\n- If the codebase has no usable structured data, say so. The answer may be \"build the data layer first\" or \"this business isn''t a good fit for pSEO.\"\n- If a page type would produce thin or near-identical pages, flag it as rejected with a clear reason.\n\n## Relationship to Other Skills\n\n- **Runs before**: All other pseo-* skills\n- **Feeds into**: pseo-audit (what to look for), pseo-data (what models to build)\n- **Independent of**: All implementation skills — this is pure research\n"},"lastSynced":"2026-03-08T02:06:54.443Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Coding Assistants and Developer Agents needing advanced programmatic SEO page analysis and generation capabilities.","zh":"非常适合需要高级程序化SEO页面分析和生成功能的AI编码助手和开发人员代理。","ja":"高度なプログラムによるSEOページ分析および生成機能を必要とするAIコーディングアシスタントや開発エージェントに最適です。","ko":"고급 프로그래밍 방식의 SEO 페이지 분석 및 생성 기능이 필요한 AI 코딩 어시스턴트 및 개발자 에이전트에 적합합니다.","es":"Perfecto para asistentes de codificación de IA y agentes de desarrollador que necesitan capacidades avanzadas de análisis y generación de páginas de SEO programáticas.","fr":"Parfait pour les assistants de codage IA et les agents de développeur ayant besoin de capacités de analyse et de génération de pages de SEO programmatiques avancées.","de":"Perfekt für AI-Coding-Assistenten und Developer-Agents, die erweiterte programmatische SEO-Seitenanalyse- und -generierungsfähigkeiten benötigen.","pt":"Perfeito para Assistente de Codificação de IA e Agentes de Desenvolvedor que necessitam de capacidades avançadas de análise e geração de páginas de SEO programáticas.","ru":"Идеально подходит для помощников кодирования ИИ и агентов разработчиков, требующих продвинутых возможностей программной анализа и генерации страниц SEO.","ar":"مثالي لمساعدي ترميز الذكاء الاصطناعي ووكلاء المطورين الذين يحتاجون إلى قدرات متقدمة لتحليل وإنشاء صفحات SEO برمجية."},"recommendation":{"en":"Empowers agents to analyze codebases, business context, and markets to determine programmatic SEO page opportunities, using data-first and intent-matched principles, and leveraging structured data to inform development decisions.","zh":"赋予代理分析代码库、业务背景和市场，以确定程序化SEO页面机会，使用数据优先和意图匹配原则，并利用结构化数据来指导开发决策。","ja":"エージェントがコードベース、ビジネス背景、市場を分析してプログラムによるSEOページの機会を判断することを可能にし、データ優先と意図の一致の原則を使用し、構造化されたデータを利用して開発の決定を下します。","ko":"에이전트가 코드베이스, 비즈니스 컨텍스트, 시장 분석을 통해 프로그래밍 방식의 SEO 페이지 기회를 판단할 수 있도록 하며, 데이터 우선 및 의도 일치 원칙을 사용하며, 구조화된 데이터를 활용하여 개발 결정에 대한 정보를 제공합니다.","es":"Habilita a los agentes a analizar bases de código, contexto empresarial y mercados para determinar oportunidades de páginas de SEO programáticas, utilizando principios de datos primero y coincidencia de intención, y aprovechando datos estructurados para informar decisiones de desarrollo.","fr":"Permet aux agents d''analyser les bases de code, le contexte commercial et les marchés pour déterminer les opportunités de pages de SEO programmatiques, en utilisant des principes de données premières et d''adéquation d''intention, et en exploitant les données structurées pour éclairer les décisions de développement.","de":"Ermächtigt Agenten, Codebasen, Geschäftskontext und Märkte zu analysieren, um Möglichkeiten für programmatische SEO-Seiten zu bestimmen, unter Verwendung von datengetriebenen und intentionsübereinstimmenden Prinzipien und unter Ausnutzung strukturierter Daten, um Entwicklungsentscheidungen zu treffen.","pt":"Habilita os agentes a analisar repositórios de código, contexto empresarial e mercados para determinar oportunidades de páginas de SEO programáticas, utilizando princípios de dados em primeiro lugar e correspondência de intenções, e aproveitando dados estruturados para informar decisões de desenvolvimento.","ru":"Наделяет агентов возможностью анализировать базы кода, бизнес-контекст и рынки для определения возможностей программных страниц SEO, используя принципы данных в первую очередь и соответствия намерений, а также используя структурированные данные для информирования решений по разработке.","ar":"تمكّن الوكلاء من تحليل مصادر الشفرة والسياق التجاري والأسواق لتحديد فرص صفحات SEO البرمجية، باستخدام مبادئ البيانات الأولى والتطابق في النوايا، واستخدام البيانات المنظمة لإبلاغ قرارات التطوير."},"useCases":{"en":["Automating programmatic SEO page discovery and planning","Generating data-driven recommendations for page development","Evaluating market and business context for optimal SEO page creation"],"zh":["自动化程序化SEO页面发现和规划","生成数据驱动的页面开发建议","评估市场和业务背景以实现最优的SEO页面创建"],"ja":["プログラムによるSEOページの発見と計画の自動化","データ駆動型のページ開発の推奨事項の生成","市場とビジネス背景の評価による最適なSEOページ作成"],"ko":["프로그래밍 방식의 SEO 페이지 발견 및 계획 자동화","데이터驱동형 페이지 개발 제안 생성","시장 및 비즈니스 컨텍스트 평가를 통한 최적의 SEO 페이지 생성"],"es":["Automatización de la detección y planificación de páginas de SEO programáticas","Generación de recomendaciones impulsadas por datos para el desarrollo de páginas","Evaluación del contexto de mercado y empresarial para la creación óptima de páginas de SEO"],"fr":["Automatisation de la découverte et de la planification de pages de SEO programmatiques","Génération de recommandations basées sur les données pour le développement de pages","Évaluation du contexte commercial et de marché pour la création optimale de pages de SEO"],"de":["Automatisierung der Entdeckung und Planung von programmatischen SEO-Seiten","Generierung von datengetriebenen Empfehlungen für die Seitenentwicklung","Bewertung des Markt- und Geschäftskontexts für die optimale Erstellung von SEO-Seiten"],"pt":["Automatizar a descoberta e planejamento de páginas de SEO programáticas","Gerar recomendações impulsionadas por dados para desenvolvimento de páginas","Avaliar o contexto de mercado e empresarial para criação ótima de páginas de SEO"],"ru":["Автоматизировать обнаружение и планирование программных страниц SEO","Генерировать рекомендации, основанные на данных, для разработки страниц","Оценивать рыночный и бизнес-контекст для оптимального создания страниц SEO"],"ar":["توفير اكتشاف وتخطيط صفحات SEO البرمجية تلقائيًا","توليد توصيات مدفوعة بالبيانات لتنمية الصفحات","تقييم السياق السوقي والتجاري لإنشاء صفحات SEO أمثل"]},"limitations":{"en":["Requires access to codebase and business context data","Dependent on availability of structured data for analysis"],"zh":["需要访问代码库和业务背景数据","依赖于结构化数据的可用性进行分析"],"ja":["コードベースとビジネス背景データへのアクセスが必要","分析のために構造化されたデータの可用性に依存する"],"ko":["코드베이스 및 비즈니스 컨텍스트 데이터에 대한 액세스가 필요","분석을 위해 구조화된 데이터의 가용성에 종속"],"es":["Requiere acceso a datos de base de código y contexto empresarial","Dependiente de la disponibilidad de datos estructurados para el análisis"],"fr":["Nécessite un accès aux données de base de code et de contexte commercial","Dépend de la disponibilité de données structurées pour l''analyse"],"de":["Benötigt Zugriff auf Codebase- und Geschäftskontextdaten","Abhängig von der Verfügbarkeit strukturierter Daten für die Analyse"],"pt":["Requer acesso aos dados do repositório de código e contexto empresarial","Depende da disponibilidade de dados estruturados para análise"],"ru":["Требует доступа к данным базы кода и бизнес-контекста","Зависит от наличия структурированных данных для анализа"],"ar":["يتطلب الوصول إلى بيانات مصدر الشفرة والسياق التجاري","يعتمد على توافر البيانات المنظمة للتحليل"]},"version":4},"contentHash":"c8f5e10b74b2d7159306fe6d22e006b1a52ee8a4dccc9e1315e15aab560a3203","qualityScore":60}');
