INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lisbeth718/pseo-skills/pseo-discovery', 'pseo-discovery', 'lisbeth718', 'pseo-skills', 'community', 'pseo-discovery lisbeth718 pseo-skills community pseo-discovery analyzes codebases, business context, and markets to determine programmatic SEO page opportunities, benefiting AI coding assistants and developers. It answers what to build and if the data exists to support it. pseo-discovery技能用于分析代码库、业务背景和市场，确定程序化SEO页面的生成，确保数据驱动和意图匹配 pseo-discoveryスキルは、コードベース、ビジネス背景、市場を分析してプログラム化SEOページの生成を決定し、データ駆動と意図の一致を保証する pseo-discovery 기능은 코드베이스, 비즈니스 contexto, 시장 분석을 통해 프로그램형 SEO 페이지 생성을 결정하며, 데이터 주도 및 의도 일치를 보장 pseo-discovery es una habilidad que analiza el código, el contexto empresarial y el mercado para determinar qué páginas de SEO programáticas se pueden y deben generar pseo-discovery est une compétence qui analyse le code, le contexte commercial et le marché pour déterminer quelles pages de SEO programmatiques peuvent et doivent être générées pseo-discovery ist eine Fähigkeit, die Code, Geschäftskontext und Markt analysiert, um zu bestimmen, welche programmatischen SEO-Seiten generiert werden können und sollten O pSEO Discovery é uma habilidade que analisa o código, contexto de negócios e mercado para determinar quais páginas de SEO programáticas podem e devem ser criadas, com base em dados estruturados pSEO Discovery — это навык, который анализирует код, бизнес-контекст и рынок, чтобы определить, какие программные страницы SEO можно и должны создать, на основе структурированных данных pSEO Discovery هو مهارة تقوم بتحليل الكود والسياق التجاري والسوق لتحديد الصفحات التي يمكن وينبغي إنشاؤها من أجل تحسين محركات البحث بشكل برمجي، بالاعتماد على البيانات المهيكلة how to use pseo-discovery what is pseo-discovery pseo-discovery alternative pseo-discovery vs pseo-audit pseo-discovery install pseo-discovery setup guide programmatic SEO page generation data-driven SEO AI coding assistant SEO pseo-discovery AIエージェント 程序化SEO页面生成 数据驱动 意图匹配 代码库分析 业务背景分析 市场分析 Analyzes codebase and business context to determine programmatic SEO page potential Follows data-first principle, requiring structured data to support page generation Applies intent-matched principle to ensure every page type has a clear purpose Runs before pseo-audit to determine what to build before assessing codebase readiness Evaluates market data to inform programmatic SEO page generation decisions Identifies available data sources to support programmatic SEO page building pseo-discovery is a skill that analyzes codebases, business context, and markets to identify potential programmatic SEO pages, following data-first and intent-matched principles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('9tykeshav/mern-ninja-cc/code-reviewer', 'community', '9tykeshav', 'mern-ninja-cc', '9tykeshav/mern-ninja-cc', 'code-reviewer', 0, 0, 60, '2026-03-08T01:57:15.406Z', '2026-03-08T02:06:54.864Z', '2da5aad6f88cfea08e8301a478422f1f3fcea1c71d0d868760415c32b1694b15', '{"id":"9tykeshav/mern-ninja-cc/code-reviewer","name":"code-reviewer","description":{"en":"The code-reviewer skill provides comprehensive code review for MERN stack projects, checking project health and code quality. It benefits developers working with MongoDB, Express, React, and Node.js.","zh":"代码审查器是MERN栈项目的综合代码审查和测试生成工具，确保项目健康和代码质量","ja":"コードレビューやテスト生成ツールは、MERNスタックプロジェクトの健全性とコード品質を確保するためのものです","ko":"코드 리뷰어는 MERN 스택 프로젝트의 종합적인 코드 리뷰와 테스트 생성을 위한 도구로, 프로젝트 건강 상태와 코드 품질을 보장합니다","es":"Code-reviewer es una herramienta de revisión de código para proyectos MERN que evalúa la salud del proyecto y genera pruebas","fr":"Code-reviewer est un outil de révision de code pour les projets MERN qui évalue la santé du projet et génère des tests","de":"Code-reviewer ist ein Tool für die Code-Überprüfung von MERN-Projekten, das die Gesundheit des Projekts bewertet und Tests generiert","pt":"O code reviewer é uma ferramenta de revisão de código para projetos MERN, que verifica a saúde do projeto e gera testes para MongoDB, Express, React e Node.js","ru":"ИИ Агент code reviewer - это инструмент для проверки кода проектов MERN, который проверяет здоровье проекта и генерирует тесты для MongoDB, Express, React и Node.js","ar":"مراقب الكود هو أداة لمراجعة الكود لمشاريع MERN، التي تفحص صحة المشروع وتوليد الاختبارات ل MongoDB و Express و React و Node.js"},"seo":{"title":{"en":"code-reviewer: MERN Stack Code Review Setup Guide | AI Ag...","zh":"代码审查工具：MERN栈代码审查器和测试生成器","ja":"AIエージェント：MERNスタックのコードレビューやテスト生成ツール","ko":"코드 리뷰어: MERN 스택 마스터리 도구 및 코드 테스트 생성기","es":"Guía de configuración de code-reviewer para MERN","fr":"Configurer code-reviewer pour les projets MERN","de":"Einrichtungsleitfaden für code-reviewer in MERN","pt":"Guia de Configuração do Code Reviewer para MERN","ru":"Настройка ИИ Агента Code Reviewer для MERN","ar":"دليل إعداد مراقب الكود لأصحاب مهارات MERN"},"description":{"en":"Unlock comprehensive code review for MongoDB, Express, React, and Node.js projects. Learn how to assess project health and dive into code with code-reviewer.","zh":"使用代码审查器工具进行MERN栈项目的综合代码审查和测试生成，确保项目健康和代码质量","ja":"MERNスタックプロジェクトに適したコードレビューとテスト生成ツールを使用して、プロジェクトの健全性とコード品質を確保します","ko":"코드 리뷰어를 사용하여 MERN 스택 프로젝트의 종합적인 코드 리뷰와 테스트 생성을 수행하여 프로젝트 건강 상태와 코드 품질을 보장합니다","es":"Aprende a utilizar code-reviewer para mejorar la salud de tus proyectos MERN con herramientas de revisión de código y generación de pruebas","fr":"Améliorez la santé de vos projets MERN avec code-reviewer, outil de révision de code et de génération de tests","de":"Verbessern Sie die Gesundheit Ihrer MERN-Projekte mit code-reviewer, einem Tool für Code-Überprüfung und Testgenerierung","pt":"Aprenda a configurar o code reviewer para projetos MERN, incluindo verificação de saúde do projeto e geração de testes","ru":"Узнайте, как настроить ИИ Агента code reviewer для проектов MERN, включая проверку здоровья проекта и генерацию тестов","ar":"تعرف على كيفية إعداد مراقب الكود لأصحاب مهارات MERN، بما في ذلك فحص صحة المشروع وتوليد الاختبارات"},"definition":{"en":"code-reviewer is a MERN stack mastery tool that performs comprehensive code review and test generation for MongoDB, Express, React, and Node.js projects.","zh":"代码审查器是一种MERN栈代码审查和测试生成工具，用于评估项目健康状态和代码质量","ja":"コードレビューやテスト生成ツールは、MERNスタックプロジェクトの健全性とコード品質を評価するためのツールです","ko":"코드 리뷰어는 MERN 스택 프로젝트의 건강 상태와 코드 품질을 평가하기 위한 코드 리뷰와 테스트 생성 도구입니다","es":"Code-reviewer es una herramienta de revisión de código que utiliza inteligencia general y especialización en MERN","fr":"Code-reviewer est un outil de révision de code qui utilise l''intelligence générale et la spécialisation MERN","de":"Code-reviewer ist ein Tool für die Code-Überprüfung, das allgemeine Intelligenz und MERN-Spezialisierung verwendet","pt":"O code reviewer é uma ferramenta de revisão de código que verifica a saúde do projeto e gera testes para tecnologias MERN","ru":"ИИ Агент code reviewer - это инструмент для проверки кода, который проверяет здоровье проекта и генерирует тесты для технологий MERN","ar":"مراقب الكود هو أداة لمراجعة الكود التي تفحص صحة المشروع وتوليد الاختبارات لتكنولوجيا MERN"},"features":{"en":["Assesses project health by running `tsc --noEmit` for build status","Checks project documentation, including README and STATUS/BUGS/TODO files","Performs comprehensive code review using general intelligence and MERN specialization","Generates tests for MongoDB, Express, React, and Node.js projects","Dives into code quality after assessing project health"],"zh":["支持MERN栈项目的综合代码审查","自动测试生成功能","项目健康状态评估","代码质量检查","支持React、Node.js、Express和MongoDB"],"ja":["MERNスタックプロジェクトの総合的なコードレビューをサポート","自動テスト生成機能","プロジェクトの健全性を評価","コード品質をチェック","React、Node.js、Express、MongoDBをサポート"],"ko":["MERN 스택 프로젝트의 종합적인 코드 리뷰 지원","자동 테스트 생성 기능","프로젝트 건강 상태 평가","코드 품질 검사","React, Node.js, Express, MongoDB 지원"],"es":["Evaluación de la salud del proyecto con comandos como `tsc --noEmit`","Revisión de documentos del proyecto como README y archivos de estado","Generación de pruebas para proyectos MERN","Soporte para MongoDB, Express, React y Node.js","Revisión de código en un flujo de trabajo de 6 fases","Comprobación de errores de compilación y estado de construcción"],"fr":["Évaluation de la santé du projet avec des commandes comme `tsc --noEmit`","Révision des documents du projet comme README et fichiers d''état","Génération de tests pour les projets MERN","Prise en charge de MongoDB, Express, React et Node.js","Révision de code dans un flux de travail de 6 phases","Vérification des erreurs de compilation et de l''état de construction"],"de":["Bewertung der Gesundheit des Projekts mit Befehlen wie `tsc --noEmit`","Überprüfung der Projektdokumente wie README und Statusdateien","Generierung von Tests für MERN-Projekte","Unterstützung für MongoDB, Express, React und Node.js","Code-Überprüfung in einem 6-Phasen-Workflow","Überprüfung von Kompilierungsfehlern und Build-Status"],"pt":["Verificação de saúde do projeto","Geração de testes para MongoDB","Suporte a Express e React","Análise de código para Node.js","Verificação de build status com tsc --noEmit","Leitura de documentos do projeto, como README e STATUS"],"ru":["Проверка здоровья проекта","Генерация тестов для MongoDB","Поддержка Express и React","Анализ кода для Node.js","Проверка статуса сборки с помощью tsc --noEmit","Чтение документов проекта, таких как README и STATUS"],"ar":["فحص صحة المشروع","توليد الاختبارات ل MongoDB","دعم Express و React","تحليل الكود ل Node.js","فحص حالة البناء باستخدام tsc --noEmit","قراءة وثائق المشروع، مثل README و STATUS"]},"keywords":{"en":["how to use code-reviewer","code-reviewer alternative","MERN stack code review","code-reviewer setup guide","code-reviewer vs competitor","comprehensive code review for Node.js","code-reviewer install","what is code-reviewer","code-reviewer for React projects"],"zh":["代码审查工具","MERN栈代码审查","代码测试生成","项目健康状态评估","代码质量检查","React代码审查","Node.js代码审查","Express代码审查","MongoDB代码审查"],"ja":["AIエージェント","コードレビューツール","MERNスタックコードレビュー","テスト生成","プロジェクトの健全性評価","コード品質チェック","Reactコードレビュー","Node.jsコードレビュー","Expressコードレビュー","MongoDBコードレビュー"],"ko":["코드 리뷰어","MERN 스택 코드 리뷰","코드 테스트 생성","프로젝트 건강 상태 평가","코드 품질 검사","React 코드 리뷰","Node.js 코드 리뷰","Express 코드 리뷰","MongoDB 코드 리뷰"],"es":["code-reviewer","herramientas de revisión de código","MERN","MongoDB","Express","React","Node.js","generación de pruebas","evaluación de proyectos","salud de proyectos"],"fr":["code-reviewer","outils de révision de code","MERN","MongoDB","Express","React","Node.js","génération de tests","évaluation de projets","santé de projets"],"de":["code-reviewer","Tools für die Code-Überprüfung","MERN","MongoDB","Express","React","Node.js","Testgenerierung","Projektbewertung","Gesundheit von Projekten"],"pt":["code reviewer MERN","ferramenta de revisão de código","verificação de saúde do projeto","geração de testes","MongoDB","Express","React","Node.js","tsc --noEmit","README"],"ru":["ИИ Агент code reviewer MERN","инструмент для проверки кода","проверка здоровья проекта","генерация тестов","MongoDB","Express","React","Node.js","tsc --noEmit","README"],"ar":["مراقب الكود MERN","أداة لمراجعة الكود","فحص صحة المشروع","توليد الاختبارات","MongoDB","Express","React","Node.js","tsc --noEmit","README"]}},"owner":"9tykeshav","repo":"mern-ninja-cc","repoPath":"9tykeshav/mern-ninja-cc","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.406Z","topics":[],"category":"community","skillMd":{"name":"code-reviewer","description":"Use when asked to review MERN stack code - comprehensive code reviewer that checks project health, security, maintainability, performance, testing, and architecture. Combines general code quality analysis with MERN-specific expertise.","bodyPreview":"# Code Reviewer\n\n## Overview\n\nComprehensive code review: General intelligence + MERN specialization.\n\n**Philosophy:** Check project health FIRST, then dive into code. A 6,000-line file is a problem regardless of what''s in it.\n\n## Review Workflow\n\n### Phase 0: Project Health (Do This First)\n\nBefore reading any code, assess project health:\n\n1. **Build status:** Run `tsc --noEmit` or check for compilation errors\n2. **Project docs:** Read README, any STATUS/BUGS/TODO files - look for deployment bloc","body":"# Code Reviewer\n\n## Overview\n\nComprehensive code review: General intelligence + MERN specialization.\n\n**Philosophy:** Check project health FIRST, then dive into code. A 6,000-line file is a problem regardless of what''s in it.\n\n## Review Workflow\n\n### Phase 0: Project Health (Do This First)\n\nBefore reading any code, assess project health:\n\n1. **Build status:** Run `tsc --noEmit` or check for compilation errors\n2. **Project docs:** Read README, any STATUS/BUGS/TODO files - look for deployment blockers\n3. **Test health:** Do tests exist? Check `package.json` scripts, look for test directories\n4. **File sizes:** `find src -name \"*.ts\" -o -name \"*.tsx\" | xargs wc -l | sort -n | tail -20`\n5. **Dependencies:** Check for `npm audit` issues, unusual deps (Angular in React?)\n\n**Stop here if:** Build is broken, docs say \"DO NOT DEPLOY\", or critical blockers found. Report immediately.\n\n### Phase 1: Scope Detection\n\n1. Identify scope from context:\n   - Full repo → Broad review, sample key files\n   - Feature/PR → All changed files\n   - Single file → Deep dive\n2. Detect layers: React? Express? MongoDB? Node.js?\n3. If ambiguous → ask user\n\n### Phase 2: Review by Priority\n\n| Priority | Focus | Severity |\n|----------|-------|----------|\n| 0. Blockers | Build failures, \"DO NOT DEPLOY\", broken deploys | STOP |\n| 1. Security | Injection, auth, secrets, XSS | Critical |\n| 2. Maintainability | God files, complexity, duplication | Critical/Important |\n| 3. Performance | N+1, missing indexes, re-renders | Important |\n| 4. Testing | No tests, low coverage, flaky tests | Important |\n| 5. Best Practices | Error handling, async patterns | Suggestion |\n| 6. Architecture | API design, state management | Suggestion |\n\nLoad reference files ON-DEMAND when you hit MERN-specific edge cases.\n\n### Phase 3: Report\n\nUse the output format below. Offer to fix starting with Critical.\n\n## Output Format\n\n```markdown\n# MERN Code Review\n\n## Project Health\n- Build: [Compiles / X errors / Not checked]\n- Tests: [X passing / X failing / None found]\n- Blockers: [Any deployment blockers from docs]\n- Large files: [Files >500 lines]\n\n## Scope\n[What was reviewed]\n\n## Summary\n- Files reviewed: X\n- Issues: X Critical, X Important, X Suggestions\n\n## Critical (Must Fix)\n### [C1] Category: Title\n**File:** `path:line`\n**Why:** [1-2 sentences]\n**Fix:** [Code or instruction]\n\n## Important (Should Fix)\n### [I1] Category: Title\n...\n\n## Suggestions\n- `file:line` - Note\n\n## What''s Good\n- [Positive observations]\n\n## Verdict\n[Ready to deploy / Blocked / Needs fixes] - [1 sentence reason]\n\n---\n**Ready to fix these?** Starting with Critical issues.\n```\n\n## Checklists\n\n**Minimum required checks.** Report other issues you find during review.\n\n### Blockers (Check First)\n- [ ] Project compiles without errors\n- [ ] No \"DO NOT DEPLOY\" or similar warnings in docs\n- [ ] No critical security advisories in `npm audit`\n\n### Security\n- [ ] No `$where`, `$ne`, `$regex` with user input (NoSQL injection/ReDoS)\n- [ ] No `dangerouslySetInnerHTML` without DOMPurify\n- [ ] JWT in httpOnly cookies, not localStorage\n- [ ] Secrets in env vars, not hardcoded (check config files too, not just code)\n- [ ] Helmet middleware configured\n- [ ] CORS properly restricted\n- [ ] Rate limiting on auth endpoints\n- [ ] Input validation on all endpoints\n- [ ] No `eval()` or `new Function()` with user input\n\n### Maintainability\n- [ ] No file >500 lines (god files)\n- [ ] No function >50 lines\n- [ ] No class/component with >20 methods\n- [ ] No deep nesting (>4 levels)\n- [ ] No copy-paste blocks >10 lines (DRY)\n- [ ] Clear naming (no cryptic abbreviations)\n- [ ] Consistent code style\n\n### Performance\n- [ ] No N+1 queries (use populate/$lookup)\n- [ ] Indexes on frequently queried fields\n- [ ] `.lean()` for read-only Mongoose queries\n- [ ] No `fs.readFileSync` in request handlers\n- [ ] React.memo on expensive components\n- [ ] useCallback/useMemo where beneficial\n- [ ] Pagination on list endpoints\n\n### Testing\n- [ ] Tests exist for critical paths (auth, payments, core flows)\n- [ ] Test coverage reasonable (>50% for services)\n- [ ] No skipped/commented-out tests\n- [ ] Tests actually assert behavior (not just \"doesn''t crash\")\n- [ ] Mocks don''t hide real integration issues\n\n### Best Practices\n- [ ] Async errors handled (try/catch or error middleware)\n- [ ] useEffect cleanup functions present\n- [ ] No floating promises (unhandled async)\n- [ ] Middleware order correct (body-parser before routes, error handler last)\n- [ ] Environment variables validated at startup\n- [ ] Graceful shutdown handlers\n\n### Architecture\n- [ ] Consistent API response format\n- [ ] Service layer between controllers and DB\n- [ ] Types aligned frontend/backend\n- [ ] No circular dependencies\n- [ ] Clear module boundaries\n- [ ] No god components (React >300 lines)\n- [ ] State management appropriate for complexity\n\n## Red Flags (Immediate Critical)\n\nThese are automatic Critical issues:\n\n- `eval()`, `new Function()` with user input\n- Hardcoded secrets/credentials in code\n- `dangerouslySetInnerHTML` without sanitization\n- JWT/auth tokens in localStorage\n- Missing auth middleware on protected routes\n- `$where` clause with user input\n- File >1000 lines\n- \"DO NOT DEPLOY\" in project docs\n- `npm audit` critical vulnerabilities\n\n## Scope Calibration\n\n| Scope | Phase 0 | Code Depth | Focus |\n|-------|---------|------------|-------|\n| Single file | Skip | Deep | All checklists on that file |\n| Last commit | Quick | Medium | Changed lines + immediate context |\n| Feature/PR | Quick | Medium | All changed files |\n| Full repo | Full | Broad | Sample key files, architecture |\n\n## Reference Files\n\nLoad ONLY when you encounter MERN-specific patterns you need to verify:\n\n| When to Load | Reference |\n|--------------|-----------|\n| NoSQL query security question | [security.md](reference/security.md) |\n| React hooks/re-render issue | [react.md](reference/react.md) |\n| Express middleware question | [express.md](reference/express.md) |\n| MongoDB schema/index question | [mongodb.md](reference/mongodb.md) |\n| Node.js async/memory issue | [nodejs.md](reference/nodejs.md) |\n| API design/auth flow question | [fullstack.md](reference/fullstack.md) |\n\n**Do NOT load all references upfront.** They''re for edge cases, not general review.\n\n## Don''t\n\n- Don''t claim \"no issues found\" without actually searching for them\n- Don''t report on code you haven''t read\n- Don''t classify style issues as Critical\n\n## Examples\n\n### God File Detection\n```\nFound: EventService.ts - 6,165 lines\n→ Critical [C1] Maintainability: God file\n→ Recommend split into: EventQueryService, EventBookingService,\n   EventGuestService, EventInviteService (~500 lines each)\n```\n\n### Missing Health Check\n```\nFound: CURRENT_STATUS_AND_BUGS.md contains \"DO NOT DEPLOY\"\n→ Critical [C1] Blocker: Deployment blocked by known issues\n→ Fix TypeScript errors in EditEventModal.tsx before proceeding\n```\n\n### Security + Specific Fix\n```\nFound: No Helmet middleware in index.ts\n→ Critical [C2] Security: Missing security headers\n→ Fix: npm install helmet && app.use(helmet())\n```\n"},"lastSynced":"2026-03-08T02:06:54.864Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing comprehensive MERN stack project analysis and code quality checks.","zh":"非常适合需要对 MERN 栈项目进行全面分析和代码质量检查的全栈代理","ja":"MERN スタック プロジェクトの包括的な分析とコード品質チェックが必要なフルスタック エージェントに最適","ko":"전체 스택 에이전트에게 적합하며, MERN 스택 프로젝트에 대한 포괄적인 분석 및 코드 품질 확인이 필요합니다.","es":"Perfecto para Agentes de Stack Completo que necesitan un análisis de proyecto de pila MERN integral y controles de calidad de código.","fr":"Parfait pour les agents Full Stack ayant besoin d''une analyse de projet de pile MERN complète et de contrôles de qualité de code.","de":"Perfekt für Full-Stack-Agents, die eine umfassende Analyse von MERN-Stack-Projekten und Code-Qualitätsprüfungen benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de análise abrangente de projetos MERN e verificações de qualidade de código.","ru":"Идеально подходит для полноценных агентов, которым требуется всесторонний анализ проектов MERN и проверка качества кода.","ar":"مثالي لعميل الويب الكامل الذين يحتاجون إلى تحليل شامل لمشاريع MERN وفحص جودة الكود."},"recommendation":{"en":"Empowers agents to assess project health and code quality, utilizing technologies like MongoDB, Express, React, and Node.js, and providing insights through a 6-phase review workflow, including build status checks with `tsc --noEmit` and project documentation analysis.","zh":"赋予代理评估项目健康状况和代码质量的能力，利用诸如 MongoDB、Express、React 和 Node.js 等技术，并通过 6 阶段审查工作流提供洞察，包括使用 `tsc --noEmit` 进行构建状态检查和项目文档分析","ja":"エージェントがプロジェクトの健全性とコード品質を評価できるようにし、MongoDB、Express、React、Node.js などの技術を利用し、`tsc --noEmit` を使用したビルド状態の確認やプロジェクト文書の分析を含む 6 つの段階のレビュー ワークフローを通じて洞察を提供する","ko":"에이전트가 프로젝트 건강 상태와 코드 품질을 평가할 수 있도록 하고, MongoDB, Express, React 및 Node.js와 같은 기술을 사용하며, `tsc --noEmit`를 사용한 빌드 상태 확인 및 프로젝트 문서 분석을 포함한 6단계 검토 워크플로우를 통해 통찰력을 제공합니다.","es":"Permite a los agentes evaluar la salud del proyecto y la calidad del código, utilizando tecnologías como MongoDB, Express, React y Node.js, y proporcionando información a través de un flujo de trabajo de revisión de 6 fases, incluyendo controles de estado de compilación con `tsc --noEmit` y análisis de documentación del proyecto.","fr":"Permet aux agents d''évaluer la santé du projet et la qualité du code, en utilisant des technologies comme MongoDB, Express, React et Node.js, et en fournissant des informations à travers un flux de travail de révision de 6 phases, incluant des contrôles d''état de construction avec `tsc --noEmit` et une analyse de la documentation du projet.","de":"Ermöglicht es Agents, die Projektgesundheit und Codequalität zu bewerten, indem Technologien wie MongoDB, Express, React und Node.js verwendet werden, und Erkenntnisse durch einen 6-Phasen-Überprüfungs-Workflow bereitzustellen, einschließlich Build-Status-Checks mit `tsc --noEmit` und Projekt-Dokumentationsanalyse.","pt":"Permite que os agentes avaliem a saúde do projeto e a qualidade do código, utilizando tecnologias como MongoDB, Express, React e Node.js, e fornecendo informações por meio de um fluxo de trabalho de revisão em 6 fases, incluindo verificações de status de compilação com `tsc --noEmit` e análise de documentação do projeto.","ru":"Позволяет агентам оценивать здоровье проекта и качество кода, используя технологии seperti MongoDB, Express, React и Node.js, и предоставляя сведения через рабочий процесс рассмотрения в 6 фазах, включая проверки статуса сборки с `tsc --noEmit` и анализ документации проекта.","ar":"تمكن العميل من تقييم صحة المشروع وجودة الكود، باستخدام تقنيات مثل MongoDB و Express و React و Node.js، وتقديم معلومات من خلال تدفق عمل استعراضي في 6 مراحل، بما في ذلك فحص حالة البناء مع `tsc --noEmit` وتحليل توثيق المشروع."},"useCases":{"en":["Assessing MERN project health through build status and documentation","Evaluating code quality in Express and React components","Identifying deployment blockers in Node.js projects"],"zh":["通过构建状态和文档评估 MERN 项目的健康状况","评估 Express 和 React 组件的代码质量","识别 Node.js 项目中的部署阻塞"],"ja":["ビルド状態とドキュメントを通じて MERN プロジェクトの健全性を評価する","Express と React コンポーネントのコード品質を評価する","Node.js プロジェクトのデプロイ ブロッカーを特定する"],"ko":["빌드 상태 및 문서를 통해 MERN 프로젝트의 건강 상태를 평가","Express 및 React 컴포넌트의 코드 품질을 평가","Node.js 프로젝트의 배포 블로커를 식별"],"es":["Evaluar la salud del proyecto MERN a través del estado de compilación y la documentación","Evaluar la calidad del código en componentes Express y React","Identificar bloqueadores de implementación en proyectos Node.js"],"fr":["Évaluer la santé du projet MERN à travers l''état de construction et la documentation","Évaluer la qualité du code dans les composants Express et React","Identifier les bloqueurs de déploiement dans les projets Node.js"],"de":["Bewerten der Projektgesundheit von MERN durch Build-Status und Dokumentation","Bewerten der Codequalität in Express- und React-Komponenten","Identifizieren von Implementierungsblockierern in Node.js-Projekten"],"pt":["Avaliando a saúde do projeto MERN por meio do status de compilação e documentação","Avaliando a qualidade do código nos componentes Express e React","Identificando bloqueadores de implantação em projetos Node.js"],"ru":["Оценка здоровья проекта MERN через статус сборки и документацию","Оценка качества кода в компонентах Express и React","Определение блокировщиков развертывания в проектах Node.js"],"ar":["تقييم صحة مشروع MERN من خلال حالة البناء والتوثيق","تقييم جودة الكود في مكونات Express و React","تحديد معوقات النشر في مشاريع Node.js"]},"limitations":{"en":["Requires access to project codebase","MERN stack projects only","Limited to comprehensive code review, not implementation or debugging"],"zh":["需要访问项目代码库","仅限 MERN 栈项目","仅限全面代码审查，不包括实现或调试"],"ja":["プロジェクトのコードベースへのアクセスが必要","MERN スタック プロジェクトのみ","包括的なコードレビューのみ、実装やデバッグは含まない"],"ko":["프로젝트 코드베이스에 대한 액세스가 필요","MERN 스택 프로젝트만 해당","포괄적인 코드 리뷰만 해당, 구현 및 디버깅은 포함하지 않음"],"es":["Requiere acceso a la base de código del proyecto","Proyectos de pila MERN solamente","Limitado a una revisión de código integral, no implementación ni depuración"],"fr":["Nécessite un accès à la base de code du projet","Projets de pile MERN uniquement","Limité à une révision de code complète, et non à la mise en œuvre ou au débogage"],"de":["Benötigt Zugriff auf den Codebasis des Projekts","Nur MERN-Stack-Projekte","Begrenzt auf eine umfassende Code-Überprüfung, nicht auf Implementierung oder Fehlersuche"],"pt":["Requer acesso à base de código do projeto","Apenas projetos MERN","Limitado à revisão abrangente de código, não implementação ou depuração"],"ru":["Требуется доступ к базе кода проекта","Только проекты MERN","Ограниченный всесторонний обзор кода, не реализация или отладка"],"ar":["يتطلب الوصول إلى قاعدة الشفرة للمشروع","مشاريع MERN فقط","محدود بالاستعراض الشامل للكود، وليس التنفيذ أو التصحيح"]},"version":4},"contentHash":"2da5aad6f88cfea08e8301a478422f1f3fcea1c71d0d868760415c32b1694b15","qualityScore":60}');
