INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('9tykeshav/mern-ninja-cc/code-reviewer', 'code-reviewer', '9tykeshav', 'mern-ninja-cc', 'community', 'code-reviewer 9tykeshav mern-ninja-cc community The code-reviewer skill provides comprehensive code review for MERN stack projects, checking project health and code quality. It benefits developers working with MongoDB, Express, React, and Node.js. 代码审查器是MERN栈项目的综合代码审查和测试生成工具，确保项目健康和代码质量 コードレビューやテスト生成ツールは、MERNスタックプロジェクトの健全性とコード品質を確保するためのものです 코드 리뷰어는 MERN 스택 프로젝트의 종합적인 코드 리뷰와 테스트 생성을 위한 도구로, 프로젝트 건강 상태와 코드 품질을 보장합니다 Code-reviewer es una herramienta de revisión de código para proyectos MERN que evalúa la salud del proyecto y genera pruebas Code-reviewer est un outil de révision de code pour les projets MERN qui évalue la santé du projet et génère des tests Code-reviewer ist ein Tool für die Code-Überprüfung von MERN-Projekten, das die Gesundheit des Projekts bewertet und Tests generiert O code reviewer é uma ferramenta de revisão de código para projetos MERN, que verifica a saúde do projeto e gera testes para MongoDB, Express, React e Node.js ИИ Агент code reviewer - это инструмент для проверки кода проектов MERN, который проверяет здоровье проекта и генерирует тесты для MongoDB, Express, React и Node.js مراقب الكود هو أداة لمراجعة الكود لمشاريع MERN، التي تفحص صحة المشروع وتوليد الاختبارات ل MongoDB و Express و React و Node.js how to use code-reviewer code-reviewer alternative MERN stack code review code-reviewer setup guide code-reviewer vs competitor comprehensive code review for Node.js code-reviewer install what is code-reviewer code-reviewer for React projects 代码审查工具 MERN栈代码审查 代码测试生成 项目健康状态评估 代码质量检查 React代码审查 Node.js代码审查 Express代码审查 MongoDB代码审查 Assesses project health by running `tsc --noEmit` for build status Checks project documentation, including README and STATUS/BUGS/TODO files Performs comprehensive code review using general intelligence and MERN specialization Generates tests for MongoDB, Express, React, and Node.js projects Dives into code quality after assessing project health code-reviewer is a MERN stack mastery tool that performs comprehensive code review and test generation for MongoDB, Express, React, and Node.js projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('markus41/Demo-0.2/harness-ci', 'community', 'markus41', 'Demo-0.2', 'markus41/Demo-0.2', 'harness-ci', 0, 0, 60, '2026-03-08T01:57:15.411Z', '2026-03-08T02:07:04.177Z', '0b7a8e2a6d516aed6706a75565bbd452a334a665e051b096d426737e16b9b47a', '{"id":"markus41/Demo-0.2/harness-ci","name":"harness-ci","description":{"en":"The harness-ci skill provides comprehensive continuous integration for container-native builds, benefiting developers and teams managing complex pipelines. It offers features like test intelligence and caching for optimized build processes.","zh":"Harness CI是一种容器原生构建工具，提供测试智能、缓存和构建基础设施管理","ja":"Harness CIは、コンテナネイティブビルドを実現するツールで、テストインテリジェンス、キャッシング、ビルドインフラ管理を提供","ko":"Harness CI는 컨테이너 네이티브 빌드를 제공하는 도구로, 테스트 인텔리전스, 캐싱, 빌드 인프라 관리 기능을 제공합니다","es":"Harness CI es una herramienta de integración continua que ofrece inteligencia de pruebas, caché y gestión de infraestructura de compilación para optimizar tus pipelines de desarrollo","fr":"Harness CI est un outil d''intégration continue qui propose l''intelligence de tests, le cache et la gestion de l''infrastructure de build pour optimiser vos pipelines de développement","de":"Harness CI ist ein Tool für kontinuierliche Integration, das Testintelligenz, Caching und Build-Infrastruktur-Management bietet, um Ihre Entwicklungs-Pipelines zu optimieren","pt":"Harness CI é uma solução de integração contínua para builds nativos de contêiner com inteligência de teste e cache","ru":"Harness CI - это решение для непрерывной интеграции для сборки контейнеров с тестовой интеллект и кэшированием","ar":"Harness CI هو حل للاندماج المستمر للبناء الأصلي للحاويات مع ذكاء الاختبار والتخزين المؤقت"},"seo":{"title":{"en":"harness-ci: Container-Native CI Setup Guide | AI Agent Skill","zh":"Harness CI_SETUP GUIDE - CONTAINER-NATIVE Builds","ja":"Harness CI_BEST PRACTICES - AIエージェントによるCI","ko":"Harness CI_SETUP TUTORIAL - CONTAINER-NATIVE 빌드","es":"Guía de configuración de Harness CI para integración cont...","fr":"Guide de mise en place de Harness CI pour l''intégration c...","de":"Einrichtungsleitfaden für Harness CI zur kontinuierlichen...","pt":"Guia de Configuração Harness CI para Builds Contínuas","ru":"Настройка Harness CI для непрерывной интеграции: ИИ Агенты","ar":"دليل إعداد Harness CI للبناء المستمر: أدوات ذكاء اصطناعي"},"description":{"en":"Unlock efficient container-native builds with test intelligence and caching. Learn how to setup harness-ci for AI agents and streamline your development work...","zh":"了解Harness CI的强大功能，包括测试智能、缓存和构建基础设施管理","ja":"Harness CIの機能を活用して、CIパイプラインを最適化する方法を学びましょう","ko":"Harness CI의 기능을 활용하여 컨테이너 네이티브 빌드를 최적화하는 방법을 알아보세요","es":"Aprende a configurar Harness CI para optimizar tus pipelines de integración continua con inteligencia de pruebas, caché y gestión de infraestructura de compi...","fr":"Découvrez comment configurer Harness CI pour optimiser vos pipelines d''intégration continue avec l''intelligence de tests, le cache et la gestion de l''infrast...","de":"Erfahren Sie, wie Sie Harness CI einrichten, um Ihre Continuous-Integration-Pipelines mit Testintelligenz, Caching und Build-Infrastruktur-Management zu opti...","pt":"Aprenda a configurar Harness CI para otimizar seus pipelines de build e teste com inteligência de teste e cache","ru":"Узнайте, как настроить Harness CI для оптимизации ваших конвейеров сборки и тестирования с помощью тестовой интеллект и кэширования","ar":"تعلم كيفية إعداد Harness CI لتحسين أنابيب البناء والاختبار الخاصة بك مع ذكاء الاختبار والتخزين المؤقت"},"definition":{"en":"harness-ci is a continuous integration skill for container-native builds, offering test intelligence, caching, and build infrastructure management for efficient development workflows.","zh":"Harness CI是一种用于容器原生构建的CI工具","ja":"Harness CIは、コンテナネイティブビルド用のCIツール","ko":"Harness CI는 컨테이너 네이티브 빌드를 위한 CI 도구입니다","es":"Harness CI es una herramienta de integración continua que automatiza la compilación, las pruebas y la implementación de software","fr":"Harness CI est un outil d''intégration continue qui automatise la construction, les tests et le déploiement de logiciels","de":"Harness CI ist ein Tool für kontinuierliche Integration, das den Build-, Test- und Deployment-Prozess von Software automatisiert","pt":"Harness CI é uma ferramenta de integração contínua que otimiza os pipelines de build e teste","ru":"Harness CI - это инструмент непрерывной интеграции, который оптимизирует конвейеры сборки и тестирования","ar":"Harness CI هو أداة للاندماج المستمر التي تحسن أنابيب البناء والاختبار"},"features":{"en":["Configures build steps using Run, RunTests, and BuildAndPush","Sets up test intelligence for faster test execution","Supports caching strategies with S3 and GCS","Manages build infrastructure on Kubernetes, Harness Cloud, and VMs","Enables parallelization for optimized build processes"],"zh":["支持Run、RunTests、BuildAndPush等构建步骤","提供测试智能功能，实现更快的测试执行","支持S3、GCS等缓存策略","支持Kubernetes、Harness Cloud、VMs等构建基础设施管理"],"ja":["Run、RunTests、BuildAndPushなどのビルドステップをサポート","テストインテリジェンス機能を提供し、テストの実行を高速化","S3、GCSなどのキャッシング戦略をサポート","Kubernetes、Harness Cloud、VMsなどのビルドインフラ管理をサポート"],"ko":["Run, RunTests, BuildAndPush 등 빌드 단계 지원","테스트 인텔리전스 기능을 제공하여 테스트 실행을 빠르게","S3, GCS 등 캐싱 전략 지원","Kubernetes, Harness Cloud, VMs 등 빌드 인프라 관리 지원"],"es":["Integración con Kubernetes","Gestión de infraestructura de compilación con Harness Cloud y VMs","Estrategias de caché con S3 y GCS","Inteligencia de pruebas para una ejecución de pruebas más rápida","Compilación y ejecución de pruebas en paralelo"],"fr":["Intégration avec Kubernetes","Gestion de l''infrastructure de build avec Harness Cloud et VMs","Stratégies de cache avec S3 et GCS","Intelligence de tests pour une exécution de tests plus rapide","Construction et exécution de tests en parallèle"],"de":["Integration mit Kubernetes","Build-Infrastruktur-Management mit Harness Cloud und VMs","Caching-Strategien mit S3 und GCS","Testintelligenz für eine schnellere Testausführung","Build- und Testausführung in Parallelschritten"],"pt":["Integração contínua para builds nativos de contêiner","Inteligência de teste para execução de testes mais rápida","Estratégias de cache para S3 e GCS","Gerenciamento de infraestrutura de build com Kubernetes e Harness Cloud","Execução paralela de builds e testes"],"ru":["Непрерывная интеграция для сборки контейнеров","Тестовая интеллект для более быстрой выполнения тестов","Стратегии кэширования для S3 и GCS","Управление инфраструктурой сборки с помощью Kubernetes и Harness Cloud","Параллельное выполнение сборки и тестирования"],"ar":["الاندماج المستمر للبناء الأصلي للحاويات","ذكاء الاختبار لتنفيذ الاختبارات بشكل أسرع","استراتيجيات التخزين المؤقت ل S3 و GCS","إدارة بنية تحتية البناء مع Kubernetes و Harness Cloud","تنفيذ 병렬 للبناء والاختبار"]},"keywords":{"en":["how to use harness-ci","harness-ci setup guide","harness-ci vs Jenkins","container-native CI","test intelligence with harness-ci","harness-ci install for AI agents","harness-ci pipeline management","harness-ci caching strategies","harness-ci alternative for container builds"],"zh":["Harness CI","容器原生构建","测试智能","缓存策略","构建基础设施管理","CI工具","容器化构建","自动化测试","持续集成"],"ja":["Harness CI","コンテナネイティブビルド","テストインテリジェンス","キャッシング戦略","ビルドインフラ管理","CIツール","コンテナ化ビルド","自動テスト","継続的インテグレーション"],"ko":["Harness CI","컨테이너 네이티브 빌드","테스트 인텔리전스","캐싱 전략","빌드 인프라 관리","CI 도구","컨테이너화 빌드","자동화 테스트","지속적 통합"],"es":["harness ci","integración continua","inteligencia de pruebas","caché","gestión de infraestructura de compilación","kubernetes","harness cloud","vms","s3","gcs"],"fr":["harness ci","intégration continue","intelligence de tests","cache","gestion de l''infrastructure de build","kubernetes","harness cloud","vms","s3","gcs"],"de":["harness ci","kontinuierliche integration","testintelligenz","caching","build-infrastruktur-management","kubernetes","harness cloud","vms","s3","gcs"],"pt":["harness ci","integração contínua","builds nativos de contêiner","inteligência de teste","cache","kubernetes","harness cloud","devops","ci cd"],"ru":["harness ci","непрерывная интеграция","сборка контейнеров","тестовая интеллект","кэширование","kubernetes","harness cloud","devops","ci cd"],"ar":["harness ci","الاندماج المستمر","بناء الحاويات الأصلي","ذكاء الاختبار","التخزين المؤقت","kubernetes","harness cloud","devops","ci cd"]}},"owner":"markus41","repo":"Demo-0.2","repoPath":"markus41/Demo-0.2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.411Z","topics":[],"category":"community","skillMd":{"name":"harness-ci","description":"Harness CI (Continuous Integration) for container-native builds, test intelligence, caching, parallelization, and build infrastructure management. Activate for build pipelines, CI steps, test automation, artifact publishing, and build optimization.","bodyPreview":"# Harness CI Skill\n\nComprehensive Harness CI (Continuous Integration) for container-native builds with test intelligence, caching, and build infrastructure management.\n\n## When to Use This Skill\n\nActivate this skill when:\n- Creating or managing Harness CI pipelines\n- Configuring build steps (Run, RunTests, BuildAndPush)\n- Setting up test intelligence for faster test execution\n- Configuring caching strategies (S3, GCS)\n- Managing build infrastructure (Kubernetes, Harness Cloud, VMs)\n- Parallelizi","body":"# Harness CI Skill\n\nComprehensive Harness CI (Continuous Integration) for container-native builds with test intelligence, caching, and build infrastructure management.\n\n## When to Use This Skill\n\nActivate this skill when:\n- Creating or managing Harness CI pipelines\n- Configuring build steps (Run, RunTests, BuildAndPush)\n- Setting up test intelligence for faster test execution\n- Configuring caching strategies (S3, GCS)\n- Managing build infrastructure (Kubernetes, Harness Cloud, VMs)\n- Parallelizing builds with matrix strategies\n- Publishing artifacts and container images\n- Integrating with code repositories\n- Troubleshooting build failures\n\n## Build Infrastructure Types\n\n### Harness Cloud (Recommended)\n\nZero-configuration hosted build infrastructure:\n\n```yaml\ninfrastructure:\n  type: Cloud\n  spec:\n    os: Linux  # Linux, MacOS, or Windows\n```\n\n**Benefits:**\n- No setup required\n- Auto-scaling\n- Pre-installed tools\n- Managed updates\n\n### Kubernetes Infrastructure\n\nSelf-hosted on your K8s cluster:\n\n```yaml\ninfrastructure:\n  type: KubernetesDirect\n  spec:\n    connectorRef: k8s_connector\n    namespace: harness-builds\n    automountServiceAccountToken: true\n    nodeSelector:\n      kubernetes.io/os: linux\n    tolerations:\n      - key: \"dedicated\"\n        operator: \"Equal\"\n        value: \"ci\"\n        effect: \"NoSchedule\"\n    harnessImageConnectorRef: docker_connector\n    os: Linux\n```\n\n### VM Infrastructure\n\nAWS, Azure, or GCP VMs:\n\n```yaml\ninfrastructure:\n  type: VM\n  spec:\n    type: Pool\n    spec:\n      poolName: linux-pool\n      os: Linux\n```\n\n## CI Pipeline Structure\n\n### Basic Pipeline\n\n```yaml\npipeline:\n  name: Build Pipeline\n  identifier: build_pipeline\n  projectIdentifier: my_project\n  orgIdentifier: default\n  properties:\n    ci:\n      codebase:\n        connectorRef: harness_code\n        repoName: my-service\n        build: <+input>\n  stages:\n    - stage:\n        name: Build and Test\n        identifier: build_test\n        type: CI\n        spec:\n          cloneCodebase: true\n          infrastructure:\n            type: Cloud\n            spec:\n              os: Linux\n          execution:\n            steps:\n              - step:\n                  name: Install Dependencies\n                  identifier: install\n                  type: Run\n                  spec:\n                    shell: Sh\n                    command: npm ci\n              - step:\n                  name: Run Tests\n                  identifier: test\n                  type: Run\n                  spec:\n                    shell: Sh\n                    command: npm test -- --coverage\n                    reports:\n                      type: JUnit\n                      spec:\n                        paths:\n                          - \"junit.xml\"\n              - step:\n                  name: Build\n                  identifier: build\n                  type: Run\n                  spec:\n                    shell: Sh\n                    command: npm run build\n```\n\n## Step Types\n\n### Run Step\n\nExecute shell commands:\n\n```yaml\n- step:\n    name: Run Script\n    identifier: run_script\n    type: Run\n    spec:\n      connectorRef: docker_connector  # Optional for Harness Cloud\n      image: node:18-alpine           # Optional for Harness Cloud\n      shell: Sh  # Sh, Bash, Powershell, Pwsh, Python\n      command: |\n        echo \"Building application\"\n        npm ci\n        npm run build\n      envVariables:\n        NODE_ENV: production\n        API_URL: https://api.company.com\n      outputVariables:\n        - name: BUILD_VERSION\n      reports:\n        type: JUnit\n        spec:\n          paths:\n            - \"**/test-results/*.xml\"\n      resources:\n        limits:\n          memory: 2Gi\n          cpu: \"1\"\n```\n\n### Run Tests Step (Test Intelligence)\n\nRun tests with intelligent test selection:\n\n```yaml\n- step:\n    name: Run Tests with TI\n    identifier: run_tests_ti\n    type: RunTests\n    spec:\n      connectorRef: docker_connector\n      image: maven:3.8-openjdk-17\n      language: Java  # Java, Kotlin, Scala, CSharp, Python, Ruby\n      buildTool: Maven  # Maven, Gradle, Bazel, SBT, Nunit, Pytest, Unittest, Rspec\n      args: test\n      packages: com.myapp\n      runOnlySelectedTests: true  # Enable Test Intelligence\n      testAnnotations: org.junit.Test\n      preCommand: |\n        echo \"Setting up test environment\"\n      postCommand: |\n        echo \"Test cleanup\"\n      reports:\n        type: JUnit\n        spec:\n          paths:\n            - \"**/surefire-reports/*.xml\"\n      enableTestSplitting: true  # For parallel execution\n```\n\n### Build and Push Docker\n\nBuild and push container images:\n\n```yaml\n- step:\n    name: Build and Push\n    identifier: build_push\n    type: BuildAndPushDockerRegistry\n    spec:\n      connectorRef: docker_connector\n      repo: myorg/myapp\n      tags:\n        - <+pipeline.sequenceId>\n        - <+codebase.shortCommitSha>\n        - latest\n      dockerfile: Dockerfile\n      context: .\n      optimize: true  # Harness build optimization\n      caching: true   # Layer caching\n      buildArgs:\n        VERSION: <+pipeline.sequenceId>\n        BUILD_DATE: <+pipeline.startTs>\n      labels:\n        maintainer: team@company.com\n        commit: <+codebase.commitSha>\n      target: production  # Multi-stage target\n      remoteCacheRepo: myorg/myapp-cache  # Remote cache\n```\n\n### Build and Push to ECR\n\n```yaml\n- step:\n    name: Build and Push ECR\n    identifier: build_push_ecr\n    type: BuildAndPushECR\n    spec:\n      connectorRef: aws_connector\n      region: us-east-1\n      account: \"123456789012\"\n      imageName: myapp\n      tags:\n        - <+pipeline.sequenceId>\n      dockerfile: Dockerfile\n      caching: true\n```\n\n### Build and Push to GCR\n\n```yaml\n- step:\n    name: Build and Push GCR\n    identifier: build_push_gcr\n    type: BuildAndPushGCR\n    spec:\n      connectorRef: gcp_connector\n      host: gcr.io\n      projectID: my-gcp-project\n      imageName: myapp\n      tags:\n        - <+pipeline.sequenceId>\n      dockerfile: Dockerfile\n      caching: true\n```\n\n### Build and Push to ACR\n\n```yaml\n- step:\n    name: Build and Push ACR\n    identifier: build_push_acr\n    type: BuildAndPushACR\n    spec:\n      connectorRef: azure_connector\n      repository: myacr.azurecr.io/myapp\n      tags:\n        - <+pipeline.sequenceId>\n      dockerfile: Dockerfile\n      caching: true\n```\n\n## Caching Strategies\n\n### S3 Cache\n\n```yaml\n# Save cache\n- step:\n    name: Save Cache\n    identifier: save_cache\n    type: SaveCacheS3\n    spec:\n      connectorRef: aws_connector\n      region: us-east-1\n      bucket: harness-cache\n      key: node-modules-{{ checksum \"package-lock.json\" }}\n      sourcePaths:\n        - node_modules\n      archiveFormat: Tar\n\n# Restore cache\n- step:\n    name: Restore Cache\n    identifier: restore_cache\n    type: RestoreCacheS3\n    spec:\n      connectorRef: aws_connector\n      region: us-east-1\n      bucket: harness-cache\n      key: node-modules-{{ checksum \"package-lock.json\" }}\n      archiveFormat: Tar\n      failIfKeyNotFound: false\n```\n\n### GCS Cache\n\n```yaml\n# Save cache\n- step:\n    name: Save Cache\n    identifier: save_cache\n    type: SaveCacheGCS\n    spec:\n      connectorRef: gcp_connector\n      bucket: harness-cache\n      key: maven-{{ checksum \"pom.xml\" }}\n      sourcePaths:\n        - ~/.m2/repository\n      archiveFormat: Tar\n\n# Restore cache\n- step:\n    name: Restore Cache\n    identifier: restore_cache\n    type: RestoreCacheGCS\n    spec:\n      connectorRef: gcp_connector\n      bucket: harness-cache\n      key: maven-{{ checksum \"pom.xml\" }}\n      archiveFormat: Tar\n      failIfKeyNotFound: false\n```\n\n### Harness Cache Intelligence\n\n```yaml\n# Automatic caching based on build tool detection\n- step:\n    name: Build with Cache\n    identifier: build\n    type: Run\n    spec:\n      shell: Sh\n      command: |\n        npm ci\n        npm run build\n      caching:\n        enabled: true\n        key: npm-<+codebase.branch>\n        paths:\n          - node_modules\n```\n\n## Parallelism and Matrix\n\n### Matrix Strategy\n\nRun steps with multiple configurations:\n\n```yaml\n- step:\n    name: Test Matrix\n    identifier: test_matrix\n    type: Run\n    spec:\n      shell: Sh\n      command: |\n        echo \"Testing on Node $NODE_VERSION with $DB_TYPE\"\n        npm test\n      envVariables:\n        NODE_VERSION: <+matrix.nodeVersion>\n        DB_TYPE: <+matrix.database>\n    strategy:\n      matrix:\n        nodeVersion:\n          - \"16\"\n          - \"18\"\n          - \"20\"\n        database:\n          - postgres\n          - mysql\n        exclude:\n          - nodeVersion: \"16\"\n            database: mysql\n      maxConcurrency: 4\n```\n\n### Parallelism\n\nRun same step multiple times in parallel:\n\n```yaml\n- step:\n    name: Parallel Tests\n    identifier: parallel_tests\n    type: Run\n    spec:\n      shell: Sh\n      command: |\n        npm test -- --shard=$HARNESS_STAGE_INDEX/$HARNESS_STAGE_TOTAL\n    strategy:\n      parallelism: 4\n```\n\n### Step Groups for Parallelism\n\n```yaml\n- stepGroup:\n    name: Parallel Build\n    identifier: parallel_build\n    steps:\n      - parallel:\n          - step:\n              name: Build Frontend\n              identifier: build_frontend\n              type: Run\n              spec:\n                command: npm run build:frontend\n          - step:\n              name: Build Backend\n              identifier: build_backend\n              type: Run\n              spec:\n                command: npm run build:backend\n          - step:\n              name: Build Docs\n              identifier: build_docs\n              type: Run\n              spec:\n                command: npm run build:docs\n```\n\n## Background Services\n\nStart services for integration tests:\n\n```yaml\n# Database service\n- step:\n    name: Start PostgreSQL\n    identifier: postgres\n    type: Background\n    spec:\n      connectorRef: docker_connector\n      image: postgres:14\n      shell: Sh\n      envVariables:\n        POSTGRES_USER: test\n        POSTGRES_PASSWORD: test\n        POSTGRES_DB: testdb\n      portBindings:\n        \"5432\": \"5432\"\n      resources:\n        limits:\n          memory: 1Gi\n\n# Redis service\n- step:\n    name: Start Redis\n    identifier: redis\n    type: Background\n    spec:\n      connectorRef: docker_connector\n      image: redis:7-alpine\n      portBindings:\n        \"6379\": \"6379\"\n\n# Wait for services\n- step:\n    name: Wait for Services\n    identifier: wait\n    type: Run\n    spec:\n      shell: Sh\n      command: |\n        # Wait for PostgreSQL\n        until pg_isready -h localhost -p 5432; do\n          sleep 1\n        done\n\n        # Wait for Redis\n        until redis-cli -h localhost ping; do\n          sleep 1\n        done\n```\n\n## Test Intelligence\n\n### Configuration\n\n```yaml\n- step:\n    name: Run Tests with TI\n    identifier: test_ti\n    type: RunTests\n    spec:\n      language: Java\n      buildTool: Maven\n      runOnlySelectedTests: true  # Enable TI\n      testGlobs: \"**/test/**/*.java\"\n      testAnnotations: org.junit.Test, org.junit.jupiter.api.Test\n      packages: com.mycompany\n      args: test -Dmaven.test.failure.ignore=true\n      reports:\n        type: JUnit\n        spec:\n          paths:\n            - \"**/surefire-reports/*.xml\"\n```\n\n### Supported Languages\n\n| Language | Build Tools |\n|----------|-------------|\n| **Java** | Maven, Gradle, Bazel |\n| **Kotlin** | Maven, Gradle, Bazel |\n| **Scala** | Maven, Gradle, Bazel, SBT |\n| **C#** | NUnit, dotnet |\n| **Python** | Pytest, Unittest |\n| **Ruby** | RSpec |\n\n### Test Splitting\n\n```yaml\n- step:\n    name: Parallel Tests\n    identifier: parallel_tests\n    type: RunTests\n    spec:\n      language: Python\n      buildTool: Pytest\n      runOnlySelectedTests: true\n      enableTestSplitting: true  # Split across parallel instances\n      testSplitStrategy: ClassTiming  # or TestCount\n      args: --junitxml=report.xml\n    strategy:\n      parallelism: 4  # Run 4 parallel test containers\n```\n\n## Plugins\n\n### Harness Plugins\n\n```yaml\n# Slack notification\n- step:\n    name: Notify Slack\n    identifier: slack\n    type: Plugin\n    spec:\n      connectorRef: docker_connector\n      image: plugins/slack\n      settings:\n        webhook: <+secrets.getValue(\"slack_webhook\")>\n        channel: builds\n        template: |\n          Build {{#success build.status}}succeeded{{else}}failed{{/success}}\n          Repository: {{repo.name}}\n          Branch: {{build.branch}}\n          Commit: {{build.commit}}\n\n# Upload to S3\n- step:\n    name: Upload Artifacts\n    identifier: upload_s3\n    type: Plugin\n    spec:\n      connectorRef: docker_connector\n      image: plugins/s3\n      settings:\n        bucket: build-artifacts\n        region: us-east-1\n        access_key: <+secrets.getValue(\"aws_access_key\")>\n        secret_key: <+secrets.getValue(\"aws_secret_key\")>\n        source: dist/**/*\n        target: builds/<+pipeline.sequenceId>\n```\n\n### GitHub Actions\n\n```yaml\n- step:\n    name: GitHub Action\n    identifier: github_action\n    type: Action\n    spec:\n      uses: actions/setup-node@v3\n      with:\n        node-version: \"18\"\n        cache: npm\n```\n\n### Bitrise Steps\n\n```yaml\n- step:\n    name: Bitrise Step\n    identifier: bitrise\n    type: Bitrise\n    spec:\n      uses: script@1\n      with:\n        content: |\n          echo \"Running Bitrise step\"\n```\n\n## Artifact Management\n\n### Upload Artifacts\n\n```yaml\n- step:\n    name: Upload Artifact\n    identifier: upload_artifact\n    type: Run\n    spec:\n      shell: Sh\n      command: |\n        tar -czf dist.tar.gz dist/\n      outputVariables:\n        - name: ARTIFACT_PATH\n          type: String\n          value: dist.tar.gz\n```\n\n### GCS Artifacts\n\n```yaml\n- step:\n    name: Upload to GCS\n    identifier: upload_gcs\n    type: GCSUpload\n    spec:\n      connectorRef: gcp_connector\n      bucket: build-artifacts\n      sourcePath: dist/\n      target: builds/<+pipeline.sequenceId>/\n```\n\n### S3 Artifacts\n\n```yaml\n- step:\n    name: Upload to S3\n    identifier: upload_s3\n    type: S3Upload\n    spec:\n      connectorRef: aws_connector\n      region: us-east-1\n      bucket: build-artifacts\n      sourcePath: dist/\n      target: builds/<+pipeline.sequenceId>/\n```\n\n## CI Expressions\n\n| Expression | Description |\n|------------|-------------|\n| `<+codebase.branch>` | Git branch name |\n| `<+codebase.tag>` | Git tag (if tagged) |\n| `<+codebase.commitSha>` | Full commit SHA |\n| `<+codebase.shortCommitSha>` | Short commit SHA (7 chars) |\n| `<+codebase.commitMessage>` | Commit message |\n| `<+codebase.commitRef>` | Commit reference |\n| `<+codebase.repoUrl>` | Repository URL |\n| `<+codebase.gitUserId>` | Git user ID |\n| `<+codebase.gitUserEmail>` | Git user email |\n| `<+codebase.sourceBranch>` | PR source branch |\n| `<+codebase.targetBranch>` | PR target branch |\n| `<+codebase.prNumber>` | Pull request number |\n| `<+codebase.prTitle>` | Pull request title |\n| `<+codebase.prBody>` | Pull request body |\n| `<+pipeline.sequenceId>` | Build number |\n| `<+pipeline.executionId>` | Execution UUID |\n| `<+pipeline.startTs>` | Start timestamp |\n\n## Triggers\n\n### Push Trigger\n\n```yaml\ntrigger:\n  name: Build on Push\n  identifier: build_on_push\n  enabled: true\n  pipelineIdentifier: build_pipeline\n  source:\n    type: Webhook\n    spec:\n      type: Harness\n      spec:\n        type: Push\n        spec:\n          connectorRef: harness_code\n          repoName: my-service\n          autoAbortPreviousExecutions: true\n          payloadConditions:\n            - key: targetBranch\n              operator: In\n              value:\n                - main\n                - develop\n```\n\n### Pull Request Trigger\n\n```yaml\ntrigger:\n  name: Build on PR\n  identifier: build_on_pr\n  enabled: true\n  pipelineIdentifier: build_pipeline\n  source:\n    type: Webhook\n    spec:\n      type: Harness\n      spec:\n        type: PullRequest\n        spec:\n          connectorRef: harness_code\n          repoName: my-service\n          autoAbortPreviousExecutions: true\n          actions:\n            - Open\n            - Reopen\n            - Synchronize\n          payloadConditions:\n            - key: targetBranch\n              operator: Equals\n              value: main\n```\n\n### Tag Trigger\n\n```yaml\ntrigger:\n  name: Build on Tag\n  identifier: build_on_tag\n  enabled: true\n  pipelineIdentifier: release_pipeline\n  source:\n    type: Webhook\n    spec:\n      type: Harness\n      spec:\n        type: Tag\n        spec:\n          connectorRef: harness_code\n          repoName: my-service\n          tagCondition:\n            operator: Regex\n            value: \"^v[0-9]+\\\\.[0-9]+\\\\.[0-9]+$\"\n```\n\n## Complete CI/CD Pipeline Example\n\n```yaml\npipeline:\n  name: Full CI/CD Pipeline\n  identifier: full_cicd\n  projectIdentifier: my_project\n  orgIdentifier: default\n  properties:\n    ci:\n      codebase:\n        connectorRef: harness_code\n        repoName: my-service\n        build: <+input>\n  stages:\n    # CI Stage\n    - stage:\n        name: Build and Test\n        identifier: build_test\n        type: CI\n        spec:\n          cloneCodebase: true\n          infrastructure:\n            type: Cloud\n            spec:\n              os: Linux\n          caching:\n            enabled: true\n            key: npm-<+codebase.branch>\n            paths:\n              - node_modules\n          execution:\n            steps:\n              - step:\n                  name: Install\n                  identifier: install\n                  type: Run\n                  spec:\n                    shell: Sh\n                    command: npm ci\n              - parallel:\n                  - step:\n                      name: Lint\n                      identifier: lint\n                      type: Run\n                      spec:\n                        shell: Sh\n                        command: npm run lint\n                  - step:\n                      name: Type Check\n                      identifier: typecheck\n                      type: Run\n                      spec:\n                        shell: Sh\n                        command: npm run typecheck\n              - step:\n                  name: Test\n                  identifier: test\n                  type: Run\n                  spec:\n                    shell: Sh\n                    command: npm test -- --coverage\n                    reports:\n                      type: JUnit\n                      spec:\n                        paths:\n                          - junit.xml\n              - step:\n                  name: Build\n                  identifier: build\n                  type: Run\n                  spec:\n                    shell: Sh\n                    command: npm run build\n              - step:\n                  name: Build and Push\n                  identifier: build_push\n                  type: BuildAndPushDockerRegistry\n                  spec:\n                    connectorRef: docker_connector\n                    repo: myorg/myapp\n                    tags:\n                      - <+pipeline.sequenceId>\n                      - <+codebase.shortCommitSha>\n                    caching: true\n                    optimize: true\n\n    # CD Stage\n    - stage:\n        name: Deploy to Dev\n        identifier: deploy_dev\n        type: Deployment\n        spec:\n          deploymentType: Kubernetes\n          service:\n            serviceRef: my_service\n            serviceInputs:\n              serviceDefinition:\n                type: Kubernetes\n                spec:\n                  artifacts:\n                    primary:\n                      primaryArtifactRef: docker_image\n                      sources:\n                        - identifier: docker_image\n                          type: DockerRegistry\n                          spec:\n                            tag: <+pipeline.sequenceId>\n          environment:\n            environmentRef: development\n            infrastructureDefinitions:\n              - identifier: dev_k8s\n          execution:\n            steps:\n              - step:\n                  name: Rolling Deployment\n                  identifier: rollingDeployment\n                  type: K8sRollingDeploy\n                  timeout: 10m\n                  spec:\n                    skipDryRun: false\n            rollbackSteps:\n              - step:\n                  name: Rollback\n                  identifier: rollback\n                  type: K8sRollingRollback\n                  timeout: 10m\n                  spec: {}\n```\n\n## Troubleshooting\n\n### Common Issues\n\n| Issue | Cause | Solution |\n|-------|-------|----------|\n| Build timeout | Long-running step | Increase timeout, optimize build |\n| Cache miss | Key mismatch | Check checksum file path |\n| Image pull failed | Auth issue | Verify connector credentials |\n| Test Intelligence not working | Missing config | Check language/buildTool settings |\n| Out of memory | Resource limits | Increase memory in step spec |\n\n### Debug Logging\n\n```yaml\n- step:\n    name: Debug Info\n    identifier: debug\n    type: Run\n    spec:\n      shell: Sh\n      command: |\n        echo \"=== Build Debug Info ===\"\n        echo \"Branch: <+codebase.branch>\"\n        echo \"Commit: <+codebase.commitSha>\"\n        echo \"PR: <+codebase.prNumber>\"\n        echo \"Build: <+pipeline.sequenceId>\"\n        echo \"=== Environment ===\"\n        env | sort\n        echo \"=== Disk Usage ===\"\n        df -h\n        echo \"=== Memory ===\"\n        free -m\n```\n\n## Related Documentation\n\n- [Harness CI Docs](https://developer.harness.io/docs/continuous-integration)\n- [Test Intelligence](https://developer.harness.io/docs/continuous-integration/use-ci/run-tests/ti-overview)\n- [Caching](https://developer.harness.io/docs/continuous-integration/use-ci/caching-ci-data/caching-overview)\n- [Build Infrastructure](https://developer.harness.io/docs/continuous-integration/use-ci/set-up-build-infrastructure)\n- [Harness Knowledge Base](../docs/HARNESS-KNOWLEDGE-BASE.md)\n"},"lastSynced":"2026-03-08T02:07:04.177Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing advanced continuous integration for container-native builds with features like test intelligence and caching.","zh":"非常适合需要高级持续集成的DevOps代理，用于容器本地构建，具有测试智能和缓存等功能。","ja":"コンテナネイティブビルドの高度な継続的インテグレーションを必要とするDevOpsエージェントに最適です。テストインテリジェンスやキャッシングなどの機能を備えています。","ko":"고급 컨테이너 네이티브 빌드의 지속적인 통합이 필요한 DevOps 에이전트에 적합합니다. 테스트 인텔리전스 및 캐싱과 같은 기능을 제공합니다.","es":"Perfecto para agentes de DevOps que necesitan integración continua avanzada para compilaciones nativas de contenedores con características como inteligencia de pruebas y almacenamiento en caché.","fr":"Parfait pour les agents DevOps ayant besoin d''une intégration continue avancée pour des builds natifs de conteneurs avec des fonctionnalités comme l''intelligence de test et le caching.","de":"Perfekt für DevOps-Agents, die eine erweiterte kontinuierliche Integration für container-native Builds mit Funktionen wie Testintelligenz und Caching benötigen.","pt":"Perfeito para agentes DevOps que necessitam de integração contínua avançada para compilações nativas de contêiner com recursos como inteligência de teste e cache.","ru":"Идеально подходит для агентов DevOps, которым требуется продвинутая непрерывная интеграция для сборки контейнеров с функциями, такими как интеллект тестирования и кэширование.","ar":"مثالي لعميل DevOps الذين يحتاجون إلى تكامل مستمر متقدم لعمليات بناء أصلية للحاويات مع ميزات مثل ذكاء الاختبار والتخزين المؤقت."},"recommendation":{"en":"Empowers agents to manage complex pipelines with optimized build processes, utilizing test intelligence, caching strategies like S3 and GCS, and build infrastructure management for Kubernetes, Harness Cloud, and VMs.","zh":"赋予代理管理复杂管道的能力，优化构建过程，利用测试智能、缓存策略（如S3和GCS）以及Kubernetes、Harness Cloud和VM的构建基础设施管理。","ja":"エージェントが複雑なパイプラインを管理し、ビルドプロセスを最適化する能力を付与します。テストインテリジェンス、キャッシング戦略（S3やGCSなど）およびKubernetes、Harness Cloud、VMのビルドインフラストラクチャ管理を利用します。","ko":"에이전트가 복잡한 파이프라인을 관리하고 빌드 프로세스를 최적화 할 수 있는 능력을 부여합니다. 테스트 인텔리전스, 캐싱 전략(S3 및 GCS 등) 및 Kubernetes, Harness Cloud 및 VM의 빌드 인프라 관리를 활용합니다.","es":"Habilita a los agentes a gestionar pipelines complejos con procesos de compilación optimizados, utilizando inteligencia de pruebas, estrategias de caching como S3 y GCS, y gestión de infraestructura de compilación para Kubernetes, Harness Cloud y VMs.","fr":"Permet aux agents de gérer des pipelines complexes avec des processus de build optimisés, en utilisant l''intelligence de test, des stratégies de caching comme S3 et GCS, et la gestion d''infrastructure de build pour Kubernetes, Harness Cloud et VMs.","de":"Ermächtigt Agents, komplexe Pipelines mit optimierten Build-Prozessen zu verwalten, indem Testintelligenz, Caching-Strategien wie S3 und GCS und Build-Infrastrukturverwaltung für Kubernetes, Harness Cloud und VMs verwendet werden.","pt":"Habilita os agentes a gerenciar pipelines complexos com processos de compilação otimizados, utilizando inteligência de teste, estratégias de cache como S3 e GCS e gerenciamento de infraestrutura de compilação para Kubernetes, Harness Cloud e VMs.","ru":"Наделяет агентов возможностью управлять сложными конвейерами с оптимизированными процессами сборки, используя интеллект тестирования, стратегии кэширования, такие как S3 и GCS, и управление инфраструктурой сборки для Kubernetes, Harness Cloud и виртуальных машин.","ar":"يمكّن الوكلاء من إدارة خطوط أنابيب معقدة مع عمليات بناء محسّنة، باستخدام ذكاء الاختبار وстрatégies التخزين المؤقت مثل S3 و GCS وإدارة بنية تحتية البناء لـ Kubernetes و Harness Cloud و VMs."},"useCases":{"en":["Configuring build steps for container-native applications","Implementing test intelligence for faster test execution","Managing build infrastructure across multiple environments"],"zh":["为容器本地应用程序配置构建步骤","实现测试智能以加速测试执行","跨多个环境管理构建基础设施"],"ja":["コンテナネイティブアプリケーションのビルドステップを構成する","テストインテリジェンスを実装してテスト実行を高速化する","複数の環境にわたるビルドインフラストラクチャを管理する"],"ko":["컨테이너 네이티브 애플리케이션을 위한 빌드 단계 구성","테스트 인텔리전스를 구현하여 테스트 실행을 가속화","여러 환경에서 빌드 인프라를 관리"],"es":["Configuración de pasos de compilación para aplicaciones nativas de contenedores","Implementación de inteligencia de pruebas para una ejecución de pruebas más rápida","Gestión de infraestructura de compilación en varios entornos"],"fr":["Configuration des étapes de build pour des applications natives de conteneurs","Mise en œuvre de l''intelligence de test pour une exécution de test plus rapide","Gestion de l''infrastructure de build dans plusieurs environnements"],"de":["Konfiguration von Build-Schritten für container-native Anwendungen","Implementierung von Testintelligenz für eine schnellere Testausführung","Verwaltung von Build-Infrastruktur in mehreren Umgebungen"],"pt":["Configurando etapas de compilação para aplicações nativas de contêiner","Implementando inteligência de teste para execução de testes mais rápida","Gerenciando infraestrutura de compilação em vários ambientes"],"ru":["Настройка шагов сборки для контейнерных приложений","Реализация интеллекта тестирования для более быстрой выполнения тестов","Управление инфраструктурой сборки в нескольких средах"],"ar":["تكوين خطوات البناء للتطبيقات الأصلية للحاويات","تنفيذ ذكاء الاختبار للتنفيذ السريع للاختبارات","إدارة بنية تحتية البناء في بيئات متعددة"]},"limitations":{"en":["Requires container-native build environment","Limited to Kubernetes, Harness Cloud, and VMs for build infrastructure management"],"zh":["需要容器本地构建环境","仅限Kubernetes、Harness Cloud和VM进行构建基础设施管理"],"ja":["コンテナネイティブビルド環境が必要","ビルドインフラストラクチャ管理はKubernetes、Harness Cloud、VMに限定"],"ko":["컨테이너 네이티브 빌드 환경 필요","빌드 인프라 관리는 Kubernetes, Harness Cloud 및 VM에 제한"],"es":["Requiere un entorno de compilación nativo de contenedores","Limitado a Kubernetes, Harness Cloud y VMs para la gestión de infraestructura de compilación"],"fr":["Nécessite un environnement de build natif de conteneurs","Limité à Kubernetes, Harness Cloud et VMs pour la gestion de l''infrastructure de build"],"de":["Benötigt eine container-native Build-Umgebung","Begrenzt auf Kubernetes, Harness Cloud und VMs für die Build-Infrastrukturverwaltung"],"pt":["Requer ambiente de compilação nativo de contêiner","Limitado a Kubernetes, Harness Cloud e VMs para gerenciamento de infraestrutura de compilação"],"ru":["Требуется контейнерная среда сборки","Ограничен для Kubernetes, Harness Cloud и виртуальных машин для управления инфраструктурой сборки"],"ar":["يتطلب بيئة بناء أصلية للحاويات","محدود لـ Kubernetes و Harness Cloud و VMs لإدارة بنية تحتية البناء"]},"version":4},"contentHash":"0b7a8e2a6d516aed6706a75565bbd452a334a665e051b096d426737e16b9b47a","qualityScore":60}');
