INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('markus41/Demo-0.2/harness-ci', 'harness-ci', 'markus41', 'Demo-0.2', 'community', 'harness-ci markus41 Demo-0.2 community The harness-ci skill provides comprehensive continuous integration for container-native builds, benefiting developers and teams managing complex pipelines. It offers features like test intelligence and caching for optimized build processes. Harness CI是一种容器原生构建工具，提供测试智能、缓存和构建基础设施管理 Harness CIは、コンテナネイティブビルドを実現するツールで、テストインテリジェンス、キャッシング、ビルドインフラ管理を提供 Harness CI는 컨테이너 네이티브 빌드를 제공하는 도구로, 테스트 인텔리전스, 캐싱, 빌드 인프라 관리 기능을 제공합니다 Harness CI es una herramienta de integración continua que ofrece inteligencia de pruebas, caché y gestión de infraestructura de compilación para optimizar tus pipelines de desarrollo Harness CI est un outil d''intégration continue qui propose l''intelligence de tests, le cache et la gestion de l''infrastructure de build pour optimiser vos pipelines de développement Harness CI ist ein Tool für kontinuierliche Integration, das Testintelligenz, Caching und Build-Infrastruktur-Management bietet, um Ihre Entwicklungs-Pipelines zu optimieren Harness CI é uma solução de integração contínua para builds nativos de contêiner com inteligência de teste e cache Harness CI - это решение для непрерывной интеграции для сборки контейнеров с тестовой интеллект и кэшированием Harness CI هو حل للاندماج المستمر للبناء الأصلي للحاويات مع ذكاء الاختبار والتخزين المؤقت how to use harness-ci harness-ci setup guide harness-ci vs Jenkins container-native CI test intelligence with harness-ci harness-ci install for AI agents harness-ci pipeline management harness-ci caching strategies harness-ci alternative for container builds Harness CI 容器原生构建 测试智能 缓存策略 构建基础设施管理 CI工具 容器化构建 自动化测试 持续集成 Configures build steps using Run, RunTests, and BuildAndPush Sets up test intelligence for faster test execution Supports caching strategies with S3 and GCS Manages build infrastructure on Kubernetes, Harness Cloud, and VMs Enables parallelization for optimized build processes harness-ci is a continuous integration skill for container-native builds, offering test intelligence, caching, and build infrastructure management for efficient development workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Trevoke/org-gtd.el/writing-skills', 'community', 'Trevoke', 'org-gtd.el', 'Trevoke/org-gtd.el', 'writing-skills', 0, 0, 60, '2026-03-08T01:57:15.411Z', '2026-03-08T02:07:04.713Z', '7021abf950802a3ea7e80f76ac7cfd2c09dc19dbf362a7dd5b10e2679e70c07c', '{"id":"Trevoke/org-gtd.el/writing-skills","name":"writing-skills","description":{"en":"Writing-Skills applies Test-Driven Development to process documentation, benefiting developers who use GTD with org-mode. It enables users to write test cases, watch them fail, and then pass with the written skill.","zh":"writing-skills 是一种将测试驱动开发应用于文档化过程的技术，通过写测试用例和重构来确保文档的质量","ja":"Writing Skills は、テスト駆動開発を文書化プロセスに適用することで、エージェントのコンプライアンスを高める技術です","ko":"writing-skills 는 문서화 프로세스에 테스트 주도 개발을 적용하여 문서의 품질을 보장하는 기술입니다","es":"Writing-skills es una herramienta de Agente de Inteligencia Artificial que aplica el desarrollo dirigido por pruebas a la documentación de procesos con GTD y org-mode","fr":"Writing-skills est un outil d''Agent d''Intelligence Artificielle qui applique le développement dirigé par les tests à la documentation de processus avec GTD et org-mode","de":"Writing-skills ist ein Tool für künstliche Intelligenz-Agenten, das das testgetriebene Entwicklung auf die Prozessdokumentation mit GTD und org-mode anwendet","pt":"Habilidades de escrita aplicam o desenvolvimento orientado a testes à documentação de processos em org-mode","ru":"Навыки письма применяют тест-ориентированное развитие к документации процессов в org-mode","ar":"مهارات الكتابة تطبق التطوير الموجه بالاختبار لتدوين العملية في org-mode"},"seo":{"title":{"en":"Writing-Skills: Test-Driven Documentation Setup Guide | A...","zh":"writing-skills 技术文档最佳实践指南","ja":"Writing Skills のためのテスト駆動開発ガイド","ko":"writing-skills 문서화 프로세스 최적화 설정 가이드","es":"Guía de configuración para writing-skills con GTD y org-mode","fr":"Guide d''installation pour writing-skills avec GTD et org-...","de":"Einrichtungsleitfaden für writing-skills mit GTD und org-...","pt":"Guia de Configuração de Habilidades de Escrita para Ferra...","ru":"Руководство по настройке навыков письма для ИИ Агентов","ar":"دليل إعداد مهارات الكتابة لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient documentation with Writing-Skills! Learn how to apply Test-Driven Development to process documentation and streamline your workflow. Get sta...","zh":"了解 writing-skills 的核心原理和技术细节，实现高效的文档化过程","ja":"Writing Skills のテスト駆動開発アプローチを学び、エージェントのコンプライアンスを確保する","ko":"writing-skills 를 사용하여 문서화 프로세스를 최적화하고 에이전트의 컴플라이언스를 높이세요","es":"Mejora tus habilidades de escritura con writing-skills, una herramienta de Agente de Inteligencia Artificial para GTD y org-mode","fr":"Améliorez vos compétences en écriture avec writing-skills, un outil d''Agent d''Intelligence Artificielle pour GTD et org-mode","de":"Verbessern Sie Ihre Schreibfähigkeiten mit writing-skills, einem Tool für künstliche Intelligenz-Agenten für GTD und org-mode","pt":"Aprenda a configurar habilidades de escrita com testes orientados para documentação de processos em org-mode","ru":"Узнайте, как настроить навыки письма с помощью тестирования, ориентированного на документацию процессов в org-mode для ИИ Агентов","ar":"تعلم كيفية إعداد مهارات الكتابة باستخدام الاختبارات الموجهة لتدوين عملية في org-mode لأدوات الذكاء الاصطناعي"},"definition":{"en":"Writing-skills is a package for using GTD with org-mode, applying Test-Driven Development principles to process documentation.","zh":"writing-skills 是一种将测试驱动开发应用于文档化过程的技术","ja":"Writing Skills はテスト駆動開発を文書化プロセスに適用する技術です","ko":"writing-skills 는 문서화 프로세스에 테스트 주도 개발을 적용하는 기술입니다","es":"Writing-skills es una técnica de desarrollo que aplica pruebas para mejorar la documentación de procesos","fr":"Writing-skills est une technique de développement qui applique des tests pour améliorer la documentation de processus","de":"Writing-skills ist eine Entwicklungstechnik, die Tests anwendet, um die Prozessdokumentation zu verbessern","pt":"Habilidades de escrita são uma abordagem de desenvolvimento orientada a testes para documentação de processos","ru":"Навыки письма - это подход к разработке, ориентированный на тестирование, для документации процессов","ar":"مهارات الكتابة هي نهج التطوير الموجه بالاختبار لتدوين العملية"},"features":{"en":["Applies Test-Driven Development to process documentation","Utilizes agent-specific directories (~/.claude/skills, ~/.codex/skills)","Enables writing test cases with pressure scenarios and subagents","Supports watching tests fail and pass with the written skill","Allows refactoring to close loopholes in documentation"],"zh":["使用测试驱动开发方法确保文档质量","支持 GTD 和 org-mode","通过写测试用例和重构来优化文档","确保文档的完整性和一致性","支持 Claude Code 和 Codex 的 agent-specific 目录"],"ja":["テスト駆動開発アプローチを使用して文書の品質を確保","GTD と org-mode をサポート","テストケースの作成とリファクタリングによって文書を最適化","文書の完全性と一貫性を確保","Claude Code と Codex のエージェント固有ディレクトリをサポート"],"ko":["테스트 주도 개발 방법을 사용하여 문서의 품질을 보장","GTD 와 org-mode 를 지원","테스트 케이스의 작성과 리팩토링으로 문서를 최적화","문서의 완전성과 일관성을 보장","Claude Code 와 Codex 의 에이전트 고유 디렉토리를 지원"],"es":["Aplicación de desarrollo dirigido por pruebas","Integración con GTD y org-mode","Creación de casos de prueba y escenarios de presión","Refactorización de la documentación de procesos","Compatibilidad con agentes de inteligencia artificial como Claude Code y Codex"],"fr":["Application du développement dirigé par les tests","Intégration avec GTD et org-mode","Création de cas de test et de scénarios de pression","Refactorisation de la documentation de processus","Compatibilité avec les agents d''intelligence artificielle tels que Claude Code et Codex"],"de":["Anwendung des testgetriebenen Entwicklungs","Integration mit GTD und org-mode","Erstellung von Testfällen und Druckszenarien","Refaktorisierung der Prozessdokumentation","Kompatibilität mit künstlichen Intelligenz-Agenten wie Claude Code und Codex"],"pt":["Testes orientados para documentação de processos","Integração com org-mode","Desenvolvimento de habilidades personalizadas em diretórios de agentes","Refinamento de habilidades por meio de testes e iterações","Uso de subagentes para simular cenários de pressão"],"ru":["Тестирование, ориентированное на документацию процессов","Интеграция с org-mode","Разработка индивидуальных навыков в директориях агентов","Уточнение навыков посредством тестирования и итераций","Использование субагентов для имитации сценариев давления"],"ar":["الاختبارات الموجهة لتدوين العملية","التكامل مع org-mode","تطوير مهارات مخصصة في دلائل الوكلاء","تحسين المهارات من خلال الاختبارات والتحولات","استخدام الوكلاء الفرعيين لمحاكاة سيناريوهات الضغط"]},"keywords":{"en":["how to use writing-skills","writing-skills alternative","writing-skills setup guide","what is writing-skills","writing-skills vs org-mode","writing-skills install for GTD"],"zh":["writing-skills","测试驱动开发","文档化过程","GTD","org-mode","AIエージェント","文档质量","测试用例"],"ja":["Writing Skills","テスト駆動開発","文書化プロセス","GTD","org-mode","AIエージェント","文書の品質","テストケース"],"ko":["writing-skills","테스트 주도 개발","문서화 프로세스","GTD","org-mode","AI 에이전트","문서 품질","테스트 케이스"],"es":["writing-skills","GTD","org-mode","desarrollo dirigido por pruebas","Agente de Inteligencia Artificial","documentación de procesos","Claude Code","Codex","herramientas de desarrollo"],"fr":["writing-skills","GTD","org-mode","développement dirigé par les tests","Agent d''Intelligence Artificielle","documentation de processus","Claude Code","Codex","outils de développement"],"de":["writing-skills","GTD","org-mode","testgetriebenes Entwicklung","künstliche Intelligenz-Agenten","Prozessdokumentation","Claude Code","Codex","Entwicklungstools"],"pt":["habilidades de escrita","desenvolvimento orientado a testes","documentação de processos","org-mode","ferramentas de inteligência artificial","testes de pressão","subagentes","refinamento de habilidades"],"ru":["навыки письма","тест-ориентированное развитие","документация процессов","org-mode","ИИ Агенты","тестирование под давлением","субагенты","уточнение навыков"],"ar":["مهارات الكتابة","التطوير الموجه بالاختبار","تدوين العملية","org-mode","أدوات الذكاء الاصطناعي","اختبارات الضغط","الوكلاء الفرعيين","تحسين المهارات"]}},"owner":"Trevoke","repo":"org-gtd.el","repoPath":"Trevoke/org-gtd.el","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.411Z","topics":[],"category":"community","skillMd":{"name":"writing-skills","description":"Use when creating new skills, editing existing skills, or verifying skills work before deployment","bodyPreview":"# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Personal skills live in agent-specific directories (`~/.claude/skills` for Claude Code, `~/.codex/skills` for Codex)** \n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn''t watch an agent fail without the skil","body":"# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Personal skills live in agent-specific directories (`~/.claude/skills` for Claude Code, `~/.codex/skills` for Codex)** \n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn''t watch an agent fail without the skill, you don''t know if the skill teaches the right thing.\n\n**REQUIRED BACKGROUND:** You MUST understand superpowers:test-driven-development before using this skill. That skill defines the fundamental RED-GREEN-REFACTOR cycle. This skill adapts TDD to documentation.\n\n**Official guidance:** For Anthropic''s official skill authoring best practices, see anthropic-best-practices.md. This document provides additional patterns and guidelines that complement the TDD-focused approach in this skill.\n\n## What is a Skill?\n\nA **skill** is a reference guide for proven techniques, patterns, or tools. Skills help future Claude instances find and apply effective approaches.\n\n**Skills are:** Reusable techniques, patterns, tools, reference guides\n\n**Skills are NOT:** Narratives about how you solved a problem once\n\n## TDD Mapping for Skills\n\n| TDD Concept | Skill Creation |\n|-------------|----------------|\n| **Test case** | Pressure scenario with subagent |\n| **Production code** | Skill document (SKILL.md) |\n| **Test fails (RED)** | Agent violates rule without skill (baseline) |\n| **Test passes (GREEN)** | Agent complies with skill present |\n| **Refactor** | Close loopholes while maintaining compliance |\n| **Write test first** | Run baseline scenario BEFORE writing skill |\n| **Watch it fail** | Document exact rationalizations agent uses |\n| **Minimal code** | Write skill addressing those specific violations |\n| **Watch it pass** | Verify agent now complies |\n| **Refactor cycle** | Find new rationalizations → plug → re-verify |\n\nThe entire skill creation process follows RED-GREEN-REFACTOR.\n\n## When to Create a Skill\n\n**Create when:**\n- Technique wasn''t intuitively obvious to you\n- You''d reference this again across projects\n- Pattern applies broadly (not project-specific)\n- Others would benefit\n\n**Don''t create for:**\n- One-off solutions\n- Standard practices well-documented elsewhere\n- Project-specific conventions (put in CLAUDE.md)\n\n## Skill Types\n\n### Technique\nConcrete method with steps to follow (condition-based-waiting, root-cause-tracing)\n\n### Pattern\nWay of thinking about problems (flatten-with-flags, test-invariants)\n\n### Reference\nAPI docs, syntax guides, tool documentation (office docs)\n\n## Directory Structure\n\n\n```\nskills/\n  skill-name/\n    SKILL.md              # Main reference (required)\n    supporting-file.*     # Only if needed\n```\n\n**Flat namespace** - all skills in one searchable namespace\n\n**Separate files for:**\n1. **Heavy reference** (100+ lines) - API docs, comprehensive syntax\n2. **Reusable tools** - Scripts, utilities, templates\n\n**Keep inline:**\n- Principles and concepts\n- Code patterns (< 50 lines)\n- Everything else\n\n## SKILL.md Structure\n\n**Frontmatter (YAML):**\n- Only two fields supported: `name` and `description`\n- Max 1024 characters total\n- `name`: Use letters, numbers, and hyphens only (no parentheses, special chars)\n- `description`: Third-person, describes ONLY when to use (NOT what it does)\n  - Start with \"Use when...\" to focus on triggering conditions\n  - Include specific symptoms, situations, and contexts\n  - **NEVER summarize the skill''s process or workflow** (see CSO section for why)\n  - Keep under 500 characters if possible\n\n```markdown\n---\nname: Skill-Name-With-Hyphens\ndescription: Use when [specific triggering conditions and symptoms]\n---\n\n# Skill Name\n\n## Overview\nWhat is this? Core principle in 1-2 sentences.\n\n## When to Use\n[Small inline flowchart IF decision non-obvious]\n\nBullet list with SYMPTOMS and use cases\nWhen NOT to use\n\n## Core Pattern (for techniques/patterns)\nBefore/after code comparison\n\n## Quick Reference\nTable or bullets for scanning common operations\n\n## Implementation\nInline code for simple patterns\nLink to file for heavy reference or reusable tools\n\n## Common Mistakes\nWhat goes wrong + fixes\n\n## Real-World Impact (optional)\nConcrete results\n```\n\n\n## Claude Search Optimization (CSO)\n\n**Critical for discovery:** Future Claude needs to FIND your skill\n\n### 1. Rich Description Field\n\n**Purpose:** Claude reads description to decide which skills to load for a given task. Make it answer: \"Should I read this skill right now?\"\n\n**Format:** Start with \"Use when...\" to focus on triggering conditions\n\n**CRITICAL: Description = When to Use, NOT What the Skill Does**\n\nThe description should ONLY describe triggering conditions. Do NOT summarize the skill''s process or workflow in the description.\n\n**Why this matters:** Testing revealed that when a description summarizes the skill''s workflow, Claude may follow the description instead of reading the full skill content. A description saying \"code review between tasks\" caused Claude to do ONE review, even though the skill''s flowchart clearly showed TWO reviews (spec compliance then code quality).\n\nWhen the description was changed to just \"Use when executing implementation plans with independent tasks\" (no workflow summary), Claude correctly read the flowchart and followed the two-stage review process.\n\n**The trap:** Descriptions that summarize workflow create a shortcut Claude will take. The skill body becomes documentation Claude skips.\n\n```yaml\n# ❌ BAD: Summarizes workflow - Claude may follow this instead of reading skill\ndescription: Use when executing plans - dispatches subagent per task with code review between tasks\n\n# ❌ BAD: Too much process detail\ndescription: Use for TDD - write test first, watch it fail, write minimal code, refactor\n\n# ✅ GOOD: Just triggering conditions, no workflow summary\ndescription: Use when executing implementation plans with independent tasks in the current session\n\n# ✅ GOOD: Triggering conditions only\ndescription: Use when implementing any feature or bugfix, before writing implementation code\n```\n\n**Content:**\n- Use concrete triggers, symptoms, and situations that signal this skill applies\n- Describe the *problem* (race conditions, inconsistent behavior) not *language-specific symptoms* (setTimeout, sleep)\n- Keep triggers technology-agnostic unless the skill itself is technology-specific\n- If skill is technology-specific, make that explicit in the trigger\n- Write in third person (injected into system prompt)\n- **NEVER summarize the skill''s process or workflow**\n\n```yaml\n# ❌ BAD: Too abstract, vague, doesn''t include when to use\ndescription: For async testing\n\n# ❌ BAD: First person\ndescription: I can help you with async tests when they''re flaky\n\n# ❌ BAD: Mentions technology but skill isn''t specific to it\ndescription: Use when tests use setTimeout/sleep and are flaky\n\n# ✅ GOOD: Starts with \"Use when\", describes problem, no workflow\ndescription: Use when tests have race conditions, timing dependencies, or pass/fail inconsistently\n\n# ✅ GOOD: Technology-specific skill with explicit trigger\ndescription: Use when using React Router and handling authentication redirects\n```\n\n### 2. Keyword Coverage\n\nUse words Claude would search for:\n- Error messages: \"Hook timed out\", \"ENOTEMPTY\", \"race condition\"\n- Symptoms: \"flaky\", \"hanging\", \"zombie\", \"pollution\"\n- Synonyms: \"timeout/hang/freeze\", \"cleanup/teardown/afterEach\"\n- Tools: Actual commands, library names, file types\n\n### 3. Descriptive Naming\n\n**Use active voice, verb-first:**\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `condition-based-waiting` not `async-test-helpers`\n\n### 4. Token Efficiency (Critical)\n\n**Problem:** getting-started and frequently-referenced skills load into EVERY conversation. Every token counts.\n\n**Target word counts:**\n- getting-started workflows: <150 words each\n- Frequently-loaded skills: <200 words total\n- Other skills: <500 words (still be concise)\n\n**Techniques:**\n\n**Move details to tool help:**\n```bash\n# ❌ BAD: Document all flags in SKILL.md\nsearch-conversations supports --text, --both, --after DATE, --before DATE, --limit N\n\n# ✅ GOOD: Reference --help\nsearch-conversations supports multiple modes and filters. Run --help for details.\n```\n\n**Use cross-references:**\n```markdown\n# ❌ BAD: Repeat workflow details\nWhen searching, dispatch subagent with template...\n[20 lines of repeated instructions]\n\n# ✅ GOOD: Reference other skill\nAlways use subagents (50-100x context savings). REQUIRED: Use [other-skill-name] for workflow.\n```\n\n**Compress examples:**\n```markdown\n# ❌ BAD: Verbose example (42 words)\nyour human partner: \"How did we handle authentication errors in React Router before?\"\nYou: I''ll search past conversations for React Router authentication patterns.\n[Dispatch subagent with search query: \"React Router authentication error handling 401\"]\n\n# ✅ GOOD: Minimal example (20 words)\nPartner: \"How did we handle auth errors in React Router?\"\nYou: Searching...\n[Dispatch subagent → synthesis]\n```\n\n**Eliminate redundancy:**\n- Don''t repeat what''s in cross-referenced skills\n- Don''t explain what''s obvious from command\n- Don''t include multiple examples of same pattern\n\n**Verification:**\n```bash\nwc -w skills/path/SKILL.md\n# getting-started workflows: aim for <150 each\n# Other frequently-loaded: aim for <200 total\n```\n\n**Name by what you DO or core insight:**\n- ✅ `condition-based-waiting` > `async-test-helpers`\n- ✅ `using-skills` not `skill-usage`\n- ✅ `flatten-with-flags` > `data-structure-refactoring`\n- ✅ `root-cause-tracing` > `debugging-techniques`\n\n**Gerunds (-ing) work well for processes:**\n- `creating-skills`, `testing-skills`, `debugging-with-logs`\n- Active, describes the action you''re taking\n\n### 4. Cross-Referencing Other Skills\n\n**When writing documentation that references other skills:**\n\nUse skill name only, with explicit requirement markers:\n- ✅ Good: `**REQUIRED SUB-SKILL:** Use superpowers:test-driven-development`\n- ✅ Good: `**REQUIRED BACKGROUND:** You MUST understand superpowers:systematic-debugging`\n- ❌ Bad: `See skills/testing/test-driven-development` (unclear if required)\n- ❌ Bad: `@skills/testing/test-driven-development/SKILL.md` (force-loads, burns context)\n\n**Why no @ links:** `@` syntax force-loads files immediately, consuming 200k+ context before you need them.\n\n## Flowchart Usage\n\n```dot\ndigraph when_flowchart {\n    \"Need to show information?\" [shape=diamond];\n    \"Decision where I might go wrong?\" [shape=diamond];\n    \"Use markdown\" [shape=box];\n    \"Small inline flowchart\" [shape=box];\n\n    \"Need to show information?\" -> \"Decision where I might go wrong?\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Small inline flowchart\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Use markdown\" [label=\"no\"];\n}\n```\n\n**Use flowcharts ONLY for:**\n- Non-obvious decision points\n- Process loops where you might stop too early\n- \"When to use A vs B\" decisions\n\n**Never use flowcharts for:**\n- Reference material → Tables, lists\n- Code examples → Markdown blocks\n- Linear instructions → Numbered lists\n- Labels without semantic meaning (step1, helper2)\n\nSee @graphviz-conventions.dot for graphviz style rules.\n\n**Visualizing for your human partner:** Use `render-graphs.js` in this directory to render a skill''s flowcharts to SVG:\n```bash\n./render-graphs.js ../some-skill           # Each diagram separately\n./render-graphs.js ../some-skill --combine # All diagrams in one SVG\n```\n\n## Code Examples\n\n**One excellent example beats many mediocre ones**\n\nChoose most relevant language:\n- Testing techniques → TypeScript/JavaScript\n- System debugging → Shell/Python\n- Data processing → Python\n\n**Good example:**\n- Complete and runnable\n- Well-commented explaining WHY\n- From real scenario\n- Shows pattern clearly\n- Ready to adapt (not generic template)\n\n**Don''t:**\n- Implement in 5+ languages\n- Create fill-in-the-blank templates\n- Write contrived examples\n\nYou''re good at porting - one great example is enough.\n\n## File Organization\n\n### Self-Contained Skill\n```\ndefense-in-depth/\n  SKILL.md    # Everything inline\n```\nWhen: All content fits, no heavy reference needed\n\n### Skill with Reusable Tool\n```\ncondition-based-waiting/\n  SKILL.md    # Overview + patterns\n  example.ts  # Working helpers to adapt\n```\nWhen: Tool is reusable code, not just narrative\n\n### Skill with Heavy Reference\n```\npptx/\n  SKILL.md       # Overview + workflows\n  pptxgenjs.md   # 600 lines API reference\n  ooxml.md       # 500 lines XML structure\n  scripts/       # Executable tools\n```\nWhen: Reference material too large for inline\n\n## The Iron Law (Same as TDD)\n\n```\nNO SKILL WITHOUT A FAILING TEST FIRST\n```\n\nThis applies to NEW skills AND EDITS to existing skills.\n\nWrite skill before testing? Delete it. Start over.\nEdit skill without testing? Same violation.\n\n**No exceptions:**\n- Not for \"simple additions\"\n- Not for \"just adding a section\"\n- Not for \"documentation updates\"\n- Don''t keep untested changes as \"reference\"\n- Don''t \"adapt\" while running tests\n- Delete means delete\n\n**REQUIRED BACKGROUND:** The superpowers:test-driven-development skill explains why this matters. Same principles apply to documentation.\n\n## Testing All Skill Types\n\nDifferent skill types need different test approaches:\n\n### Discipline-Enforcing Skills (rules/requirements)\n\n**Examples:** TDD, verification-before-completion, designing-before-coding\n\n**Test with:**\n- Academic questions: Do they understand the rules?\n- Pressure scenarios: Do they comply under stress?\n- Multiple pressures combined: time + sunk cost + exhaustion\n- Identify rationalizations and add explicit counters\n\n**Success criteria:** Agent follows rule under maximum pressure\n\n### Technique Skills (how-to guides)\n\n**Examples:** condition-based-waiting, root-cause-tracing, defensive-programming\n\n**Test with:**\n- Application scenarios: Can they apply the technique correctly?\n- Variation scenarios: Do they handle edge cases?\n- Missing information tests: Do instructions have gaps?\n\n**Success criteria:** Agent successfully applies technique to new scenario\n\n### Pattern Skills (mental models)\n\n**Examples:** reducing-complexity, information-hiding concepts\n\n**Test with:**\n- Recognition scenarios: Do they recognize when pattern applies?\n- Application scenarios: Can they use the mental model?\n- Counter-examples: Do they know when NOT to apply?\n\n**Success criteria:** Agent correctly identifies when/how to apply pattern\n\n### Reference Skills (documentation/APIs)\n\n**Examples:** API documentation, command references, library guides\n\n**Test with:**\n- Retrieval scenarios: Can they find the right information?\n- Application scenarios: Can they use what they found correctly?\n- Gap testing: Are common use cases covered?\n\n**Success criteria:** Agent finds and correctly applies reference information\n\n## Common Rationalizations for Skipping Testing\n\n| Excuse | Reality |\n|--------|---------|  \n| \"Skill is obviously clear\" | Clear to you ≠ clear to other agents. Test it. |\n| \"It''s just a reference\" | References can have gaps, unclear sections. Test retrieval. |\n| \"Testing is overkill\" | Untested skills have issues. Always. 15 min testing saves hours. |\n| \"I''ll test if problems emerge\" | Problems = agents can''t use skill. Test BEFORE deploying. |\n| \"Too tedious to test\" | Testing is less tedious than debugging bad skill in production. |\n| \"I''m confident it''s good\" | Overconfidence guarantees issues. Test anyway. |\n| \"Academic review is enough\" | Reading ≠ using. Test application scenarios. |\n| \"No time to test\" | Deploying untested skill wastes more time fixing it later. |\n\n**All of these mean: Test before deploying. No exceptions.**\n\n## Bulletproofing Skills Against Rationalization\n\nSkills that enforce discipline (like TDD) need to resist rationalization. Agents are smart and will find loopholes when under pressure.\n\n**Psychology note:** Understanding WHY persuasion techniques work helps you apply them systematically. See persuasion-principles.md for research foundation (Cialdini, 2021; Meincke et al., 2025) on authority, commitment, scarcity, social proof, and unity principles.\n\n### Close Every Loophole Explicitly\n\nDon''t just state the rule - forbid specific workarounds:\n\n<Bad>\n```markdown\nWrite code before test? Delete it.\n```\n</Bad>\n\n<Good>\n```markdown\nWrite code before test? Delete it. Start over.\n\n**No exceptions:**\n- Don''t keep it as \"reference\"\n- Don''t \"adapt\" it while writing tests\n- Don''t look at it\n- Delete means delete\n```\n</Good>\n\n### Address \"Spirit vs Letter\" Arguments\n\nAdd foundational principle early:\n\n```markdown\n**Violating the letter of the rules is violating the spirit of the rules.**\n```\n\nThis cuts off entire class of \"I''m following the spirit\" rationalizations.\n\n### Build Rationalization Table\n\nCapture rationalizations from baseline testing (see Testing section below). Every excuse agents make goes in the table:\n\n```markdown\n| Excuse | Reality |\n|--------|---------|  \n| \"Too simple to test\" | Simple code breaks. Test takes 30 seconds. |\n| \"I''ll test after\" | Tests passing immediately prove nothing. |\n| \"Tests after achieve same goals\" | Tests-after = \"what does this do?\" Tests-first = \"what should this do?\" |\n```\n\n### Create Red Flags List\n\nMake it easy for agents to self-check when rationalizing:\n\n```markdown\n## Red Flags - STOP and Start Over\n\n- Code before test\n- \"I already manually tested it\"\n- \"Tests after achieve the same purpose\"\n- \"It''s about spirit not ritual\"\n- \"This is different because...\"\n\n**All of these mean: Delete code. Start over with TDD.**\n```\n\n### Update CSO for Violation Symptoms\n\nAdd to description: symptoms of when you''re ABOUT to violate the rule:\n\n```yaml\ndescription: use when implementing any feature or bugfix, before writing implementation code\n```\n\n## RED-GREEN-REFACTOR for Skills\n\nFollow the TDD cycle:\n\n### RED: Write Failing Test (Baseline)\n\nRun pressure scenario with subagent WITHOUT the skill. Document exact behavior:\n- What choices did they make?\n- What rationalizations did they use (verbatim)?\n- Which pressures triggered violations?\n\nThis is \"watch the test fail\" - you must see what agents naturally do before writing the skill.\n\n### GREEN: Write Minimal Skill\n\nWrite skill that addresses those specific rationalizations. Don''t add extra content for hypothetical cases.\n\nRun same scenarios WITH skill. Agent should now comply.\n\n### REFACTOR: Close Loopholes\n\nAgent found new rationalization? Add explicit counter. Re-test until bulletproof.\n\n**Testing methodology:** See @testing-skills-with-subagents.md for the complete testing methodology:\n- How to write pressure scenarios\n- Pressure types (time, sunk cost, authority, exhaustion)\n- Plugging holes systematically\n- Meta-testing techniques\n\n## Anti-Patterns\n\n### ❌ Narrative Example\n\"In session 2025-10-03, we found empty projectDir caused...\"\n**Why bad:** Too specific, not reusable\n\n### ❌ Multi-Language Dilution\nexample-js.js, example-py.py, example-go.go\n**Why bad:** Mediocre quality, maintenance burden\n\n### ❌ Code in Flowcharts\n```dot\nstep1 [label=\"import fs\"];\nstep2 [label=\"read file\"];\n```\n**Why bad:** Can''t copy-paste, hard to read\n\n### ❌ Generic Labels\nhelper1, helper2, step3, pattern4\n**Why bad:** Labels should have semantic meaning\n\n## STOP: Before Moving to Next Skill\n\n**After writing ANY skill, you MUST STOP and complete the deployment process.**\n\n**Do NOT:**\n- Create multiple skills in batch without testing each\n- Move to next skill before current one is verified\n- Skip testing because \"batching is more efficient\"\n\n**The deployment checklist below is MANDATORY for EACH skill.**\n\nDeploying untested skills = deploying untested code. It''s a violation of quality standards.\n\n## Skill Creation Checklist (TDD Adapted with BD)\n\n**IMPORTANT: Create bd issues for EACH checklist item below.**\n\n```bash\n# Create checklist items as bd issues\nbd create \"RED: Create pressure scenarios\" --type task --priority 1\nbd create \"RED: Run baseline tests without skill\" --type task --priority 1 --deps blocks:<previous>\nbd create \"RED: Document baseline behavior\" --type task --priority 1 --deps blocks:<previous>\nbd create \"GREEN: Write minimal skill\" --type task --priority 1 --deps blocks:<previous>\nbd create \"GREEN: Run tests WITH skill\" --type task --priority 1 --deps blocks:<previous>\nbd create \"REFACTOR: Identify new rationalizations\" --type task --priority 2 --deps blocks:<previous>\nbd create \"REFACTOR: Close loopholes\" --type task --priority 2 --deps blocks:<previous>\nbd create \"Quality: CSO optimization\" --type task --priority 2\nbd create \"Deploy: Commit and push\" --type task --priority 3 --deps blocks:<all-previous>\n```\n\n**RED Phase - Write Failing Test:**\n- [ ] Create pressure scenarios (3+ combined pressures for discipline skills)\n- [ ] Run scenarios WITHOUT skill - document baseline behavior verbatim\n- [ ] Identify patterns in rationalizations/failures\n\n**GREEN Phase - Write Minimal Skill:**\n- [ ] Name uses only letters, numbers, hyphens (no parentheses/special chars)\n- [ ] YAML frontmatter with only name and description (max 1024 chars)\n- [ ] Description starts with \"Use when...\" and includes specific triggers/symptoms\n- [ ] Description written in third person\n- [ ] Keywords throughout for search (errors, symptoms, tools)\n- [ ] Clear overview with core principle\n- [ ] Address specific baseline failures identified in RED\n- [ ] Code inline OR link to separate file\n- [ ] One excellent example (not multi-language)\n- [ ] Run scenarios WITH skill - verify agents now comply\n\n**REFACTOR Phase - Close Loopholes:**\n- [ ] Identify NEW rationalizations from testing\n- [ ] Add explicit counters (if discipline skill)\n- [ ] Build rationalization table from all test iterations\n- [ ] Create red flags list\n- [ ] Re-test until bulletproof\n\n**Quality Checks:**\n- [ ] Small flowchart only if decision non-obvious\n- [ ] Quick reference table\n- [ ] Common mistakes section\n- [ ] No narrative storytelling\n- [ ] Supporting files only for tools or heavy reference\n\n**Deployment:**\n- [ ] Commit skill to git and push to your fork (if configured)\n- [ ] Consider contributing back via PR (if broadly useful)\n\n## Discovery Workflow\n\nHow future Claude finds your skill:\n\n1. **Encounters problem** (\"tests are flaky\")\n3. **Finds SKILL** (description matches)\n4. **Scans overview** (is this relevant?)\n5. **Reads patterns** (quick reference table)\n6. **Loads example** (only when implementing)\n\n**Optimize for this flow** - put searchable terms early and often.\n\n## The Bottom Line\n\n**Creating skills IS TDD for process documentation.**\n\nSame Iron Law: No skill without failing test first.\nSame cycle: RED (baseline) → GREEN (write skill) → REFACTOR (close loopholes).\nSame benefits: Better quality, fewer surprises, bulletproof results.\n\nIf you follow TDD for code, follow it for skills. It''s the same discipline applied to documentation."},"lastSynced":"2026-03-08T02:07:04.713Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and Codex that require advanced process documentation and test-driven development capabilities.","zh":"适用于Claude Code和Codex等需要高级流程文档和测试驱动开发能力的AI代理。","ja":"Claude CodeやCodexのような高度なプロセス文書化とテスト駆動開発機能を必要とするAIエージェントに適しています。","ko":"클라우드 코드와 코덱스 같은 고급 프로세스 문서화 및 테스트 주도 개발 기능을 필요로 하는 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Claude Code y Codex que requieren documentación de procesos avanzada y capacidades de desarrollo dirigido por pruebas.","fr":"Idéal pour les agents IA comme Claude Code et Codex qui nécessitent une documentation de processus avancée et des capacités de développement piloté par les tests.","de":"Ideal für KI-Agents wie Claude Code und Codex, die eine erweiterte Prozessdokumentation und Test-Driven-Development-Fähigkeiten erfordern.","pt":"Ideal para Agentes de IA como Claude Code e Codex que requerem documentação de processo avançada e capacidades de desenvolvimento orientado a testes.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и Codex, которые требуют передовой документации процесса и возможностей разработки, управляемой тестированием.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude Code و Codex الذين يتطلبون توثيق عملية متقدم وقدرات التطوير الموجهة بالاختبار."},"recommendation":{"en":"Empowers agents to apply Test-Driven Development to process documentation, utilizing pressure scenarios with subagents and org-mode for GTD, thereby ensuring compliance and closing loopholes through continuous refactoring and testing with libraries like GTD and org-mode.","zh":"赋予代理应用测试驱动开发到流程文档，利用压力场景与子代理和org-mode进行GTD，从而通过持续重构和测试确保合规性并关闭漏洞，使用类似GTD和org-mode的库。","ja":"エージェントがプロセス文書化にテスト駆動開発を適用できるようにし、サブエージェントとorg-modeを使用した圧力シナリオでGTDを行い、GTDやorg-modeのようなライブラリを使用して継続的なリファクタリングとテストを通じてコンプライアンスを確保し、抜け穴を閉じます。","ko":"에이전트가 프로세스 문서화에 테스트 주도 개발을 적용할 수 있도록 하여, 하위 에이전트 및 org-mode를 사용한 압력 시나리오로 GTD를 수행하고, GTD 및 org-mode와 같은 라이브러리를 사용하여 지속적인 리팩토링 및 테스트를 통해 규정 준수를 보장하고, 취약점을 제거합니다.","es":"Habilita a los agentes a aplicar el Desarrollo Dirigido por Pruebas a la documentación de procesos, utilizando escenarios de presión con subagentes y org-mode para GTD, garantizando así el cumplimiento y cerrando lagunas a través de la refactorización y prueba continua con bibliotecas como GTD y org-mode.","fr":"Permet aux agents d''appliquer le développement piloté par les tests à la documentation de processus, en utilisant des scénarios de pression avec des sous-agents et org-mode pour GTD, assurant ainsi la conformité et fermant les lacunes grâce à une refactorisation et à des tests continus avec des bibliothèques comme GTD et org-mode.","de":"Ermöglicht es Agenten, Test-Driven Development auf die Prozessdokumentation anzuwenden, indem Druckszenarien mit Subagenten und org-mode für GTD verwendet werden, um so die Einhaltung zu gewährleisten und Lücken durch kontinuierliches Refaktorieren und Testen mit Bibliotheken wie GTD und org-mode zu schließen.","pt":"Habilita os agentes a aplicar o Desenvolvimento Orientado a Testes à documentação de processo, utilizando cenários de pressão com subagentes e org-mode para GTD, garantindo assim a conformidade e fechando lacunas por meio de refatoração e teste contínuos com bibliotecas como GTD e org-mode.","ru":"Наделяет агентов возможностью применять разработку, управляемую тестированием, к документации процесса, используя сценарии давления с субагентами и org-mode для GTD, обеспечивая тем самым соблюдение требований и устранение лазеек посредством непрерывной рефакторинга и тестирования с использованием библиотек, таких как GTD и org-mode.","ar":"يمنح الوكيل تطبيق التطوير الموجه بالاختبار على توثيق العملية، باستخدام سيناريوهات الضغط مع الوكلاء التابعين و org-mode من أجل GTD، وبالتالي ضمان الامتثال وإغلاق الثغرات من خلال إعادة هيكلة وتجريب مستمر مع مكتبات مثل GTD و org-mode."},"useCases":{"en":["Writing test cases for process documentation","Debugging agent behavior with pressure scenarios","Refactoring skills for improved compliance and efficiency"],"zh":["为流程文档编写测试用例","使用压力场景调试代理行为","为了提高合规性和效率而重构技能"],"ja":["プロセス文書化のテストケースを書くこと","圧力シナリオを使用してエージェントの動作をデバッグすること","コンプライアンスと効率を向上させるためにスキルをリファクタリングすること"],"ko":["프로세스 문서화를 위한 테스트 케이스 작성","압력 시나리오를 사용한 에이전트 동작 디버깅","준수 및 효율성을 개선하기 위한 스킬 리팩토링"],"es":["Escribir casos de prueba para la documentación de procesos","Depurar el comportamiento del agente con escenarios de presión","Reestructurar habilidades para mejorar el cumplimiento y la eficiencia"],"fr":["Écrire des cas de test pour la documentation de processus","Déboguer le comportement de l''agent avec des scénarios de pression","Réorganiser les compétences pour améliorer la conformité et l''efficacité"],"de":["Testfälle für die Prozessdokumentation schreiben","Das Verhalten des Agents mit Druckszenarien debuggen","Fähigkeiten für verbesserte Einhaltung und Effizienz umstrukturieren"],"pt":["Escrever casos de teste para documentação de processo","Depurar comportamento do agente com cenários de pressão","Refatorar habilidades para melhorar a conformidade e a eficiência"],"ru":["Написание тестовых случаев для документации процесса","Отладка поведения агента с помощью сценариев давления","Рефакторинг навыков для улучшения соблюдения требований и эффективности"],"ar":["كتابة حالات اختبار لتوثيق العملية","تصحيح سلوك الوكيل باستخدام سيناريوهات الضغط","إعادة هيكلة المهارات لتحسين الامتثال والكفاءة"]},"limitations":{"en":["Requires agent-specific directories for skill storage","Dependent on GTD with org-mode for process documentation","Needs continuous testing and refactoring for optimal performance"],"zh":["需要代理特定目录来存储技能","依赖于GTD和org-mode进行流程文档","需要持续测试和重构以获得最佳性能"],"ja":["スキルを保存するためにエージェント固有のディレクトリが必要","GTDとorg-modeを使用したプロセス文書化に依存","最適なパフォーマンスを得るために継続的なテストとリファクタリングが必要"],"ko":["스킬을 저장하기 위해 에이전트 고유의 디렉토리가 필요함","GTD 및 org-mode를 사용한 프로세스 문서화에 의존함","최적의 성능을 얻기 위해 지속적인 테스트 및 리팩토링이 필요함"],"es":["Requiere directorios específicos de agente para el almacenamiento de habilidades","Depende de GTD con org-mode para la documentación de procesos","Necesita pruebas y refactorización continuas para un rendimiento óptimo"],"fr":["Nécessite des répertoires spécifiques à l''agent pour le stockage des compétences","Dépend de GTD avec org-mode pour la documentation de processus","Nécessite des tests et une refactorisation continus pour des performances optimales"],"de":["Benötigt agentenspezifische Verzeichnisse für die Speicherung von Fähigkeiten","Hängt von GTD mit org-mode für die Prozessdokumentation ab","Benötigt kontinuierliche Tests und Refaktorierung für optimale Leistung"],"pt":["Requer diretórios específicos do agente para armazenamento de habilidades","Depende do GTD com org-mode para documentação de processo","Necessita testes e refatoração contínuos para desempenho ótimo"],"ru":["Требует агент-специфических директорий для хранения навыков","Зависит от GTD с org-mode для документации процесса","Требует непрерывного тестирования и рефакторинга для оптимальной производительности"],"ar":["يتطلب أدلة محددة للوكيل لتخزين المهارات","يعتمد على GTD مع org-mode لتوثيق العملية","يحتاج إلى اختبار وإعادة هيكلة مستمرين لأداء مثالي"]},"version":4},"contentHash":"7021abf950802a3ea7e80f76ac7cfd2c09dc19dbf362a7dd5b10e2679e70c07c","qualityScore":60}');
