INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Trevoke/org-gtd.el/writing-skills', 'writing-skills', 'Trevoke', 'org-gtd.el', 'community', 'writing-skills Trevoke org-gtd.el community Writing-Skills applies Test-Driven Development to process documentation, benefiting developers who use GTD with org-mode. It enables users to write test cases, watch them fail, and then pass with the written skill. writing-skills 是一种将测试驱动开发应用于文档化过程的技术，通过写测试用例和重构来确保文档的质量 Writing Skills は、テスト駆動開発を文書化プロセスに適用することで、エージェントのコンプライアンスを高める技術です writing-skills 는 문서화 프로세스에 테스트 주도 개발을 적용하여 문서의 품질을 보장하는 기술입니다 Writing-skills es una herramienta de Agente de Inteligencia Artificial que aplica el desarrollo dirigido por pruebas a la documentación de procesos con GTD y org-mode Writing-skills est un outil d''Agent d''Intelligence Artificielle qui applique le développement dirigé par les tests à la documentation de processus avec GTD et org-mode Writing-skills ist ein Tool für künstliche Intelligenz-Agenten, das das testgetriebene Entwicklung auf die Prozessdokumentation mit GTD und org-mode anwendet Habilidades de escrita aplicam o desenvolvimento orientado a testes à documentação de processos em org-mode Навыки письма применяют тест-ориентированное развитие к документации процессов в org-mode مهارات الكتابة تطبق التطوير الموجه بالاختبار لتدوين العملية في org-mode how to use writing-skills writing-skills alternative writing-skills setup guide what is writing-skills writing-skills vs org-mode writing-skills install for GTD writing-skills 测试驱动开发 文档化过程 GTD org-mode AIエージェント 文档质量 测试用例 Applies Test-Driven Development to process documentation Utilizes agent-specific directories (~/.claude/skills, ~/.codex/skills) Enables writing test cases with pressure scenarios and subagents Supports watching tests fail and pass with the written skill Allows refactoring to close loopholes in documentation Writing-skills is a package for using GTD with org-mode, applying Test-Driven Development principles to process documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('renato0307/rocha/done', 'community', 'renato0307', 'rocha', 'renato0307/rocha', 'done', 0, 0, 60, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:06.893Z', '00822b6f95132b406f616079d32b4add3e58a24b0b3570bb9a34afbe04743930', '{"id":"renato0307/rocha/done","name":"done","description":{"en":"The done skill helps developers manage code agents, guiding them through task completion workflows. It ensures git history appears human-authored, following conventional commit formats.","zh":"Done 代码管理代理是一种帮助开发者管理代码的工具，提供任务完成工作流和代码提交规则","ja":"Done AIエージェントは、開発者がコードを管理するためのタスク完了ワークフローとコード提交ルールを提供するツールです","ko":"Done 코드 에이전트는 개발자가 코드를 관리하는 데 도움을 주는 도구로, 작업 완료 워크플ロー와 코드 제출 규칙을 제공합니다","es":"El skill ''done'' ayuda a gestionar agentes de código, garantizando commits y solicitudes de extracción limpios y convencionales","fr":"Le skill ''done'' aide à gérer les agents de code, assurant des commits et des demandes d''extraction propres et conventionnels","de":"Der ''done''-Skill hilft bei der Verwaltung von Code-Agents, um saubere und konventionelle Commits und Pull-Requests zu gewährleisten","pt":"O agente de código ''done'' ajuda a gerenciar tarefas de desenvolvimento. Siga as dicas para commit, rebase e criar pull requests.","ru":"ИИ агент ''done'' помогает управлять задачами разработки. Следуйте советам для коммита, ребейза и создания пулл-реквестов.","ar":"يوفر وكيل الشفرة ''done'' إدارة لمهام التطوير. اتبع النصائح لتأكيد، إعادة التركيب وإنشاء طلبات السحب."},"seo":{"title":{"en":"done: Task Completion Workflow Setup Guide | AI Agent Skill","zh":"Done 代码管理代理设置指南","ja":"Done AIエージェントのベストプラクティス","ko":"Done 코드 에이전트 설정 가이드","es":"Guía de Configuración de ''done'' para Agentes de Código","fr":"Configurer ''done'' pour les Agents de Code : Meilleures Pr...","de":"Einrichtungsleitfaden für ''done'' in der Code-Agenten-Verw...","pt":"Guia de Configuração do Agente de Código ''done'' para Dese...","ru":"Настройка ИИ Агента ''done'' для Разработчиков: Руководство","ar":"دليل إعداد وكيل الشفرة ''done'' لأغراض التطوير"},"description":{"en":"Master task completion with done! Learn how to commit changes, rebase on main, and create pull requests like a pro. Get started now!","zh":"了解 Done 代码管理代理的设置步骤和关键规则，实现高效的代码管理","ja":"Done AIエージェントを使用してコード管理を効率化するためのベストプラクティスと設定方法","ko":"Done 코드 에이전트를 설정하고 사용하는 방법을 알아보세요. 효율적인 코드 관리를 위한 핵심 규칙과 단계","es":"Aprende a configurar ''done'' para gestionar agentes de código de manera efectiva y seguir las reglas críticas para commits y solicitudes de extracción","fr":"Découvrez comment configurer ''done'' pour gérer les agents de code et respecter les règles critiques pour les commits et les demandes d''extraction","de":"Erfahren Sie, wie Sie ''done'' für die Code-Agenten-Verwaltung einrichten und die kritischen Regeln für Commits und Pull-Requests befolgen","pt":"Aprenda a configurar o agente de código ''done'' para melhorar sua produtividade de desenvolvimento com dicas e práticas recomendadas.","ru":"Узнайте, как настроить ИИ агент ''done'' для повышения производительности разработки с помощью советов и рекомендаций.","ar":"تعلم كيفية إعداد وكيل الشفرة ''done'' لتحسين إنتاجية التطوير باستخدام نصائح وأفضل الممارسات."},"definition":{"en":"done is a code agent management skill that streamlines task completion workflows, enforcing critical rules for git history and commit formats.","zh":"Done 代码管理代理是一种自动化代码管理工具","ja":"Done AIエージェントは、コード管理を自動化するためのツールです","ko":"Done 코드 에이전트는 코드 관리를 자동화하는 도구입니다","es":"El skill ''done'' es una herramienta de gestión de agentes de código que garantiza la calidad de los commits y solicitudes de extracción","fr":"Le skill ''done'' est un outil de gestion d''agents de code qui assure la qualité des commits et des demandes d''extraction","de":"Der ''done''-Skill ist ein Tool zur Verwaltung von Code-Agents, das die Qualität von Commits und Pull-Requests sicherstellt","pt":"O que é o agente de código ''done''? É uma ferramenta para gerenciar o fluxo de trabalho de desenvolvimento.","ru":"Что такое ИИ агент ''done''? Это инструмент для управления рабочим процессом разработки.","ar":"ما هو وكيل الشفرة ''done''? إنه أداة لإدارة تدفق عمل التطوير."},"features":{"en":["Enforces conventional commit format: <type>: <description>","Runs pre-flight checks sequentially, including git verification","Creates pull requests while maintaining human-authored git history","Rebases on main branch for seamless integration","Excludes AI tool references in commits, PRs, and code comments"],"zh":["任务完成工作流","代码提交规则","Git 历史记录管理","代码提交格式规范","预飞行检查"],"ja":["タスク完了ワークフロー","コード提交ルール","Git 歴史レコード管理","コード提交フォーマット規範","プレフライトチェック"],"ko":["작업 완료 워크플ロー","코드 제출 규칙","Git 기록 관리","코드 제출 형식 규칙","프리플ライト 체크"],"es":["Verificación de commits con formato convencional","Rebase en la rama principal antes de crear solicitudes de extracción","Creación de solicitudes de extracción limpias y documentadas","Evitación de referencias a herramientas de IA en commits y solicitudes de extracción","Seguimiento de reglas críticas para garantizar la calidad del código"],"fr":["Vérification des commits avec un format conventionnel","Rebase sur la branche principale avant de créer des demandes d''extraction","Création de demandes d''extraction propres et documentées","Évitement des références aux outils d''IA dans les commits et les demandes d''extraction","Suivi des règles critiques pour assurer la qualité du code"],"de":["Überprüfung von Commits mit konventionellem Format","Rebase auf dem Hauptzweig vor der Erstellung von Pull-Requests","Erstellung von sauberen und dokumentierten Pull-Requests","Vermeidung von Verweisen auf KI-Tools in Commits und Pull-Requests","Einhalten kritischer Regeln zur Gewährleistung der Code-Qualität"],"pt":["Suporte ao fluxo de trabalho de conclusão de tarefas","Verificação de pré-voo para garantir a integridade do código","Rebase e criação de pull requests","Formatação de commit convencional","Histórico do Git que aparece como criado por humanos"],"ru":["Поддержка рабочего процесса завершения задач","Предполетные проверки для обеспечения целостности кода","Ребейз и создание пулл-реквестов","Конвенциональный формат коммита","История Git, которая выглядит как созданная человеком"],"ar":["دعم تدفق عمل إكمال المهام","فحص ما قبل الطيران لضمان صحة الشفرة","إعادة التركيب وإنشاء طلبات السحب","تنسيق التأكيد التقليدي","تاريخ Git الذي يبدو وكأنه من صنع الإنسان"]},"keywords":{"en":["how to use done","done setup guide","git workflow management","conventional commit format","task completion workflow","done alternative","done vs gitflow","done install","what is done"],"zh":["代码管理代理","Done 设置指南","代码提交规则","Git 历史记录管理","代码管理工具","自动化代码管理"],"ja":["AIエージェント","Done ベストプラクティス","コード提交ルール","Git 歴史レコード管理","コード管理ツール","自動化コード管理"],"ko":["코드 에이전트","Done 설정 가이드","코드 제출 규칙","Git 기록 관리","코드 관리 도구","자동화 코드 관리"],"es":["agentes de código","herramientas de IA","commits","solicitudes de extracción","gestión de código","reglas críticas","calidad del código","desarrollo de software","integración continua"],"fr":["agents de code","outils d''IA","commits","demandes d''extraction","gestion de code","règles critiques","qualité du code","développement de logiciels","intégration continue"],"de":["Code-Agents","KI-Tools","Commits","Pull-Requests","Code-Verwaltung","kritische Regeln","Code-Qualität","Software-Entwicklung","kontinuierliche Integration"],"pt":["agente de código","desenvolvimento de software","fluxo de trabalho de desenvolvimento","commit","rebase","pull request","ferramentas de desenvolvimento","produtividade de desenvolvimento"],"ru":["ИИ агент","разработка программного обеспечения","рабочий процесс разработки","коммит","ребейз","пулл-реквест","инструменты разработки","производительность разработки"],"ar":["وكيل الشفرة","تطوير البرمجيات","تدفق عمل التطوير","التأكيد","إعادة التركيب","طلبات السحب","أدوات التطوير","إنتاجية التطوير"]}},"owner":"renato0307","repo":"rocha","repoPath":"renato0307/rocha","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"done","description":"Finish a task by committing changes, rebasing on main, and creating a PR","bodyPreview":"# Task Completion Workflow\n\nYou are finishing a development task. Follow these steps in order to commit changes, rebase on main, and create a pull request.\n\n## CRITICAL RULES\n\n- **NEVER** include AI tool references in commits, PRs, or code comments\n- **NO** \"Co-Authored-By: Claude\" or similar AI attributions\n- All git history must appear human-authored\n- Follow conventional commit format: `<type>: <description>`\n\n## Step 1: Pre-flight Checks\n\nRun these checks **sequentially**:\n\n1. Verify in git","body":"# Task Completion Workflow\n\nYou are finishing a development task. Follow these steps in order to commit changes, rebase on main, and create a pull request.\n\n## CRITICAL RULES\n\n- **NEVER** include AI tool references in commits, PRs, or code comments\n- **NO** \"Co-Authored-By: Claude\" or similar AI attributions\n- All git history must appear human-authored\n- Follow conventional commit format: `<type>: <description>`\n\n## Step 1: Pre-flight Checks\n\nRun these checks **sequentially**:\n\n1. Verify in git repository:\n   ```bash\n   git rev-parse --git-dir\n   ```\n\n2. Get current branch:\n   ```bash\n   git branch --show-current\n   ```\n\n3. Check for changes:\n   ```bash\n   git status --porcelain\n   ```\n\n**Stop conditions:**\n- If not in git repo → **Error**: \"Not in a git repository\"\n- If on `main` branch → **Error**: \"Cannot commit directly to main branch. Create a feature branch first.\"\n- If no changes (empty output) → **Error**: \"No changes to commit\"\n\nIf all checks pass, proceed to Step 2.\n\n## Step 2: Analyze and Commit Changes\n\n### 2.1 Review Changes\n\nRun these commands to understand what changed:\n\n```bash\ngit status\ngit diff HEAD\n```\n\nIf there are already staged files, also check:\n```bash\ngit diff --staged\n```\n\n### 2.2 Analyze Changes\n\nBased on the diff output, determine:\n\n- **Commit type**: Choose from:\n  - `feat` - New feature\n  - `fix` - Bug fix\n  - `refactor` - Code restructuring without behavior change\n  - `docs` - Documentation only\n  - `style` - Formatting, whitespace, missing semicolons\n  - `test` - Adding or updating tests\n  - `chore` - Build process, dependencies, tooling\n\n- **Description**: Write a concise summary (< 72 characters) that completes the sentence: \"This commit will...\"\n  - Good: \"add user authentication middleware\"\n  - Good: \"fix null pointer dereference in login handler\"\n  - Bad: \"changes\" or \"updates stuff\"\n\n- **Body** (optional): Add if the change is complex and needs explanation\n\n### 2.3 Security Check\n\nCheck if any changed files match sensitive patterns:\n```bash\ngit status --porcelain | grep -E ''\\.(env|key|pem)|credentials|secrets''\n```\n\nIf matches found:\n- **Warn the user**: \"Detected potential sensitive files: [list]. Are you sure you want to commit these?\"\n- **Wait for user confirmation** before proceeding\n- If user declines, stop here\n\n### 2.4 Stage Files\n\nPrefer staging specific files rather than using `git add .`:\n\n```bash\ngit add <file1> <file2> <file3>\n```\n\nOnly use `git add .` if justified (many files changed, all safe to commit).\n\n### 2.5 Create Commit\n\n**If $ARGUMENTS is provided**: Use it as the commit message directly:\n```bash\ngit commit -m \"$ARGUMENTS\"\n```\n\n**Otherwise**: Generate the commit message using the format:\n```\n<type>: <description>\n```\n\nExample:\n```bash\ngit commit -m \"feat: add user authentication middleware\"\n```\n\n**CRITICAL**: Do NOT add any Co-Authored-By or AI attribution trailers.\n\n### 2.6 Verify Commit\n\nCheck the commit was created:\n```bash\ngit log -1 --oneline\n```\n\nIf commit failed (pre-commit hooks, etc.):\n- Show the error message to the user\n- **STOP**: Let the user fix the issue\n- User can run `/done` again after fixing\n\n## Step 3: Rebase on origin/main\n\n### 3.1 Fetch Latest\n\nUpdate the remote tracking branches:\n```bash\ngit fetch origin\n```\n\n### 3.2 Rebase\n\nRebase current branch onto origin/main:\n```bash\ngit rebase origin/main\n```\n\n### 3.3 Handle Rebase Result\n\n**If rebase succeeds**: Proceed to Step 4.\n\n**If conflicts are detected** (non-zero exit code):\n\n**STOP** and inform the user:\n\n```\nRebase conflicts detected. To resolve:\n\n1. Check conflict status:\n   git status\n\n2. Open conflicted files and resolve conflicts (look for <<<<<<< markers)\n\n3. Stage resolved files:\n   git add <resolved-file>\n\n4. Continue the rebase:\n   git rebase --continue\n\n5. After resolving all conflicts, run /done again to create the PR\n\nTo abort the rebase:\n   git rebase --abort\n```\n\n**DO NOT** attempt automatic conflict resolution. This requires human judgment.\n\n## Step 4: Create Pull Request\n\n### 4.1 Gather Context\n\nGet branch and commit information:\n\n```bash\n# Current branch name\ngit branch --show-current\n\n# All commits in this branch (not in main)\ngit log origin/main..HEAD --oneline\n\n# Full commit details\ngit log origin/main..HEAD\n\n# Summary of changed files\ngit diff origin/main...HEAD --stat\n```\n\n### 4.2 Analyze Commits\n\nReview ALL commits in the branch to understand the overall change:\n- If **single commit**: PR title = commit message (which already includes the type prefix)\n- If **multiple commits**: Summarize the overall feature/fix with appropriate type prefix (feat, fix, refactor, etc.)\n\n### 4.3 Generate PR Title\n\n- **MUST** start with conventional commit type prefix: `feat:`, `fix:`, `refactor:`, `docs:`, `style:`, `test:`, or `chore:`\n- Use clear, concise language after the prefix\n- Keep under 72 characters total\n- No AI attribution\n\nExample titles:\n- \"feat: add user authentication middleware\"\n- \"fix: null pointer dereference in login handler\"\n- \"refactor: session management for improved performance\"\n- \"docs: add API documentation for auth endpoints\"\n- \"chore: update dependencies to latest versions\"\n\n### 4.4 Generate PR Body\n\nUse this format:\n\n```markdown\n## Summary\n\n- [Key change 1]\n- [Key change 2]\n- [Key change 3]\n\n## Test plan\n\n- [ ] [Test scenario 1]\n- [ ] [Test scenario 2]\n- [ ] [Test scenario 3]\n```\n\nGuidelines:\n- 3-5 bullet points in Summary\n- Focus on \"what\" and \"why\", not implementation details\n- Test plan should be actionable checklist items\n- **NO** \"Generated with Claude Code\" or AI attribution footer\n\n### 4.5 Push Branch (if needed)\n\nBefore creating the PR, check if the branch has been pushed:\n\n```bash\ngit rev-parse --abbrev-ref --symbolic-full-name @{u} 2>/dev/null\n```\n\n**If this command fails** (no upstream branch set):\n\nPush the branch and set upstream:\n```bash\ngit push -u origin <branch-name>\n```\n\n**If this command succeeds** (upstream branch exists):\n\nCheck if local is ahead of remote:\n```bash\ngit status -sb\n```\n\nIf the output shows `[ahead N]` or `[ahead N, behind M]`:\n- After rebase, the branch needs a force push\n- Run: `git push --force-with-lease`\n\n### 4.6 Create PR\n\nUse heredoc for proper formatting:\n\n```bash\ngh pr create --title \"PR title here\" --body \"$(cat <<''EOF''\n## Summary\n\n- Key change 1\n- Key change 2\n- Key change 3\n\n## Test plan\n\n- [ ] Test scenario 1\n- [ ] Test scenario 2\n- [ ] Test scenario 3\nEOF\n)\" --base main\n```\n\n### 4.7 Handle PR Creation Result\n\n**If successful**:\n- Display the PR URL to the user\n\n**If PR already exists**:\n- Show error message\n- If possible, extract and display the existing PR URL from the error\n- Inform user: \"A PR already exists for this branch\"\n\n**If GitHub CLI not found**:\n- Show installation instructions:\n  ```\n  GitHub CLI (gh) not found. Install it:\n  - macOS: brew install gh\n  - Linux: See https://github.com/cli/cli#installation\n\n  After installation, authenticate: gh auth login\n  ```\n\n## Error Handling\n\nFor any command that fails:\n1. Show the **exact error message** from the command\n2. Provide **actionable next steps** for the user\n3. **DO NOT** proceed to the next phase\n4. User can fix the issue and run `/done` again\n\n## Notes\n\n- The workflow automatically handles pushing the branch if needed (Step 4.5)\n- Prefer clear, atomic commits over large batch commits\n- The PR description should help reviewers understand the context quickly\n- If pre-commit hooks modify files, they''ll need to be staged and committed again\n- After rebase, force push with `--force-with-lease` is safer than `--force` (protects against overwriting others'' work)\n\n## Usage Examples\n\n**Basic usage (auto-generated commit message):**\n```\n/done\n```\n\n**With custom commit message:**\n```\n/done \"feat: add new authentication feature\"\n```\n\n**With multi-line commit message:**\n```\n/done \"feat: add authentication\n\nImplements OAuth2 flow with JWT tokens.\nIncludes session management and refresh tokens.\"\n```\n"},"lastSynced":"2026-03-08T02:07:06.893Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Management Agents requiring standardized commit formats and rebase workflows.","zh":"适用于需要标准化提交格式和变基工作流的代码管理代理。","ja":"標準化されたコミット形式とリベースワークフローを必要とするコード管理エージェントに最適です。","ko":"표준화된 커밋 형식 및 리베이스 워크플로가 필요한 코드 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de código que requieren formatos de compromiso estandarizados y flujos de trabajo de rebase.","fr":"Idéal pour les agents de gestion de code nécessitant des formats de commit standardisés et des flux de travail de rebase.","de":"Ideal für Code-Management-Agents, die standardisierte Commit-Formate und Rebase-Workflows erfordern.","pt":"Ideal para Agentes de Gerenciamento de Código que requerem formatos de commit padronizados e fluxos de trabalho de rebase.","ru":"Идеально подходит для агентов управления кодом, требующих стандартизированных форматов коммитов и рабочих процессов ребейза.","ar":"مثالي لعمليات إدارة التعليمات البرمجية التي تتطلب تنسيقات إيداع معيارية وعمليات إعادة التوجيه."},"recommendation":{"en":"Empowers agents to maintain a human-authored git history, ensuring conventional commit formats and seamless task completion workflows using git protocols, while adhering to critical rules such as excluding AI tool references in commits and PRs.","zh":"赋予代理维护人类编写的git历史记录，确保传统的提交格式和无缝的任务完成工作流，使用git协议，同时遵守关键规则，例如在提交和PR中排除AI工具引用。","ja":"エージェントに人間が書いたgit履歴を維持することを可能にし、伝統的なコミット形式とシームレスなタスク完了ワークフローを確保し、gitプロトコルを使用し、コミットおよびPRにAIツールの参照を含めないなどの重要なルールに従います。","ko":"에이전트가 인간이 작성한 git 기록을 유지할 수 있도록 해주며, 전통적인 커밋 형식과 無縫な 작업 완료 워크플ロー를 보장하며, git 프로토콜을 사용하며, 커밋 및 PR에 AI 도구 참조를 포함하지 않는 것과 같은 중요한 규칙을 준수합니다.","es":"Habilita a los agentes a mantener un historial de git creado por humanos, garantizando formatos de commit convencionales y flujos de trabajo de finalización de tareas sin problemas utilizando protocolos de git, mientras se adhieren a reglas críticas como excluir referencias de herramientas de inteligencia artificial en commits y solicitudes de extracción.","fr":"Permet aux agents de maintenir un historique git créé par l''homme, en garantissant des formats de commit conventionnels et des flux de travail de finition de tâches sans problème en utilisant les protocoles git, tout en respectant les règles critiques telles que l''exclusion des références d''outils d''intelligence artificielle dans les commits et les demandes d''extraction.","de":"Ermächtigt Agenten, ein von Menschen erstelltes git-Historie beizubehalten, wodurch konventionelle Commit-Formate und nahtlose Arbeitsablauf-Workflows unter Verwendung von git-Protokollen sichergestellt werden, während kritische Regeln wie das Ausschließen von AI-Tool-Verweisen in Commits und Pull-Requests eingehalten werden.","pt":"Permite que os agentes mantenham um histórico de git criado por humanos, garantindo formatos de commit convencionais e fluxos de trabalho de conclusão de tarefas sem interrupção usando protocolos git, ao mesmo tempo em que adere a regras críticas, como excluir referências de ferramentas de IA em commits e PRs.","ru":"Наделяет агентов возможностью поддерживать историю git, созданную человеком, обеспечивая соблюдение стандартных форматов коммитов и бесперебойные рабочие процессы выполнения задач с использованием протоколов git, при этом соблюдая критически важные правила, такие как исключение ссылок на инструменты ИИ в коммитах и PR.","ar":"تمكن الوكلاء من الحفاظ على سجل git تم إنشاؤه بواسطة الإنسان، وضمان تنسيقات الالتزام التقليدية وعمليات سير عمل إكمال المهام دون انقطاع باستخدام بروتوكولات git، مع اتباع القواعد الحرجة مثل استبعاد إشارات أدوات الذكاء الاصطناعي في الالتزامات و PR."},"useCases":{"en":["Automating commit message formatting","Rebasing code on main branches","Creating pull requests with standardized descriptions"],"zh":["自动化提交消息格式化","在主分支上重新基础代码","使用标准化描述创建拉取请求"],"ja":["コミットメッセージの形式を自動化する","メインブランチでコードを再ベースする","標準化された説明を使用してプルリクエストを作成する"],"ko":["커밋 메시지 형식 자동화","메인 브랜치에서 코드 재베이스","표준화된 설명을 사용하여 풀 리퀘스트 만들기"],"es":["Automatización del formato de mensaje de commit","Rebasar el código en ramas principales","Crear solicitudes de extracción con descripciones estandarizadas"],"fr":["Automatisation du format de message de commit","Réorganisation du code sur les branches principales","Création de demandes d''extraction avec des descriptions standardisées"],"de":["Automatisierung des Commit-Nachrichten-Formats","Neuanordnung des Codes in Hauptzweigen","Erstellung von Pull-Requests mit standardisierten Beschreibungen"],"pt":["Automação de formatação de mensagens de commit","Rebasing de código em branches principais","Criação de solicitações de pull com descrições padronizadas"],"ru":["Автоматизация форматирования сообщений коммитов","Ребейзинг кода в основных ветках","Создание запросов на принятие изменений с стандартизированными описаниями"],"ar":["أتمتة تنسيق رسائل الالتزام","إعادة توجيه التعليمات البرمجية في الفروع الرئيسية","إنشاء طلبات سحب مع описات معيارية"]},"limitations":{"en":["Requires adherence to conventional commit format","Git history must appear human-authored","No AI tool references allowed in commits or PRs"],"zh":["需要遵守传统的提交格式","git历史记录必须看起来是人类编写的","提交或PR中不允许有AI工具引用"],"ja":["伝統的なコミット形式に従う必要がある","git履歴は人間が書いたように見える必要がある","コミットまたはPRにはAIツールの参照を含めることはできない"],"ko":["전통적인 커밋 형식에 따라야 함","git 기록은 인간이 작성한 것처럼 보이게 해야 함","커밋 또는 PR에는 AI 도구 참조를 포함할 수 없음"],"es":["Requiere adherencia al formato de commit convencional","El historial de git debe parecer creado por humanos","No se permiten referencias de herramientas de inteligencia artificial en commits o solicitudes de extracción"],"fr":["Nécessite l''adérence au format de commit conventionnel","L''historique git doit apparaître comme créé par l''homme","Les références d''outils d''intelligence artificielle ne sont pas autorisées dans les commits ou les demandes d''extraction"],"de":["Erfordert die Einhaltung des konventionellen Commit-Formats","Die git-Historie muss wie von Menschen erstellt erscheinen","Keine AI-Tool-Verweise in Commits oder Pull-Requests erlaubt"],"pt":["Exige aderência ao formato de commit convencional","O histórico do git deve parecer criado por humanos","Não são permitidas referências a ferramentas de IA em commits ou PRs"],"ru":["Требует соблюдения стандартного формата коммитов","История git должна выглядеть как созданная человеком","Запрещены ссылки на инструменты ИИ в коммитах или PR"],"ar":["يتطلب اتباع تنسيق الالتزام التقليدي","يجب أن يبدو سجل git وكأنه تم إنشاؤه بواسطة الإنسان","لا يسمح بإشارات أدوات الذكاء الاصطناعي في الالتزامات أو PR"]},"version":4},"contentHash":"00822b6f95132b406f616079d32b4add3e58a24b0b3570bb9a34afbe04743930","qualityScore":60}');
