INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('miethe/deal-brain/planning', 'planning', 'miethe', 'deal-brain', 'community', 'planning miethe deal-brain community The Planning Skill generates comprehensive PRDs and Implementation Plans as AI artifacts, optimized for AI agent consumption. It benefits developers by creating phased plans with subagent task assignments. AI规划技能生成和优化产品需求文档（PRD）和实施计划，用于AI代理的文件缓存优化 AIエージェントの計画スキルは、AI代理のファイルベースのコンテキストキャッシュに最適化されたPRDと実装計画を生成および最適化します AI 플래닝 스킬은 AI 에이전트의 파일 기반 컨텍스트 캐시에 최적화된 제품 요구 사항 문서와 구현 계획을 생성 및 최적화합니다 La habilidad de planificación genera documentos de requisitos de producto y planes de implementación para agentes de IA. Optimiza la planificación existente mediante la creación de archivos token-eficientes. La compétence de planification génère des documents de spécifications de produit et des plans de mise en œuvre pour les outils d''IA. Elle optimise la planification existante en créant des fichiers token-eficients. Die Planungsfähigkeit generiert Produktanforderungsdokumente und Implementierungspläne für KI-Agenten. Sie optimiert die bestehende Planung durch die Erstellung token-efizienter Dateien. A habilidade de planejamento gera e otimiza PRDs e planos de implementação como artefatos de IA. Ela cria planos fásicos com atribuições de tarefas para subagentes. Навык планирования генерирует и оптимизирует документы требований продукта и планы реализации как артефакты ИИ. Он создает фазовые планы с назначением задач субагентам. مهارة التخطيط تولد وتحسن مستندات متطلبات المنتج وخطط التنفيذ كمخزون سياق الملفات المُحسّن لاستهلاك وكيل الذكاء الاصطناعي. وهي Creates خطط مرحلية مع تعيينات مهام للوكيل الفرعي how to use planning skill planning skill alternative planning skill setup guide what is planning skill planning skill vs project management planning skill install for AI agents product requirements document generation implementation plan optimization token-efficient file planning AI规划技能 产品需求文档 实施计划 AI代理 文件缓存优化 MP模板 进度跟踪 Generates comprehensive PRDs from feature requests following MP template Creates phased Implementation Plans with subagent task assignments Optimizes existing planning docs by breaking into token-efficient files Sets up progress tracking for AI agent consumption Uses file-based context caches for optimized AI artifact generation Planning is a skill that generates and optimizes Product Requirements Documents and Implementation Plans as AI artifacts, using file-based context caches.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Dexploarer/hyper-forge/api-gateway-configurator', 'community', 'Dexploarer', 'hyper-forge', 'Dexploarer/hyper-forge', 'api-gateway-configurator', 0, 0, 60, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:07.646Z', '17eaebca7e4360c85ecf663e2a12143a2df8a212d4cfd58fdec69cdfc1bfff29', '{"id":"Dexploarer/hyper-forge/api-gateway-configurator","name":"api-gateway-configurator","description":{"en":"The api-gateway-configurator skill helps developers configure and manage API gateways for microservices architectures, enabling features like rate limiting and API authentication. It benefits developers working with microservices.","zh":"API网关配置工具是一种AI驱动的技能，用于配置和管理微服务架构中的API网关","ja":"APIゲートウェイ設定ツールは、マイクロサービスアーキテクチャのAPIゲートウェイを設定して管理するためのAI駆動型スキルです","ko":"API 게이트웨이 설정 가이드는 마이크로 서비스 아키텍처에서 API 게이트웨이를 설정하고 관리하기 위한 AI 구동형 스킬입니다","es":"El configurador de API gateway es una herramienta para configurar y gestionar API gateways para microservicios, que incluye rate limiting, autenticación y autorización","fr":"Le configureur de passerelle API est un outil pour configurer et gérer les passerelles API pour les microservices, qui inclut la limitation de débit, l''authentification et l''autorisation","de":"Der API-Gateway-Konfigurator ist ein Tool zum Konfigurieren und Verwalten von API-Gateways für Microservice-Architekturen, das Rate Limiting, Authentifizierung und Autorisierung umfasst","pt":"O API Gateway Configurator é uma ferramenta de configuração e gerenciamento de gateways de API para microsserviços","ru":"ИИ Агент для настройки и управления шлюзами API в микросервисных архитектурах","ar":"API Gateway Configurator هو أداة لتكوين وإدارة بوابات واجهة برمجة التطبيقات للархitectures الموزعة"},"seo":{"title":{"en":"api-gateway-configurator: Setup Guide for Microservices A...","zh":"API网关配置工具：微服务架构最佳实践","ja":"APIゲートウェイ設定ツール：マイクロサービスアーキテクチャのベストプラクティス","ko":"API 게이트웨이 설정 가이드: 마이크로 서비스 아키텍처","es":"Configurador de API Gateway: Guía de configuración","fr":"Configureur de passerelle API: Meilleures pratiques","de":"API-Gateway-Konfigurator: Einrichtungsleitfaden","pt":"Guia de Configuração do API Gateway Configurator","ru":"Настройка шлюза API: ИИ Агенты для микросервисов","ar":"دليل تكوين بوابة واجهة برمجة التطبيقات API Gateway Config..."},"description":{"en":"Discover how to configure and manage API gateways for microservices with our expert guide. Learn to implement rate limiting, authentication, and more with ap...","zh":"使用AI Agent技能配置和管理API网关，实现微服务架构的高效率和安全性","ja":"AIエージェントのスキルを使用してAPIゲートウェイを設定して管理し、マイクロサービスアーキテクチャの効率とセキュリティを実現します","ko":"AI 에이전트를 사용하여 API 게이트웨이를 설정하고 관리하여 마이크로 서비스 아키텍처의 효율성과 보안을 실현합니다","es":"Descubre cómo configurar y gestionar API gateways para arquitecturas de microservicios con nuestro configurador de API gateway","fr":"Découvrez comment configurer et gérer les passerelles API pour les architectures de microservices avec notre outil de configuration de passerelle API","de":"Erfahren Sie, wie Sie API-Gateways für Microservice-Architekturen mit unserem API-Gateway-Konfigurator konfigurieren und verwalten","pt":"Aprenda a configurar e gerenciar gateways de API para arquiteturas de microsserviços com o API Gateway Configurator","ru":"Используйте ИИ Агенты для настройки и управления шлюзами API в микросервисных архитектурах","ar":"تعرف على كيفية تكوين وإدارة بوابات واجهة برمجة التطبيقات للархitectures الموزعة باستخدام API Gateway Configurator"},"definition":{"en":"api-gateway-configurator is an enterprise skill for configuring and managing API gateways, implementing features such as rate limiting, authentication, and request/response transformation.","zh":"API网关配置工具是一种用于配置和管理API网关的AI驱动技能","ja":"APIゲートウェイ設定ツールは、APIゲートウェイを設定して管理するためのAI駆動型スキルです","ko":"API 게이트웨이 설정 가이드는 API 게이트웨이를 설정하고 관리하기 위한 AI 구동형 스킬입니다","es":"Un configurador de API gateway es una herramienta que permite configurar y gestionar API gateways para microservicios","fr":"Un configureur de passerelle API est un outil qui permet de configurer et de gérer les passerelles API pour les microservices","de":"Ein API-Gateway-Konfigurator ist ein Tool, das das Konfigurieren und Verwalten von API-Gateways für Microservice-Architekturen ermöglicht","pt":"O que é API Gateway Configurator? Uma ferramenta para configurar e gerenciar gateways de API","ru":"Что такое ИИ Агент для шлюза API? Инструмент для настройки и управления шлюзами API","ar":"ما هو API Gateway Configurator? أداة لتكوين وإدارة بوابات واجهة برمجة التطبيقات"},"features":{"en":["Configures rate limiting and throttling for API gateways","Implements API authentication and authorization strategies","Supports request/response transformation and API routing","Enables API versioning strategies and load balancing","Sets up API monitoring and analytics for performance optimization","Manages API documentation for microservices architectures"],"zh":["支持微服务架构的API网关配置","实现API认证和授权","支持请求/响应转换","支持API路由和负载均衡","支持API版本控制","支持API监控和分析"],"ja":["マイクロサービスアーキテクチャのAPIゲートウェイ設定をサポート","API認証と認可を実現","リクエスト/レスポンス変換をサポート","APIルーティングと負荷分散をサポート","APIバージョニングをサポート","APIモニタリングと分析をサポート"],"ko":["마이크로 서비스 아키텍처의 API 게이트웨이 설정을 지원","API 인증과 인가 구현","요청/응답 변환 지원","API 라우팅과 부하 분산 지원","API 버전 관리 지원","API 모니터링과 분석 지원"],"es":["Configuración de rate limiting y throttling","Implementación de autenticación y autorización de API","Configuración de transformación de solicitudes y respuestas","Gestión de enrutamiento y equilibrio de carga de API","Implementación de estrategias de versionado de API","Configuración de monitoreo y análisis de API"],"fr":["Configuration de la limitation de débit et du throttling","Mise en œuvre de l''authentification et de l''autorisation d''API","Configuration de la transformation des requêtes et des réponses","Gestion du routage et de l''équilibrage de charge d''API","Mise en œuvre de stratégies de versionning d''API","Configuration du monitoring et de l''analyse d''API"],"de":["Konfiguration von Rate Limiting und Throttling","Implementierung von Authentifizierung und Autorisierung von API","Konfiguration von Anfrage- und Antworttransformation","Verwaltung von API-Routing und Lastverteilung","Implementierung von API-Versionierungsstrategien","Konfiguration von API-Monitoring und -Analyse"],"pt":["Configuração de rate limiting e throttling","Implementação de autenticação e autorização de API","Configuração de transformação de solicitação e resposta","Configuração de roteamento e balanceamento de carga de API","Implementação de estratégias de versionamento de API","Configuração de monitoramento e análise de API"],"ru":["Настройка ограничения скорости и регулирования трафика","Реализация аутентификации и авторизации API","Настройка трансформации запросов и ответов","Настройка маршрутизации и балансировки нагрузки API","Реализация стратегий версионирования API","Настройка мониторинга и анализа API"],"ar":["تكوين تحديد معدل وضبط الحمل الزائد","تنفيذ مصادقة وتصريح واجهة برمجة التطبيقات","تكوين تحويل الطلبات والاستجابات","تكوين التوجيه وتحليل الحمل لبوابة واجهة برمجة التطبيقات","تنفيذ استراتيجيات إصدار واجهة برمجة التطبيقات","تكوين مراقبة وتحليل واجهة برمجة التطبيقات"]},"keywords":{"en":["how to use api-gateway-configurator","api-gateway-configurator setup guide","api-gateway-configurator vs nginx","what is api-gateway-configurator","api-gateway-configurator install","api-gateway-configurator microservices architecture","api gateway configuration best practices","api-gateway-configurator alternative solutions","api-gateway-configurator tutorial"],"zh":["API网关配置","微服务架构","AI驱动技能","API认证","API授权","请求/响应转换","API路由","负载均衡","API版本控制","API监控"],"ja":["APIゲートウェイ設定","マイクロサービスアーキテクチャ","AI駆動型スキル","API認証","API認可","リクエスト/レスポンス変換","APIルーティング","負荷分散","APIバージョニング","APIモニタリング"],"ko":["API 게이트웨이 설정","마이크로 서비스 아키텍처","AI 구동형 스킬","API 인증","API 인가","요청/응답 변환","API 라우팅","부하 분산","API 버전 관리","API 모니터링"],"es":["configurador de API gateway","microservicios","rate limiting","autenticación de API","autorización de API","transformación de solicitudes","enrutamiento de API","equilibrio de carga de API","versionado de API","monitoreo de API"],"fr":["configureur de passerelle API","microservices","limitation de débit","authentification d''API","autorisation d''API","transformation des requêtes","routage d''API","équilibrage de charge d''API","versionning d''API","monitoring d''API"],"de":["API-Gateway-Konfigurator","Microservice-Architekturen","Rate Limiting","Authentifizierung von API","Autorisierung von API","Anfrage- und Antworttransformation","API-Routing","Lastverteilung von API","API-Versionierung","API-Monitoring"],"pt":["API Gateway Configurator","configuração de gateway de API","microsserviços","rate limiting","autenticação de API","transformação de solicitação","roteamento de API","versionamento de API"],"ru":["ИИ Агент для шлюза API","настройка шлюза API","микросервисы","ограничение скорости","аутентификация API","трансформация запросов","маршрутизация API","версионирование API"],"ar":["API Gateway Configurator","تكوين بوابة واجهة برمجة التطبيقات","الархitectures الموزعة","تحديد معدل","مصادقة واجهة برمجة التطبيقات","تحويل الطلبات","توجيه بوابة واجهة برمجة التطبيقات","إصدار واجهة برمجة التطبيقات"]}},"owner":"Dexploarer","repo":"hyper-forge","repoPath":"Dexploarer/hyper-forge","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"api-gateway-configurator","description":"Configure and manage API gateways including Kong, Tyk, AWS API Gateway, and Apigee. Activates when users need help setting up API gateways, rate limiting, authentication, request transformation, or API management.","bodyPreview":"# API Gateway Configurator\n\nEnterprise skill for configuring and managing API gateways for microservices architectures.\n\n## When to Use\n\nThis skill should be used when:\n- Setting up API gateway for microservices\n- Configuring rate limiting and throttling\n- Implementing API authentication and authorization\n- Setting up request/response transformation\n- Configuring API routing and load balancing\n- Implementing API versioning strategies\n- Setting up API monitoring and analytics\n- Managing API docum","body":"# API Gateway Configurator\n\nEnterprise skill for configuring and managing API gateways for microservices architectures.\n\n## When to Use\n\nThis skill should be used when:\n- Setting up API gateway for microservices\n- Configuring rate limiting and throttling\n- Implementing API authentication and authorization\n- Setting up request/response transformation\n- Configuring API routing and load balancing\n- Implementing API versioning strategies\n- Setting up API monitoring and analytics\n- Managing API documentation and developer portals\n\n## Instructions\n\n### Step 1: Choose API Gateway Platform\n\nSelect the appropriate API gateway based on requirements:\n\n**Kong Gateway (Open Source/Enterprise):**\n- Best for: Kubernetes-native, plugin ecosystem\n- Strengths: Performance, extensibility, cloud-native\n- Use cases: Microservices, multi-cloud, hybrid cloud\n\n**AWS API Gateway:**\n- Best for: AWS-native applications, serverless\n- Strengths: AWS integration, managed service, scalability\n- Use cases: Lambda functions, AWS services, serverless APIs\n\n**Tyk:**\n- Best for: GraphQL, multi-cloud, analytics\n- Strengths: Developer portal, analytics, open source\n- Use cases: GraphQL federation, API analytics\n\n**Apigee (Google Cloud):**\n- Best for: Enterprise API management, monetization\n- Strengths: Analytics, developer portal, API products\n- Use cases: External APIs, partner APIs, API monetization\n\n### Step 2: Configure Core Features\n\n#### Kong Configuration Example:\n\n```yaml\n# kong.yml - Declarative configuration\n_format_version: \"3.0\"\n\nservices:\n  - name: user-service\n    url: http://user-service:8080\n    routes:\n      - name: user-routes\n        paths:\n          - /api/v1/users\n        methods:\n          - GET\n          - POST\n        strip_path: false\n    plugins:\n      - name: rate-limiting\n        config:\n          minute: 100\n          policy: local\n      - name: jwt\n        config:\n          claims_to_verify:\n            - exp\n      - name: cors\n        config:\n          origins:\n            - \"*\"\n          methods:\n            - GET\n            - POST\n          headers:\n            - Accept\n            - Authorization\n          max_age: 3600\n\n  - name: order-service\n    url: http://order-service:8080\n    routes:\n      - name: order-routes\n        paths:\n          - /api/v1/orders\n    plugins:\n      - name: rate-limiting\n        config:\n          minute: 50\n      - name: request-transformer\n        config:\n          add:\n            headers:\n              - \"X-Gateway:Kong\"\n\n# Global plugins\nplugins:\n  - name: prometheus\n    config:\n      per_consumer: true\n  - name: correlation-id\n    config:\n      header_name: X-Correlation-ID\n      generator: uuid\n```\n\n#### AWS API Gateway Configuration:\n\n```yaml\n# serverless.yml for AWS API Gateway\nprovider:\n  name: aws\n  runtime: nodejs18.x\n  apiGateway:\n    apiKeys:\n      - name: premium-api-key\n        value: ${env:API_KEY}\n    usagePlan:\n      - premium:\n          quota:\n            limit: 5000\n            period: MONTH\n          throttle:\n            burstLimit: 200\n            rateLimit: 100\n    resourcePolicy:\n      - Effect: Allow\n        Principal: \"*\"\n        Action: execute-api:Invoke\n        Resource:\n          - execute-api:/*/*/*\n\nfunctions:\n  getUsers:\n    handler: users.getUsers\n    events:\n      - http:\n          path: users\n          method: get\n          cors: true\n          authorizer:\n            name: jwtAuthorizer\n            type: request\n          request:\n            parameters:\n              querystrings:\n                page: false\n                limit: false\n          throttling:\n            maxRequestsPerSecond: 100\n            maxConcurrentRequests: 50\n\n  createUser:\n    handler: users.createUser\n    events:\n      - http:\n          path: users\n          method: post\n          cors: true\n          authorizer: jwtAuthorizer\n```\n\n### Step 3: Implement Authentication & Authorization\n\n#### JWT Authentication (Kong):\n\n```yaml\n# Create JWT consumer\nconsumers:\n  - username: mobile-app\n    jwt_credentials:\n      - key: mobile-app-key\n        algorithm: HS256\n        secret: ${JWT_SECRET}\n\n# Apply JWT plugin to service\nservices:\n  - name: protected-service\n    plugins:\n      - name: jwt\n        config:\n          header_names:\n            - Authorization\n          claims_to_verify:\n            - exp\n            - nbf\n```\n\n#### OAuth2 (Kong):\n\n```yaml\nplugins:\n  - name: oauth2\n    config:\n      scopes:\n        - read\n        - write\n        - admin\n      mandatory_scope: true\n      enable_authorization_code: true\n      enable_client_credentials: true\n      enable_implicit_grant: false\n      token_expiration: 3600\n      refresh_token_ttl: 2592000\n```\n\n### Step 4: Configure Rate Limiting & Throttling\n\n```yaml\n# Kong - Multiple rate limiting strategies\nplugins:\n  # Per-consumer rate limiting\n  - name: rate-limiting\n    consumer: mobile-app\n    config:\n      second: 10\n      minute: 100\n      hour: 1000\n      policy: redis\n      redis:\n        host: redis-cluster\n        port: 6379\n        database: 0\n\n  # Advanced rate limiting\n  - name: rate-limiting-advanced\n    config:\n      limit:\n        - minute: 100\n        - hour: 1000\n      window_size:\n        - 60\n        - 3600\n      sync_rate: 10\n      strategy: cluster\n      dictionary_name: kong_rate_limiting_counters\n```\n\n### Step 5: Set Up Request/Response Transformation\n\n```yaml\n# Request transformation\nplugins:\n  - name: request-transformer\n    config:\n      add:\n        headers:\n          - \"X-Request-ID:$(uuid)\"\n          - \"X-Forwarded-For:$(client_ip)\"\n        querystring:\n          - \"version:v1\"\n      remove:\n        headers:\n          - \"Authorization\"  # Don''t pass to backend\n      replace:\n        headers:\n          - \"Host:backend-service\"\n\n# Response transformation\nplugins:\n  - name: response-transformer\n    config:\n      add:\n        headers:\n          - \"X-Response-Time:$(latency)\"\n          - \"X-Gateway:Kong\"\n      remove:\n        headers:\n          - \"X-Internal-Secret\"\n      replace:\n        json:\n          - \"$.metadata.source:api-gateway\"\n```\n\n### Step 6: Implement API Versioning\n\n```yaml\n# URL path versioning\nservices:\n  - name: user-service-v1\n    url: http://user-service-v1:8080\n    routes:\n      - paths:\n          - /api/v1/users\n\n  - name: user-service-v2\n    url: http://user-service-v2:8080\n    routes:\n      - paths:\n          - /api/v2/users\n\n# Header-based versioning\nroutes:\n  - name: versioned-route\n    paths:\n      - /api/users\n    plugins:\n      - name: request-transformer\n        config:\n          add:\n            headers:\n              - \"X-API-Version:$(header.Accept-Version)\"\n```\n\n### Step 7: Configure Monitoring & Analytics\n\n```yaml\n# Prometheus metrics\nplugins:\n  - name: prometheus\n    config:\n      per_consumer: true\n      status_code_metrics: true\n      latency_metrics: true\n      bandwidth_metrics: true\n      upstream_health_metrics: true\n\n# Logging\nplugins:\n  - name: file-log\n    config:\n      path: /var/log/kong/access.log\n      reopen: true\n\n  - name: http-log\n    config:\n      http_endpoint: http://log-aggregator:8080/logs\n      method: POST\n      content_type: application/json\n      timeout: 10000\n      keepalive: 60000\n\n# Datadog integration\nplugins:\n  - name: datadog\n    config:\n      host: datadog-agent\n      port: 8125\n      metrics:\n        - name: request_count\n          stat_type: counter\n        - name: latency\n          stat_type: timer\n```\n\n## Best Practices\n\n### Security:\n- ✅ Always use HTTPS/TLS for API gateway\n- ✅ Implement JWT or OAuth2 for authentication\n- ✅ Use API keys for external partners\n- ✅ Enable CORS with specific origins\n- ✅ Implement request size limits\n- ✅ Add security headers (HSTS, CSP, etc.)\n\n### Performance:\n- ✅ Enable caching for GET requests\n- ✅ Use Redis for distributed rate limiting\n- ✅ Configure connection pooling to backends\n- ✅ Set appropriate timeouts\n- ✅ Enable gzip compression\n- ✅ Use CDN for static content\n\n### Reliability:\n- ✅ Configure health checks for backends\n- ✅ Implement circuit breakers\n- ✅ Set up retry policies\n- ✅ Configure fallback responses\n- ✅ Use multiple gateway instances\n- ✅ Monitor gateway metrics\n\n### Operations:\n- ✅ Use declarative configuration (GitOps)\n- ✅ Version control gateway configs\n- ✅ Implement blue-green deployments\n- ✅ Set up comprehensive logging\n- ✅ Configure alerts for anomalies\n- ✅ Regular security audits\n\n## Examples\n\n### Example 1: Microservices E-Commerce Gateway\n\n```yaml\n# Kong configuration for e-commerce platform\nservices:\n  - name: product-catalog\n    url: http://catalog-service:8080\n    routes:\n      - paths: [\"/api/v1/products\"]\n    plugins:\n      - name: rate-limiting\n        config:\n          minute: 1000\n      - name: cors\n      - name: jwt\n      - name: response-cache\n        config:\n          strategy: memory\n          memory:\n            dictionary_name: kong_cache\n\n  - name: shopping-cart\n    url: http://cart-service:8080\n    routes:\n      - paths: [\"/api/v1/cart\"]\n    plugins:\n      - name: rate-limiting\n        config:\n          minute: 100\n      - name: jwt\n      - name: request-size-limiting\n        config:\n          allowed_payload_size: 10\n\n  - name: checkout\n    url: http://checkout-service:8080\n    routes:\n      - paths: [\"/api/v1/checkout\"]\n    plugins:\n      - name: rate-limiting\n        config:\n          minute: 50\n      - name: jwt\n      - name: bot-detection\n      - name: ip-restriction\n        config:\n          allow:\n            - 10.0.0.0/8\n```\n\n### Example 2: AWS API Gateway with Lambda\n\n```yaml\n# API Gateway with Lambda integration\nfunctions:\n  getUserProfile:\n    handler: handlers/users.getProfile\n    events:\n      - http:\n          path: users/{userId}/profile\n          method: get\n          cors:\n            origin: ''https://app.example.com''\n            headers:\n              - Content-Type\n              - Authorization\n          authorizer:\n            arn: arn:aws:lambda:us-east-1:123456789:function:authorizer\n            resultTtlInSeconds: 300\n            identitySource: method.request.header.Authorization\n          request:\n            parameters:\n              paths:\n                userId: true\n          caching:\n            enabled: true\n            ttlInSeconds: 300\n            dataEncrypted: true\n```\n\n## Common Mistakes to Avoid\n\n- ❌ Not implementing rate limiting\n- ❌ Exposing internal service URLs\n- ❌ No authentication on public APIs\n- ❌ Missing CORS configuration\n- ❌ No monitoring or logging\n- ❌ Hardcoding credentials in config\n- ❌ Not versioning APIs\n- ❌ Single gateway instance (no HA)\n- ❌ No request/response validation\n- ❌ Missing error handling\n\n✅ **Correct approach:**\n- Implement multi-layer rate limiting\n- Use service discovery internally\n- JWT/OAuth2 authentication\n- Proper CORS with allowed origins\n- Comprehensive monitoring\n- Use environment variables/secrets\n- Version APIs from day one\n- Deploy in HA configuration\n- Validate all inputs/outputs\n- Implement circuit breakers\n\n## Tips\n\n- 💡 Start with managed API gateway for faster setup\n- 💡 Use declarative configuration for repeatability\n- 💡 Implement caching to reduce backend load\n- 💡 Monitor gateway metrics continuously\n- 💡 Use API gateway for security boundary\n- 💡 Implement request tracing for debugging\n- 💡 Version APIs early, migrate gradually\n- 💡 Test rate limiting before production\n\n## Related Skills/Commands\n\n### Skills:\n- `microservices-orchestrator` - Microservices architecture\n- `service-mesh-integrator` - Service mesh integration\n- `distributed-tracing-setup` - Request tracing\n\n### Commands:\n- `/dependency-graph` - Visualize API dependencies\n- `/load-test-suite` - Test API gateway performance\n- `/security-posture` - Security assessment\n\n### Agents:\n- `enterprise-architect` - Architecture design\n- `security-architect` - Security configuration\n- `sre-consultant` - SLO/SLI setup\n\n## Notes\n\n**API Gateway Selection Criteria:**\n- ✅ **Kong**: Best for Kubernetes, open source, plugin ecosystem\n- ✅ **AWS API Gateway**: Best for AWS Lambda, managed service\n- ✅ **Tyk**: Best for GraphQL, analytics, multi-cloud\n- ✅ **Apigee**: Best for enterprise API management\n\n**Common Patterns:**\n- Backend for Frontend (BFF) pattern\n- API composition\n- API aggregation\n- Protocol translation (REST to gRPC)\n- Request/response transformation\n\n**Production Checklist:**\n- [ ] TLS/HTTPS enabled\n- [ ] Authentication configured\n- [ ] Rate limiting implemented\n- [ ] CORS configured\n- [ ] Monitoring enabled\n- [ ] Logging configured\n- [ ] Health checks set up\n- [ ] High availability (3+ instances)\n- [ ] Backup and disaster recovery\n- [ ] Documentation updated\n"},"lastSynced":"2026-03-08T02:07:07.646Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Native Agents requiring advanced API gateway configuration and management capabilities for microservices architectures.","zh":"非常适合需要为微服务架构提供高级 API 网关配置和管理功能的云原生 Agent。","ja":"マイクロサービスアーキテクチャのために高度なAPIゲートウェイ構成および管理機能を必要とするクラウドネイティブAgentに理想的です。","ko":"마이크로서비스 아키텍처를 위한 고급 API 게이트웨이 구성 및 관리 기능이 필요한 클라우드 네이티브 에이전트에 이상적입니다.","es":"Ideal para Agentes Nativos en la Nube que requieren una configuración y capacidad de gestión de pasarela de API avanzada para arquitecturas de microservicios.","fr":"Idéal pour les Agents Cloud Natifs nécessitant une configuration et des capacités de gestion de passerelle API avancées pour les architectures de microservices.","de":"Ideal für Cloud Native Agents, die eine erweiterte API-Gateway-Konfiguration und -Verwaltungsfähigkeiten für Microservices-Architekturen erfordern.","pt":"Ideal para Agentes Nativos em Nuvem que requerem configuração e capacidades de gerenciamento avançadas de gateway de API para arquiteturas de microsserviços.","ru":"Идеально подходит для облачных агентов, требующих расширенной настройки и возможностей управления шлюзом API для архитектур микросервисов.","ar":"مثالي لعميل الحوسبة السحابية التي تتطلب تكوين و إمكانيات إدارة متقدمة لبوابة واجهة البرمجيات من أجل هندسة Microsystems."},"recommendation":{"en":"Empowers agents to implement rate limiting, API authentication, and request/response transformation using protocols like HTTP and HTTPS, while also configuring API routing, load balancing, and versioning strategies.","zh":"使 Agent 能够使用 HTTP 和 HTTPS 等协议实施速率限制、API 身份验证和请求/响应转换，同时还能配置 API 路由、负载均衡和版本控制策略。","ja":"HTTPやHTTPSなどのプロトコルを使用してレート制限、API認証、およびリクエスト/レスポンス変換を実装するとともに、APIルーティング、負荷分散、およびバージョニング戦略を構成することをAgentに可能にします。","ko":"HTTP 및 HTTPS와 같은 프로토콜을 사용하여 속도 제한, API 인증 및 요청/응답 변환을 구현하고, 동시에 API 라우팅, 로드 밸런싱 및 버전 관리 전략을 구성할 수 있도록 에이전트에 권한을 부여합니다.","es":"Habilita a los agentes a implementar límites de velocidad, autenticación de API y transformación de solicitudes/respuestas utilizando protocolos como HTTP y HTTPS, y también a configurar estrategias de enrutamiento de API, equilibrio de carga y control de versiones.","fr":"Permet aux agents de mettre en œuvre une limitation de débit, une authentification API et une transformation de requêtes/réponses en utilisant des protocoles tels que HTTP et HTTPS, tout en configurant des stratégies de routage API, d''équilibrage de charge et de gestion de versions.","de":"Ermöglicht es Agenten, Rate Limiting, API-Authentifizierung und Anfrage/Antwort-Transformation mithilfe von Protokollen wie HTTP und HTTPS zu implementieren, sowie API-Routing-, Lastverteilungs- und Versionsverwaltungsstrategien zu konfigurieren.","pt":"Habilita os agentes a implementar limitação de taxa, autenticação de API e transformação de solicitação/resposta usando protocolos como HTTP e HTTPS, além de configurar estratégias de roteamento de API, balanceamento de carga e versionamento.","ru":"Позволяет агентам реализовать ограничение скорости, аутентификацию API и преобразование запроса/ответа с помощью протоколов như HTTP и HTTPS, а также настраивать стратегии маршрутизации API, балансировки нагрузки и версионирования.","ar":"تمكّن الوكلاء من تنفيذ تحديد سرعة و مصادقة واجهة البرمجيات و تحويلات الطلب/الاستجابة باستخدام بروتوكولات مثل HTTP و HTTPS ، بالإضافة إلى تكوين استراتيجيات توجيه واجهة البرمجيات و موازنة الحمل و إستراتيجيات الإصدار."},"useCases":{"en":["Configuring rate limiting and throttling for APIs","Implementing API authentication and authorization using JSON Web Tokens","Setting up request/response transformation for microservices"],"zh":["为 API 配置速率限制和节流","使用 JSON Web Tokens 实施 API 身份验证和授权","为微服务设置请求/响应转换"],"ja":["APIのレート制限とスロットリングの構成","JSON Web Tokensを使用したAPI認証と承認の実装","マイクロサービスのためのリクエスト/レスポンス変換の設定"],"ko":["API에 대한 속도 제한 및 스로틀링 구성","JSON Web Tokens를 사용한 API 인증 및 권한 부여 구현","마이크로서비스를 위한 요청/응답 변환 설정"],"es":["Configuración de límites de velocidad y limitación para APIs","Implementación de autenticación y autorización de API mediante JSON Web Tokens","Configuración de transformación de solicitudes/respuestas para microservicios"],"fr":["Configuration de la limitation de débit et du contrôle de débit pour les API","Mise en œuvre de l''authentification et de l''autorisation API à l''aide de JSON Web Tokens","Configuration de la transformation de requêtes/réponses pour les microservices"],"de":["Konfiguration von Rate Limiting und Drosselung für APIs","Implementierung von API-Authentifizierung und -Autorisierung mithilfe von JSON Web Tokens","Konfiguration von Anfrage/Antwort-Transformation für Microservices"],"pt":["Configurando limitação de taxa e controle de fluxo para APIs","Implementando autenticação e autorização de API usando JSON Web Tokens","Configurando transformação de solicitação/resposta para microsserviços"],"ru":["Настройка ограничения скорости и ограничения потока для API","Реализация аутентификации и авторизации API с помощью JSON Web Tokens","Настройка преобразования запроса/ответа для микросервисов"],"ar":["تكوين تحديد سرعة و ضبط تدفق ل واجهة البرمجيات","تنفيذ مصادقة و تفويض واجهة البرمجيات باستخدام رموز الويب JSON","تكوين تحويلات الطلب/الاستجابة ل Microservices"]},"limitations":{"en":["Requires knowledge of microservices architecture","Limited to API gateway configuration and management"],"zh":["需要微服务架构知识","仅限于 API 网关配置和管理"],"ja":["マイクロサービスアーキテクチャの知識が必要","APIゲートウェイの構成と管理に限定される"],"ko":["마이크로서비스 아키텍처에 대한 지식 필요","API 게이트웨이 구성 및 관리로 제한됨"],"es":["Requiere conocimiento de arquitectura de microservicios","Limitado a la configuración y gestión de la pasarela de API"],"fr":["Nécessite des connaissances en matière d''architecture de microservices","Limité à la configuration et à la gestion de la passerelle API"],"de":["Benötigt Kenntnisse über Microservices-Architektur","Begrenzt auf API-Gateway-Konfiguration und -Verwaltung"],"pt":["Requer conhecimento de arquitetura de microsserviços","Limitado à configuração e gerenciamento de gateway de API"],"ru":["Требует знания архитектуры микросервисов","Ограничен настройкой и управлением шлюзом API"],"ar":["يتطلب معرفة ب هيكلة Microsystems","محدود بتكوين و إدارة بوابة واجهة البرمجيات"]},"version":4},"contentHash":"17eaebca7e4360c85ecf663e2a12143a2df8a212d4cfd58fdec69cdfc1bfff29","qualityScore":60}');
