INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dexploarer/hyper-forge/api-gateway-configurator', 'api-gateway-configurator', 'Dexploarer', 'hyper-forge', 'community', 'api-gateway-configurator Dexploarer hyper-forge community The api-gateway-configurator skill helps developers configure and manage API gateways for microservices architectures, enabling features like rate limiting and API authentication. It benefits developers working with microservices. API网关配置工具是一种AI驱动的技能，用于配置和管理微服务架构中的API网关 APIゲートウェイ設定ツールは、マイクロサービスアーキテクチャのAPIゲートウェイを設定して管理するためのAI駆動型スキルです API 게이트웨이 설정 가이드는 마이크로 서비스 아키텍처에서 API 게이트웨이를 설정하고 관리하기 위한 AI 구동형 스킬입니다 El configurador de API gateway es una herramienta para configurar y gestionar API gateways para microservicios, que incluye rate limiting, autenticación y autorización Le configureur de passerelle API est un outil pour configurer et gérer les passerelles API pour les microservices, qui inclut la limitation de débit, l''authentification et l''autorisation Der API-Gateway-Konfigurator ist ein Tool zum Konfigurieren und Verwalten von API-Gateways für Microservice-Architekturen, das Rate Limiting, Authentifizierung und Autorisierung umfasst O API Gateway Configurator é uma ferramenta de configuração e gerenciamento de gateways de API para microsserviços ИИ Агент для настройки и управления шлюзами API в микросервисных архитектурах API Gateway Configurator هو أداة لتكوين وإدارة بوابات واجهة برمجة التطبيقات للархitectures الموزعة how to use api-gateway-configurator api-gateway-configurator setup guide api-gateway-configurator vs nginx what is api-gateway-configurator api-gateway-configurator install api-gateway-configurator microservices architecture api gateway configuration best practices api-gateway-configurator alternative solutions api-gateway-configurator tutorial API网关配置 微服务架构 AI驱动技能 API认证 API授权 请求/响应转换 API路由 负载均衡 API版本控制 API监控 Configures rate limiting and throttling for API gateways Implements API authentication and authorization strategies Supports request/response transformation and API routing Enables API versioning strategies and load balancing Sets up API monitoring and analytics for performance optimization Manages API documentation for microservices architectures api-gateway-configurator is an enterprise skill for configuring and managing API gateways, implementing features such as rate limiting, authentication, and request/response transformation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaredlander/freshbooks-speed/javascript-ember', 'community', 'jaredlander', 'freshbooks-speed', 'jaredlander/freshbooks-speed', 'javascript-ember', 0, 0, 60, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:09.639Z', '00453b246993ecf8d2975b16c4efc3e2ed9b87d326acd01a53104d73d4412494', '{"id":"jaredlander/freshbooks-speed/javascript-ember","name":"javascript-ember","description":{"en":"The javascript-ember skill helps developers write modern, performant Ember.js applications following Ember Octane conventions, fixing speed issues in the Freshbooks website.","zh":"javascript-ember是一种Chrome扩展，用于优化Freshbooks网站的性能，通过Ember.js编写高效的代码","ja":"javascript-emberは、Freshbooksサイトのパフォーマンスを最適化するChrome拡張機能で、Ember.jsを使用して効率的なコードを記述します","ko":"javascript-ember는 Freshbooks 웹사이트의 성능을 최적화하는 Chrome 확장 프로그램으로 Ember.js를 사용하여 효율적인 코드를 작성합니다","es":"javascript-ember es una extensión de Chrome que soluciona problemas de velocidad en Freshbooks, utilizando Ember.js y seguindo las convenciones de Ember Octane","fr":"javascript-ember est une extension Chrome qui résout les problèmes de vitesse sur Freshbooks, en utilisant Ember.js et en suivant les conventions d''Ember Octane","de":"javascript-ember ist eine Chrome-Erweiterung, die Geschwindigkeitsprobleme in Freshbooks löst, indem sie Ember.js und die Ember-Octane-Konventionen verwendet","pt":"O javascript-ember é uma extensão Chrome que resolve problemas de velocidade no site Freshbooks, utilizando Ember.js","ru":"javascript-ember - расширение Chrome, которое решает проблемы скорости на сайте Freshbooks, используя Ember.js и ИИ Агенты","ar":"javascript-ember هو ملحق Chrome لحل مشاكل السرعة في موقع Freshbooks باستخدام Ember.js"},"seo":{"title":{"en":"javascript-ember: Ember Octane Conventions Setup Guide | ...","zh":"javascript-ember Setup Guide: 优化Freshbooks网站性能","ja":"javascript-emberセットアップ