INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jaredlander/freshbooks-speed/javascript-ember', 'javascript-ember', 'jaredlander', 'freshbooks-speed', 'community', 'javascript-ember jaredlander freshbooks-speed community The javascript-ember skill helps developers write modern, performant Ember.js applications following Ember Octane conventions, fixing speed issues in the Freshbooks website. javascript-ember是一种Chrome扩展，用于优化Freshbooks网站的性能，通过Ember.js编写高效的代码 javascript-emberは、Freshbooksサイトのパフォーマンスを最適化するChrome拡張機能で、Ember.jsを使用して効率的なコードを記述します javascript-ember는 Freshbooks 웹사이트의 성능을 최적화하는 Chrome 확장 프로그램으로 Ember.js를 사용하여 효율적인 코드를 작성합니다 javascript-ember es una extensión de Chrome que soluciona problemas de velocidad en Freshbooks, utilizando Ember.js y seguindo las convenciones de Ember Octane javascript-ember est une extension Chrome qui résout les problèmes de vitesse sur Freshbooks, en utilisant Ember.js et en suivant les conventions d''Ember Octane javascript-ember ist eine Chrome-Erweiterung, die Geschwindigkeitsprobleme in Freshbooks löst, indem sie Ember.js und die Ember-Octane-Konventionen verwendet O javascript-ember é uma extensão Chrome que resolve problemas de velocidade no site Freshbooks, utilizando Ember.js javascript-ember - расширение Chrome, которое решает проблемы скорости на сайте Freshbooks, используя Ember.js и ИИ Агенты javascript-ember هو ملحق Chrome لحل مشاكل السرعة في موقع Freshbooks باستخدام Ember.js how to use javascript-ember what is javascript-ember javascript-ember alternative javascript-ember vs ember-cli javascript-ember install javascript-ember setup guide ember octane conventions context7 MCP freshbooks website speed optimization javascript-ember Ember.js Freshbooks Chrome扩展 性能优化 代码效率 context7 MCP Ember Octane Writes modern, performant Ember.js applications following Ember Octane conventions Uses context7 MCP to check for relevant documentation and project-specific conventions Follows current best practices for Ember.js development Checks for relevant documentation before generating, modifying, or reviewing Ember code Provides project-specific architectural patterns and coding standards Enables use of context7 MCP for consistent Ember code development javascript-ember is a Chrome extension skill that provides expert Ember.js development following Ember Octane conventions and current best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JacobSoderblom/lidx/lidx-architecture', 'community', 'JacobSoderblom', 'lidx', 'JacobSoderblom/lidx', 'lidx-architecture', 0, 0, 60, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:09.936Z', 'e080ae2276434d3523c1d65167100990d338c65c4b86197450db93b97a98326c', '{"id":"JacobSoderblom/lidx/lidx-architecture","name":"lidx-architecture","description":{"en":"The lidx-architecture skill helps developers navigate and understand module boundaries, design new features, and plan architectural changes. It benefits developers working with multiple modules.","zh":"lidx-architecture提供模块导航和CLI集成，帮助开发者优化开发流程","ja":"lidx-architectureはモジュールマップとAIエージェントの活用を提供し、開発者の開発効率を向上させる","ko":"lidx-architecture는 모듈 네비게이션과 CLI 통합을 제공하여 개발자의 개발 효율성을 높입니다","es":"La arquitectura lidx es un framework para desarrollar aplicaciones escalables. Utiliza clap para la definición de argumentos de línea de comandos y Rust como lenguaje de programación","fr":"L''architecture lidx est un framework pour développer des applications évolutives. Elle utilise clap pour la définition des arguments de ligne de commande et Rust comme langage de programmation","de":"Die lidx-Architektur ist ein Framework für die Entwicklung von skalierbaren Anwendungen. Sie verwendet clap für die Definition von Kommandozeilenargumenten und Rust als Programmiersprache","pt":"A arquitetura lidx é projetada para fornecer uma navegação eficiente entre módulos, com definições de CLI e mapeamento de módulos claros","ru":"Архитектура lidx предназначена для обеспечения эффективной навигации между модулями, с четкими определениями CLI и картой модулей","ar":"بنية ليدكس مصممة لتوفير التنقل الفعال بين الوحدات، مع تعريفات واضحة لCLI وخرائط الوحدات"},"seo":{"title":{"en":"lidx-architecture: Navigation Setup Guide | AI Agent Skill","zh":"lidx-architecture 设计指南：模块导航和CLI集成","ja":"lidx-architectur