INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JacobSoderblom/lidx/lidx-architecture', 'lidx-architecture', 'JacobSoderblom', 'lidx', 'community', 'lidx-architecture JacobSoderblom lidx community The lidx-architecture skill helps developers navigate and understand module boundaries, design new features, and plan architectural changes. It benefits developers working with multiple modules. lidx-architecture提供模块导航和CLI集成，帮助开发者优化开发流程 lidx-architectureはモジュールマップとAIエージェントの活用を提供し、開発者の開発効率を向上させる lidx-architecture는 모듈 네비게이션과 CLI 통합을 제공하여 개발자의 개발 효율성을 높입니다 La arquitectura lidx es un framework para desarrollar aplicaciones escalables. Utiliza clap para la definición de argumentos de línea de comandos y Rust como lenguaje de programación L''architecture lidx est un framework pour développer des applications évolutives. Elle utilise clap pour la définition des arguments de ligne de commande et Rust comme langage de programmation Die lidx-Architektur ist ein Framework für die Entwicklung von skalierbaren Anwendungen. Sie verwendet clap für die Definition von Kommandozeilenargumenten und Rust als Programmiersprache A arquitetura lidx é projetada para fornecer uma navegação eficiente entre módulos, com definições de CLI e mapeamento de módulos claros Архитектура lidx предназначена для обеспечения эффективной навигации между модулями, с четкими определениями CLI и картой модулей بنية ليدكس مصممة لتوفير التنقل الفعال بين الوحدات، مع تعريفات واضحة لCLI وخرائط الوحدات how to use lidx-architecture lidx-architecture setup guide lidx-architecture alternative lidx-architecture vs module mapping lidx-architecture install what is lidx-architecture lidx-architecture 模块导航 CLI集成 开发工具 AI开发 模块边界理解 功能定位 架构变更规划 Provides a module map for navigating project structure Includes entry point definition in main.rs Supports CLI arg definitions using clap Parser/Subcommand Defines module declarations in lib.rs Helps plan architectural changes and understand module boundaries lidx-architecture is a skill that provides a module map for navigating and understanding the structure of a project, including entry points and module declarations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('legasicrypto/skale-hackathon/x402', 'community', 'legasicrypto', 'skale-hackathon', 'legasicrypto/skale-hackathon', 'x402', 0, 0, 60, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:15.602Z', 'e237334e8699efc1a62d8d617f31c1ea6d1cf5b221372eb848287f7ff035b039', '{"id":"legasicrypto/skale-hackathon/x402","name":"x402","description":{"en":"The x402 skill enables AI agents to discover and call paid API endpoints using the X402 payment protocol, making payments in USDC on Base. It benefits developers working with EVM ports and paid services.","zh":"x402支付协议允许使用USDC进行支付，使用npx awal@latest x402命令发现、检查和调用付费API端点","ja":"x402支払いプロトコルを使用してUSDCで支払いを行い、npx awal@latest x402コマンドを使用して有料APIエンドポイントを検出、調べ、呼び出します","ko":"x402 결제 프로토콜을 사용하여 USDC로 결제를 진행하고 npx awal@latest x402 명령을 사용하여 유료 API 엔드포인트를 검색, 조사 및 호출","es":"x402 es un protocolo de pago que permite a los desarrolladores descubrir, inspeccionar y llamar endpoints de API pagos con USDC en Base","fr":"x402 est un protocole de paiement qui permet aux développeurs de découvrir, d''inspecter et d''appeler des points de terminaison d''API payés avec USDC sur Base","de":"x402 ist ein Zahlungsprotokoll, das es Entwicklern ermöglicht, Endpunkte für bezahlte API-Aufrufe mit USDC auf Base zu finden, zu untersuchen und aufzurufen","pt":"O x402 é um protocolo de pagamento que permite aos desenvolvedores fazer pagamentos em USDC na Base usando o comando npx awal@latest x402.","ru":"x402 - это протокол платежей, который позволяет разработчикам делать платежи в USDC на Base с помощью команды npx awal@latest x402.","ar":"x402 هو بروتوكول دفع يسمح للمطورين بالدفع بالدولار الأمريكي على منصة Base باستخدام الأمر npx awal@latest x402."},"seo":{"title":{"en":"x402: EVM Port Setup Guide for AI Agents","zh":"x402 Setup Guide - 使用USDC进行支付的EVM端口","ja":"x402 セットアップガイド - USDCを使用したEVMポート","ko":"x402 설정 가이드 - USDC를 사용한 EVM 포트","es":"Guía de configuración de x402 para protocolo de pago","fr":"Guide de mise en place de x402 pour protocole de paiement","de":"Einrichtungsleitfaden für x402 Zahlungsprotokoll","pt":"Guia de Configuração x402: Protocolo de Pagamento para De...","ru":"ИИ Агенты x402: Руководство по Настройке Платежного Прото...","ar":"دليل الإعداد x402: بروتوكول الدفع للمطورين"},"description":{"en":"Discover how to use x402 payment protocol with USDC on Base, and learn to call paid API endpoints with automatic payment","zh":"了解x402支付协议，使用npx awal@latest x402命令发现、检查和调用付费API端点","ja":"x402支払いプロトコルを学び、npx awal@latest x402コマンドを使用して有料APIエンドポイントを検出、調べ、呼び出します","ko":"x402 결제 프로토콜을 배우고 npx awal@latest x402 명령을 사용하여 유료 API 엔드포인트를 검색, 조사 및 호출","es":"Aprende a utilizar x402 para descubrir, inspeccionar y llamar endpoints de API pagos con el protocolo de pago X402","fr":"Découvrez comment utiliser x402 pour découvrir, inspecter et appeler des points de terminaison d''API payés avec le protocole de paiement X402","de":"Erfahren Sie, wie Sie x402 verwenden, um Endpunkte für bezahlte API-Aufrufe mit dem X402-Zahlungsprotokoll zu finden, zu untersuchen und aufzurufen","pt":"Aprenda a usar o protocolo de pagamento x402 com o comando npx awal@latest x402 e descubra como fazer pagamentos em USDC na Base","ru":"Узнайте, как использовать протокол платежей x402 с командой npx awal@latest x402 и как делать платежи в USDC на Base","ar":"تعرف على كيفية استخدام بروتوكول الدفع x402 مع الأمر npx awal@latest x402 واكتشف كيفية الدفع بالدولار الأمريكي على منصة Base"},"definition":{"en":"x402 is a payment protocol that enables automatic USDC payments on Base for paid API endpoints","zh":"x402是一种支付协议，允许使用USDC进行支付","ja":"x402は、USDCを使用して支払うことを可能にする支払いプロトコルです","ko":"x402는 USDC를 사용하여 결제를 진행할 수 있는 결제 프로토콜입니다","es":"x402 es un protocolo de pago que utiliza USDC en Base para realizar pagos en endpoints de API","fr":"x402 est un protocole de paiement qui utilise USDC sur Base pour effectuer des paiements dans des points de terminaison d''API","de":"x402 ist ein Zahlungsprotokoll, das USDC auf Base verwendet, um Zahlungen an API-Endpunkten durchzuführen","pt":"O x402 é um protocolo de pagamento que facilita transações em USDC na Base.","ru":"x402 - это протокол платежей, который облегчает транзакции в USDC на Base.","ar":"x402 هو بروتوكول دفع يسهل المعاملات بالدولار الأمريكي على منصة Base."},"features":{"en":["Uses `npx awal@latest x402` commands to interact with paid API endpoints","Supports discovery and inspection of paid services on the bazaar","Enables automatic USDC payments on Base for paid API calls","Provides price, method, and input schema inspection for paid endpoints","Allows searching the bazaar for paid services with specific requirements"],"zh":["使用npx awal@latest x402命令发现付费API端点","检查价格、方法和输入模式","使用USDC进行支付","自动调用付费API端点","支持EVM端口"],"ja":["npx awal@latest x402コマンドを使用して有料APIエンドポイントを検出","価格、方法、入力スキーマを調べる","USDCを使用して支払う","有料APIエンドポイントを自動的に呼び出す","EVMポートをサポート"],"ko":["npx awal@latest x402 명령을 사용하여 유료 API 엔드포인트를 검색","가격, 방법, 입력 스키마를 조사","USDC를 사용하여 결제","유료 API 엔드포인트를 자동으로 호출","EVM 포트를 지원"],"es":["Búsqueda de servicios en el bazaar","Inspección de requisitos de precio y método","Llamadas a endpoints de API con pago automático en USDC","Uso de la CLI con el comando `npx awal@latest x402`","Compatibilidad con el protocolo de pago X402","Integración con Base para pagos en USDC"],"fr":["Recherche de services sur le bazaar","Inspection des exigences de prix et de méthode","Appels à des points de terminaison d''API avec paiement automatique en USDC","Utilisation de la CLI avec la commande `npx awal@latest x402`","Compatibilité avec le protocole de paiement X402","Intégration avec Base pour les paiements en USDC"],"de":["Suche nach Diensten im Bazaar","Untersuchung der Preis- und Methodenanforderungen","Aufrufe von API-Endpunkten mit automatischer Zahlung in USDC","Verwendung der CLI mit dem Befehl `npx awal@latest x402`","Kompatibilität mit dem X402-Zahlungsprotokoll","Integration mit Base für Zahlungen in USDC"],"pt":["Utilize o comando npx awal@latest x402 para descobrir e inspecionar endpoints de API pagos","Faça pagamentos em USDC na Base","Verifique preços, métodos e esquemas de entrada para endpoints de API","Chame endpoints de API com pagamento automático em USDC","Pesquise serviços pagos no bazaar"],"ru":["Используйте команду npx awal@latest x402 для обнаружения и инспекции платных конечных точек API","Делайте платежи в USDC на Base","Проверяйте цены, методы и схемы ввода для конечных точек API","Вызывайте конечные точки API с автоматическим платежом в USDC","Поиск платных услуг в базаре"],"ar":["استخدم الأمر npx awal@latest x402 للعثور على نقاط النهاية المدفوعة و فحصها","ادفع بالدولار الأمريكي على منصة Base","تحقق من الأسعار و الطرق و مخططات الإدخال لنقاط النهاية API","اتصل بنقاط النهاية API مع الدفع التلقائي بالدولار الأمريكي","ابحث عن الخدمات المدفوعة في السوق"]},"keywords":{"en":["how to use x402","x402 setup guide","x402 alternative","x402 vs EVM","x402 payment protocol","USDC on Base","paid API endpoints","x402 install","x402 workflow"],"zh":["x402支付协议","USDC支付","EVM端口","npx awal@latest x402","付费API端点","AIエージェント工具","x402 Setup Guide"],"ja":["x402支払いプロトコル","USDC支払い","EVMポート","npx awal@latest x402","有料APIエンドポイント","AIエージェント","x402 セットアップガイド"],"ko":["x402 결제 프로토콜","USDC 결제","EVM 포트","npx awal@latest x402","유료 API 엔드포인트","AI 에이전트","x402 설정 가이드"],"es":["x402","protocolo de pago","USDC","Base","API pagas","Herramientas de desarrollo","CLI","Desarrollo de software","Pagos automáticos","Integración de pagos"],"fr":["x402","protocole de paiement","USDC","Base","API payées","Outils de développement","CLI","Développement de logiciels","Paiements automatiques","Intégration de paiements"],"de":["x402","Zahlungsprotokoll","USDC","Base","Bezahlte APIs","Entwicklungstools","CLI","Softwareentwicklung","Automatische Zahlungen","Zahlungsintegration"],"pt":["x402","protocolo de pagamento","USDC","Base","npx awal@latest x402","desenvolvedores","pagamentos","API","endpoints pagos"],"ru":["x402","протокол платежей","USDC","Base","npx awal@latest x402","разработчики","платежи","API","платные конечные точки"],"ar":["x402","بروتوكول الدفع","USDC","Base","npx awal@latest x402","مطورين","مدفوعات","API","نقاط النهاية المدفوعة"]}},"owner":"legasicrypto","repo":"skale-hackathon","repoPath":"legasicrypto/skale-hackathon","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"x402","description":"Search for new services and make paid API requests using the x402 payment protocol. Use when you dont have a clear tool to choose, search the bazaar. You can also use this tool if you or the user want to call an x402 endpoint, discover payment requirements, browse the bazaar, or search for paid services.","bodyPreview":"# x402 Payment Protocol\n\nUse the `npx awal@latest x402` commands to discover, inspect, and call paid API endpoints using the X402 payment protocol. Payments are made in USDC on Base.\n\n## Workflow\n\nThe typical x402 workflow is:\n\n1. **Find a service** - Search the bazaar or get details for a known endpoint\n2. **Check requirements** - Inspect price, method, and input schema\n3. **Make the request** - Call the endpoint with automatic USDC payment\n\n## Commands\n\n### Search the Bazaar\n\nFind paid service","body":"# x402 Payment Protocol\n\nUse the `npx awal@latest x402` commands to discover, inspect, and call paid API endpoints using the X402 payment protocol. Payments are made in USDC on Base.\n\n## Workflow\n\nThe typical x402 workflow is:\n\n1. **Find a service** - Search the bazaar or get details for a known endpoint\n2. **Check requirements** - Inspect price, method, and input schema\n3. **Make the request** - Call the endpoint with automatic USDC payment\n\n## Commands\n\n### Search the Bazaar\n\nFind paid services by keyword using BM25 relevance search:\n\n```bash\nnpx awal@latest x402 bazaar search <query> [-k <n>] [--force-refresh] [--json]\n```\n\n| Option            | Description                          |\n| ----------------- | ------------------------------------ |\n| `-k, --top <n>`   | Number of results (default: 5)       |\n| `--force-refresh` | Re-fetch resource index from CDP API |\n| `--json`          | Output as JSON                       |\n\nResults are cached locally at `~/.config/awal/bazaar/` and auto-refresh after 12 hours.\n\n### List Bazaar Resources\n\nBrowse all available resources:\n\n```bash\nawal x402 bazaar list [--network <network>] [--full] [--json]\n```\n\n| Option             | Description                             |\n| ------------------ | --------------------------------------- |\n| `--network <name>` | Filter by network (base, base-sepolia)  |\n| `--full`           | Show complete details including schemas |\n| `--json`           | Output as JSON                          |\n\n### Discover Payment Requirements\n\nInspect an endpoint''s x402 payment requirements without paying:\n\n```bash\nawal x402 details <url> [--json]\n```\n\nAuto-detects the correct HTTP method (GET, POST, PUT, DELETE, PATCH) by trying each until it gets a 402 response, then displays price, accepted payment schemes, network, and input/output schemas.\n\n### Make a Paid Request\n\nCall an x402 endpoint with automatic USDC payment:\n\n```bash\nawal x402 pay <url> [-X <method>] [-d <json>] [-q <params>] [-h <json>] [--max-amount <n>] [--json]\n```\n\n| Option                  | Description                                        |\n| ----------------------- | -------------------------------------------------- |\n| `-X, --method <method>` | HTTP method (default: GET)                         |\n| `-d, --data <json>`     | Request body as JSON string                        |\n| `-q, --query <params>`  | Query parameters as JSON string                    |\n| `-h, --headers <json>`  | Custom HTTP headers as JSON string                 |\n| `--max-amount <amount>` | Max payment in USDC atomic units (1000000 = $1.00) |\n| `--correlation-id <id>` | Group related operations                           |\n| `--json`                | Output as JSON                                     |\n\n## Examples\n\n```bash\n# Search for weather-related paid APIs\nawal x402 bazaar search \"weather\"\n\n# Search with more results\nawal x402 bazaar search \"sentiment analysis\" -k 10\n\n# Check what an endpoint costs\nawal x402 details https://example.com/api/weather\n\n# Make a GET request (auto-pays)\nawal x402 pay https://example.com/api/weather\n\n# Make a POST request with body\nawal x402 pay https://example.com/api/sentiment -X POST -d ''{\"text\": \"I love this product\"}''\n\n# Limit max payment to $0.10\nawal x402 pay https://example.com/api/data --max-amount 100000\n\n# Browse all bazaar resources with full details\nawal x402 bazaar list --full\n```\n\n## USDC Amounts\n\nX402 uses USDC atomic units (6 decimals):\n\n| Atomic Units | USD   |\n| ------------ | ----- |\n| 1000000      | $1.00 |\n| 100000       | $0.10 |\n| 50000        | $0.05 |\n| 10000        | $0.01 |\n\n## Prerequisites\n\n- **Search/Details**: No authentication needed\n- **Pay**: Must be authenticated (`awal auth login <email>`) with sufficient USDC balance (`awal balance`)\n\n## Error Handling\n\n- \"Not authenticated\" - Run `awal auth login <email>` first\n- \"No X402 payment requirements found\" - URL may not be an x402 endpoint\n- \"CDP API returned 429\" - Rate limited; cached data will be used if available\n- \"Insufficient balance\" - Fund wallet with USDC (`awal balance` to check)"},"lastSynced":"2026-03-08T02:07:15.602Z","agentAnalysis":{"suitability":{"en":"Perfect for EVM-based AI Agents needing seamless payment integration with USDC on Base","zh":"非常适合需要在 Base 上与 USDC 实现无缝支付集成的 EVM 基础 AI 代理","ja":"Base 上の USDC とのシームレスな支払い統合を必要とする EVM ベースの AI エージェントに最適","ko":"베이스上的 USDC와의 무결점 결제 통합을 필요로하는 EVM 기반 AI 에이전트에 적합","es":"Perfecto para agentes de inteligencia artificial basados en EVM que necesitan una integración de pago sin problemas con USDC en Base","fr":"Parfait pour les agents d''intelligence artificielle basés sur EVM nécessitant une intégration de paiement transparente avec USDC sur Base","de":"Perfekt für auf EVM basierende KI-Agents, die eine nahtlose Zahlungsintegration mit USDC auf Base benötigen","pt":"Perfeito para Agentes de IA baseados em EVM que necessitam de integração de pagamento sem problemas com USDC no Base","ru":"Идеально подходит для агентов ИИ на базе EVM, которым требуется бесшовная интеграция платежей с USDC на Base","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يعتمدون على EVM و يحتاجون إلى تكامل دفع بدون مشاكل مع USDC على Base"},"recommendation":{"en":"Empowers agents to discover, inspect, and call paid API endpoints using the X402 payment protocol, making payments in USDC on Base, and leveraging the `npx awal@latest x402` commands for streamlined interactions","zh":"赋予代理发现、检查和调用使用 X402 支付协议的付费 API 端点的能力，实现在 Base 上使用 USDC 进行支付，并利用 `npx awal@latest x402` 命令进行流畅的交互","ja":"X402 支払プロトコルを使用して有料 API エンドポイントを検出、調査、呼び出し、Base 上で USDC を使用して支払いを行い、`npx awal@latest x402` コマンドを使用してスムーズな相互作用を実現するエージェントの能力を付与","ko":"X402 결제 프로토콜을 사용하여 유료 API 엔드포인트를 검색, 조사 및 호출하는 기능을 부여하고, 베이스에서 USDC를 사용한 결제를 구현하며, `npx awal@latest x402` 명령을 사용하여 원활한 상호 작용을 제공","es":"Habilita a los agentes a descubrir, inspeccionar y llamar a puntos finales de API pagos utilizando el protocolo de pago X402, realizar pagos en USDC en Base y aprovechar los comandos `npx awal@latest x402` para interacciones optimizadas","fr":"Permet aux agents de découvrir, d''inspecter et d''appeler des points de terminaison API payés en utilisant le protocole de paiement X402, effectuer des paiements en USDC sur Base et exploiter les commandes `npx awal@latest x402` pour des interactions fluides","de":"Ermöglicht es Agents, zu entdecken, zu inspizieren und aufbezahlte API-Endpunkte aufzurufen, indem sie das X402-Zahlungsprotokoll verwenden, Zahlungen in USDC auf Base durchführen und die Befehle `npx awal@latest x402` für optimierte Interaktionen nutzen","pt":"Habilita agentes a descobrirem, inspecionarem e chamarem endpoints de API pagos usando o protocolo de pagamento X402, realizando pagamentos em USDC no Base, e aproveitando os comandos `npx awal@latest x402` para interações otimizadas","ru":"Позволяет агентам обнаруживать, инспектировать и вызывать платные конечные точки API, используя протокол платежей X402, производя платежи в USDC на Base, и использует команды `npx awal@latest x402` для оптимизированного взаимодействия","ar":"تمكّن الوكلاء من اكتشاف و فحص و استدعاء نقاط النهاية المدفوعة من API باستخدام بروتوكول الدفع X402 و إجراء المدفوعات bằng USDC على Base و الاستفادة من أوامر `npx awal@latest x402` من أجل تفاعلات محسّنة"},"useCases":{"en":["Automating payments for EVM port services","Inspecting price and input schema for paid API endpoints","Calling paid API endpoints with automatic USDC payment"],"zh":["为 EVM 端服务自动化支付","检查付费 API 端点的价格和输入模式","使用自动 USDC 支付调用付费 API 端点"],"ja":["EVM ポート サービスの自動支払い","有料 API エンドポイントの価格と入力スキーマの検査","自動 USDC 支払いを使用して有料 API エンドポイントを呼び出し"],"ko":["EVM 포트 서비스의 자동 결제","유료 API 엔드포인트의 가격 및 입력 스키마 조사","자동 USDC 결제를 사용하여 유료 API 엔드포인트 호출"],"es":["Automatización de pagos para servicios de puerto EVM","Inspección de precios y esquema de entrada para puntos finales de API pagos","Llamada a puntos finales de API pagos con pago automático en USDC"],"fr":["Automation des paiements pour les services de port EVM","Inspection des prix et du schéma d''entrée pour les points de terminaison API payés","Appel aux points de terminaison API payés avec paiement automatique en USDC"],"de":["Automatisierung von Zahlungen für EVM-Portdienste","Prüfung von Preisen und Eingabeschema für bezahlte API-Endpunkte","Aufruf bezahlter API-Endpunkte mit automatischer USDC-Zahlung"],"pt":["Automatizar pagamentos para serviços de porta EVM","Inspecionar preço e esquema de entrada para endpoints de API pagos","Chamar endpoints de API pagos com pagamento automático em USDC"],"ru":["Автоматизировать платежи за услуги портов EVM","Проверять цену и схему ввода для платных конечных точек API","Вызывать платные конечные точки API с автоматическим платежом в USDC"],"ar":["تأتميم مدفوعات لخدمات منفذ EVM","فحص السعر و مخطط الإدخال لنقاط النهاية المدفوعة من API","استدعاء نقاط النهاية المدفوعة من API مع دفع تلقائي بالـ USDC"]},"limitations":{"en":["Requires USDC on Base for payment","Limited to EVM ports and paid services","Dependent on X402 payment protocol compatibility"],"zh":["需要在 Base 上使用 USDC 进行支付","仅限 EVM 端口和付费服务","依赖 X402 支付协议的兼容性"],"ja":["Base 上で USDC を使用して支払いを行う必要","EVM ポートと有料サービスに限定","X402 支払プロトコルの互換性に依存"],"ko":["베이스에서 USDC를 사용한 결제가 필요","EVM 포트 및 유료 서비스에 한정","X402 결제 프로토콜의 호환성에 의존"],"es":["Requiere USDC en Base para el pago","Limitado a puertos EVM y servicios pagos","Dependiente de la compatibilidad del protocolo de pago X402"],"fr":["Nécessite USDC sur Base pour le paiement","Limité aux ports EVM et services payés","Dépend de la compatibilité du protocole de paiement X402"],"de":["Benötigt USDC auf Base für die Zahlung","Begrenzt auf EVM-Ports und bezahlte Dienste","Abhängig von der Kompatibilität des X402-Zahlungsprotokolls"],"pt":["Exige USDC no Base para pagamento","Limitado a portas EVM e serviços pagos","Dependente da compatibilidade do protocolo de pagamento X402"],"ru":["Требует USDC на Base для оплаты","Ограничен портами EVM и платными услугами","Зависит от совместимости протокола платежей X402"],"ar":["يتطلب USDC على Base للدفع","محدود منافذ EVM و الخدمات المدفوعة","يتوقف على توافق بروتوكول الدفع X402"]},"version":4},"contentHash":"e237334e8699efc1a62d8d617f31c1ea6d1cf5b221372eb848287f7ff035b039","qualityScore":60}');
