INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('legasicrypto/skale-hackathon/x402', 'x402', 'legasicrypto', 'skale-hackathon', 'community', 'x402 legasicrypto skale-hackathon community The x402 skill enables AI agents to discover and call paid API endpoints using the X402 payment protocol, making payments in USDC on Base. It benefits developers working with EVM ports and paid services. x402支付协议允许使用USDC进行支付，使用npx awal@latest x402命令发现、检查和调用付费API端点 x402支払いプロトコルを使用してUSDCで支払いを行い、npx awal@latest x402コマンドを使用して有料APIエンドポイントを検出、調べ、呼び出します x402 결제 프로토콜을 사용하여 USDC로 결제를 진행하고 npx awal@latest x402 명령을 사용하여 유료 API 엔드포인트를 검색, 조사 및 호출 x402 es un protocolo de pago que permite a los desarrolladores descubrir, inspeccionar y llamar endpoints de API pagos con USDC en Base x402 est un protocole de paiement qui permet aux développeurs de découvrir, d''inspecter et d''appeler des points de terminaison d''API payés avec USDC sur Base x402 ist ein Zahlungsprotokoll, das es Entwicklern ermöglicht, Endpunkte für bezahlte API-Aufrufe mit USDC auf Base zu finden, zu untersuchen und aufzurufen O x402 é um protocolo de pagamento que permite aos desenvolvedores fazer pagamentos em USDC na Base usando o comando npx awal@latest x402. x402 - это протокол платежей, который позволяет разработчикам делать платежи в USDC на Base с помощью команды npx awal@latest x402. x402 هو بروتوكول دفع يسمح للمطورين بالدفع بالدولار الأمريكي على منصة Base باستخدام الأمر npx awal@latest x402. how to use x402 x402 setup guide x402 alternative x402 vs EVM x402 payment protocol USDC on Base paid API endpoints x402 install x402 workflow x402支付协议 USDC支付 EVM端口 npx awal@latest x402 付费API端点 AIエージェント工具 x402 Setup Guide Uses `npx awal@latest x402` commands to interact with paid API endpoints Supports discovery and inspection of paid services on the bazaar Enables automatic USDC payments on Base for paid API calls Provides price, method, and input schema inspection for paid endpoints Allows searching the bazaar for paid services with specific requirements x402 is a payment protocol that enables automatic USDC payments on Base for paid API endpoints');
