INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sanjitsaluja/zugzwang-puzzle-trainer/dex-plan', 'dex-plan', 'sanjitsaluja', 'zugzwang-puzzle-trainer', 'community', 'dex-plan sanjitsaluja zugzwang-puzzle-trainer community dex-plan is a skill that converts markdown documents to trackable tasks. It benefits developers and teams who use markdown for planning and need to track progress. dex-plan 是一个将 Markdown 文档转换为可追踪的任务的工具，使用 dex 命令行工具即可完成转换 dex-plan は、Markdown ドキュメントをトラック可能なタスクに変換するツールです。dex コマンドライン ツールを使用して簡単に変換できます dex-plan은 마크다운 문서를 추적 가능한 태스크로 변환하는 도구입니다. dex 명령줄 도구를 사용하여 쉽게 변환할 수 있습니다 dex-plan es una herramienta que convierte documentos de Markdown en tareas de seguimiento con dex. Utiliza la línea de comandos dex para convertir documentos de planificación dex-plan est un outil qui convertit des documents Markdown en tâches de suivi avec dex. Utilisez la ligne de commande dex pour convertir des documents de planification dex-plan ist ein Tool, das Markdown-Dokumente in nachverfolgbare dex-Aufgaben umwandelt. Verwenden Sie die dex-Kommandozeile, um Planungsdokumente umzuwandeln O dex-plan é uma ferramenta que converte documentos Markdown em tarefas trackeáveis. Use o comando `dex` para integrar o dex-plan na sua workflow de desenvolvimento dex-plan - это инструмент, который конвертирует документы Markdown в отслеживаемые задачи. Используйте команду `dex`, чтобы интегрировать dex-plan в ваш процесс разработки dex-plan هو أداة لتحويل مستندات Markdown إلى مهام قابلة للتعقب. استخدم الأمر `dex` لدمج dex-plan في تدفق عملك how to use dex-plan dex-plan setup guide markdown to task conversion dex-plan alternative dex-plan vs task management tools installing dex-plan what is dex-plan dex-plan command line tool converting markdown to tasks dex-plan Markdown 文档转换 可追踪的任务 dex 命令行工具 AI 工具 计划文档转换 Uses `dex` command for invocation Supports conversion of markdown documents to trackable tasks Utilizes `npx @zeeg/dex` as an alternative command Checks if `dex` is on PATH for seamless execution Employs the `/dex-plan` command for markdown conversion dex-plan is a command-line tool that converts markdown planning documents to trackable dex tasks using the `/dex-plan` command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Treytucker05/pt-study-sop/conductor-setup', 'community', 'Treytucker05', 'pt-study-sop', 'Treytucker05/pt-study-sop', 'conductor-setup', 0, 0, 60, '2026-03-08T01:57:15.425Z', '2026-03-08T02:07:28.116Z', 'e7629bc7911189ada9401dadd8ad983e8ec2077603880f3f7ea7e9490debc940', '{"id":"Treytucker05/pt-study-sop/conductor-setup","name":"conductor-setup","description":{"en":"The conductor-setup skill initializes or resumes Conductor project setup through interactive Q&A, creating foundational project documentation. It benefits developers working on Conductor setup tasks or workflows.","zh":"Conductor-setup 是一个 AI 代理技能，用于通过交互式问答处理 Conductor 设置任务。它协助创建基础项目文档，并提供设置指导、最佳实践和检查清单。","ja":"conductor-setupは、インタラクティブなQ&Aを通じてConductorの設定タスクを処理するAIエージェントスキルです。基礎的なプロジェクトドキュメントの作成を支援し、設定のガイダンス、ベストプラクティス、チェックリストを提供します。","ko":"conductor-setup은 대화형 Q&A를 통해 Conductor 설정 작업을 처리하는 AI 에이전트 스킬입니다. 기본 프로젝트 문서 생성을 지원하고 설정 지침, 모범 사례 및 체크리스트를 제공합니다.","es":"Esta skill de IA inicializa o reanuda la configuración de un proyecto Conductor, automatizando la creación de documentación técnica fundamental a través de un proceso interactivo de preguntas y respuestas para workflows.","fr":"Cette skill IA initialise ou reprend la configuration d''un projet Conductor, automatisant la création d''une documentation technique de base via un processus interactif de questions-réponses pour les workflows.","de":"Dieses KI-Tool initialisiert oder setzt die Einrichtung eines Conductor-Projekts fort, automatisiert die Erstellung grundlegender technischer Dokumentation durch einen interaktiven Frage-Antwort-Prozess für Workflows.","pt":"O skill conductor-setup automatiza a inicialização de projetos Conductor, gerando documentação técnica através de um Q&A interativo. Ele fornece orientação especializada, melhores práticas e checklists para workflows de configuração.","ru":"Навык conductor-setup автоматизирует инициализацию проектов Conductor, генерируя техническую документацию через интерактивный Q&A. Он предоставляет специализированные руководства, лучшие практики и чек-листы для рабочих процессов настройки.","ar":"تتيح مهارة conductor-setup أتمتة تهيئة مشاريع Conductor، مما يولد وثائق فنية عبر الأسئلة والأجوبة التفاعلية. يوفر توجيهات متخصصة وأفضل الممارسات وقوائم التحقق لسير عمل الإعداد."},"seo":{"title":{"en":"conductor-setup: Interactive Setup Guide for AI Agents","zh":"Conductor Setup 指南：AI 代理设置最佳实践","ja":"Conductor Setup ガイド：AIエージェントの設定とベストプラクティス","ko":"Conductor Setup 가이드: AI 에이전트 설정 및 모범 사례","es":"Conductor Setup: Guía de Configuración para Proyectos de IA","fr":"Configuration Conductor : Guide de Mise en Place pour Pro...","de":"Conductor Setup: Einrichtungsleitfaden für KI-Agenten Pro...","pt":"Conductor Setup: Guia de Configuração e Melhores Práticas...","ru":"Conductor Setup: Руководство по настройке и лучшие практи...","ar":"Conductor Setup: دليل الإعداد وأفضل الممارسات لوكلاء الذك..."},"description":{"en":"Discover how to streamline Conductor project setup with this AI agent skill. Get started with interactive Q&A and best practices today!","zh":"通过交互式问答初始化或恢复 Conductor 项目设置。本指南提供基础项目文档创建、最佳实践清单和设置工作流的具体指导，专为开发者设计。","ja":"インタラクティブなQ&Aを通じてConductorプロジェクトの設定を初期化または再開します。基礎的なプロジェクトドキュメントの作成、ベストプラクティスチェックリスト、設定ワークフローに関する具体的なガイダンスを提供するAIエージェントスキルです。","ko":"대화형 Q&A를 통해 Conductor 프로젝트 설정을 초기화하거나 재개합니다. 기본 프로젝트 문서 생성, 모범 사례 체크리스트 및 설정 워크플로우에 대한 구체적인 지침을 제공하는 AI 에이전트 스킬입니다.","es":"Automatiza la configuración de proyectos Conductor con esta skill de IA. Crea documentación fundacional mediante Q&A interactiva, siguiendo las mejores práct...","fr":"Automatisez la configuration de projets Conductor avec cette skill IA. Créez une documentation de base via un Q&A interactif, en suivant les meilleures prati...","de":"Automatisieren Sie die Einrichtung von Conductor-Projekten mit dieser KI-Tool Skill. Erstellen Sie grundlegende Dokumentation durch interaktive Q&A und folge...","pt":"Use o comando conductor-setup para inicializar ou retomar a configuração de projetos Conductor. Crie documentação de projeto fundamental através de Q&A inter...","ru":"Используйте команду conductor-setup для инициализации или возобновления настройки проектов Conductor. Создавайте основную проектную документацию с помощью ин...","ar":"استخدم أمر conductor-setup لتهيئة أو استئناف إعداد مشاريع Conductor. أنشئ وثائق المشروع الأساسية من خلال الأسئلة والأجوبة التفاعلية واتبع قوائم التحقق من أفض..."},"definition":{"en":"conductor-setup is a skill that initializes or resumes Conductor project setup, providing guidance and best practices through interactive Q&A.","zh":"Conductor-setup 是一个专门的 AI 代理技能，旨在通过交互式对话初始化或恢复 Netflix Conductor 项目设置。它通过问答形式引导用户，自动化创建项目文档和配置工作流的过程。","ja":"conductor-setupは、インタラクティブな対話を通じてNetflix Conductorプロジェクトの設定を初期化または再開するように設計された専門的なAIエージェントスキルです。Q&A形式でユーザーを導き、プロジェクトドキュメントと設定ワークフローの作成を自動化します。","ko":"conductor-setup은 대화형 대화를 통해 Netflix Conductor 프로젝트 설정을 초기화하거나 재개하도록 설계된 전문 AI 에이전트 스킬입니다. Q&A 형식으로 사용자를 안내하고 프로젝트 문서 및 설정 워크플로우 생성을 자동화합니다.","es":"Conductor Setup es una skill de IA que guía a los desarrolladores en la configuración inicial de proyectos Conductor. Mediante Q&A interactiva, genera documentación técnica fundacional, checklist y mejores prácticas para workflows específicos.","fr":"Conductor Setup est une skill IA qui guide les développeurs dans la configuration initiale des projets Conductor. Via un Q&A interactif, elle génère une documentation technique de base, des checklist et des meilleures pratiques pour des workflows spécifiques.","de":"Conductor Setup ist eine KI-Tool Skill, die Entwickler bei der initialen Einrichtung von Conductor-Projekten anleitet. Durch interaktive Q&A generiert sie grundlegende technische Dokumentation, Checklisten und Best Practices für spezifische Workflows.","pt":"Conductor-setup é um comando de AI Agent que inicializa ou retoma a configuração de um projeto Conductor. Ele cria documentação de projeto fundamental através de um processo interativo de Q&A, aplicando melhores práticas e checklists para workflows de setup.","ru":"Conductor-setup — это команда ИИ Агента, которая инициализирует или возобновляет настройку проекта Conductor. Она создает основную проектную документацию через интерактивный процесс Q&A, применяя лучшие практики и чек-листы для рабочих процессов настройки.","ar":"Conductor-setup هو أمر وكيل الذكاء الاصطناعي الذي يقوم بتهيئة أو استئناف إعداد مشروع Conductor. ينشئ وثائق المشروع الأساسية من خلال عملية تفاعلية للأسئلة والأجوبة، مع تطبيق أفضل الممارسات وقوائم التحقق لسير عمل الإعداد."},"features":{"en":["Creates foundational project documentation through interactive Q&A","Provides guidance and best practices for Conductor setup","Supports Conductor project setup tasks and workflows","Applies requirements and constraints to setup process","Clarifies goals and required inputs for Conductor setup"],"zh":["通过交互式问答初始化 Conductor 项目","创建基础的项目文档和配置","提供设置工作流的具体指导和最佳实践","包含设置任务的检查清单功能","明确项目目标、约束和所需输入"],"ja":["インタラクティブなQ&AによるConductorプロジェクトの初期化","基礎的なプロジェクトドキュメントと設定の作成","設定ワークフローに関する具体的なガイダンスとベストプラクティスの提供","設定タスクのチェックリスト機能を含む","プロジェクトの目標、制約、必要な入力の明確化"],"ko":["대화형 Q&A를 통한 Conductor 프로젝트 초기화","기본 프로젝트 문서 및 설정 생성","설정 워크플로우에 대한 구체적인 지침 및 모범 사례 제공","설정 작업을 위한 체크리스트 기능 포함","프로젝트 목표, 제약 조건 및 필수 입력 명확화"],"es":["Inicialización interactiva de proyectos Conductor mediante Q&A","Generación automatizada de documentación técnica fundacional","Checklist de mejores prácticas para configuración de workflows","Clarificación de objetivos y restricciones del proyecto","Soporte para tareas de setup y reanudación de proyectos"],"fr":["Initialisation interactive de projets Conductor via Q&A","Génération automatisée de documentation technique de base","Checklist de meilleures pratiques pour la configuration de workflows","Clarification des objectifs et contraintes du projet","Support pour les tâches de setup et reprise de projets"],"de":["Interaktive Initialisierung von Conductor-Projekten durch Q&A","Automatisierte Generierung grundlegender technischer Dokumentation","Checklisten mit Best Practices für Workflow-Einrichtung","Klärung von Projektzielen und -einschränkungen","Unterstützung für Setup- und Wiederaufnahmeaufgaben von Projekten"],"pt":["Inicialização interativa de projeto via Q&A","Geração automática de documentação técnica fundamental","Aplicação de checklists de melhores práticas para setup","Suporte para retomada de configurações de projetos existentes","Orientação especializada para workflows Conductor","Clarificação de objetivos e restrições do projeto"],"ru":["Интерактивная инициализация проекта через Q&A","Автоматическая генерация основной технической документации","Применение чек-листов лучших практик для настройки","Поддержка возобновления настроек существующих проектов","Специализированное руководство для рабочих процессов Conductor","Уточнение целей и ограничений проекта"],"ar":["تهيئة مشروع تفاعلية عبر الأسئلة والأجوبة","إنشاء تلقائي للوثائق الفنية الأساسية","تطبيق قوائم التحقق من أفضل الممارسات للإعداد","دعم استئناف إعدادات المشاريع الحالية","توجيه متخصص لسير عمل Conductor","توضيح أهداف وقيود المشروع"]},"keywords":{"en":["how to use conductor-setup","conductor-setup setup guide","conductor-setup alternative","conductor-setup vs other tools","conductor-setup install","what is conductor-setup","conductor-setup best practices","conductor-setup workflow automation"],"zh":["conductor setup","netflix conductor 配置","ai 代理设置","conductor 工作流","项目初始化指南","交互式设置工具","conductor 最佳实践","开发运维工具"],"ja":["conductor setup","netflix conductor 設定","AIエージェント 設定","conductor ワークフロー","プロジェクト初期化ガイド","インタラクティブ設定ツール","conductor ベストプラクティス","開発者向けツール"],"ko":["conductor setup","netflix conductor 설정","AI 에이전트 설정","conductor 워크플로우","프로젝트 초기화 가이드","대화형 설정 도구","conductor 모범 사례","개발자 도구"],"es":["conductor setup configuración","skill IA conductor setup","automatización documentación técnica","workflows conductor mejores prácticas","configuración proyecto conductor","QA interactivo conductor","checklist setup conductor","herramientas desarrollo IA"],"fr":["configuration conductor setup","skill IA configuration conductor","automatisation documentation technique","workflows conductor meilleures pratiques","setup projet conductor","QA interactif conductor","checklist configuration conductor","outils développement IA"],"de":["conductor setup einrichtung","KI-Tool conductor setup","automatisierung technische dokumentation","workflows conductor best practices","projekteinrichtung conductor","interaktive QA conductor","checklist setup conductor","entwicklungstools KI"],"pt":["conductor setup tutorial","configuração conductor AI agent","melhores práticas conductor setup","comando conductor-setup CLI","documentação projeto conductor","workflow setup conductor","inicialização projeto conductor","checklist setup conductor"],"ru":["conductor setup руководство","настройка conductor ИИ агент","лучшие практики conductor setup","команда conductor-setup CLI","документация проекта conductor","рабочий процесс настройки conductor","инициализация проекта conductor","чек-лист настройки conductor"],"ar":["دليل إعداد conductor","إعداد conductor وكيل ذكاء اصطناعي","أفضل ممارسات إعداد conductor","أمر conductor-setup CLI","وثائق مشروع conductor","سير عمل إعداد conductor","تهيئة مشروع conductor","قائمة التحقق من إعداد conductor"]}},"owner":"Treytucker05","repo":"pt-study-sop","repoPath":"Treytucker05/pt-study-sop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.425Z","topics":[],"category":"community","skillMd":{"name":"conductor-setup","description":"Initialize project with Conductor artifacts (product definition,","bodyPreview":"# Conductor Setup\n\nInitialize or resume Conductor project setup. This command creates foundational project documentation through interactive Q&A.\n\n## Use this skill when\n\n- Working on conductor setup tasks or workflows\n- Needing guidance, best practices, or checklists for conductor setup\n\n## Do not use this skill when\n\n- The task is unrelated to conductor setup\n- You need a different domain or tool outside this scope\n\n## Instructions\n\n- Clarify goals, constraints, and required inputs.\n- Apply re","body":"# Conductor Setup\n\nInitialize or resume Conductor project setup. This command creates foundational project documentation through interactive Q&A.\n\n## Use this skill when\n\n- Working on conductor setup tasks or workflows\n- Needing guidance, best practices, or checklists for conductor setup\n\n## Do not use this skill when\n\n- The task is unrelated to conductor setup\n- You need a different domain or tool outside this scope\n\n## Instructions\n\n- Clarify goals, constraints, and required inputs.\n- Apply relevant best practices and validate outcomes.\n- Provide actionable steps and verification.\n- If detailed examples are required, open `resources/implementation-playbook.md`.\n\n## Pre-flight Checks\n\n1. Check if `conductor/` directory already exists in the project root:\n   - If `conductor/product.md` exists: Ask user whether to resume setup or reinitialize\n   - If `conductor/setup_state.json` exists with incomplete status: Offer to resume from last step\n\n2. Detect project type by checking for existing indicators:\n   - **Greenfield (new project)**: No .git, no package.json, no requirements.txt, no go.mod, no src/ directory\n   - **Brownfield (existing project)**: Any of the above exist\n\n3. Load or create `conductor/setup_state.json`:\n   ```json\n   {\n     \"status\": \"in_progress\",\n     \"project_type\": \"greenfield|brownfield\",\n     \"current_section\": \"product|guidelines|tech_stack|workflow|styleguides\",\n     \"current_question\": 1,\n     \"completed_sections\": [],\n     \"answers\": {},\n     \"files_created\": [],\n     \"started_at\": \"ISO_TIMESTAMP\",\n     \"last_updated\": \"ISO_TIMESTAMP\"\n   }\n   ```\n\n## Interactive Q&A Protocol\n\n**CRITICAL RULES:**\n\n- Ask ONE question per turn\n- Wait for user response before proceeding\n- Offer 2-3 suggested answers plus \"Type your own\" option\n- Maximum 5 questions per section\n- Update `setup_state.json` after each successful step\n- Validate file writes succeeded before continuing\n\n### Section 1: Product Definition (max 5 questions)\n\n**Q1: Project Name**\n\n```\nWhat is your project name?\n\nSuggested:\n1. [Infer from directory name]\n2. [Infer from package.json/go.mod if brownfield]\n3. Type your own\n```\n\n**Q2: Project Description**\n\n```\nDescribe your project in one sentence.\n\nSuggested:\n1. A web application that [does X]\n2. A CLI tool for [doing Y]\n3. Type your own\n```\n\n**Q3: Problem Statement**\n\n```\nWhat problem does this project solve?\n\nSuggested:\n1. Users struggle to [pain point]\n2. There''s no good way to [need]\n3. Type your own\n```\n\n**Q4: Target Users**\n\n```\nWho are the primary users?\n\nSuggested:\n1. Developers building [X]\n2. End users who need [Y]\n3. Internal teams managing [Z]\n4. Type your own\n```\n\n**Q5: Key Goals (optional)**\n\n```\nWhat are 2-3 key goals for this project? (Press enter to skip)\n```\n\n### Section 2: Product Guidelines (max 3 questions)\n\n**Q1: Voice and Tone**\n\n```\nWhat voice/tone should documentation and UI text use?\n\nSuggested:\n1. Professional and technical\n2. Friendly and approachable\n3. Concise and direct\n4. Type your own\n```\n\n**Q2: Design Principles**\n\n```\nWhat design principles guide this project?\n\nSuggested:\n1. Simplicity over features\n2. Performance first\n3. Developer experience focused\n4. User safety and reliability\n5. Type your own (comma-separated)\n```\n\n### Section 3: Tech Stack (max 5 questions)\n\nFor **brownfield projects**, first analyze existing code:\n\n- Run `Glob` to find package.json, requirements.txt, go.mod, Cargo.toml, etc.\n- Parse detected files to pre-populate tech stack\n- Present findings and ask for confirmation/additions\n\n**Q1: Primary Language(s)**\n\n```\nWhat primary language(s) does this project use?\n\n[For brownfield: \"I detected: Python 3.11, JavaScript. Is this correct?\"]\n\nSuggested:\n1. TypeScript\n2. Python\n3. Go\n4. Rust\n5. Type your own (comma-separated)\n```\n\n**Q2: Frontend Framework (if applicable)**\n\n```\nWhat frontend framework (if any)?\n\nSuggested:\n1. React\n2. Vue\n3. Next.js\n4. None / CLI only\n5. Type your own\n```\n\n**Q3: Backend Framework (if applicable)**\n\n```\nWhat backend framework (if any)?\n\nSuggested:\n1. Express / Fastify\n2. Django / FastAPI\n3. Go standard library\n4. None / Frontend only\n5. Type your own\n```\n\n**Q4: Database (if applicable)**\n\n```\nWhat database (if any)?\n\nSuggested:\n1. PostgreSQL\n2. MongoDB\n3. SQLite\n4. None / Stateless\n5. Type your own\n```\n\n**Q5: Infrastructure**\n\n```\nWhere will this be deployed?\n\nSuggested:\n1. AWS (Lambda, ECS, etc.)\n2. Vercel / Netlify\n3. Self-hosted / Docker\n4. Not decided yet\n5. Type your own\n```\n\n### Section 4: Workflow Preferences (max 4 questions)\n\n**Q1: TDD Strictness**\n\n```\nHow strictly should TDD be enforced?\n\nSuggested:\n1. Strict - tests required before implementation\n2. Moderate - tests encouraged, not blocked\n3. Flexible - tests recommended for complex logic\n```\n\n**Q2: Commit Strategy**\n\n```\nWhat commit strategy should be followed?\n\nSuggested:\n1. Conventional Commits (feat:, fix:, etc.)\n2. Descriptive messages, no format required\n3. Squash commits per task\n```\n\n**Q3: Code Review Requirements**\n\n```\nWhat code review policy?\n\nSuggested:\n1. Required for all changes\n2. Required for non-trivial changes\n3. Optional / self-review OK\n```\n\n**Q4: Verification Checkpoints**\n\n```\nWhen should manual verification be required?\n\nSuggested:\n1. After each phase completion\n2. After each task completion\n3. Only at track completion\n```\n\n### Section 5: Code Style Guides (max 2 questions)\n\n**Q1: Languages to Include**\n\n```\nWhich language style guides should be generated?\n\n[Based on detected languages, pre-select]\n\nOptions:\n1. TypeScript/JavaScript\n2. Python\n3. Go\n4. Rust\n5. All detected languages\n6. Skip style guides\n```\n\n**Q2: Existing Conventions**\n\n```\nDo you have existing linting/formatting configs to incorporate?\n\n[For brownfield: \"I found .eslintrc, .prettierrc. Should I incorporate these?\"]\n\nSuggested:\n1. Yes, use existing configs\n2. No, generate fresh guides\n3. Skip this step\n```\n\n## Artifact Generation\n\nAfter completing Q&A, generate the following files:\n\n### 1. conductor/index.md\n\n```markdown\n# Conductor - [Project Name]\n\nNavigation hub for project context.\n\n## Quick Links\n\n- [Product Definition](./product.md)\n- [Product Guidelines](./product-guidelines.md)\n- [Tech Stack](./tech-stack.md)\n- [Workflow](./workflow.md)\n- [Tracks](./tracks.md)\n\n## Active Tracks\n\n<!-- Auto-populated by /conductor:new-track -->\n\n## Getting Started\n\nRun `/conductor:new-track` to create your first feature track.\n```\n\n### 2. conductor/product.md\n\nTemplate populated with Q&A answers for:\n\n- Project name and description\n- Problem statement\n- Target users\n- Key goals\n\n### 3. conductor/product-guidelines.md\n\nTemplate populated with:\n\n- Voice and tone\n- Design principles\n- Any additional standards\n\n### 4. conductor/tech-stack.md\n\nTemplate populated with:\n\n- Languages (with versions if detected)\n- Frameworks (frontend, backend)\n- Database\n- Infrastructure\n- Key dependencies (for brownfield, from package files)\n\n### 5. conductor/workflow.md\n\nTemplate populated with:\n\n- TDD policy and strictness level\n- Commit strategy and conventions\n- Code review requirements\n- Verification checkpoint rules\n- Task lifecycle definition\n\n### 6. conductor/tracks.md\n\n```markdown\n# Tracks Registry\n\n| Status | Track ID | Title | Created | Updated |\n| ------ | -------- | ----- | ------- | ------- |\n\n<!-- Tracks registered by /conductor:new-track -->\n```\n\n### 7. conductor/code_styleguides/\n\nGenerate selected style guides from `$CLAUDE_PLUGIN_ROOT/templates/code_styleguides/`\n\n## State Management\n\nAfter each successful file creation:\n\n1. Update `setup_state.json`:\n   - Add filename to `files_created` array\n   - Update `last_updated` timestamp\n   - If section complete, add to `completed_sections`\n2. Verify file exists with `Read` tool\n\n## Completion\n\nWhen all files are created:\n\n1. Set `setup_state.json` status to \"complete\"\n2. Display summary:\n\n   ```\n   Conductor setup complete!\n\n   Created artifacts:\n   - conductor/index.md\n   - conductor/product.md\n   - conductor/product-guidelines.md\n   - conductor/tech-stack.md\n   - conductor/workflow.md\n   - conductor/tracks.md\n   - conductor/code_styleguides/[languages]\n\n   Next steps:\n   1. Review generated files and customize as needed\n   2. Run /conductor:new-track to create your first track\n   ```\n\n## Resume Handling\n\nIf `--resume` argument or resuming from state:\n\n1. Load `setup_state.json`\n2. Skip completed sections\n3. Resume from `current_section` and `current_question`\n4. Verify previously created files still exist\n5. If files missing, offer to regenerate\n\n## Error Handling\n\n- If file write fails: Halt and report error, do not update state\n- If user cancels: Save current state for future resume\n- If state file corrupted: Offer to start fresh or attempt recovery\n"},"lastSynced":"2026-03-08T02:07:28.116Z","agentAnalysis":{"suitability":{"en":"Ideal for Workflow Automation Agents requiring streamlined Conductor project setup and interactive Q&A capabilities.","zh":"适用于需要简化Conductor项目设置和交互式Q&A功能的工作流自动化代理。","ja":"Conductorプロジェクトの設定とインタラクティブなQ&A機能を簡素化するためのワークフロー自動化エージェントに適しています。","ko":"Conductor 프로젝트 설정과 상호작용형 Q&A 기능을 간소화하는 워크플로 자동화 에이전트에 적합합니다.","es":"Ideal para Agentes de Automatización de Flujo de Trabajo que requieren una configuración de proyecto de Conductor simplificada y capacidades de preguntas y respuestas interactivas.","fr":"Idéal pour les agents d''automatisation de workflow nécessitant une configuration de projet Conductor simplifiée et des capacités de questions et réponses interactives.","de":"Ideal für Workflow-Automatisierungsagenten, die eine vereinfachte Conductor-Projektsetup und interaktive Frage- und Antwortfunktionen erfordern.","pt":"Ideal para Agentes de Automação de Fluxo de Trabalho que exigem configuração de projeto Conductor simplificada e capacidades de Q&A interativas.","ru":"Идеально подходит для агентов автоматизации рабочих процессов, требующих упрощенной настройки проекта Conductor и интерактивных возможностей Q&A.","ar":"مثالي لعمليات وكيل أتمتة سير العمل التي تتطلب إعداد مشروع Conductor مبسط وقدرات استجواب تفاعلية."},"recommendation":{"en":"Empowers agents to create foundational project documentation through interactive Q&A, leveraging Conductor setup best practices and checklists to guide developers through setup tasks and workflows, utilizing foundational project documentation.","zh":"通过交互式Q&A，利用Conductor设置最佳实践和清单来指导开发人员完成设置任务和工作流，赋予代理创建基础项目文档的能力。","ja":"Conductorの設定ベストプラクティスとチェックリストを利用して、開発者が設定タスクとワークフローを完了するためのインタラクティブなQ&Aを通じて、基本的なプロジェクト文書を作成するエージェントの能力を付与します。","ko":"Conductor 설정의 모범 사례와 체크리스트를 사용하여 개발자가 설정 작업과 워크플로를 완료하도록 하기 위한 상호작용형 Q&A를 통해 기본 프로젝트 문서를 생성할 수 있는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a crear documentación de proyecto fundamental a través de preguntas y respuestas interactivas, aprovechando las mejores prácticas de configuración de Conductor y listas de verificación para guiar a los desarrolladores a través de tareas de configuración y flujos de trabajo, utilizando documentación de proyecto fundamental.","fr":"Permet aux agents de créer une documentation de projet fondamentale via des questions et réponses interactives, en exploitant les meilleures pratiques de configuration de Conductor et des listes de vérification pour guider les développeurs à travers les tâches de configuration et les flux de travail, en utilisant la documentation de projet fondamentale.","de":"Ermächtigt Agenten, grundlegende Projektdokumentation durch interaktive Frage- und Antwortfunktionen zu erstellen, indem es die besten Praktiken für die Conductor-Setup und Checklisten nutzt, um Entwickler durch die Setup-Aufgaben und Workflows zu führen, unter Verwendung der grundlegenden Projektdokumentation.","pt":"Habilita os agentes a criar documentação de projeto fundamental por meio de Q&A interativa, aproveitando as melhores práticas de configuração do Conductor e listas de verificação para orientar os desenvolvedores nas tarefas de configuração e fluxos de trabalho, utilizando documentação de projeto fundamental.","ru":"Наделяет агентов возможностью создавать базовую документацию проекта через интерактивный Q&A, используя лучшие практики настройки Conductor и контрольные списки для руководства разработчиками при выполнении задач настройки и рабочих процессов, используя базовую документацию проекта.","ar":"تمكين الوكلاء من إنشاء توثيق مشروع أساسي من خلال استجواب تفاعلي، مستفيدة من أفضل الممارسات لإعداد Conductor وقوائم المراجعة لتوجيه المطورين خلال مهام الإعداد وسير العمل، باستخدام توثيق مشروع أساسي."},"useCases":{"en":["Initializing Conductor projects with guided Q&A","Resuming incomplete Conductor setup tasks","Generating foundational project documentation for Conductor workflows"],"zh":["使用指导式Q&A初始化Conductor项目","恢复未完成的Conductor设置任务","为Conductor工作流生成基础项目文档"],"ja":["ガイド付きQ&Aを使用してConductorプロジェクトを初期化する","完了していないConductor設定タスクを再開する","Conductorワークフロー用の基本的なプロジェクト文書を生成する"],"ko":["상호작용형 Q&A를 사용하여 Conductor 프로젝트를 초기화합니다","완료되지 않은 Conductor 설정 작업을 다시 시작합니다","Conductor 워크플로우를 위한 기본 프로젝트 문서를 생성합니다"],"es":["Inicialización de proyectos de Conductor con preguntas y respuestas guiadas","Reanudación de tareas de configuración de Conductor incompletas","Generación de documentación de proyecto fundamental para flujos de trabajo de Conductor"],"fr":["Initialisation de projets Conductor avec questions et réponses guidées","Reprise de tâches de configuration de Conductor incomplètes","Génération de documentation de projet fondamentale pour les flux de travail Conductor"],"de":["Initialisierung von Conductor-Projekten mit interaktiver Frage- und Antwortfunktion","Wiederaufnahme unvollständiger Conductor-Setup-Aufgaben","Generierung grundlegender Projektdokumentation für Conductor-Workflows"],"pt":["Inicialização de projetos Conductor com Q&A orientada","Retomada de tarefas de configuração Conductor incompletas","Geração de documentação de projeto fundamental para fluxos de trabalho Conductor"],"ru":["Инициализация проектов Conductor с помощью Q&A","Возобновление незавершенных задач настройки Conductor","Генерация базовой документации проекта для рабочих процессов Conductor"],"ar":["ت.secret مشاريع Conductor مع استجواب موجه","استئناف مهام إعداد Conductor غير المكتملة","генерация توثيق مشروع أساسي لسير العمل Conductor"]},"limitations":{"en":["Limited to Conductor setup tasks and workflows","Requires interactive Q&A input"],"zh":["仅限Conductor设置任务和工作流","需要交互式Q&A输入"],"ja":["Conductorの設定タスクとワークフローに限定される","インタラクティブなQ&A入力を必要とする"],"ko":["Conductor 설정 작업 및 워크플로우에만 제한됨","상호작용형 Q&A 입력이 필요함"],"es":["Limitado a tareas y flujos de trabajo de configuración de Conductor","Requiere entrada de preguntas y respuestas interactivas"],"fr":["Limité aux tâches et flux de travail de configuration de Conductor","Nécessite une entrée de questions et réponses interactives"],"de":["Begrenzt auf Conductor-Setup-Aufgaben und -Workflows","Benötigt interaktive Frage- und Antworteingabe"],"pt":["Limitado a tarefas e fluxos de trabalho de configuração Conductor","Exige entrada de Q&A interativa"],"ru":["Ограничен задачами настройки и рабочими процессами Conductor","Требует интерактивного ввода Q&A"],"ar":["محدود بمهام إعداد Conductor وسير العمل","يتطلب إدخال استجواب تفاعلي"]},"version":4},"contentHash":"e7629bc7911189ada9401dadd8ad983e8ec2077603880f3f7ea7e9490debc940","qualityScore":60}');
