INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('miwtoo/credit-card-extraction/extracting-pdf-text', 'extracting-pdf-text', 'miwtoo', 'credit-card-extraction', 'community', 'extracting-pdf-text miwtoo credit-card-extraction community This AI Agent skill provides targeted Python scripts and a decision guide for extracting text from PDFs into formats suitable for Language Model consumption. It benefits developers building AI agents that require high-quality text extraction from diverse PDF sources. 本技能提供了从PDF中提取文本的工具和指南，支持简单文本、表格和扫描图像PDF このスキルは、シンプルなテキスト、表、スキャンされたイメージPDFからテキストを抽出するためのツールとガイドを提供します 이 스킬은 단순 텍스트, 표, 스캔된 이미지 PDF에서 텍스트를 추출하는 도구와 가이드를 제공합니다 Esta habilidad proporciona herramientas y orientación para extraer texto de PDF en formatos adecuados para el consumo de modelos de lenguaje Cette compétence fournit des outils et des conseils pour extraire du texte de PDF dans des formats adaptés à la consommation de modèles de langage Diese Fähigkeit bietet Tools und Anleitungen zur Extraktion von Text aus PDF in Formaten, die für die Verwendung in Sprachmodellen geeignet sind Extraia texto de PDFs de forma eficiente com as ferramentas certas. Aprenda a usar PyMuPDF, pdfplumber e pytesseract. Извлекайте текст из PDF эффективно с правильными инструментами. Узнайте, как использовать PyMuPDF, pdfplumber и pytesseract. استخرج نصًا من ملفات PDF بفعالية باستخدام الأدوات المناسبة. تعلم كيفية استخدام PyMuPDF و pdfplumber و pytesseract. how to extract text from PDF for LLM extracting-pdf-text vs Adobe Acrobat PyMuPDF pdfplumber comparison install extracting-pdf-text skill PDF OCR for AI agents pytesseract extracting-pdf-text setup guide best PDF text extraction for language models Mistr PDF extraction PDF文本提取 PyMuPDF pdfplumber pytesseract 语言模型 PDF处理 文本抽出 AI工具 AIエージェント Provides a Quick Decision Guide for selecting the optimal extraction method Includes `extract_pymupdf.py` script for simple text-based PDFs using PyMuPDF Offers `extract_pdfplumber.py` script for handling PDFs containing tables Supports OCR via `extract_with_ocr.py` using pytesseract for scanned/image PDFs References Mistr for complex layouts requiring the highest accuracy extracting-pdf-text is an AI Agent skill that provides tools and guidance for converting PDF content into text consumable by Large Language Models. It offers a quick decision guide and specific Python scripts for different PDF types, including simple text, tables, and scanned documents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sinjie2008/Foundational-Electronics-Core-Systems/project-specification-writer', 'community', 'sinjie2008', 'Foundational-Electronics-Core-Systems', 'sinjie2008/Foundational-Electronics-Core-Systems', 'project-specification-writer', 0, 0, 60, '2026-03-08T01:57:15.434Z', '2026-03-08T02:07:36.212Z', '363693d36287063a00947b8881b3224308f5b5d73846ea4cbf46d66aadd2f89d', '{"id":"sinjie2008/Foundational-Electronics-Core-Systems/project-specification-writer","name":"project-specification-writer","description":{"en":"The project-specification-writer skill generates a comprehensive specification document for the current repository/project, including architecture, data model, and key processes. It benefits developers and project managers by providing a single source of truth for project documentation.","zh":"项目规范撰写工具可以生成包含11个必要部分的项目规范文档，包括架构、数据模型、伪代码等","ja":"プロジェクト仕様書作成ツールは、プロジェクトのアーキテクチャ、データモデル、疑似コードなど11の必要なセクションを含む詳細な仕様書を生成します","ko":"프로젝트 규격 작성 도구는 아키텍처, 데이터 모델, 의사 코드 등 11개의 필수 섹션을 포함한 종합적인 프로젝트 규격 문서를 생성합니다","es":"Project Specification Writer es una herramienta que genera documentos de especificación de proyectos completos con secciones como arquitectura y tecnología, modelo de datos y procesos clave","fr":"Project Specification Writer est un outil qui génère des documents de spécification de projet complets avec des sections telles que l''architecture et la technologie, le modèle de données et les processus clés","de":"Project Specification Writer ist ein Tool, das umfassende Projektspezifikationsdokumente mit Abschnitten wie Architektur und Technologie, Datenmodell und Schlüsselprozessen erstellt","pt":"O project-specification-writer é uma ferramenta que gera documentos de especificação de projeto completos com seções de arquitetura, modelo de dados e pseudocódigo","ru":"Project-specification-writer - это инструмент, который генерирует полные документы спецификации проекта с разделами архитектуры, модели данных и псевдокода для ИИ Агентов","ar":"project-specification-writer هو أداة تنتج مستندات مواصفات المشروع الشاملة مع أقسام الهندسة المعمارية ونموذج البيانات والكود النصي لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"project-specification-writer: Comprehensive Documentation...","zh":"项目规范撰写工具：全面项目规范文档生成","ja":"プロジェクト仕様書作成ツール：AIエージェントによる詳細な仕様書生成","ko":"프로젝트 규격 작성 도구: 종합적인 프로젝트 규격 문서 생성","es":"Guía de configuración de Project Specification Writer par...","fr":"Guide de mise en place de Project Specification Writer po...","de":"Einrichtungsleitfaden für Project Specification Writer-En...","pt":"Guia de Configuração do project-specification-writer para...","ru":"Руководство по настройке project-specification-writer для...","ar":"دليل إعداد project-specification-writer لمنشئي أدوات الذك..."},"description":{"en":"Discover how project-specification-writer generates a single, comprehensive specification document with all required sections. Learn how to invoke it for you...","zh":"利用项目规范撰写工具，生成包含架构、数据模型、伪代码等所有必要部分的项目规范文档，提高开发效率","ja":"プロジェクト仕様書作成ツールを使用して、体系的なプロジェクト仕様書を生成しましょう。アーキテクチャ、データモデル、疑似コードなどが含まれています","ko":"프로젝트 규격 작성 도구를 사용하여 아키텍처, 데이터 모델, 의사 코드 등을 포함한 종합적인 프로젝트 규격 문서를 생성하여 개발 효율성을 높입니다","es":"Aprende a utilizar Project Specification Writer para generar documentos de especificación de proyectos completos con secciones de arquitectura, modelo de dat...","fr":"Découvrez comment utiliser Project Specification Writer pour générer des documents de spécification de projet complets avec des sections d''architecture, de m...","de":"Erfahren Sie, wie Sie Project Specification Writer verwenden, um umfassende Projektspezifikationsdokumente mit Architektur-, Datenmodell- und weiteren Abschn...","pt":"Aprenda a usar o project-specification-writer para criar documentos de especificação de projeto completos com seções de arquitetura, modelo de dados e pseudo...","ru":"Узнайте, как использ