INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sinjie2008/Foundational-Electronics-Core-Systems/project-specification-writer', 'project-specification-writer', 'sinjie2008', 'Foundational-Electronics-Core-Systems', 'community', 'project-specification-writer sinjie2008 Foundational-Electronics-Core-Systems community The project-specification-writer skill generates a comprehensive specification document for the current repository/project, including architecture, data model, and key processes. It benefits developers and project managers by providing a single source of truth for project documentation. 项目规范撰写工具可以生成包含11个必要部分的项目规范文档，包括架构、数据模型、伪代码等 プロジェクト仕様書作成ツールは、プロジェクトのアーキテクチャ、データモデル、疑似コードなど11の必要なセクションを含む詳細な仕様書を生成します 프로젝트 규격 작성 도구는 아키텍처, 데이터 모델, 의사 코드 등 11개의 필수 섹션을 포함한 종합적인 프로젝트 규격 문서를 생성합니다 Project Specification Writer es una herramienta que genera documentos de especificación de proyectos completos con secciones como arquitectura y tecnología, modelo de datos y procesos clave Project Specification Writer est un outil qui génère des documents de spécification de projet complets avec des sections telles que l''architecture et la technologie, le modèle de données et les processus clés Project Specification Writer ist ein Tool, das umfassende Projektspezifikationsdokumente mit Abschnitten wie Architektur und Technologie, Datenmodell und Schlüsselprozessen erstellt O project-specification-writer é uma ferramenta que gera documentos de especificação de projeto completos com seções de arquitetura, modelo de dados e pseudocódigo Project-specification-writer - это инструмент, который генерирует полные документы спецификации проекта с разделами архитектуры, модели данных и псевдокода для ИИ Агентов project-specification-writer هو أداة تنتج مستندات مواصفات المشروع الشاملة مع أقسام الهندسة المعمارية ونموذج البيانات والكود النصي لأدوات الذكاء الاصطناعي how to use project-specification-writer project-specification-writer alternative project-specification-writer setup guide what is project-specification-writer project-specification-writer vs documentation tools project-specification-writer install comprehensive specification document generation project documentation automation AI agent for project specification 项目规范撰写工具 AI驱动的项目规范文档生成 项目开发效率提高 项目规范文档生成 架构和技术选择 数据模型和伪代码 系统上下文图 容器/部署概述 Generates a single, comprehensive specification document with all required sections Includes architecture and technology choices, data model, and key processes Produces pseudocode, system context diagram, and container/deployment overview Creates module relationship diagram for backend and frontend Generates sequence diagram, ER diagram, and class diagram for key backend classes project-specification-writer is a skill that produces a comprehensive specification document with sections including architecture and technology choices, data model, and system context diagram.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('quests-org/quests/changelog', 'community', 'quests-org', 'quests', 'quests-org/quests', 'changelog', 0, 0, 60, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:44.329Z', '47d2a62152e7f8eecd66bdfd5bd0221ba8553ea072cf32224e49dd3c0ca53922', '{"id":"quests-org/quests/changelog","name":"changelog","description":{"en":"The changelog skill generates a change log based on git commits and tags, benefiting developers by automating version tracking. It uses git to find the most recent tagged non-beta version and inspects commit content.","zh":"Changelog技能用于生成变更日志，通过Git查找最新标签版本并生成Markdown代码块","ja":"Changelog スキルは、Git を使用して最新のタグ付きバージョンを検索し、Markdown コードブロックを生成して変更ログを作成するために使用されます","ko":"Changelog 스킬은 Git을 사용하여 최신 태그가 있는 버전을 찾고 Markdown 코드 블록을 생성하여 변경 로그를 생성하는 데 사용됩니다","es":"El agente de AI ''changelog'' utiliza git para generar registros de cambios en tu proyecto de desarrollo","fr":"L''agent d''AI ''changelog'' utilise git pour générer des journaux de modifications dans votre projet de développement","de":"Der AI-Agent ''changelog'' verwendet git, um Änderungsprotokolle in Ihrem Entwicklungsprojekt zu generieren","pt":"O changelog é uma ferramenta de código aberto que gera registros de alterações para aplicativos. Ele usa git e markdown para criar um registro de alterações.","ru":"Чейнджлог - это открытый инструмент, который генерирует журнал изменений для приложений. Он использует git и markdown для создания журнала изменений.","ar":"سجل التغييرات هو أداة بناء تطبيقات مفتوحة المصدر التي ت生成 سجلات التغييرات لتطبيقات. انها تستخدم git و markdown لإنشاء سجل التغييرات"},"seo":{"title":{"en":"Changelog: Automated Version Tracking Guide | AI Agent Skill","zh":"Changelog Setup Guide: 使用Git生成变更日志","ja":"Changelog セットアップガイド: Git を使用した変更ログの生成","ko":"Changelog 설정 가이드: Git을 사용한 변경 로그 생성","es":"Guía de configuración de changelog para desarrolladores","fr":"Guide de mise en place de changelog pour les développeurs","de":"Changelog-Setup-Anleitung für Entwickler","pt":"Guia de Configuração de Changelog: Gerando Registros de A...","ru":"Настройка Чейнджлога: Руководство по ИИ Агентам","ar":"دليل إعداد سجل التغييرات: أداة بناء التطبيقات المفتوحة"},"description":{"en":"Discover how to leverage git and markdown for effortless changelog generation - explore the changelog skill now and streamline your version tracking!","zh":"了解如何使用Changelog技能生成变更日志，包括使用Git查找最新标签版本和生成Markdown代码块","ja":"Changelog スキルを使用して変更ログを生成する方法について学びます。Git を使用して最新のタグ付きバージョンを検索し、Markdown コードブロックを生成します","ko":"Changelog 스킬을 사용하여 변경 로그를 생성하는 방법에 대해 알아보세요. Git을 사용하여 최신 태그가 있는 버전을 찾고 Markdown 코드 블록을 생성합니다","es":"Aprende a utilizar el agente de AI ''changelog'' para generar registros de cambios en tu proyecto de desarrollo con git","fr":"Découvrez comment utiliser l''agent d''AI ''changelog'' pour générer des journaux de modifications dans votre projet de développement avec git","de":"Erfahren Sie, wie Sie den AI-Agent ''changelog'' verwenden, um Änderungsprotokolle in Ihrem Entwicklungsprojekt mit git zu generieren","pt":"Aprenda a configurar o changelog com git e markdown. Descubra como gerar registros de alterações para o seu aplicativo.","ru":"Узнайте, как настроить чейнджлог с помощью git и markdown. Откройте для себя, как создать журнал изменений для вашего приложения с помощью ИИ Агентов.","ar":"تعرف على كيفية إعداد سجل التغييرات باستخدام git و markdown. اكتشف كيفية إنشاء سجل التغييرات لتطبيقك مع أداة بناء التطبيقات المفتوحة"},"definition":{"en":"changelog is an open-source app builder that automates version tracking using git and markdown","zh":"Changelog是一种使用Git生成变更日志的开源应用程序构建器","ja":"Changelog は、Git を使用して変更ログを生成するオープンソースのアプリケーションビルダーです","ko":"Changelog는 Git을 사용하여 변경 로그를 생성하는 오픈소스 애플리케이션 빌더입니다","es":"Un changelog es un registro de cambios en un proyecto de desarrollo, generado automáticamente con git","fr":"Un journal de modifications est un registre des modifications apportées à un projet de développement, généré automatiquement avec git","de":"Ein Änderungsprotokoll ist ein Protokoll der Änderungen in einem Entwicklungsprojekt, automatisch mit git generiert","pt":"Changelog é uma ferramenta que gera registros de alterações para aplicativos.","ru":"Чейнджлог - это инструмент, который генерирует журнал изменений для приложений.","ar":"سجل التغييرات هو أداة ت生成 سجلات التغييرات لتطبيقات"},"features":{"en":["Uses git to find the most recent tagged non-beta version","Inspects content of larger commits for change log generation","Generates a change log in markdown code block format","Finds the previous version for comparison","Returns results in a markdown code block","Follows a specific style based on example change logs"],"zh":["使用Git查找最新标签版本","生成Markdown代码块","支持多种版本控制系统","自动检测变更","生成易于阅读的变更日志"],"ja":["Git を使用して最新のタグ付きバージョンを検索","Markdown コードブロックを生成","複数のバージョン管理システムをサポート","自動で変更を検出","読みやすい変更ログを生成"],"ko":["Git을 사용하여 최신 태그가 있는 버전을 찾기","Markdown 코드 블록을 생성","여러 버전 관리 시스템을 지원","자동으로 변경을 감지","읽기 쉬운 변경 로그를 생성"],"es":["Utiliza git para buscar la versión más reciente","Genera un registro de cambios en formato markdown","Incluye la inspección de commits más grandes","No incluye mensajes de commit verbatim","Escribe copias para una audiencia general","Utiliza la versión más reciente si no hay etiquetas"],"fr":["Utilise git pour rechercher la version la plus récente","Génère un journal de modifications au format markdown","Inclut l''inspection des commits plus importants","N''inclut pas les messages de commit verbatim","Écrit des copies pour un public général","Utilise la version la plus récente si aucune étiquette n''est présente"],"de":["Verwendet git, um die neueste Version zu suchen","Generiert ein Änderungsprotokoll im markdown-Format","Beinhaltet die Inspektion größerer Commits","Beinhaltet keine wörtlichen Commit-Meldungen","Schreibt Kopien für eine allgemeine Zielgruppe","Verwendet die neueste Version, wenn keine Tags vorhanden sind"],"pt":["Utiliza git para encontrar a versão mais recente","Gera registros de alterações em markdown","Inclui apenas as alterações mais importantes","Não inclui mensagens de commit verbatim","Escreve cópias para um público geral"],"ru":["Использует git для поиска последней версии","Генерирует журнал изменений в markdown","Включает только наиболее важные изменения","Не включает сообщения коммитов verbatim","Пишет копии для широкой аудитории"],"ar":["تستخدم git للعثور على الإصدار الأخير","تولد سجلات التغييرات في markdown","تتضمن فقط التغييرات الأكثر أهمية","لا تتضمن رسائل Commit verbatim","تكتب نسخًا للجمهور العام"]},"keywords":{"en":["how to use changelog","what is changelog","changelog alternative","changelog vs git","changelog install","changelog setup guide","automated version tracking","git commit analysis","markdown change log generation"],"zh":["Changelog","Git","变更日志","Markdown","开源应用程序构建器","AIエージェント","版本控制系统"],"ja":["Changelog","Git","変更ログ","Markdown","オープンソースアプリケーションビルダー","AIエージェント","バージョン管理システム"],"ko":["Changelog","Git","변경 로그","Markdown","오픈소스 애플리케이션 빌더","AI 에이전트","버전 관리 시스템"],"es":["changelog","git","registro de cambios","desarrollo de software","agente de AI","generador de changelog","markdown","commits","versiones de software"],"fr":["journal de modifications","git","registre des modifications","développement de logiciels","agent d''AI","générateur de journal de modifications","markdown","commits","versions de logiciels"],"de":["Änderungsprotokoll","git","Protokoll der Änderungen","Softwareentwicklung","AI-Agent","Änderungsprotokoll-Generator","markdown","Commits","Softwareversionen"],"pt":["changelog","git","markdown","registros de alterações","ferramentas de desenvolvimento","desenvolvimento de aplicativos","geração de registros de alterações"],"ru":["чейнджлог","git","markdown","журнал изменений","инструменты разработки","разработка приложений","генерация журнала изменений","ИИ Агенты"],"ar":["سجل التغييرات","git","markdown","سجلات التغييرات","أدوات التطوير","تطوير التطبيقات","إنشاء سجلات التغييرات","أداة بناء التطبيقات المفتوحة"]}},"owner":"quests-org","repo":"quests","repoPath":"quests-org/quests","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"changelog","description":"Generate changelog from git commits","bodyPreview":"## Approach\n\n1. Use `git` to look for the most recent tagged non-beta version.\n2. If the most recent commit doesn''t have a tag, use it as the current version.\n3. Find the previous version.\n4. Inspect the content of any larger commits.\n5. Generate a change log for that based on the style of a few of these example change logs down below.\n6. Return the results in a markdown code block.\n\n## Guidelines\n\n- Don''t include verbatim commit messages.\n- Write copy for a general audience.\n- Only include the","body":"## Approach\n\n1. Use `git` to look for the most recent tagged non-beta version.\n2. If the most recent commit doesn''t have a tag, use it as the current version.\n3. Find the previous version.\n4. Inspect the content of any larger commits.\n5. Generate a change log for that based on the style of a few of these example change logs down below.\n6. Return the results in a markdown code block.\n\n## Guidelines\n\n- Don''t include verbatim commit messages.\n- Write copy for a general audience.\n- Only include the \"Features\" and \"Bug Fixes\" sections.\n\n## Example 1\n\n```markdown\n## Features\n\n- **Chat mode** has landed! Switch between building apps and chatting with the agent.\n- **Projects page** with table view - delete, stop, and manage all your projects in one place.\n- Recent projects displayed on new tab.\n- Copy button for pre blocks in Markdown.\n- Use new projects page for eval viewing.\n- Incorporate upstream error messages for multiple matches.\n\n## Bug Fixes\n\n- Full width assistant messages always, and copy button for single line code too.\n- Support navigation API even on root pages like not found.\n- Remove redundant app type in tab title.\n- Remove more markdown in titles.\n- Attempt to avoid race condition during project deletion due to session abort.\n- Make command/ctrl + r work everywhere unless disabled.\n- Disallow creation of session db during entire deletion process.\n- Better handle ripgrep arguments.\n- Animated stop icon in proper places.\n\n## ⛵︎\n\n_72 commits since v1.5.0_\n\nMore will follow.\n```\n\n## Example 2\n\n```markdown\n## 🧬 Features\n\n- Evals have landed!\n- A couple clicks and you can compare rich output from as many models and apps you desire.\n- Built-in prompts for standard eval apps and some goofy ones too.\n- Suport fo custom eval prompts.\n- Dedicated runs page with bulk actions.\n\n## 🩹 Bug Fixes\n\n- Linux: Fixed DBus safe storage issues by setting up direct DBus communication.\n- Workspace: Ensured runtime starts when agent session spawns to prevent missing dependencies.\n- AI Gateway: Fixed handling of `:latest` style model names (e.g., `gpt-oss:latest`).\n- Workspace: Blocked `pnpm dev`, `pnpm start`, and `pnpm run` variants since Quests already manages app lifecycle.\n\n## Water Vehicle\n\n<!-- Image placeholder -->\n\n_23 commits since v1.4.2_\n```\n"},"lastSynced":"2026-03-08T02:07:44.329Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated version tracking and release note generation using git commits and tags.","zh":"非常适合需要使用git提交和标签自动跟踪版本和生成发布说明的开发代理","ja":"開発エージェントがgitコミットとタグを使用して自動バージョントラッキングとリリースノートの生成を必要とする場合に最適","ko":"git 커밋과 태그를 사용하여 자동 버전 추적 및 릴리스 노트 생성이 필요한 개발 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollo que necesitan un seguimiento de versiones automatizado y generación de notas de lanzamiento utilizando git commits y tags.","fr":"Parfait pour les Agents de Développement ayant besoin d''un suivi de version automatisé et de génération de notes de publication à l''aide de git commits et tags.","de":"Perfekt für Entwicklungsmittel, die ein automatisiertes Versionsverfolgen und eine Generierung von Versionshinweisen unter Verwendung von git-Commits und -Tags benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de rastreamento de versão automatizado e geração de notas de lançamento usando commits e tags do git.","ru":"Идеально для агентов разработки, которым требуется автоматизированный отслеживание версий и генерация заметок о выпуске с использованием коммитов и тегов git.","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى تتبع إصدار آلي وتوليد ملاحظات الإصدار باستخدام التعليقات والتسميات الجيت."},"recommendation":{"en":"Empowers agents to generate detailed change logs based on git history, utilizing markdown formatting and excluding verbatim commit messages, while providing a clear overview of changes between versions using git tags and commit inspection.","zh":"使代理能够生成基于git历史的详细更改日志，利用markdown格式化，并排除逐字的提交消息，同时提供git标签和提交检查之间的更改的清晰概述","ja":"エージェントがgit履歴に基づいて詳細な変更ログを生成できるようにし、markdown形式を使用し、逐語のコミットメッセージを除外し、gitタグとコミットの検査によってバージョン間の変更の明確な概要を提供する","ko":"에이전트가 git 기록을 기반으로詳細한 변경 로그를 생성할 수 있도록 하며, markdown 형식을 사용하고,逐語의 커밋 메시지를 제외하며, git 태그와 커밋 검사에 의한 버전 간의 변경의 명확한 개요를 제공","es":"Habilita a los agentes a generar registros de cambios detallados en función del historial de git, utilizando la formato markdown y excluyendo los mensajes de commit literales, al mismo tiempo que proporciona una visión general clara de los cambios entre versiones utilizando git tags y inspección de commit.","fr":"Permet aux agents de générer des journaux de modifications détaillés en fonction de l''historique de git, en utilisant le formatage markdown et en excluant les messages de commit verbatim, tout en fournissant une vue d''ensemble claire des modifications entre les versions à l''aide de git tags et d''inspection de commit.","de":"Ermächtigt die Mittel, detaillierte Änderungsprotokolle auf der Grundlage der git-Historie zu erstellen, wobei das markdown-Format verwendet und die wörtlichen Commit-Mitteilungen ausgeschlossen werden, während gleichzeitig eine klare Übersicht über die Änderungen zwischen den Versionen mithilfe von git-Tags und Commit-Inspektion bereitgestellt wird.","pt":"Habilita os agentes a gerar registros de alterações detalhados com base na história do git, utilizando formatação markdown e excluindo mensagens de commit literal, enquanto fornece uma visão geral clara das alterações entre versões usando tags e inspeção de commit do git.","ru":"Наделяет агентов возможностью генерировать подробные журналы изменений на основе истории git, используя форматирование markdown и исключая дословные сообщения коммитов, а также обеспечивая четкий обзор изменений между версиями с помощью тегов и инспекции коммитов git.","ar":"يمنح الوكلاء القدرة على توليد سجلات تغيير مفصلة بناءً على تاريخ الجيت، باستخدام تنسيق ماركداون واستبعاد رسائل Commit الحرفية، مع تقديم نظرة عامة واضحة للتغييرات بين الإصدارات باستخدام علامات الجيت وفحص Commit."},"useCases":{"en":["Automating release note generation","Generating version-specific change logs","Inspecting commit content for key changes"],"zh":["自动生成发布说明","生成特定版本的更改日志","检查提交内容以获取关键更改"],"ja":["リリースノートの自動生成","バージョン別の変更ログの生成","コミット内容の検査による重要な変更の検出"],"ko":["릴리스 노트 자동 생성","버전별 변경 로그 생성","커밋 내용 검사에 의한 주요 변경 사항 검출"],"es":["Automatización de la generación de notas de lanzamiento","Generación de registros de cambios específicos de la versión","Inspección del contenido del commit para detectar cambios clave"],"fr":["Automatisation de la génération de notes de publication","Génération de journaux de modifications spécifiques à la version","Inspection du contenu du commit pour détecter les modifications clés"],"de":["Automatisierung der Generierung von Versionshinweisen","Erstellung von versionspezifischen Änderungsprotokollen","Inspektion des Commit-Inhalts zur Erkennung von Schlüsseländerungen"],"pt":["Automatizar a geração de notas de lançamento","Gerar registros de alterações específicos da versão","Inspecionar o conteúdo do commit para alterações importantes"],"ru":["Автоматизировать генерацию заметок о выпуске","Генерировать журналы изменений, специфичные для версии","Осматривать содержимое коммита на ключевые изменения"],"ar":["تأتمتة توليد ملاحظات الإصدار","توليد سجلات التغيير الخاصة بالإصدار","فحص محتوى Commit للتحديثات الرئيسية"]},"limitations":{"en":["Requires git repository access","Only supports non-beta tagged versions","Excludes verbatim commit messages"],"zh":["需要git仓库访问权限","仅支持非beta标记的版本","排除逐字的提交消息"],"ja":["gitリポジトリへのアクセスが必要","ベータ以外のタグ付けされたバージョンのみをサポート","逐語のコミットメッセージを除外"],"ko":["git 저장소 액세스 필요","비 베타 태그가 붙은 버전만 지원","逐語의 커밋 메시지를 제외"],"es":["Requiere acceso al repositorio git","Solo admite versiones con etiquetas no beta","Excluye los mensajes de commit literales"],"fr":["Nécessite un accès au référentiel git","N''est compatible qu''avec les versions étiquetées non bêta","Exclut les messages de commit verbatim"],"de":["Benötigt Zugriff auf das git-Repository","Unterstützt nur nicht-beta-getaggte Versionen","Schließt die wörtlichen Commit-Mitteilungen aus"],"pt":["Exige acesso ao repositório git","Apenas suporta versões não-beta com tags","Exclui mensagens de commit literal"],"ru":["Требует доступа к репозиторию git","Поддерживает только версии, не отмеченные как бета","Исключает дословные сообщения коммитов"],"ar":["يتطلب الوصول إلى مستودع الجيت","يدعم فقط الإصدارات غير بيتا المسمى","استبعاد رسائل Commit الحرفية"]},"version":4},"contentHash":"47d2a62152e7f8eecd66bdfd5bd0221ba8553ea072cf32224e49dd3c0ca53922","qualityScore":60}');
