INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('quests-org/quests/changelog', 'changelog', 'quests-org', 'quests', 'community', 'changelog quests-org quests community The changelog skill generates a change log based on git commits and tags, benefiting developers by automating version tracking. It uses git to find the most recent tagged non-beta version and inspects commit content. Changelog技能用于生成变更日志，通过Git查找最新标签版本并生成Markdown代码块 Changelog スキルは、Git を使用して最新のタグ付きバージョンを検索し、Markdown コードブロックを生成して変更ログを作成するために使用されます Changelog 스킬은 Git을 사용하여 최신 태그가 있는 버전을 찾고 Markdown 코드 블록을 생성하여 변경 로그를 생성하는 데 사용됩니다 El agente de AI ''changelog'' utiliza git para generar registros de cambios en tu proyecto de desarrollo L''agent d''AI ''changelog'' utilise git pour générer des journaux de modifications dans votre projet de développement Der AI-Agent ''changelog'' verwendet git, um Änderungsprotokolle in Ihrem Entwicklungsprojekt zu generieren O changelog é uma ferramenta de código aberto que gera registros de alterações para aplicativos. Ele usa git e markdown para criar um registro de alterações. Чейнджлог - это открытый инструмент, который генерирует журнал изменений для приложений. Он использует git и markdown для создания журнала изменений. سجل التغييرات هو أداة بناء تطبيقات مفتوحة المصدر التي ت生成 سجلات التغييرات لتطبيقات. انها تستخدم git و markdown لإنشاء سجل التغييرات how to use changelog what is changelog changelog alternative changelog vs git changelog install changelog setup guide automated version tracking git commit analysis markdown change log generation Changelog Git 变更日志 Markdown 开源应用程序构建器 AIエージェント 版本控制系统 Uses git to find the most recent tagged non-beta version Inspects content of larger commits for change log generation Generates a change log in markdown code block format Finds the previous version for comparison Returns results in a markdown code block Follows a specific style based on example change logs changelog is an open-source app builder that automates version tracking using git and markdown');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nilecui/SkillsBase/mermaid', 'community', 'nilecui', 'SkillsBase', 'nilecui/SkillsBase', 'mermaid', 0, 0, 60, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:41.718Z', '30cca46e4a8e86a467cded4732d24c0eff4e2e584fb60800a23035ddf802f86a', '{"id":"nilecui/SkillsBase/mermaid","name":"mermaid","description":{"en":"The Mermaid skill helps developers create, validate, and render Mermaid diagrams from natural language descriptions, code analysis, or by editing existing diagrams, benefiting developers and technical writers.","zh":"Mermaid Skill帮助您创建、验证和渲染Mermaid图表，支持自然语言描述、代码分析和现有图表编辑","ja":"Mermaid AIエージェントは、自然言語の説明、コード分析、または既存のダイアグラムの編集からMermaidダイアグラムを作成、検証、レンダリングするのに役立ちます","ko":"Mermaid Skill은 자연어 설명, 코드 분석 또는 기존 다이어그램 편집에서 Mermaid 다이어그램을 생성, 검증 및 렌더링하는 데 도움이 됩니다","es":"Mermaid es una habilidad que permite crear y validar diagramas desde descripciones de lenguaje natural o análisis de código","fr":"Mermaid est une compétence qui permet de créer et de valider des diagrammes à partir de descriptions de langage naturel ou d''analyse de code","de":"Mermaid ist eine Fähigkeit, die das Erstellen und Validieren von Diagrammen aus natürlichen Sprachbeschreibungen oder Codeanalysen ermöglicht","pt":"O Mermaid é uma habilidade que permite criar, validar e renderizar diagramas a partir de descrições em linguagem natural ou análise de código. Ele suporta vários tipos de diagramas, incluindo flowcharts e sequências","ru":"Mermaid — это навык, который позволяет создавать, проверять и отображать диаграммы из естественных языковых описаний или анализа кода. Он поддерживает различные типы диаграмм, включая потоковые диаграммы и последовательности","ar":"Mermaid هو مهارة تسمح بإنشاء وتحويل وتصيير مخططات من وصفات لغة طبيعية أو تحليل رمز. يدعم عدة أنواع من المخططات، بما في ذلك مخططات التدفق ومخططات التتابع"},"seo":{"title":{"en":"Mermaid: Diagram Creation and Validation Guide | AI Agent...","zh":"Mermaid Setup Guide: AIエージェント diagram 创建和验证","ja":"Mermaid AIエージェントを使用したダイアグラム作成と検証","ko":"Mermaid 다이어그램 생성 및 유효성 검사 가이드","es":"Guía de configuración de Mermaid para diagramas de flujo","fr":"Guide de mise en place de Mermaid pour les diagrammes de ...","de":"Einrichtungsleitfaden für Mermaid-Diagramme","pt":"Guia de Configuração do Mermaid para Desenvolvedores","ru":"Руководство по настройке Mermaid для разработчиков ИИ Аге...","ar":"دليل إعداد Mermaid لمنشئي التطبيقات"},"description":{"en":"Unlock the power of Mermaid diagrams! Learn how to create, validate, and render diagrams from natural language descriptions and code analysis. Get started now!","zh":"了解Mermaid Skill的功能和工作流程，掌握AIエージェント技术创建和验证Mermaid图表的方法","ja":"Mermaid AIエージェントを使用して、フローチャート、シーケンス、クラス図などを作成と検証する方法を学ぶ","ko":"Mermaid 다이어그램 생성 및 유효성 검사를 위한 핵심 워크플로우와 기능을 확인하십시오","es":"Cree diagramas de Mermaid con nuestro agente de inteligencia artificial, incluyendo flujo, secuencia y jerarquía","fr":"Créez des diagrammes Mermaid avec notre outil d''IA, y compris les flux, les séquences et les hiérarchies","de":"Erstellen Sie Mermaid-Diagramme mit unserem KI-Tool, einschließlich Fluss, Sequenz und Hierarchie","pt":"Aprenda a criar, validar e renderizar diagramas Mermaid a partir de descrições em linguagem natural, análise de código ou edição de diagramas existentes","ru":"Узнайте, как создавать, проверять и отображать диаграммы Mermaid из естественных языковых описаний, анализа кода или редактирования существующих диаграмм с п...","ar":"تعلم كيفية إنشاء وتحويل وتصيير مخططات Mermaid من وصفات لغة طبيعية أو تحليل رمز أو تحرير مخططات موجودة"},"definition":{"en":"Mermaid is a skill that enables the creation, validation, and rendering of Mermaid diagrams from various inputs, including natural language and code analysis.","zh":"Mermaid Skill是一种AIエージェント技术，用于创建、验证和渲染Mermaid图表","ja":"Mermaid AIエージェントは、Mermaidダイアグラムを作成、検証、レンダリングするための技術です","ko":"Mermaid Skill은 Mermaid 다이어그램을 생성, 검증 및 렌더링하는 데 사용되는 기술입니다","es":"Mermaid es un agente de inteligencia artificial para crear diagramas de flujo y secuencia","fr":"Mermaid est un outil d''IA pour créer des diagrammes de flux et de séquence","de":"Mermaid ist ein KI-Tool zum Erstellen von Fluss- und Sequenzdiagrammen","pt":"O Mermaid é uma habilidade de criação de diagramas que usa linguagem natural ou análise de código para gerar diagramas","ru":"Mermaid — это навык создания диаграмм, который использует естественные языковые описания или анализ кода для генерации диаграмм","ar":"Mermaid هو مهارة لإنشاء المخططات التي تستخدم لغة طبيعية أو تحليل رمز لإنشاء مخططات"},"features":{"en":["Creates Mermaid diagrams from natural language descriptions","Validates and renders diagrams from code analysis","Supports editing of existing diagrams","Identifies diagram type needed, such as flowchart or sequence diagram","Extracts key elements like entities, relationships, and flow"],"zh":["支持自然语言描述创建Mermaid图表","支持代码分析生成Mermaid图表","支持编辑现有Mermaid图表","创建流程图、序列图、类图等","支持图表验证和渲染"],"ja":["自然言語の説明からMermaidダイアグラムを作成","コード分析からMermaidダイアグラムを作成","既存のMermaidダイアグラムの編集","フローチャート、シーケンス、クラス図などの作成","ダイアグラムの検証とレンダリング"],"ko":["자연어 설명에서 Mermaid 다이어그램 생성","코드 분석에서 Mermaid 다이어그램 생성","기존 Mermaid 다이어그램 편집","흐름도, 시퀀스도, 클래스도 등 생성","다이어그램 유효성 검사 및 렌더링"],"es":["Creación de diagramas de flujo y secuencia","Validación de diagramas","Edición de diagramas existentes","Generación de diagramas a partir de código","Soporte para entidades, relaciones y jerarquías"],"fr":["Création de diagrammes de flux et de séquence","Validation de diagrammes","Édition de diagrammes existants","Génération de diagrammes à partir de code","Prise en charge d''entités, de relations et de hiérarchies"],"de":["Erstellung von Fluss- und Sequenzdiagrammen","Validierung von Diagrammen","Bearbeitung von bestehenden Diagrammen","Generierung von Diagrammen aus Code","Unterstützung für Entitäten, Beziehungen und Hierarchien"],"pt":["Criação de diagramas a partir de descrições em linguagem natural","Validação e renderização de diagramas","Suporte a vários tipos de diagramas, incluindo flowcharts e sequências","Edição de diagramas existentes","Geração de diagramas a partir de análise de código"],"ru":["Создание диаграмм из естественных языковых описаний","Проверка и отображение диаграмм","Поддержка различных типов диаграмм, включая потоковые диаграммы и последовательности","Редактирование существующих диаграмм","Генерация диаграмм из анализа кода с помощью ИИ Агентов"],"ar":["إنشاء مخططات من وصفات لغة طبيعية","تحويل وتصيير مخططات","دعم عدة أنواع من المخططات، بما في ذلك مخططات التدفق ومخططات التتابع","تحرير مخططات موجودة","إنشاء مخططات من تحليل رمز"]},"keywords":{"en":["how to use mermaid","what is mermaid","mermaid alternative","mermaid vs graphviz","mermaid install","mermaid setup guide","mermaid diagram creation","mermaid validation and rendering"],"zh":["Mermaid图表","AIエージェント技术","自然语言描述","代码分析","图表验证","Mermaid Skill","Mermaid Setup Guide"],"ja":["Mermaidダイアグラム","AIエージェント","自然言語の説明","コード分析","ダイアグラムの検証","Mermaid AIエージェント","Mermaidの使い方"],"ko":["Mermaid 다이어그램","AI 에이전트","자연어 설명","코드 분석","다이어그램 유효성 검사","Mermaid Skill","Mermaid 사용법"],"es":["Mermaid","diagramas de flujo","diagramas de secuencia","agente de inteligencia artificial","herramientas de desarrollo","creación de diagramas","validación de diagramas","edición de diagramas"],"fr":["Mermaid","diagrammes de flux","diagrammes de séquence","outils d''IA","outils de développement","création de diagrammes","validation de diagrammes","édition de diagrammes"],"de":["Mermaid","Flussdiagramme","Sequenzdiagramme","KI-Tool","Entwicklertools","Erstellung von Diagrammen","Validierung von Diagrammen","Bearbeitung von Diagrammen"],"pt":["Mermaid","criação de diagramas","análise de código","linguagem natural","flowcharts","sequências","edição de diagramas","desenvolvimento de software"],"ru":["Mermaid","создание диаграмм","анализ кода","естественные языковые описания","потоковые диаграммы","последовательности","редактирование диаграмм","разработка программного обеспечения","ИИ Агенты"],"ar":["Mermaid","إنشاء مخططات","تحليل رمز","لغة طبيعية","مخططات التدفق","مخططات التتابع","تحرير مخططات","تطوير تطبيقات","أدوات الذكاء الاصطناعي"]}},"owner":"nilecui","repo":"SkillsBase","repoPath":"nilecui/SkillsBase","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"mermaid","description":"Guide for creating mermaid diagrams. This skill should be used when users want to create a mermaid diagram (or update an existing diagram).","bodyPreview":"# Mermaid Diagram Skill\n\nThis skill helps you create, validate, and render Mermaid diagrams from natural language descriptions, code analysis, or by editing existing diagrams.\n\n## Core Workflow\n\nFollow these steps for every diagram creation/modification:\n\n### 1. Understand the Request\n- Identify the diagram type needed (flowchart, sequence, class, etc.)\n- Extract key elements: entities, relationships, flow, hierarchy\n- Determine if creating new, editing existing, or generating from code\n\n### 2.","body":"# Mermaid Diagram Skill\n\nThis skill helps you create, validate, and render Mermaid diagrams from natural language descriptions, code analysis, or by editing existing diagrams.\n\n## Core Workflow\n\nFollow these steps for every diagram creation/modification:\n\n### 1. Understand the Request\n- Identify the diagram type needed (flowchart, sequence, class, etc.)\n- Extract key elements: entities, relationships, flow, hierarchy\n- Determine if creating new, editing existing, or generating from code\n\n### 2. Generate Mermaid Code\n- Create syntactically correct Mermaid diagram code\n- Use appropriate diagram type syntax\n- Apply consistent naming and styling\n- Refer to `examples/` directory for type-specific syntax (load on-demand)\n\n### 3. Save to File\n- Write code to `.mmd` file\n- Generate meaningful filename based on diagram purpose (e.g., `user-authentication-flow.mmd`, `database-schema.mmd`)\n- Use kebab-case for filenames\n\n### 4. Validate with CLI\n- **ALWAYS** validate using: `mmdc -i <filename>.mmd`\n- Check for syntax errors and warnings\n- If validation fails, proceed to step 5\n\n### 5. Auto-Correct Errors\n- Analyze error messages from `mmdc`\n- Common issues:\n  - Invalid syntax or keywords\n  - Missing quotes around labels with spaces\n  - Incorrect arrow syntax\n  - Malformed node definitions\n- Automatically fix the code\n- Re-save and re-validate\n- Repeat until validation succeeds\n\n### 6. Render on Request\n- Default format: **SVG**\n- Command: `mmdc -i <filename>.mmd -o <filename>.svg`\n- Alternative formats: PNG (`-o <filename>.png`), PDF (`-o <filename>.pdf`)\n- Only render when user explicitly requests a preview/image\n\n## Supported Diagram Types\n\nLoad examples from `examples/` directory as needed:\n\n**Basic Diagrams:**\n- Flowchart (`examples/flowchart.md`)\n- Sequence Diagram (`examples/sequence.md`)\n- Class Diagram (`examples/class.md`)\n- State Diagram (`examples/state.md`)\n- Entity Relationship (`examples/er.md`)\n\n**Planning & Management:**\n- Gantt Chart (`examples/gantt.md`)\n- User Journey (`examples/journey.md`)\n- Timeline (`examples/timeline.md`)\n- Kanban (`examples/kanban.md`)\n\n**Data Visualization:**\n- Pie Chart (`examples/pie.md`)\n- XY Chart (`examples/xy-chart.md`)\n- Quadrant Chart (`examples/quadrant.md`)\n- Sankey (`examples/sankey.md`)\n- Radar (`examples/radar.md`)\n- Treemap (`examples/treemap.md`)\n\n**Technical Diagrams:**\n- Git Graph (`examples/git.md`)\n- C4 Diagram (`examples/c4.md`)\n- Requirement Diagram (`examples/requirement.md`)\n- Architecture (`examples/architecture.md`)\n- Block Diagram (`examples/block.md`)\n- Packet (`examples/packet.md`)\n\n**Organizational:**\n- Mindmap (`examples/mindmap.md`)\n- ZenUML (`examples/zenuml.md`)\n\n## Code Analysis → Diagram\n\nWhen analyzing code to create diagrams:\n\n**Class Diagrams:**\n- Extract classes, methods, properties, inheritance, interfaces\n- Show relationships: inheritance, composition, aggregation\n\n**Sequence Diagrams:**\n- Track function calls, async operations, API interactions\n- Show actors, lifelines, activation boxes\n\n**Flowcharts:**\n- Map control flow, conditionals, loops\n- Show function entry/exit points\n\n**State Diagrams:**\n- Identify states from enums, state machines, status fields\n- Map transitions and events\n\n## Templates\n\nCommon patterns available in `templates/common-patterns.md` (load on-demand):\n- Standard flowchart structures\n- API sequence patterns\n- Database ER patterns\n- Microservice architecture layouts\n- State machine templates\n\n## Best Practices\n\n**Styling:**\n- Use meaningful node IDs\n- Add clear, concise labels\n- Apply subgraphs for grouping related elements\n- Use classDefs for visual consistency\n\n**Readability:**\n- Keep diagrams focused (split large diagrams into smaller ones)\n- Use top-to-bottom or left-to-right orientation consistently\n- Add comments in code for complex sections\n\n**Validation:**\n- NEVER skip validation step\n- Always fix errors before presenting to user\n- Test rendered output when in doubt\n\n## Error Handling\n\nIf `mmdc` validation fails:\n1. Read error message carefully\n2. Identify line number and issue\n3. Apply fix (common fixes in examples)\n4. Re-validate\n5. Inform user only if repeated attempts fail\n\n## Output Format\n\nPresent to user:\n```\nCreated: <filename>.mmd\n\n<Show the mermaid code in a code block>\n\n✓ Validated successfully with mermaid-cli\n```\n\nIf rendered:\n```\nCreated: <filename>.mmd\nRendered: <filename>.svg\n\n[Show file paths]\n```\n\n## Notes\n\n- Assume `mmdc` (mermaid-cli) is installed and available\n- Default output format: SVG\n- Always validate before presenting\n- Fix errors autonomously\n- Only load example files when needed for specific diagram type\n"},"lastSynced":"2026-03-08T02:08:41.718Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing advanced diagramming and visualization capabilities for Mermaid diagrams.","zh":"非常适合需要高级图表和可视化功能的技术写作代理，尤其是用于Mermaid图表。","ja":"Mermaidダイアグラムの高度な図表化および視覚化機能を必要とするテクニカルライティングエージェントに最適です。","ko":"Mermaid 다이어그램에 대한 고급 도표 및 시각화 기능을 필요로 하는 기술 문서 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Escritura Técnica que necesitan capacidades de diagramación y visualización avanzadas para diagramas Mermaid.","fr":"Parfait pour les agents de rédaction technique ayant besoin de capacités de diagramme et de visualisation avancées pour les diagrammes Mermaid.","de":"Perfekt für technische Schreibagenten, die erweiterte Diagramm- und Visualisierungsfunktionen für Mermaid-Diagramme benötigen.","pt":"Perfeito para Agentes de Redação Técnica que necessitam de capacidades avançadas de diagramação e visualização para diagramas Mermaid.","ru":"Идеально для агентов технической документации, которым требуются расширенные возможности диаграммирования и визуализации для диаграмм Mermaid.","ar":"مثالي لوكلاء الكتابة الفنية الذين يحتاجون إلى إمكانيات متقدمة لرسوم التخطيط والتصوير للمخططات Mermaid."},"recommendation":{"en":"Empowers agents to generate, validate, and render Mermaid diagrams from natural language descriptions, code analysis, or by editing existing diagrams, utilizing Mermaid syntax and supporting flowcharts, sequences, and class diagrams in various formats.","zh":"赋予代理生成、验证和渲染Mermaid图表的能力，从自然语言描述、代码分析或编辑现有图表，利用Mermaid语法，并支持流程图、序列图和类图等多种格式。","ja":"エージェントが自然言語の説明、コード分析、または既存のダイアグラムの編集からMermaidダイアグラムを生成、検証、レンダリングする能力を提供し、Mermaid構文を利用し、さまざまな形式のフローチャート、シーケンスダイアグラム、クラスダイアグラムをサポートします。","ko":"에이전트가 자연어 설명, 코드 분석 또는 기존 다이어그램 편집에서 Mermaid 다이어그램을 생성, 검증 및 렌더링 할 수 있는 기능을 제공하며, Mermaid 구문을 사용하고 다양한 형식의 흐름도, 시퀸스 다이어그램, 클래스 다이어그램을 지원합니다.","es":"Permite a los agentes generar, validar y renderizar diagramas Mermaid a partir de descripciones de lenguaje natural, análisis de código o editando diagramas existentes, utilizando la sintaxis Mermaid y admitiendo flujogramas, secuencias y diagramas de clases en varios formatos.","fr":"Permet aux agents de générer, de valider et de rendre des diagrammes Mermaid à partir de descriptions de langage naturel, d''analyse de code ou en éditant des diagrammes existants, en utilisant la syntaxe Mermaid et en prenant en charge les organigrammes, les séquences et les diagrammes de classes dans divers formats.","de":"Ermächtigt Agenten, Mermaid-Diagramme aus natürlichen Sprachbeschreibungen, Codeanalysen oder durch Bearbeiten bestehender Diagramme zu generieren, zu validieren und zu rendern, unter Verwendung der Mermaid-Syntax und Unterstützung von Flussdiagrammen, Sequenzen und Klassendiagrammen in verschiedenen Formaten.","pt":"Habilita os agentes a gerar, validar e renderizar diagramas Mermaid a partir de descrições em linguagem natural, análise de código ou editando diagramas existentes, utilizando a sintaxe Mermaid e suportando fluxogramas, sequências e diagramas de classe em vários formatos.","ru":"Наделяет агентов возможностью генерировать, проверять и отображать диаграммы Mermaid из естественно-языковых описаний, анализа кода или редактирования существующих диаграмм, используя синтаксис Mermaid и поддерживая блок-схемы, последовательности и диаграммы классов в различных форматах.","ar":"يمنح الوكلاء القدرة على إنتاج وตรวจ验 وعرض مخططات Mermaid من وصفات اللغة الطبيعية أو تحليل الشفرة أو تحرير المخططات الحالية، باستخدام بناء الجملة Mermaid ودعم مخططات الانسياب والتسلسلات ومخططات الفئة في صيغ متعددة."},"useCases":{"en":["Creating flowcharts from code analysis","Editing existing Mermaid diagrams for technical documentation","Generating sequence diagrams from natural language descriptions"],"zh":["从代码分析创建流程图","编辑现有的Mermaid图表以进行技术文档编写","从自然语言描述生成序列图"],"ja":["コード分析からフローチャートを作成する","技術文書化のために既存のMermaidダイアグラムを編集する","自然言語の説明からシーケンスダイアグラムを生成する"],"ko":["코드 분석에서 흐름도를 생성하는 것","기존의 Mermaid 다이어그램을 편집하여 기술 문서를 작성하는 것","자연어 설명에서 시퀸스 다이어그램을 생성하는 것"],"es":["Creación de flujogramas a partir del análisis de código","Edición de diagramas Mermaid existentes para documentación técnica","Generación de diagramas de secuencia a partir de descripciones de lenguaje natural"],"fr":["Création d''organigrammes à partir de l''analyse de code","Édition de diagrammes Mermaid existants pour la documentation technique","Génération de diagrammes de séquence à partir de descriptions de langage naturel"],"de":["Erstellung von Flussdiagrammen aus Codeanalysen","Bearbeiten bestehender Mermaid-Diagramme für technische Dokumentation","Generierung von Sequenzdiagrammen aus natürlichen Sprachbeschreibungen"],"pt":["Criação de fluxogramas a partir da análise de código","Edição de diagramas Mermaid existentes para documentação técnica","Geração de diagramas de sequência a partir de descrições em linguagem natural"],"ru":["Создание блок-схем из анализа кода","Редактирование существующих диаграмм Mermaid для технической документации","Генерация диаграмм последовательности из естественно-языковых описаний"],"ar":["إنشاء مخططات انسياب من تحليل الشفرة","تحرير مخططات Mermaid الحالية لتوثيق فني","إنتاج مخططات تسلسلية من وصفات اللغة الطبيعية"]},"limitations":{"en":["Requires Mermaid syntax knowledge","Limited to Mermaid diagram types (flowchart, sequence, class, etc.)"],"zh":["需要Mermaid语法知识","仅限Mermaid图表类型（流程图、序列图、类图等）"],"ja":["Mermaid構文の知識が必要","Mermaidダイアグラムのタイプ（フローチャート、シーケンスダイアグラム、クラスダイアグラムなど）に限定される"],"ko":["Mermaid 구문 지식이 필요","Mermaid 다이어그램 유형（흐름도, 시퀸스 다이어그램, 클래스 다이어그램 등）으로 제한됨"],"es":["Requiere conocimiento de la sintaxis Mermaid","Limitado a los tipos de diagramas Mermaid (flujograma, secuencia, clase, etc.)"],"fr":["Nécessite des connaissances en syntaxe Mermaid","Limité aux types de diagrammes Mermaid (organigramme, séquence, classe, etc.)"],"de":["Benötigt Kenntnisse der Mermaid-Syntax","Begrenzt auf Mermaid-Diagrammtypen (Flussdiagramm, Sequenz, Klasse usw.)"],"pt":["Exige conhecimento da sintaxe Mermaid","Limitado a tipos de diagramas Mermaid (fluxograma, sequência, classe, etc.)"],"ru":["Требует знания синтаксиса Mermaid","Ограничен типами диаграмм Mermaid (блок-схема, последовательность, класс и т. д.)"],"ar":["يتطلب معرفة بناء الجملة Mermaid","محدود بنوع مخططات Mermaid (مخطط الانسياب، التسلسلة، الفئة، إلخ)"]},"version":4},"contentHash":"30cca46e4a8e86a467cded4732d24c0eff4e2e584fb60800a23035ddf802f86a","qualityScore":60}');
