INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getlago/lago-front/migrate-formik-to-tanstack', 'migrate-formik-to-tanstack', 'getlago', 'lago-front', 'community', 'migrate-formik-to-tanstack getlago lago-front community The migrate-formik-to-tanstack skill helps developers migrate React form components from Formik to TanStack Form, following established patterns. It guides the migration process for a target form specified by the user. 该技能指导如何将 React 表单组件从 Formik 迁移到 TanStack Form，遵循已建立的代码库模式 このスキルは、React フォーム コンポーネントを Formik から TanStack Form へ移行する方法を、既存のコードベースのパターンに従ってガイドします 이 스킬은 React 폼 컴포넌트를 Formik에서 TanStack Form으로 마이그레이션하는 방법을 이미 설정된 코드베이스 패턴을 따라 가이드합니다 Esta habilidad guía la migración de componentes de formulario de React de Formik a TanStack Cette compétence guide la migration des composants de formulaire React de Formik à TanStack Diese Fähigkeit leitet die Migration von React-Formularkomponenten von Formik zu TanStack Migre componentes de formulário React do Formik para o TanStack Form com este guia técnico Перенесите компоненты формы React из Formik в TanStack Form с помощью этого технического руководства انقل مكونات الاستمارة React من Formik إلى TanStack Form باستخدام هذا الدليل الفني how to migrate formik to tanstack migrate-formik-to-tanstack setup guide tanstack form migration tutorial formik vs tanstack form migrate-formik-to-tanstack install react form component migration tanstack form alternative to formik Formik 到 TanStack 表单迁移 React 表单组件 TanStack Form AIエージェント 表单迁移工具 React 开发 表单组件库 Guides migration of React form components from Formik to TanStack Form Utilizes the AskUserQuestion tool to prompt users for the form path Follows established patterns in the codebase for seamless integration Supports specification of target forms via $ARGUMENTS Ensures accurate migration by reading reference files for context migrate-formik-to-tanstack is a skill that enables the migration of React form components from Formik to TanStack Form, leveraging the AskUserQuestion tool for path specification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kubrickcode/specvital/validate-parser', 'community', 'kubrickcode', 'specvital', 'kubrickcode/specvital', 'validate-parser', 0, 0, 60, '2026-03-08T01:57:15.446Z', '2026-03-08T02:08:56.178Z', 'af7b09135b625e6206c12574d25965e5ef82263e66065984454c283d98022210', '{"id":"kubrickcode/specvital/validate-parser","name":"validate-parser","description":{"en":"The validate-parser skill operates within the lib directory, providing real-world parser validation for SpecVital Core parser. It benefits developers working with parser integration and validation.","zh":"validate-parser 是一个用于验证解析器的 AI 代理技能，提供解析器验证命令和报告输出","ja":"validate-parser は、パーサーを検証する AI エージェント スキルであり、パーサー検証コマンドと報告出力を提供する","ko":"validate-parser는 파서를 검증하는 AI 에이전트 스킬로 파서 유효성 검사 명령과 보고서 출력을 제공합니다","es":"Validate-parser es una herramienta de validación de parsers que opera dentro de lib, permitiendo a los desarrolladores verificar la integridad de sus parsers","fr":"Validate-parser est un outil de validation de parsers qui fonctionne à l''intérieur de lib, permettant aux développeurs de vérifier l''intégrité de leurs parsers","de":"Validate-parser ist ein Validierungstool für Parser, das innerhalb von lib arbeitet und es Entwicklern ermöglicht, die Integrität ihrer Parser zu überprüfen","pt":"O validate-parser é uma ferramenta de validação de parser que opera exclusivamente dentro do lib, com recursos de integração e testes.","ru":"Validate-parser - это инструмент валидации парсера, работающий исключительно внутри lib, с возможностями интеграции и тестирования.","ar":"validate-parser هو أداة التحقق من صحة parser التي تعمل حصريًا داخل lib، مع ميزات التكامل والاختبار."},"seo":{"title":{"en":"validate-parser: Real-World Parser Validation Setup Guide...","zh":"validate-parser 设置指南：解析器验证命令","ja":"validate-parser セットアップガイド：パーサー検証コマンド","ko":"validate-parser 설정 가이드: 파서 유효성 검사 명령","es":"Guía de Configuración de validate-parser para Agentes de IA","fr":"Guide d''Installation de validate-parser pour les Outils d''IA","de":"Einrichtungsleitfaden für validate-parser in KI-Agents","pt":"Guia de Configuração do validate-parser para Desenvolvedores","ru":"ИИ Агенты: Настройка validate-parser для Разработчиков","ar":"إعداد validate-parser للمانحين: دليل المستخدم"},"description":{"en":"Unlock efficient parser validation with validate-parser. Learn how to integrate and utilize this skill for optimized parsing. Get started now!","zh":"了解 validate-parser 的工作原理和设置方法，优化您的解析器验证流程","ja":"validate-parser のしくみと設定方法を学び、パーサー検証プロセスを最適化する","ko":"validate-parser의 작동 원리와 설정 방법을 알아보고 파서 유효성 검사 프로세스를 최적화합니다","es":"Aprende a validar parsers con validate-parser, una herramienta de IA para desarrolladores. Descubre cómo funciona y cómo integrarla en tu proyecto","fr":"Découvrez comment valider les parsers avec validate-parser, un outil d''IA pour les développeurs. Comprenez son fonctionnement et son intégration","de":"Erfahren Sie, wie Sie Parser mit validate-parser validieren, einem KI-Tool für Entwickler. Erkenne, wie es funktioniert und wie es in Ihr Projekt integriert ...","pt":"Aprenda a configurar e utilizar o validate-parser em projetos de desenvolvimento com lib e SpecVital Core parser","ru":"Узнайте, как настроить и использовать validate-parser в проектах разработки с lib и SpecVital Core parser","ar":"تعرف على كيفية إعداد وتشغيل validate-parser في مشاريع التطوير باستخدام lib و SpecVital Core parser"},"definition":{"en":"validate-parser is a skill that validates parsers within the lib directory, utilizing source code from lib/parser/, lib/crypto/, and lib/source/.","zh":"validate-parser 是一种 AI 工具，用于验证解析器的正确性和有效性","ja":"validate-parser は、パーサーの正しさと有効性を検証する AI ツールである","ko":"validate-parser는 파서의 정확성과 유효성을 검증하는 AI 도구입니다","es":"Validate-parser es una herramienta de validación de parsers que verifica la sintaxis y la estructura de los parsers","fr":"Validate-parser est un outil de validation de parsers qui vérifie la syntaxe et la structure des parsers","de":"Validate-parser ist ein Validierungstool für Parser, das die Syntax und die Struktur der Parser überprüft","pt":"O validate-parser é uma ferramenta de validação de parser que verifica a correta interpretação de comandos e arquivos","ru":"Validate-parser - это инструмент валидации парсера, проверяющий правильную интерпретацию команд и файлов","ar":"validate-parser هو أداة التحقق من صحة parser التي تحقق من تفسير الصحيح للأوامر والملفات"},"features":{"en":["Operates exclusively within the lib directory for SpecVital Core parser","Utilizes source code from lib/parser/, lib/crypto/, and lib/source/","Supports integration tests via lib/parser/tests/integration/","References repos.yaml for repository configuration","Generates reports based on parser validation results","Leverages justfile for streamlined command execution"],"zh":["基于 lib 的解析器验证","支持 integration tests 和 repos.yaml","提供 justfile 命令行工具","与 lib/parser、lib/crypto 和 lib/source 集成","支持 ADR 文档生成"],"ja":["lib ベースのパーサー検証","integration tests と repos.yaml をサポート","justfile コマンドラインツールを提供","lib/parser、lib/crypto、lib/source と統合","ADR ドキュメント生成をサポート"],"ko":["lib 기반의 파서 유효성 검사","integration tests 및 repos.yaml 지원","justfile 명령줄 도구 제공","lib/parser, lib/crypto, lib/source와의 통합","ADR 문서 생성 지원"],"es":["Validación de parsers en lib","Integración con justfile para ejecutar comandos","Soporte para tests de integración en lib/parser/tests/integration/","Compatibilidad con repos.yaml para la configuración de repositorios","Documentación de ADR en lib/docs/en/adr/core/"],"fr":["Validation de parsers dans lib","Intégration avec justfile pour exécuter des commandes","Prise en charge des tests d''intégration dans lib/parser/tests/integration/","Compatibilité avec repos.yaml pour la configuration des référentiels","Documentation de ADR dans lib/docs/en/adr/core/"],"de":["Validierung von Parsern in lib","Integration mit justfile für die Ausführung von Befehlen","Unterstützung für Integrations-tests in lib/parser/tests/integration/","Kompatibilität mit repos.yaml für die Konfiguration von Repositorien","Dokumentation von ADR in lib/docs/en/adr/core/"],"pt":["Opera exclusivamente dentro do lib","Recursos de integração com SpecVital Core parser","Testes de integração em lib/parser/tests/integration/","Suporte a comandos just em lib/justfile","Documentação de ADR em lib/docs/en/adr/core/"],"ru":["Работает исключительно внутри lib","Возможности интеграции с SpecVital Core parser","Тесты интеграции в lib/parser/tests/integration/","Поддержка команд just в lib/justfile","Документация ADR в lib/docs/en/adr/core/"],"ar":["تعمل حصريًا داخل lib","ميزات التكامل مع SpecVital Core parser","اختبارات التكامل في lib/parser/tests/integration/","دعم أوامر just في lib/justfile","توثيق ADR في lib/docs/en/adr/core/"]},"keywords":{"en":["how to use validate-parser","validate-parser setup guide","what is validate-parser","validate-parser alternative","validate-parser vs parserlint","validate-parser install","SpecVital Core parser validation","lib directory parser integration","parser validation best practices"],"zh":["AI 代理","validate-parser","解析器验证","lib","integration tests","repos.yaml","justfile","ADR 文档"],"ja":["AI エージェント","validate-parser","パーサー検証","lib","integration tests","repos.yaml","justfile","ADR ドキュメント"],"ko":["AI 에이전트","validate-parser","파서 유효성 검사","lib","integration tests","repos.yaml","justfile","ADR 문서"],"es":["validación de parsers","herramientas de ia para desarrolladores","agentes de ia","validación de sintaxis","integración con justfile","tests de integración","configuración de repositorios"],"fr":["validation de parsers","outils d''ia pour les développeurs","outils d''ia","validation de syntaxe","intégration avec justfile","tests d''intégration","configuration des référentiels"],"de":["validierung von parsern","ki-tools für entwickler","ki-agenten","validierung von syntax","integration mit justfile","integrations-tests","konfiguration von repositorien"],"pt":["validate-parser","lib","SpecVital Core parser","integração de parser","testes de integração","comandos just","ADR","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["validate-parser","lib","SpecVital Core parser","интеграция парсера","тесты интеграции","команды just","ADR","разработка программного обеспечения","инструменты разработки"],"ar":["validate-parser","lib","SpecVital Core parser","تكامل parser","اختبارات التكامل","أوامر just","ADR","تطوير البرمجيات","أدوات التطوير"]}},"owner":"kubrickcode","repo":"specvital","repoPath":"kubrickcode/specvital","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.446Z","topics":[],"category":"community","skillMd":{"name":"validate-parser","description":"Validate SpecVital parser accuracy by comparing with actual test framework CLI results","bodyPreview":"# Real-World Parser Validation Command\n\n## Working Context\n\nThis skill operates exclusively within `lib` (SpecVital Core parser).\nAll commands, file lookups, and report outputs are scoped to `lib/`.\n\n- **Source code**: `lib/parser/`, `lib/crypto/`, `lib/source/`\n- **Integration tests**: `lib/parser/tests/integration/`\n- **repos.yaml**: `lib/parser/tests/integration/repos.yaml`\n- **ADR documents**: `lib/docs/en/adr/core/`\n- **justfile**: `lib/justfile` (use `just` commands from this directory)\n-","body":"# Real-World Parser Validation Command\n\n## Working Context\n\nThis skill operates exclusively within `lib` (SpecVital Core parser).\nAll commands, file lookups, and report outputs are scoped to `lib/`.\n\n- **Source code**: `lib/parser/`, `lib/crypto/`, `lib/source/`\n- **Integration tests**: `lib/parser/tests/integration/`\n- **repos.yaml**: `lib/parser/tests/integration/repos.yaml`\n- **ADR documents**: `lib/docs/en/adr/core/`\n- **justfile**: `lib/justfile` (use `just` commands from this directory)\n- **Report output**: `lib/realworld-test-report.md`\n\nAlways `cd /workspaces/specvital/lib` before running `just` or `go test` commands.\n\n## Purpose\n\nValidate that SpecVital Core parser accurately detects tests by comparing:\n\n- **Ground Truth**: Actual test count from framework CLI (e.g., `vitest list` -> 379 tests)\n- **Parser Result**: Our parser''s detected test count (e.g., 350 tests)\n- **Delta**: If mismatch exists -> parser bug found\n\nThis is a **quality assurance tool** for the Core parser engine.\n\n## User Input\n\n```text\n$ARGUMENTS\n```\n\n**Interpretation**:\n\n- **Empty**: Auto-select a popular open-source repo (NOT in repos.yaml)\n- **Explicit request**: Specific repo name or URL -> analyze regardless of repos.yaml\n- **Implicit request**: Vague description -> find appropriate repo NOT in repos.yaml\n\n**Request Type Classification**:\n\n| Type         | Pattern                                 | repos.yaml Check |\n| ------------ | --------------------------------------- | ---------------- |\n| **Explicit** | URL, exact repo name (e.g., \"axios\")    | Skip             |\n| **Implicit** | Vague (e.g., \"Python project\", \"empty\") | Exclude          |\n\n**Examples**:\n\n| User Input                         | Type     | Interpretation                      |\n| ---------------------------------- | -------- | ----------------------------------- |\n| (empty)                            | Implicit | Pick popular repo not in repos.yaml |\n| `axios`                            | Explicit | Test axios (even if in repos.yaml)  |\n| `https://github.com/lodash/lodash` | Explicit | Test lodash (even if in repos.yaml) |\n| `Python project with pytest`       | Implicit | Find Python repo NOT in repos.yaml  |\n| `Something with Vitest`            | Implicit | Find Vitest repo NOT in repos.yaml  |\n\n---\n\n## Workflow\n\n### Phase 0: Review ADR Policies\n\n**Before starting validation**, read all ADR documents to understand current parser policies:\n\n```bash\n# List and read all core ADR documents\nls /workspaces/specvital/lib/docs/en/adr/core/\n# Read each .md file (excluding index.md)\n```\n\n**Why**: Parser behavior is defined by ADR policies. Discrepancies may be \"working as designed\" rather than bugs.\n\n### Phase 1: Repository Selection\n\n**1.1 Classify request type**:\n\n- **Explicit**: URL or exact repo name provided -> proceed directly\n- **Implicit**: Empty or vague description -> need repos.yaml exclusion\n\n**1.2 Read repos.yaml (for implicit requests only)**:\n\n```bash\n# Skip this step for explicit requests\ngrep \"url:\" lib/parser/tests/integration/repos.yaml\n```\n\n**1.3 Select repository**:\n\n- **Explicit request**: Parse and resolve to GitHub URL (ignore repos.yaml)\n- **Implicit request**: Pick well-known repo NOT in repos.yaml\n\n**1.4 Detect expected framework**:\n\n- Check package.json for JS/TS repos\n- Check pyproject.toml/setup.py for Python\n- Check go.mod for Go\n- Infer test framework from dependencies\n\n### Phase 2: Clone Repository\n\n```bash\ngit clone --depth 1 {url} /tmp/specvital-validate-{repo-name}\ncd /tmp/specvital-validate-{repo-name}\n```\n\n### Phase 3: Get Ground Truth (Actual Test Count)\n\n**Two strategies** (try in order):\n\n#### Strategy A: CLI Execution (Primary)\n\nRun the actual test framework CLI to get real test count.\n\n**Step 1: Identify framework and version**\n\nCheck the repository''s dependency file:\n\n- `package.json` -> devDependencies (jest, vitest, playwright, mocha, etc.)\n- `pyproject.toml` / `setup.py` -> pytest version\n- `go.mod` -> Go version\n\n**Step 2: Query Context7 MCP for current CLI usage**\n\nUse Context7 MCP to get up-to-date CLI documentation for the specific framework version:\n\n```\n1. mcp__context7__resolve-library-id -> Get library ID (e.g., \"/vitest/vitest\")\n2. mcp__context7__get-library-docs -> Query \"list tests CLI\" or \"collect tests\"\n```\n\nThis ensures:\n\n- Correct CLI flags for the installed version\n- Awareness of deprecated options\n- Framework-specific quirks\n\n**Step 3: Install dependencies and execute**\n\n```bash\n# Install project dependencies first\nnpm install / pip install -e . / go mod download\n\n# Run the CLI command from Context7 docs\n{framework-specific-command}\n```\n\n**Note**: Always verify CLI output format before counting\n\n#### Strategy B: AI Manual Analysis (Fallback)\n\n**When to use**: CLI fails due to:\n\n- Missing environment variables (DATABASE_URL, API_KEY, etc.)\n- Database/external service requirements\n- Complex build setup failures\n- Unsupported runtime in devcontainer\n\n**How to execute**:\n\n1. **Glob test files**: Find all test files using framework patterns\n\n   ```bash\n   # Examples\n   **/*.test.{js,ts,jsx,tsx}  # Jest/Vitest\n   **/*_test.py               # pytest\n   **/*_test.go               # Go\n   ```\n\n2. **Read each file**: Analyze test structure manually\n\n3. **Count tests**: Identify test functions/blocks by pattern\n   - JavaScript: `it()`, `test()`, `it.each()`, `test.each()`\n   - Python: `def test_*`, `@pytest.mark.parametrize`\n   - Go: `func Test*`, `func Benchmark*`\n\n4. **Handle edge cases**:\n   - Nested describes -> count leaf tests only\n   - Parameterized tests -> count as 1 (matches parser behavior)\n   - Skipped tests -> still count them\n\n**Important**: Document which strategy was used in the report\n\n### Phase 4: Run SpecVital Parser\n\n```bash\ncd /workspaces/specvital/lib\njust scan /tmp/specvital-validate-{repo-name}\n```\n\n### Phase 5: Compare Results\n\n**Calculate accuracy**:\n\n```\nGround Truth: 379 tests (from vitest list)\nParser Result: 350 tests\nDelta: -29 tests (7.7% under-detection)\n```\n\n**Interpret delta**:\n\n| Delta | Status | Meaning               |\n| ----- | ------ | --------------------- |\n| 0     | PASS   | Parser is accurate    |\n| != 0  | FAIL   | Parser bug, needs fix |\n\n**Important**: Even 1 test difference means a bug exists. No tolerance.\n\n### Phase 6: Investigate Discrepancies\n\nIf delta != 0:\n\n1. **Sample ground truth files**: Pick 5 test files from CLI output\n2. **Check parser output**: Are they detected? Correct test count?\n3. **Identify patterns**: What''s being missed?\n   - Dynamic test names?\n   - Unusual file patterns?\n   - Nested describes?\n   - Test.each/parameterized tests?\n4. **Document the bug**: Create actionable issue for parser fix\n\n### Phase 7: Generate Report\n\nCreate comprehensive validation report:\n\n- **Language**: **Korean - MANDATORY**\n  - Section headers, analysis, conclusions - ALL in Korean\n  - Only code snippets, file paths, and technical terms may remain in English\n- **Location**: `/workspaces/specvital/lib/realworld-test-report.md` (single file, overwrite)\n- **Format**: Use the report template below\n\n### Phase 8: Cleanup\n\n```bash\nrm -rf /tmp/specvital-validate-{repo-name}\n```\n\n---\n\n## Validation Criteria\n\n### PASS\n\n- Delta = 0 (exact match)\n- Framework correctly detected\n- No parse errors\n\n### FAIL\n\n- Delta != 0 (any difference = bug)\n- Wrong framework detected\n- Parser crash or timeout\n- Missing test patterns\n\n---\n\n## Report Template\n\n```markdown\n# Parser Validation Report: {repo-name}\n\n**Date**: {timestamp}\n**Repository**: [{owner}/{repo}]({url})\n**Framework**: {framework}\n\n---\n\n## Comparison Results\n\n| Source                           | Test Count             |\n| -------------------------------- | ---------------------- |\n| **Ground Truth** ({cli-command}) | {n}                    |\n| **SpecVital Parser**             | {n}                    |\n| **Delta**                        | {+/-n} ({percentage}%) |\n\n**Status**: {PASS|FAIL}\n\n---\n\n## Ground Truth Details\n\n**Method**: {CLI Execution | AI Manual Analysis}\n\n**Command/Approach used**:\n\n\\`\\`\\`bash\n{command or \"Manual file analysis via AI\"}\n\\`\\`\\`\n\n**Output sample**:\n\n\\`\\`\\`\n{first 10 lines of output or file analysis summary}\n\\`\\`\\`\n\n**Note** (if AI analysis):\n\n> CLI failed because: {reason}\n> Analyzed {n} test files manually\n\n---\n\n## Parser Results\n\n| Metric         | Value  |\n| -------------- | ------ |\n| Files Scanned  | {n}    |\n| Files Matched  | {n}    |\n| Tests Detected | {n}    |\n| Duration       | {time} |\n\n### Framework Distribution\n\n| Framework | Files | Tests |\n| --------- | ----- | ----- |\n| {name}    | {n}   | {n}   |\n\n---\n\n## Discrepancy Analysis\n\n{IF delta != 0}\n\n### Missing Tests Investigation\n\n**Sample comparison**:\n\n| File     | Ground Truth | Parser | Delta  |\n| -------- | ------------ | ------ | ------ |\n| `{path}` | {n}          | {n}    | {+/-n} |\n\n**Patterns identified**:\n\n- {pattern 1}: {description}\n- {pattern 2}: {description}\n\n**Root cause hypothesis**:\n{explanation of why tests are missing}\n\n{ELSE}\nNo significant discrepancies found.\n{ENDIF}\n\n---\n\n## Conclusion\n\n{Based on status}\n\n---\n\n## Next Steps\n\n- [ ] {action based on findings}\n```\n\n---\n\n## Key Rules\n\n### Must Do\n\n- **Write report in Korean** <- CRITICAL\n- Always get ground truth from actual test CLI\n- Install dependencies (`npm install`, `pip install`, etc.) for CLI to work\n- Compare at both file-level and test-level\n- Investigate any delta != 0\n- Document root cause of discrepancies\n\n### Must Not Do\n\n- **Write report in English** <- Use Korean only\n- Skip ground truth collection\n- Assume parser is correct without verification\n- Ignore any discrepancy (even 1 = bug)\n- Auto-select repos already in repos.yaml (for implicit requests only)\n\n**Note**: Explicit user requests override repos.yaml exclusion\n\n### Principles\n\n1. **Ground Truth First**: Real CLI results are the source of truth\n2. **Quantitative**: Measure exact delta, not \"looks right\"\n3. **Diagnostic**: Explain WHY discrepancies exist\n4. **Actionable**: Clear next steps for fixes\n\n---\n\n## Execution\n\nNow execute the parser validation according to the guidelines above.\n"},"lastSynced":"2026-03-08T02:08:56.178Z","agentAnalysis":{"suitability":{"en":"Essential for Parser Integration Agents working with SpecVital Core validation workflows.","zh":"适用于与 SpecVital Core 验证工作流集成的 Parser Integration Agents。","ja":"SpecVital Core の検証ワークフローと統合する Parser Integration Agents に不可欠です。","ko":"SpecVital Core 검증 워크플로와 통합하는 Parser Integration Agents에 필수적입니다.","es":"Esencial para los Agentes de Integración de Parser que trabajan con los flujos de trabajo de validación de SpecVital Core.","fr":"Essentiel pour les Agents d''Intégration Parser travaillant avec les flux de travail de validation de SpecVital Core.","de":"Essenziell für Parser-Integrations-Agents, die mit SpecVital Core-Validierungs-Workflows arbeiten.","pt":"Essencial para Agentes de Integração de Parser que trabalham com fluxos de trabalho de validação do SpecVital Core.","ru":"Необходим для агентов интеграции парсеров, работающих с рабочими процессами валидации SpecVital Core.","ar":"ضروري لعميل تكامل Parser العامل مع سير عمل التحقق من SpecVital Core."},"recommendation":{"en":"Provides comprehensive parser validation against real-world integration tests defined in repos.yaml. Enforces cryptographic verification and source validation through lib/crypto/ and lib/source/ modules, ensuring parser compliance with SpecVital Core standards.","zh":"提供了针对 repos.yaml 中定义的实世界集成测试的全面解析器验证。通过 lib/crypto/ 和 lib/source/ 模块强制执行加密验证和源验证，确保解析器符合 SpecVital Core 标准。","ja":"repos.yaml で定義された実世界の統合テストに対する包括的なパーサー検証を提供します。lib/crypto/ および lib/source/ モジュールを介して、暗号化検証およびソース検証を適用し、パーサーが SpecVital Core 標準に準拠していることを保証します。","ko":"repos.yaml에 정의된 실제 통합 테스트에 대한 포괄적인 파서 유효성을 제공합니다. lib/crypto/ 및 lib/source/ 모듈을 통해 암호화 확인 및 소스 확인을 적용하여 파서가 SpecVital Core 표준을 준수하는지 확인합니다.","es":"Proporciona una validación exhaustiva del parser frente a pruebas de integración del mundo real definidas en repos.yaml. Aplica verificación criptográfica y validación de origen a través de los módulos lib/crypto/ y lib/source/, garantizando el cumplimiento del parser con los estándares de SpecVital Core.","fr":"Fournit une validation complète du parser contre des tests d''intégration réels définis dans repos.yaml. Applique la vérification cryptographique et la validation de la source via les modules lib/crypto/ et lib/source/, assurant la conformité du parser avec les standards SpecVital Core.","de":"Bietet eine umfassende Parser-Validierung gegen reale Integrationstests, die in repos.yaml definiert sind. Erzwingt kryptografische Verifizierung und Quellenvalidierung durch die Module lib/crypto/ und lib/source/, um die Konformität des Parsers mit den SpecVital Core-Standards sicherzustellen.","pt":"Fornece validação de parser abrangente contra testes de integração do mundo real definidos em repos.yaml. Impõe verificação criptográfica e validação de origem por meio dos módulos lib/crypto/ e lib/source/, garantindo o cumprimento do parser com os padrões do SpecVital Core.","ru":"Предоставляет всестороннюю проверку парсера против реальных интеграционных тестов, определенных в repos.yaml. Применяет криптографическую проверку и проверку источника через модули lib/crypto/ и lib/source/, обеспечивая соответствие парсера стандартам SpecVital Core.","ar":"يقدم التحقق الشامل من Parser ضد الاختبارات التكاملية للعالم الحقيقي المحددة في repos.yaml. يفرض التحقق الكريبتوغرافي والتحقق من المصدر من خلال وحدات lib/crypto/ و lib/source/، مما يضمن امتثال Parser لمعايير SpecVital Core."},"useCases":{"en":["Executing integration test suites from lib/parser/tests/integration/","Validating parser output against cryptographic requirements","Automating ADR compliance checks from lib/docs/en/adr/core/","Running justfile commands for validation workflows"],"zh":["从 lib/parser/tests/integration/ 执行集成测试套件","验证解析器输出是否满足加密要求","从 lib/docs/en/adr/core/ 自动执行 ADR 合规性检查","运行 justfile 命令以进行验证工作流"],"ja":["lib/parser/tests/integration/ から統合テストスイートを実行する","パーサーの出力が暗号化要件を満たしていることを検証する","lib/docs/en/adr/core/ から ADR コンプライアンスチェックを自動化する","justfile コマンドを使用して検証ワークフローを実行する"],"ko":["lib/parser/tests/integration/에서 통합 테스트套件을 실행합니다.","파서 출력이 암호화 요구 사항을 충족하는지 확인합니다.","lib/docs/en/adr/core/에서 ADR 규정 준수 확인을 자동화합니다.","justfile 명령을 사용하여 유효성 검사 워크플로를 실행합니다."],"es":["Ejecutar suites de pruebas de integración desde lib/parser/tests/integration/","Validar la salida del parser frente a requisitos criptográficos","Automatizar comprobaciones de cumplimiento de ADR desde lib/docs/en/adr/core/","Ejecutar comandos justfile para flujos de trabajo de validación"],"fr":["Exécuter des suites de tests d''intégration depuis lib/parser/tests/integration/","Valider la sortie du parser par rapport aux exigences cryptographiques","Automatiser les vérifications de conformité ADR depuis lib/docs/en/adr/core/","Exécuter des commandes justfile pour les flux de travail de validation"],"de":["Ausführen von Integrationstest-Suites aus lib/parser/tests/integration/","Validieren der Parser-Ausgabe gegen kryptografische Anforderungen","Automatisieren von ADR-Compliance-Prüfungen aus lib/docs/en/adr/core/","Ausführen von justfile-Befehlen für Validierungs-Workflows"],"pt":["Executando conjuntos de testes de integração de lib/parser/tests/integration/","Validando a saída do parser contra requisitos criptográficos","Automatizando verificações de conformidade do ADR de lib/docs/en/adr/core/","Executando comandos justfile para fluxos de trabalho de validação"],"ru":["Выполнение наборов интеграционных тестов из lib/parser/tests/integration/","Проверка вывода парсера против криптографических требований","Автоматизация проверок соответствия ADR из lib/docs/en/adr/core/","Запуск команд justfile для рабочих процессов проверки"],"ar":["تنفيذ مجموعات اختبار التكامل من lib/parser/tests/integration/","التحقق من مخرجات Parser مقابل المتطلبات الكريبتوغرافية","تأتميم فحوصات امتثال ADR من lib/docs/en/adr/core/","تشغيل أوامر justfile لتدفقات العمل التحقق"]},"limitations":{"en":["Exclusively scoped to lib/ directory operations","Requires repos.yaml configuration","Dependent on SpecVital Core parser structure","Needs justfile command availability"],"zh":